-- Diálogos exclusivos do FireRed

return {
  ["g3:08172255"] = "Meus amigos e eu viemos aqui para\\ncapturar POKéMON INSETO!\\pTodos estão ansiosos por batalhas\\nPOKéMON!",
  ["g3:081722c7"] = "Ei! Você tem POKéMON!\\nSim!\\pBora batalhar!",
  ["g3:081722f9"] = "Não!\\nMeu CATERPIE não aguenta mais!",
  ["g3:08172315"] = "Shhh! Você vai assustar os insetos.\\nA gente batalha numa próxima, tá?",
  ["g3:0817234a"] = "E aí?\\nVocê não pode passar de fininho\\pTreinador POKéMON de verdade enfrenta os adversários!",
  ["g3:0817237d"] = "Hã?\\nFiquei sem POKéMON!",
  ["g3:08172398"] = "Que droga! Vou capturar uns mais\\nfortes!",
  ["g3:081723d4"] = "Ei, espera aí!\\nPor que tá com tanta pressa?",
  ["g3:08172402"] = "Eu desisto!\\nVocê tem manhã nisso!",
  ["g3:0817241f"] = "Às vezes, você pode encontrar\\ncoisas no chão.\\pTô procurando algo que deixei\\ncair. Você pode me ajudar?",
  ["g3:08172482"] = "Posso ser pequeno, mas não quero\\nque pegue leve comigo!",
  ["g3:081724bf"] = "Ah, droga.\\nDeu tudo errado.",
  ["g3:081724dc"] = "Perdi parte da minha mesada...",
  ["g3:081724f9"] = "Sabia que os POKéMON evoluem?",
  ["g3:0817251b"] = "Ah!\\nPerdi!",
  ["g3:08172527"] = "Os POKéMON INSETO evoluem rápido.\\nEles são demais!",
  ["g3:08172559"] = "Eu estava jogando POKé BOLAS para\\ncapturar POKéMON e elas acabaram.\\pPor isso, nunca é demais ter\\nPOKé BOLAS.",
  ["g3:081725c7"] = "DICAS PARA TREINADORES\\pSe seus POKéMON estão fracos e você\\nquer evitar as batalhas, afaste-se\\pdas áreas com grama alta!",
  ["g3:08172629"] = "Contra veneno, use ANTÍDOTOS!\\nCompre-os nas LOJAS POKéMON!",
  ["g3:0817265c"] = "DICAS PARA TREINADORES\\pContate o PROFESSOR CARVALHO\\natravés de um PC para ter sua\\pPOKéDEX avaliada!",
  ["g3:081726a3"] = "DICAS PARA TREINADORES\\pVocê não pode capturar um\\nPOKéMON de outra pessoa.\\pJogue POKé BOLAS apenas nos\\nPOKéMON selvagens!",
  ["g3:0817271d"] = "DICAS PARA TREINADORES\\pEnfraqueça os POKéMON antes de\\ntentar capturá-los!\\pSe estiverem saudáveis, eles podem\\nescapar!",
  ["g3:08172773"] = "VOCÊ ESTÁ SAINDO DA FLORESTA DE\\nVIRIDIAN, CIDADE DE PEWTER ADIANTE",
  ["g3:0817279d"] = "CARAMBA!\\nQue susto!\\p... Ah, é só uma criança!",
  ["g3:081727cb"] = "Uau!\\nQue surpresa!",
  ["g3:081727df"] = "As crianças como você não deveriam\\nficar vagando por aí no escuro.",
  ["g3:0817281d"] = "Você também veio explorar a\\ncaverna?",
  ["g3:08172844"] = "Perder é chato!\\nNão é legal.",
  ["g3:08172863"] = "Vim até aqui pra impressionar as\\ngarotas.",
  ["g3:08172896"] = "Uau! Aqui dentro é maior do que\\neu pensei!",
  ["g3:081728c3"] = "Ah!\\nPerdi!",
  ["g3:081728d2"] = "Como se sai daqui?\\nÉ muito grande, posso me perder.",
  ["g3:0817290b"] = "O quê?!\\nNão me assuste assim!",
  ["g3:08172927"] = "Meus POKéMON não conseguiram!",
  ["g3:0817293c"] = "Tenho que encontrar POKéMON mais\\nfortes. Onde será que eles estão?",
  ["g3:08172972"] = "O quê?!\\nTô aqui esperando os meus amigos.",
  ["g3:081729a4"] = "Eu perdi?",
  ["g3:081729ac"] = "Ouvi dizer que existem alguns\\nfósseis muito raros aqui, por isso\\peu vim.",
  ["g3:081729ea"] = "Tem homens suspeitos na caverna.\\nE quanto a você?",
  ["g3:08172a1a"] = "Você me venceu!",
  ["g3:08172a26"] = "Eu vi eles! Tenho certeza de que\\nsão da EQUIPE ROCKET!",
  ["g3:08172a55"] = "Você precisa atravessar esta\\ncaverna para chegar à CIDADE\\pDE CERULEAN.",
  ["g3:08172a8f"] = "Perdi.",
  ["g3:08172a97"] = "ZUBAT é fortão!\\nSe conseguir capturar um,\\pele com certeza será útil.",
  ["g3:08172ae0"] = "Cuidado!\\nOs ZUBAT são sanguessugas!",
  ["g3:08172b00"] = "Oi, estou escavando fósseis sob o\\nMONTE LUA.\\pÀs vezes, o BROCK do GINÁSIO de\\nPEWTER me dá uma mãozinha.",
  ["g3:08172b64"] = "Ei, pode parar aí!\\pEu encontrei esses fósseis!\\nEles são meus!",
  ["g3:08172b99"] = "Tá!\\nVou dividir!",
  ["g3:08172bab"] = "Um fóssil pra cada!\\nNão tem pra quê ter ganância!",
  ["g3:08172bd6"] = "Muito bem.\\nEntão este fóssil é meu!",
  ["g3:08172bfb"] = "Longe daqui, na ILHA DE CINNABAR,\\ntem um LABORATÓRIO POKéMON.\\pLá, eles fazem pesquisas sobre\\na regeneração de fósseis.",
  ["g3:08172c5a"] = "Nós, da EQUIPE ROCKET, vamos\\nencontrar os fósseis!\\pReviver os POKéMON a partir\\ndeles nos trará grandes riquezas!",
  ["g3:08172cb8"] = "Ugh!\\nAgora eu tô bravo!",
  ["g3:08172ccb"] = "Você me deixou bravo!\\nA EQUIPE ROCKET vai te colocar\\pna lista negra!",
  ["g3:08172cfc"] = "Nós, da EQUIPE ROCKET, somos os\\nbandidos POKéMON!\\pEspalhamos medo com nossa força!",
  ["g3:08172d46"] = "Estraguei tudo!",
  ["g3:08172d51"] = "Maldição!\\nMeus colegas vão me vingar!",
  ["g3:08172d82"] = "Estamos fazendo um grande trabalho!\\nSuma daqui, jovem!",
  ["g3:08172daf"] = "Você é muito hábil...",
  ["g3:08172dc1"] = "Se encontrar um fóssil, me entrega\\ne dá o fora!",
  ["g3:08172df0"] = "As criancinhas não deveriam se\\nmeter com os adultos!\\pIsso pode ter consequências!",
  ["g3:08172e3e"] = "Tô furioso!",
  ["g3:08172e4b"] = "Os POKéMON viviam aqui muito\\nantes das pessoas chegarem.",
  ["g3:08172e77"] = "Você quer o FÓSSIL CÚPULA?",
  ["g3:08172e94"] = "Você quer o FÓSSIL ESPIRAL?",
  ["g3:08172eb2"] = "Você obteve o FÓSSIL ESPIRAL!",
  ["g3:08172ecd"] = "Você obteve o FÓSSIL CÚPULA!",
  ["g3:08172ee7"] = "Bonjour!\\nSou o garçón deste navíô.\\pFicarréi muito feliz em servír\\nqualquer coisa que você quisérr!\\p... ... ...\\nAh! O tipo forrte e silansíô!",
  ["g3:08172f60"] = "Os passageiros estão inquietos\\ndepois dessa longa viagem.\\pOs mais entediados poderão te desafiar!",
  ["g3:08172fc3"] = "Este navio é um transatlântico de\\nluxo para TREINADORES do mundo\\ptodo!\\pEm cada porto, fazemos festas com\\nTREINADORES convidados.",
  ["g3:08173035"] = "{RIVAL}: Bonjour!\\n{PLAYER}!\\pQuem diria te ver aqui!\\n{PLAYER}, convidaram você mesmo?\\pE aí, como vai sua POKéDEX?\\pEu já capturei 40 tipos.\\nEles estão por toda parte.\\pAnde pelas áreas com grama alta\\ne procure bem por eles.",
  ["g3:08173110"] = "Humph!\\pPelo menos você está treinando\\nseus POKéMON!",
  ["g3:08173164"] = "{RIVAL}: Ouvi dizer que tinha um\\nmestre em CORTAR a bordo.\\pMas ele era só um velhote\\nenjoado!\\pCORTAR em si é bem útil.\\nVai ser uma mão na roda.\\pVocê devia ir falar com ele também.\\nFalou!",
  ["g3:0817320c"] = "O CAPITÃO é um mestre espadachim.\\nEle é incrível usando CORTAR.\\pDizem que ele até ensina aos\\nPOKéMON a CORTAR!",
  ["g3:0817326f"] = "A festa acabou.\\nO navio vai partir em breve.",
  ["g3:081732a2"] = "Oof!\\nEsfregar o convés dá um trabalhão!",
  ["g3:081732c6"] = "Urf... Tô passando mal...\\pFiquei enjoado, então saí um\\npouco para pegar ar...",
  ["g3:08173308"] = "Ei, navegante!\\pVamos dar uma dançadinha!",
  ["g3:0817332b"] = "Você é impressionante!",
  ["g3:0817333e"] = "Quantos tipos de POKéMON você\\nacha que existem nesse mundão?",
  ["g3:08173382"] = "Olá!\\nTá com enjoo?",
  ["g3:081733a0"] = "Eu só fui descuidado!",
  ["g3:081733b5"] = "Meu pai disse que existem 100 tipos\\nde POKéMON. Acho que existem mais.",
  ["g3:081733f8"] = "Você aí, mon petit!\\nEstamôs muito ocupádos aqui!\\pSaí da frentê!",
  ["g3:08173429"] = "Vi uma FRUTA estranha no lixo.\\nQual será que era?",
  ["g3:08173462"] = "Tô tão ocupado que tô ficando tonto!\\nVocê precisa me dar espaço aqui!",
  ["g3:081734a0"] = "Hum-de-hum-de-ho...\\pEu descasco batatas todo dia!\\nHum-hum...",
  ["g3:081734d3"] = "Você ouviu falar do SNORLAX?\\nÉ um comilão.\\pNenhum outro POKéMON come\\ne dorme como o SNORLAX!",
  ["g3:0817353e"] = "Snif... Snif...\\pSó fico descascando cebolas...\\nSnif...",
  ["g3:08173570"] = "Er-hem!\\nDe fato, sou o CHEF!\\pO pratô prrincipal é...",
  ["g3:0817359f"] = "Saláda de salmôn!\\pOs hóspedes podem reclamár\\nque é peixe de novo, hein!",
  ["g3:081735df"] = "Enguias no barbecuê!\\pOs hóspedes vão fazér motim,\\neu temô.",
  ["g3:08173611"] = "Bife especial!\\pMas será que tenho filés\\nsuficientes?",
  ["g3:08173646"] = "CAPITÃO: Ooargh...\\nEstou me sentindo horrível...\\pUrrp! Estou enjoado...",
  ["g3:08173676"] = "{PLAYER} massageou as costas\\ndo CAPITÃO!\\pMassageia...\\nMassageia...",
  ["g3:081736a6"] = "CAPITÃO: Ufa! Obrigado!\\nAgora estou me sentindo bem melhor.\\pQuer ver minha técnica secreta\\nde CORTAR?\\pEu até poderia te mostrar minha\\npreciosa técnica de CORTAR, se\\pnão estivesse tão mal...\\pJá sei! Você pode ficar com isto!\\nCom esta MÁQUINA OCULTA!\\pEnsine ao seu POKéMON, e você\\npoderá CORTAR a qualquer momento!",
  ["g3:081737af"] = "{PLAYER} recebeu a MO01\\ndo CAPITÃO!",
  ["g3:081737d2"] = "Usando CORTAR, você pode derrubar\\nárvores pequenas.\\pQue tal tentar nas árvores ao\\nredor da CIDADE DE VERMILION?",
  ["g3:08173831"] = "CAPITÃO: ... Ufa!\\pAgora que não estou mais enjoado,\\nacho que chegou a hora.\\pO SANTA ANA vai zarpar em breve!\\pAdeus, até nosso retorno à\\nCIDADE DE VERMILION!",
  ["g3:081738e6"] = "Eca!\\nEu não devia ter olhado!",
  ["g3:08173903"] = "Como Vencer o Enjoo...\\nO CAPITÃO está lendo isso!",
  ["g3:0817393b"] = "Ssh...!\\nSou um agente da POLÍCIA GLOBAL.\\pEstou seguindo a EQUIPE ROCKET.\\nEles estão tramando alguma coisa.",
  ["g3:08173999"] = "Eu amo POKéMON!\\nE você?",
  ["g3:081739b1"] = "Uau!\\nVocê é incrível!",
  ["g3:081739c5"] = "Escuta, escuta!\\nDeixa eu ser seu amigo, tá?\\pAí a gente pode trocar POKéMON\\ne fazer várias coisas.",
  ["g3:08173a1a"] = "Eu capturei esses POKéMON\\npelo mundo inteiro!",
  ["g3:08173a4f"] = "Ah, não!\\nEu rodei o mundo todo por eles!",
  ["g3:08173a7a"] = "Você machucou meus pobres\\nPOKéMON!\\pEu exijo que você os cure em\\num CENTRO POKéMON!",
  ["g3:08173ac5"] = "Estamos viajando pelo mundo,\\nmeus filhos e eu.",
  ["g3:08173afa"] = "Um cruzeiro pelo mundo é tão\\nelegante e aconchegante!",
  ["g3:08173b21"] = "Eu sempre viajo com WIGGLYTUFF.\\nNunca saio de casa sem ele.",
  ["g3:08173b61"] = "WIGGLYTUFF: Puup pupuu!",
  ["g3:08173b79"] = "Garçom, eu gostaria de uma torta\\nde cereja, por favor!",
  ["g3:08173ba4"] = "Garçonete, eu gostaria de uma\\ntorta de cereja, por favor!",
  ["g3:08173bd1"] = "Jovem insolente!\\nComo ousa invadir assim!",
  ["g3:08173bfa"] = "Humph! Que jovem rude!\\nVocê não tem nenhuma educação!",
  ["g3:08173c30"] = "Quero ficar sozinho!\\nVá embora!",
  ["g3:08173c52"] = "Sou apenas um viajante solitário...\\pMeus únicos companheiros e amigos\\nsão os POKéMON que capturei em\\pminhas jornadas...",
  ["g3:08173cb4"] = "Meus amigos...",
  ["g3:08173cc4"] = "Você deve ser gentil com os amigos!",
  ["g3:08173ce3"] = "Viajei por toda parte, mas em todas\\nas minhas viagens nunca vi um\\pPOKéMON dormir tanto quanto este!\\pEra mais ou menos assim!",
  ["g3:08173d63"] = "Competir contra os jovens me\\nmantém jovem.",
  ["g3:08173d92"] = "Boa luta!\\nAh, eu me sinto jovem de novo!",
  ["g3:08173db6"] = "Quinze anos atrás, eu teria vencido!",
  ["g3:08173ddb"] = "Olha só o que eu pesquei!",
  ["g3:08173df7"] = "Acabou tudo!",
  ["g3:08173e04"] = "Festa?\\pA festa do cruzeiro já deve ter\\nacabado a essa altura.",
  ["g3:08173e3a"] = "Ah, sim, eu já vi alguns POKéMON\\ntransportando pessoas pela água!",
  ["g3:08173e7b"] = "Árvores pequenas podem ser cortadas\\nusando o movimento CORTAR.\\pMas lembre-se disto!\\nCORTAR é uma técnica MO.\\pDepois de aprender, não é fácil\\nse livrar dela.",
  ["g3:08173f07"] = "O que você considera mais valioso,\\num POKéMON forte ou um raro?",
  ["g3:08173f42"] = "Tenho que te parabenizar!",
  ["g3:08173f55"] = "Pessoalmente, eu prefiro os\\nPOKéMON fortes e raros.",
  ["g3:08173f83"] = "Acho que não vi você na festa,\\nnão é?",
  ["g3:08173fab"] = "Calma aí!",
  ["g3:08173fb9"] = "Ah, eu adoro seus POKéMON fortes!\\nAh, como eu invejo você por eles!",
  ["g3:08173ff7"] = "Você já foi à ZONA DE SAFÁRI\\nna CIDADE DE FUCHSIA?\\pTem muitos tipos de POKéMON\\nraros por lá.",
  ["g3:0817404f"] = "Eu e meu papai achamos a\\nZONA DE SAFÁRI incrível!\\pQueria que a gente pudesse\\nir lá de novo.",
  ["g3:081740a1"] = "O CAPITÃO disse que está muito\\ndoente. Ele estava todo pálido.",
  ["g3:081740d6"] = "Ouvi dizer que muita gente\\npassa mal no mar.",
  ["g3:081740f6"] = "Navegante, você vai andar na prancha\\nse perder!",
  ["g3:08174123"] = "Argh!\\nDerrotado por uma criança!",
  ["g3:0817413a"] = "Quando estamos em alto-mar, POKéMON\\nágua-viva às vezes passam flutuando.",
  ["g3:08174177"] = "Olá, sem nome!\\pNão sei dizer se você vem do mar ou\\ndas montanhas, mas vamos conversar.\\pTodos os meus POKéMON são do mar.",
  ["g3:081741ef"] = "Droga!\\nDeixei aquele escapar!",
  ["g3:0817420e"] = "Queria fazer de você\\nassistente também!",
  ["g3:08174239"] = "Até nós, marinheiros, também temos\\nPOKéMON!",
  ["g3:0817425c"] = "Muito bem, você não é nada mal.",
  ["g3:08174272"] = "Capturamos todos os nossos POKéMON\\nquando estávamos em alto-mar.",
  ["g3:081742a6"] = "Gosto de crianças valentes\\ncomo você!",
  ["g3:081742c3"] = "Argh!\\nPerdi!",
  ["g3:081742d2"] = "Os POKéMON marinhos vivem em águas\\nprofundas. Você vai precisar de uma\\pVARA para pescá-los!",
  ["g3:08174315"] = "Você sabe o que dizem sobre\\nmarinheiros e batalhas!",
  ["g3:08174348"] = "Isso aí!\\nBoa batalha, camarada!",
  ["g3:08174362"] = "Hahaha!\\nQuer ser navegante, camarada?",
  ["g3:08174385"] = "Pode vir! Meu orgulho de marinheiro\\nestá em jogo!",
  ["g3:081743b3"] = "Seu espírito me afundou!",
  ["g3:081743c8"] = "Você viu o MESTRE DA PESCA\\nna CIDADE DE VERMILION?",
  ["g3:081743f8"] = "Meu amigo MACHOKE é superforte!\\pCom sua SUPERFORÇA, ele consegue\\nmover rochas enormes!",
  ["g3:08174444"] = "MACHOKE: Gwoh! Goggoh!",
  ["g3:0817445b"] = "Parece com cansaço.\\nGostaria de descansar um pouco?",
  ["g3:08174490"] = "Fico feliz em ver que todos estão\\nparecendo revigorados e animados.",
  ["g3:081744d0"] = "Ah, desculpe por pegar no seu pé.\\nVocê parece com meu irmãozinho...",
  ["g3:08174515"] = "Ah, desculpe por pegar no seu pé.\\nVocê parece com minha irmãzinha...",
  ["g3:08174559"] = "As pessoas costumam perder\\ncoisas na escuridão da\\pPASSAGEM SUBTERRÂNEA.",
  ["g3:0817459b"] = "Ouvi dizer que um POKéMON sonolento\\ntambém apareceu nos arredores da\\pCIDADE DE CELADON.",
  ["g3:081745d9"] = "O SHOPPING DE CELADON tem uma\\nótima variedade.\\pVocê vai lá com frequência?",
  ["g3:0817462c"] = "Entrei no TÚNEL DE ROCHA, mas lá\\ndentro é um breu total e dá muito\\pmedo.\\pSe eu tivesse um POKéMON para usar\\nCLARAO e iluminar o caminho...",
  ["g3:081746a7"] = "Ora, mas que surpresa!\\nOs DIGLETTS cavaram este túnel!\\pEle vai direto para a CIDADE DE\\nVIRIDIAN, pelo que me disseram.",
  ["g3:08174710"] = "Será que você tem manhã o bastante\\npara me enfrentar?",
  ["g3:08174738"] = "Eu perdi...",
  ["g3:08174744"] = "Não gosto de perder, especialmente\\npara alguém mais jovem...",
  ["g3:08174784"] = "Posso ver que você é hábil.\\nVamos ver exatamente o quanto!",
  ["g3:081747b8"] = "Minha hipótese estava certa...",
  ["g3:081747c8"] = "Tsc!\\nEu admito, você é melhor do que eu!",
  ["g3:081747ef"] = "Se conseguir passar por aqui, você\\npoderá enfrentar a ELITE DOS QUATRO.",
  ["g3:0817482c"] = "Não!\\nInacreditável!",
  ["g3:0817483e"] = "Posso te vencer quando se trata\\nde conhecimento sobre os POKéMON!",
  ["g3:08174877"] = "Esta é a ESTRADA DA VITÓRIA.\\nÉ o teste final para os TREINADORES!",
  ["g3:081748b4"] = "Atchim!",
  ["g3:081748bb"] = "Caso você se prenda, tente mover\\nalgumas rochas por aí.",
  ["g3:081748ee"] = "Ah, então você quer desafiar a\\nELITE DOS QUATRO?",
  ["g3:0817491b"] = "Você me venceu!",
  ["g3:08174927"] = "{RIVAL} também passou por aqui.",
  ["g3:08174942"] = "Vamos lá!\\nVou te dar uma surra!",
  ["g3:0817495a"] = "Fui surrado!",
  ["g3:08174969"] = "Você conquistou o direito de\\nestar na ESTRADA DA VITÓRIA...",
  ["g3:08174995"] = "A ESTRADA DA VITÓRIA é muito\\ndifícil?",
  ["g3:081749b0"] = "Muito bem!",
  ["g3:081749bb"] = "Muitos TREINADORES desistem do\\ndesafio e voltam para casa.",
  ["g3:081749f9"] = "Você deve se orgulhar por ter\\nlutado bravamente na ESTRADA\\pDA VITÓRIA.\\pEm reconhecimento ao seu feito,\\nvou te ensinar o movimento\\pPONTADA DUPLA.\\pVocê quer que eu ensine essa\\ntécnica?",
  ["g3:08174abc"] = "Posso te ensinar a técnica a\\nqualquer hora.",
  ["g3:08174ae2"] = "Para qual POKéMON devo ensinar\\no movimento PONTADA DUPLA?",
  ["g3:08174b0c"] = "Não baixe a guarda na\\nLIGA POKéMON!\\pVá lá e acabe com todos!",
  ["g3:08174b60"] = "Ouvi rumores sobre alguém que é jovem\\nprodígio.",
  ["g3:08174b83"] = "Os rumores eram verdadeiros!",
  ["g3:08174b99"] = "Então foi você quem derrotou\\nGIOVANNI da EQUIPE ROCKET?",
  ["g3:08174bca"] = "Os TREINADORES vivem para buscar\\noponentes mais fortes.",
  ["g3:08174bf4"] = "Uau!\\nQue força!",
  ["g3:08174c03"] = "Ao enfrentar batalhas difíceis,\\nvocê fica mais forte.",
  ["g3:08174c30"] = "Vou mostrar o quanto você é sagaz.\\nSó que não!",
  ["g3:08174c5a"] = "Tô furiosa!",
  ["g3:08174c67"] = "Você acabou de me mostrar\\no quão boa eu era...",
  ["g3:08174c8a"] = "Só os escolhidos podem passar\\npor aqui!",
  ["g3:08174ca9"] = "Não acredito nisso!",
  ["g3:08174cbd"] = "Todos os TREINADORES que estão aqui\\nvao participar da LIGA POKéMON.\\pTenha cuidado.",
  ["g3:08174d0c"] = "RAY: Juntos, a gente está\\ndestinado à grandeza!",
  ["g3:08174d45"] = "RAY: Isso é ridículo!\\nNão pode ser!",
  ["g3:08174d64"] = "RAY: Você derrotou a gente.\\nA grandeza continua inalcançável...",
  ["g3:08174d96"] = "RAY: Juntos, a gente acabaria\\ncom você num piscar de olhos!\\pPara batalhar com a gente, você\\nprecisa ter dois POKéMON.",
  ["g3:08174e08"] = "TYRA: Estamos tentando nos\\ntornar campeoes juntos.",
  ["g3:08174e39"] = "TYRA: Ah, mas...",
  ["g3:08174e48"] = "TYRA: Você me ensinou que o poder\\npode assumir infinitas formas.",
  ["g3:08174e8d"] = "TYRA: Você não pode batalhar com\\na gente se tiver só um POKéMON.",
  ["g3:08174eca"] = "Quem é você?\\nComo você chegou aqui?",
  ["g3:08174eed"] = "Ai!\\nDerrotado!",
  ["g3:08174efa"] = "Droga... você está desrespeitando\\na EQUIPE ROCKET, não é?",
  ["g3:08174f2c"] = "Você invadiu a operação da\\nEQUIPE ROCKET? Que ousadia!",
  ["g3:08174f60"] = "Bum!",
  ["g3:08174f66"] = "Você não vai sair impune dessa,\\ncriança!",
  ["g3:08174f94"] = "Alerta de intrusão!",
  ["g3:08174fa4"] = "Não consegui!",
  ["g3:08174fb3"] = "O VISOR SILPH? Humph!\\nNão sei onde está.",
  ["g3:08174fe1"] = "Por que você veio aqui?",
  ["g3:08174ff8"] = "Isso não vai prestar!",
  ["g3:08175007"] = "Tá bem, eu falo...\\nPega o elevador pra ver meu CHEFE.",
  ["g3:0817503a"] = "Se perdeu, cara de rato?",
  ["g3:0817505a"] = "Por quê...?",
  ["g3:08175060"] = "Ih! Essa confusão acabou abrindo\\na porta de alguma forma!",
  ["g3:0817508c"] = "O CHEFE disse que você pode ver\\nfantasmas com o VISOR SILPH.",
  ["g3:081750bf"] = "Eu me rendo!",
  ["g3:081750cc"] = "O QG da EQUIPE ROCKET tem quatro\\nandares subterrâneos.\\pAcha que consegue chegar até o\\nCHEFE?",
  ["g3:0817511a"] = "Para de se meter nos assuntos\\nda EQUIPE ROCKET, ou então...",
  ["g3:0817514a"] = "Ugh!\\nDerrotado!",
  ["g3:0817515b"] = "O VISOR SILPH?\\nAh, a máquina que o CHEFE roubou.\\pEla está por aqui em algum lugar.",
  ["g3:0817519e"] = "Recebemos um aviso lá de cima de\\nque você estava vindo!",
  ["g3:081751ce"] = "O quê?\\nEu perdi? Não!",
  ["g3:081751e0"] = "Pode ir em frente!\\pMas você não consegue usar o\\nelevador sem a CHAVE DO ELEVADOR.",
  ["g3:08175226"] = "Ora ora! Devo dizer que estou\\nimpressionado por você ter\\pchegado até aqui.\\pA EQUIPE ROCKET captura POKéMON\\ndo mundo inteiro.\\pEles são ferramentas importantes\\npara manter nosso empreendimento\\pcriminoso.\\pSou o líder, GIOVANNI!\\pPor sua insolência, você vai sentir\\numa dor sem igual!",
  ["g3:08175318"] = "O QUÊ?!\\nNão pode ser!",
  ["g3:0817532d"] = "Vejo que você cria seus POKéMON\\ncom o máximo de cuidado.\\pUma criança como você jamais\\nentenderia o que eu pretendo\\palcançar.\\pPor ora, vou me retirar!\\pEspero que a gente se encontre\\nde novo...",
  ["g3:081753d0"] = "Eu te conheço! Você arruinou\\nnossos planos no MONTE LUA!",
  ["g3:081753fe"] = "Derrotado de novo!",
  ["g3:0817540c"] = "Você tem algo contra a EQUIPE\\nROCKET?",
  ["g3:08175437"] = "Como você não consegue ver a\\nbeleza da nossa maldade?",
  ["g3:08175463"] = "Ai ai ai!",
  ["g3:0817546a"] = "CHEFE!\\nDesculpe por ter falhado com você!",
  ["g3:08175488"] = "O elevador não funciona? Quem está\\ncom a CHAVE DO ELEVADOR?",
  ["g3:081754b9"] = "Não!",
  ["g3:081754bd"] = "Ah, não!\\nDeixei a CHAVE DO ELEVADOR cair!",
  ["g3:081754dd"] = "Parece que precisa de uma chave.",
  ["g3:081754f7"] = "Boas-vindas.\\pO PRESIDENTE está na sala de\\nreunioes no P11.",
  ["g3:08175549"] = "SEDE DA COMPANHIA SILPH\\nP1",
  ["g3:08175562"] = "Socorro!\\nSou um funcionário da SILPH.",
  ["g3:0817557e"] = "Como você sabia que eu era um\\nROCKET?",
  ["g3:0817559f"] = "Trabalho para a SILPH e para a\\nEQUIPE ROCKET.",
  ["g3:081755c6"] = "É proibido entrar aqui!\\nVá embora!",
  ["g3:081755e5"] = "Você é hábil.",
  ["g3:081755f2"] = "Você pode resolver esse labirinto?\\nJá vou avisando que não é fácil!",
  ["g3:0817562d"] = "Crianças não podem entrar aqui!",
  ["g3:0817564a"] = "Que força!",
  ["g3:08175651"] = "Os azulejos em forma de diamante\\nsão blocos de teleporte.\\pSão transportadores de alta\\ntecnologia.",
  ["g3:081756ad"] = "Ei, jovem!\\nO que está fazendo aqui?",
  ["g3:081756d8"] = "Dei mole!",
  ["g3:081756e2"] = "A COMPANHIA SILPH será associada\\nà EQUIPE ROCKET!",
  ["g3:08175711"] = "Ahhh!\\nNão! Pare! Socorro!\\pAh, você não é da EQUIPE ROCKET.\\nMe desculpa, eu pensei que...\\pMe perdoaria se eu te ensinasse o\\nmovimento ONDA DE TROVÃO?",
  ["g3:0817579d"] = "Ah...\\nMas ONDA DE TROVÃO é tão útil...",
  ["g3:081757c1"] = "Para qual POKéMON devo ensinar\\no movimento ONDA DE TROVÃO?",
  ["g3:081757ec"] = "ONDA DE TROVÃO pode paralisar o\\nPOKéMON que for atingido.\\pUm POKéMON paralisado pode não\\nse mover em batalha.\\pÉ um movimento do tipo ELÉTRICO,\\nentao não vai funcionar em alguns\\pPOKéMON.",
  ["g3:08175894"] = "SEDE DA COMPANHIA SILPH\\nP2",
  ["g3:081758ad"] = "Trabalho para a COMPANHIA SILPH.\\nO que devo fazer?",
  ["g3:081758d3"] = "{PLAYER}!\\nVocê e seus POKéMON nos salvaram!",
  ["g3:081758f6"] = "Pare de brincar com a gente,\\jovem!",
  ["g3:08175911"] = "Desisto!",
  ["g3:0817591c"] = "Uma dica? Para abrir as portas\\nuse um CARTÃO-CHAVE!",
  ["g3:08175948"] = "Apoio mais a EQUIPE ROCKET do\\nque a COMPANHIA SILPH!",
  ["g3:0817597d"] = "Você acabou comigo!",
  ["g3:08175990"] = "Humph...\\pA EQUIPE ROCKET disse que me\\ndeixaria estudar os POKéMON,\\pem troca da minha ajuda.",
  ["g3:081759dc"] = "SEDE DA COMPANHIA SILPH\\nP3",
  ["g3:081759f5"] = "Shhh!\\nNão vê que tô me escondendo?",
  ["g3:08175a15"] = "Hã?\\nA EQUIPE ROCKET se foi?",
  ["g3:08175a2f"] = "A EQUIPE ROCKET assumiu o controle\\nda COMPANHIA SILPH!",
  ["g3:08175a5b"] = "Arrgh!",
  ["g3:08175a62"] = "Fuahahaha!\\nMeu CHEFE estava procurando este\\plugar!",
  ["g3:08175a90"] = "Meu POKéMON é meu servo leal.",
  ["g3:08175ab0"] = "Droga!\\nQue POKéMON fraco!",
  ["g3:08175ac8"] = "As portas estão trancadas\\neletronicamente.\\pÉ preciso um CARTÃO-CHAVE\\npara abri-las.",
  ["g3:08175b19"] = "Invasão detectada!",
  ["g3:08175b2b"] = "Quem é você?",
  ["g3:08175b38"] = "É melhor eu avisar ao CHEFE no\\nP11!",
  ["g3:08175b57"] = "SEDE DA COMPANHIA SILPH\\nP4",
  ["g3:08175b70"] = "A EQUIPE ROCKET está em alvoroço\\npor causa de uma invasão.\\pFoi você que invadiu, não é?",
  ["g3:08175bb3"] = "A EQUIPE ROCKET deu no pé!\\nVocê salvou a gente! Obrigado!",
  ["g3:08175be5"] = "Ouvi dizer que um jovem estava\\nvagando por aqui.",
  ["g3:08175c09"] = "Bum!",
  ["g3:08175c0f"] = "Provocar a EQUIPE ROCKET não é\\numa escolha inteligente!",
  ["g3:08175c40"] = "Nós estudamos a tecnologia das\\nPOKé BOLAS neste andar.",
  ["g3:08175c6d"] = "Caramba!\\nQue droga!",
  ["g3:08175c7d"] = "Trabalhamos na criação da POKé BOLA\\ndefinitiva, capaz de capturar tudo.",
  ["g3:08175cbd"] = "O quêêê?\\pNão era pra ter crianças aqui!",
  ["g3:08175ceb"] = "Oh, céus!",
  ["g3:08175cf9"] = "Você ainda está no P5.\\nFalta muito para chegar ao CHEFE!",
  ["g3:08175d28"] = "Mostre um pouco de respeito à\\nEQUIPE ROCKET!",
  ["g3:08175d4b"] = "Cof-cof...\\nCof-cof...",
  ["g3:08175d59"] = "Isso me lembra que...\\pKOFFING evolui para WEEZING!",
  ["g3:08175d89"] = "É um RELATÓRIO POKéMON!\\pPORYGON, o primeiro POKéMON de\\nrealidade virtual, foi criado no\\pLABORATÓRIO POKéMON.",
  ["g3:08175de0"] = "É um RELATÓRIO POKéMON!\\pMais de 350 técnicas POKéMON\\nforam confirmadas.",
  ["g3:08175e28"] = "É um RELATÓRIO POKéMON!\\pFoi confirmado que alguns POKéMON\\nsó evoluem quando são trocados.",
  ["g3:08175e80"] = "SEDE DA COMPANHIA SILPH\\nP5",
  ["g3:08175e99"] = "Bandidos se apoderaram do nosso\\nprédio...\\pO CHEFE deles disse que estava\\nprocurando POKéMON fortes.\\pEspero que nosso PRESIDENTE tenha\\nresolvido a situação...",
  ["g3:08175f24"] = "Os ROCKETS chegaram e assumiram\\no controle do prédio!",
  ["g3:08175f51"] = "Bem, é melhor eu voltar ao\\ntrabalho.",
  ["g3:08175f70"] = "Oh, querida!\\nMe ajude, por favor!",
  ["g3:08175f93"] = "Ficamos noivos.\\nHehehe!",
  ["g3:08175faa"] = "Esse homem do meu lado...\\nÉ tão covarde!",
  ["g3:08175fd3"] = "Ele é tão indefeso, precisava de\\nalguém como eu pra cuidar dele.",
  ["g3:08176012"] = "A EQUIPE ROCKET está tentando\\nconquistar o mundo com os POKéMON.",
  ["g3:0817604b"] = "A EQUIPE ROCKET fugiu, e tudo\\ngraças a você!",
  ["g3:0817607e"] = "Eles devem ter escolhido a SILPH\\npelos nossos produtos POKéMON.",
  ["g3:081760b6"] = "Venha trabalhar para a SILPH\\nquando você envelhecer.",
  ["g3:081760de"] = "Sou um dos quatro IRMÃOS ROCKET!",
  ["g3:08176104"] = "Que surra!",
  ["g3:0817610f"] = "Não importa!\\nMeus irmãos vão me vingar!",
  ["g3:08176136"] = "Não suporto aquele PRESIDENTE\\ndesprezível!\\pEle não deveria ter me enviado\\npara a FILIAL TIKSI!\\pFoi por isso que a EQUIPE ROCKET\\nveio atrás da gente!",
  ["g3:081761bd"] = "Droga!",
  ["g3:081761c4"] = "A FILIAL TIKSI?\\nÉ uma terra russa no meio do nada!",
  ["g3:081761f1"] = "Você ousa trair a EQUIPE ROCKET?",
  ["g3:0817620e"] = "Você é traíra!",
  ["g3:0817621b"] = "Quem defende a justiça,\\ntrai os malfeitores!",
  ["g3:0817624d"] = "SEDE DA COMPANHIA SILPH\\nP6",
  ["g3:08176266"] = "Oi! Você não é da EQUIPE ROCKET!\\nVocê veio salvar a gente?\\pPois muito obrigado!\\pComo agradecimento, quero que\\nfique com este POKéMON.",
  ["g3:081762d7"] = "{PLAYER} obteve um LAPRAS do\\nfuncionário da SILPH!",
  ["g3:08176305"] = "É um LAPRAS.\\nÉ um POKéMON muito inteligente.\\pA gente deixava ele no laboratório,\\nmas ele ficará muito melhor com\\pvocê.\\pTenho certeza que irá treiná-lo\\nmuito bem.\\pEle é um bom nadador, pode até\\nte carregar pela água!",
  ["g3:081763dd"] = "O CHEFE da EQUIPE ROCKET foi para\\na sala de reunioes!\\pNosso PRESIDENTE está bem?\\nEstou preocupado.",
  ["g3:08176444"] = "A EQUIPE ROCKET estava atrás da\\nBOLA MESTRA, que captura qualquer\\pPOKéMON.",
  ["g3:08176486"] = "Cancelamos o projeto da BOLA\\nMESTRA por causa da EQUIPE ROCKET.",
  ["g3:081764c2"] = "Seria terrível se a EQUIPE ROCKET\\nse apoderasse da SILPH ou dos\\pnossos POKéMON.",
  ["g3:08176501"] = "Uau!\\pVocê, sem ajuda de ninguém, colocou a\\nEQUIPE ROCKET pra correr?",
  ["g3:08176532"] = "Ei!\\nAqui é muito perigoso!\\pVocê veio me salvar?\\nMas você não pode!",
  ["g3:08176573"] = "Muito obrigada!",
  ["g3:08176586"] = "Ora ora!\\nSinto cheiro de um ratinho!",
  ["g3:081765a5"] = "As luzes se apagaram!",
  ["g3:081765b1"] = "Você não vai encontrar meu CHEFE se\\nficar só correndo pra lá e pra cá!",
  ["g3:081765e2"] = "Hehehe!\\pVocê me confundiu com um\\nfuncionário da SILPH?",
  ["g3:0817660c"] = "Tô acabado!",
  ["g3:08176616"] = "Apesar da sua idade, você tem habilidade como treinador!",
  ["g3:08176643"] = "Sou um dos quatro IRMÃOS ROCKET!",
  ["g3:08176669"] = "Ai!\\nIrmãos, eu perdi!",
  ["g3:08176681"] = "Não importa.\\nMeus irmãos vão dar o troco!",
  ["g3:081766b3"] = "Uma criança intrusa?\\nSó pode ser você!",
  ["g3:081766d7"] = "Já chega!\\nEu perdi!",
  ["g3:081766e5"] = "Vá pra casa antes que meu CHEFE\\nfique bravo!",
  ["g3:08176710"] = "{RIVAL}: Por que a demora, {PLAYER}?",
  ["g3:08176727"] = "{RIVAL}: Hahaha! Sabia que você ia\\naparecer se eu esperasse aqui!\\pParece que a EQUIPE ROCKET te\\natrasou, né? Mas tudo bem!\\pTe vi em SAFFRON e fiquei curioso\\npra saber se você melhorou!",
  ["g3:081767d0"] = "Ah, cara!\\nAcho que você tem o que precisa pra\\penfrentar o CHEFE ROCKET!",
  ["g3:08176827"] = "Bem, {PLAYER}!\\nContinuo melhorando e progredindo!\\pConsultando minha POKéDEX, posso\\nsaber quais são os POKéMON mais\\pfortes e como eles evoluem!\\pSou um gênio, né?\\pVou para a LIGA POKéMON para\\nderrotar a ELITE DOS QUATRO!\\pVou me tornar o melhor TREINADOR\\ndo mundo!\\pBem, {PLAYER}, boa sorte!\\nNão se esforce muito!\\pFalou!",
  ["g3:08176954"] = "SEDE DA COMPANHIA SILPH\\nP7",
  ["g3:0817696d"] = "Será o fim da SILPH?",
  ["g3:0817698c"] = "Obrigado por nos salvar!",
  ["g3:081769a2"] = "Você não vai passar daqui!",
  ["g3:081769be"] = "Te falta determinação!",
  ["g3:081769cf"] = "Se não der meia volta...\\nVou pedir reforços!",
  ["g3:081769fd"] = "Você tá causando muitos problemas\\npra gente!",
  ["g3:08176a19"] = "Hã?\\nPerdi?",
  ["g3:08176a26"] = "O que você achou do labirinto do\\nEDIFÍCIO SILPH?",
  ["g3:08176a56"] = "Sou um dos quatro IRMÃOS ROCKET!",
  ["g3:08176a7c"] = "Argh!\\nIrmãos!",
  ["g3:08176a90"] = "Meus irmãos vão cuidar de você!",
  ["g3:08176ab2"] = "SEDE DA COMPANHIA SILPH\\nP8",
  ["g3:08176acb"] = "O CHEFE da EQUIPE ROCKET é muito\\ncruel!\\pPara ele, os POKéMON são só\\nferramentas.\\pO que acontecerá se esse tirano\\nse apossar da nossa companhia?",
  ["g3:08176b54"] = "Você parece estar com cansaço.\\nÉ melhor tirar uma soneca.",
  ["g3:08176b81"] = "Não desista!",
  ["g3:08176b90"] = "Muito obrigado.",
  ["g3:08176ba3"] = "Seus POKéMON parecem te adorar,\\njovem!",
  ["g3:08176bc8"] = "Ghaaah!",
  ["g3:08176bd0"] = "Se eu tivesse começado como\\nTREINADOR na sua idade...",
  ["g3:08176bfb"] = "Seus POKéMON têm pontos fracos!\\nEu posso vê-los!",
  ["g3:08176c2b"] = "Você me deu uma surra!",
  ["g3:08176c3c"] = "Aproveite os pontos fracos!\\nPense nas vantagens de cada tipo!",
  ["g3:08176c7a"] = "Sou um dos quatro IRMÃOS ROCKET!",
  ["g3:08176ca0"] = "Argh!\\nIrmãos, eu perdi!",
  ["g3:08176cb8"] = "Meus irmãos vão me vingar!",
  ["g3:08176cd4"] = "SEDE DA COMPANHIA SILPH\\nP9",
  ["g3:08176ced"] = "Boas-vindas ao P10!\\nQue bom que você veio!",
  ["g3:08176d18"] = "Tô atordoado!",
  ["g3:08176d25"] = "Boa tentativa, mas a sala de\\nreunioes fica no andar de cima.",
  ["g3:08176d57"] = "Já chega dos seus joguinhos!",
  ["g3:08176d73"] = "Fim de jogo pra você!",
  ["g3:08176d86"] = "Tá feliz por me derrotar?\\nAgora dá o fora daqui!",
  ["g3:08176dba"] = "Buááá!\\nTô com medo!",
  ["g3:08176dce"] = "Por favor, não fala pra ninguém\\nque eu tava chorando!",
  ["g3:08176df8"] = "SEDE DA COMPANHIA SILPH\\nP10",
  ["g3:08176e12"] = "PRESIDENTE: Oh, meu jovem!\\nMuito obrigado por salvar a SILPH!\\pNunca vou me esquecer que nos\\nsalvou nesse momento tão difícil.\\pPreciso agradecê-lo de alguma\\nforma.\\pComo sou rico, posso te dar\\nqualquer coisa.\\pAqui, talvez goste disto.",
  ["g3:08176ee7"] = "PRESIDENTE: Oh, minha jovem!\\nMuito obrigado por salvar a SILPH!\\pNunca vou me esquecer que nos\\nsalvou nesse momento tão difícil.\\pPreciso agradecê-la de alguma\\nforma.\\pComo sou rico, posso te dar\\nqualquer coisa.\\pAqui, talvez goste disto.",
  ["g3:08176fbd"] = "{PLAYER} obteve uma BOLA MESTRA\\ndo PRESIDENTE!",
  ["g3:08176feb"] = "PRESIDENTE: Você não pode\\ncomprá-la em lugar nenhum.\\pÉ nosso protótipo secreto da\\nBOLA MESTRA.\\pEla capturará qualquer POKéMON\\nsem falhas!\\pNo entanto, use-a com discrição.",
  ["g3:0817708e"] = "Você não tem mais espaço.",
  ["g3:081770a9"] = "SECRETÁRIA: Muito obrigada por\\nsalvar a gente.\\pTodos nós da companhia estamos\\nem dívida com você.",
  ["g3:08177108"] = "Ah, {PLAYER}!\\nA gente se encontrou de novo!\\pO PRESIDENTE e eu estamos\\ndiscutindo algo muito importante.\\pNão se meta nos assuntos dos\\nadultos...\\pOu vai sofrer as consequências!",
  ["g3:081771ab"] = "Arrgh!!!\\nPerdi de novo?!",
  ["g3:081771c2"] = "Maldiçao!\\nVocê arruinou os nossos planos\\ppara a SILPH!\\pMas a EQUIPE ROCKET jamais será\\nderrotada!\\p{PLAYER}! Nunca se esqueça, todos\\nos POKéMON existem para a EQUIPE\\pROCKET!\\pAgora tenho que ir, mas voltarei!",
  ["g3:0817726a"] = "Pare!\\nNão se mexa!",
  ["g3:0817728c"] = "Não...\\nPor favor!",
  ["g3:0817729b"] = "Então você quer ver meu CHEFE?",
  ["g3:081772b8"] = "Alto lá! Você tem hora marcada\\ncom meu CHEFE?",
  ["g3:081772e7"] = "Argh!\\nDerrotado!",
  ["g3:081772f9"] = "É melhor ter cuidado...\\nOs POKéMON do meu CHEFE são\\pmuito fortes!",
  ["g3:0817734a"] = "SEDE DA COMPANHIA SILPH\\nP11",
  ["g3:08177364"] = "Quem é você?\\nNão era para ter ninguém aqui.",
  ["g3:08177391"] = "Ai!",
  ["g3:08177397"] = "Uma chave? Não sei do que você\\nestá falando.",
  ["g3:081773c6"] = "A-a-aaah! Você me assustou!\\nAchei que fosse um fantasma.",
  ["g3:081773fd"] = "Tsc!\\nNão consigo vencer nenhuma.",
  ["g3:08177418"] = "Eu estava explorando aqui sozinho,\\nmas fiquei com medo.\\pAcho melhor ir embora logo.",
  ["g3:08177460"] = "Um botão secreto!\\pApertar?",
  ["g3:0817747b"] = "Quem não apertaria?",
  ["g3:08177489"] = "Ainda não!",
  ["g3:08177498"] = "Não consigo sair!\\nEste lugar velho é um grande\\pquebra-cabeça.",
  ["g3:081774cb"] = "Ah, não!\\nMinha bolsa de saques!",
  ["g3:081774e3"] = "Os botoes daqui abrem e fecham\\nconjuntos alternados de portas.",
  ["g3:0817751f"] = "Diário: 5 de julho\\nGuiana, América do Sul\\pUm novo POKéMON foi descoberto\\nbem no fundo da selva.",
  ["g3:08177574"] = "Diário: 10 de julho\\nBatizamos o POKéMON\\precém-descoberto de MEW.",
  ["g3:081775e7"] = "Este lugar é, tipo, enorme!",
  ["g3:08177602"] = "Ayah!",
  ["g3:08177608"] = "Onde será que meu parceiro foi?",
  ["g3:08177628"] = "Meu mentor já viveu aqui.",
  ["g3:08177643"] = "Ufa!\\nQue sufoco!",
  ["g3:08177657"] = "Então, acabou se prendendo?\\nTente saltar ali!",
  ["g3:08177685"] = "Diário: 6 de fevereiro\\nMEW deu à luz.\\pDemos ao recém-nascido o nome\\nde MEWTWO.",
  ["g3:081776c0"] = "Xii...\\nOnde eu vim parar agora?",
  ["g3:081776d7"] = "Auuuh!",
  ["g3:081776de"] = "Dá pra achar coisas jogadas por aí.\\nOs moradores devem ter deixado elas.",
  ["g3:08177720"] = "Este lugar é ideal para um\\nlaboratório.\\pOlha todo esse espaço.",
  ["g3:08177757"] = "Pra que isso?",
  ["g3:0817776a"] = "Gosto daqui. É um lugar propício\\npara meus estudos.",
  ["g3:08177798"] = "Diário: 1º de setembro\\nMEWTWO é poderoso demais.\\pFalhamos em conter suas\\ntendências violentas...",
  ["g3:081777f2"] = "CASA DE DESCANSO",
  ["g3:081777fd"] = "DICAS PARA TREINADORES\\pAperte START para verificar o\\ntempo restante.",
  ["g3:0817782f"] = "ÁREA CENTRAL",
  ["g3:0817783b"] = "CASA DE DESCANSO",
  ["g3:08177846"] = "DICAS PARA TREINADORES\\pO tempo restante só diminui enquanto\\nvocê estiver andando.",
  ["g3:08177884"] = "ÁREA 1\\nOESTE: ÁREA CENTRAL",
  ["g3:0817789d"] = "CASA DE DESCANSO",
  ["g3:081778a8"] = "DICAS PARA TREINADORES\\pA CASA SECRETA ainda está adiante.",
  ["g3:081778d6"] = "ÁREA 2",
  ["g3:081778dd"] = "DICAS PARA TREINADORES\\pOs POKéMON se escondem na grama\\nalta.\\pCorra em zigue-zague pelas áreas\\nde grama para fazê-los aparecer.",
  ["g3:08177935"] = "DICAS PARA TREINADORES\\pGanhe uma MO ao encontrar a\\nCASA SECRETA.",
  ["g3:0817796e"] = "CASA DE DESCANSO",
  ["g3:08177979"] = "SOLICITAÇÃO\\pPor favor, procure a DENTADURA \\nperdida do DIRETOR do SAFÁRI.\\pDeve estar por aqui em algum\\nlugar.\\pTem recompensa!\\nContato: DIRETOR",
  ["g3:081779f8"] = "DICAS PARA TREINADORES\\pCampanha de exploração da área!\\nA busca pela CASA SECRETA!",
  ["g3:08177a41"] = "ÁREA 3\\nLESTE: ÁREA CENTRAL",
  ["g3:08177a5a"] = "SARA: Pra onde foi meu namorado,\\nERIK?",
  ["g3:08177a82"] = "Tô capturando POKéMON pra levar\\npra casa como presentes.",
  ["g3:08177aae"] = "Quantos você capturou?\\nTô exausto de tanto esforço!",
  ["g3:08177ae2"] = "Consegui capturar uma CHANSEY!\\pO meu esforço valeu a pena.",
  ["g3:08177b16"] = "Oof!\\nTô cansado de tanta diversão!",
  ["g3:08177b38"] = "Você pode ficar com qualquer item\\nque encontrar na ZONA DE SAFÁRI.\\pMas vai acabar o tempo se tentar\\npegar todos de uma vez.",
  ["g3:08177bab"] = "Vá para a parte mais profunda da\\nZONA DE SAFÁRI. Você vai ganhar\\pum prêmio!",
  ["g3:08177bec"] = "Meu EEVEE evoluiu para FLAREON.\\pMas o EEVEE do meu amigo virou\\num VAPOREON. Por que será?",
  ["g3:08177c47"] = "A ZONA DE SAFÁRI é enorme,\\nnão acha?\\pO LÍDER do GINÁSIO de FUCHSIA,\\nKOGA, patrulha a área de vez em\\pquando.\\pGraças a ele, podemos brincar aqui\\nsabendo que estamos seguros.",
  ["g3:08177ceb"] = "Jogar PEDRAS nos POKéMON pode\\nfazê-los fugir, mas eles ficarão\\pmais fáceis de capturar.",
  ["g3:08177d39"] = "Jogar ISCAS fará com que os\\nPOKéMON tenham mais chances\\pde ficar por perto enquanto\\pestiverem ocupados comendo.",
  ["g3:08177d8b"] = "Eu andei bastante, mas não vi\\nnenhum POKéMON que eu quisesse.",
  ["g3:08177dc1"] = "Ah! Finalmente!\\pVocê é a primeira pessoa que\\nchegou na CASA SECRETA!\\pFiz uma campanha para a nossa\\ngrande inauguração, mas já estava\\pcomeçando a ficar preocupado\\pachando que ninguém ganharia\\po prêmio.\\pParabéns!\\nVocê venceu!",
  ["g3:08177e92"] = "{PLAYER} recebeu a MO03\\ndo atendente!",
  ["g3:08177eb7"] = "A MO03 é SURFAR.\\pCom ela, os POKéMON poderão te\\ncarregar pela água.\\pE esta MO não é descartável, então\\nvocê pode usá-la várias vezes.\\pVocê teve muita sorte de ganhar\\neste prêmio incrível!",
  ["g3:08177f72"] = "Você não tem espaço para este\\nprêmio incrível!",
  ["g3:08177f9f"] = "Mew!",
  ["g3:08177fa4"] = "Boas-vindas à LIGA POKéMON!\\pSou LORELEI, da ELITE DOS QUATRO.\\pNinguém é melhor do que eu quando\\nse trata de POKéMON de gelo.\\pOs movimentos de gelo são muito\\npoderosos.\\pSeus POKéMON estarão à mercê\\nquando estiverem congelados!\\pHahaha!\\nVamos começar?",
  ["g3:08178089"] = "Boas-vindas à LIGA POKéMON!\\pEu, LORELEI da ELITE DOS QUATRO,\\nestou de volta!\\pComo já sabe, não tem ninguém\\nmelhor do que eu quando se trata\\pde POKéMON de gelo.\\pOs movimentos de gelo são muito\\npoderosos.\\pSeus POKéMON estarão à mercê\\nquando estiverem congelados!\\pHahaha!\\nVamos começar?\\n",
  ["g3:08178191"] = "... As coisas não deveriam ser assim!",
  ["g3:081781b0"] = "Você é melhor do que eu pensava.\\nContinue em frente.\\pVocê só teve um gostinho do poder\\nda LIGA POKéMON.",
  ["g3:0817820f"] = "Sou BRUNO, da ELITE DOS QUATRO!\\pAtravés de muito treinamento, as\\npessoas e os POKéMON podem se\\ptornar mais fortes.\\pSempre vivi e treinei com meus\\nPOKéMON lutadores!\\p{PLAYER}!\\pVamos acabar com você com nosso\\npoder superior!\\pHahahah!",
  ["g3:0817830c"] = "Sou BRUNO, da ELITE DOS QUATRO!\\pAtravés de muito treinamento, as\\npessoas e os POKéMON podem se\\ptornar mais fortes.\\pSempre vivi e treinei com meus\\nPOKéMON lutadores!\\p{PLAYER}!\\pVamos acabar com você com nosso\\npoder superior!\\pHahahah!",
  ["g3:08178409"] = "O quê?\\nComo pude perder?",
  ["g3:08178420"] = "Fiz minha parte.\\nVá enfrentar seu próximo desafio.",
  ["g3:0817844d"] = "Sou AGATHA, da ELITE DOS QUATRO.\\pOuvi dizer que CARVALHO tem muita\\nadmiraçao por você, criança.\\pAquele velho rabugento já foi\\nforte e bonito.\\pMas isso foi há décadas.\\nEle é só uma sombra do que era.\\pAgora ele só quer saber da sua\\nPOKéDEX.\\pEle está errado.\\nOs POKéMON são para batalhar!\\p{PLAYER}! Vou te mostrar como\\numa verdadeira TREINADORA batalha!",
  ["g3:0817858d"] = "Sou AGATHA, da ELITE DOS QUATRO.\\pVocê é pupilo do CARVALHO,\\nnão é?\\pAquele velho rabugento já foi\\nforte e bonito.\\pMas isso foi há décadas.\\nEle é só uma sombra do que era.\\pAgora ele só quer saber da sua\\nPOKéDEX.\\pEle está errado.\\nOs POKéMON são para batalhar!\\p{PLAYER}! Vou te mostrar como\\numa verdadeira TREINADORA batalha!",
  ["g3:081786d7"] = "Minha nossa!\\nVocê é muito especial, criança!",
  ["g3:08178700"] = "Você venceu!\\pAgora eu entendo o que aquele\\nvelho rabugento vê em você.\\pNão tenho mais nada a dizer.\\nAgora vá em frente, criança!",
  ["g3:08178764"] = "Ah! Eu ouvi falar de você,\\n{PLAYER}!\\pEu lidero a ELITE DOS QUATRO.\\pVocê pode me chamar de LANCE,\\no TREINADOR de dragoes.\\pOs dragoes são POKéMON míticos.\\pEles são difíceis de capturar e\\ntreinar, mas seus poderes são\\psuperiores.\\pEles são praticamente\\nindestrutíveis.\\pBem, você sabe que vai perder,\\nnão é?\\pO seu desafio na LIGA termina\\ncomigo, {PLAYER}!",
  ["g3:081788bd"] = "Ah!\\nEntao você voltou, {PLAYER}!\\pEu lidero a ELITE DOS QUATRO.\\pVocê pode me chamar de LANCE,\\no TREINADOR de dragoes.\\pOs dragoes são POKéMON míticos.\\pEles são difíceis de capturar e\\ntreinar, mas seus poderes são\\psuperiores.\\pEles são praticamente\\nindestrutíveis.\\pBem, você sabe que vai perder,\\nnão é?\\pO seu desafio na LIGA termina\\ncomigo, {PLAYER}!\\n",
  ["g3:08178a15"] = "Já basta!\\pEu odeio admitir, mas você é\\num mestre POKéMON!",
  ["g3:08178a52"] = "Ainda não consigo acreditar que\\nmeus dragoes perderam para você,\\p{PLAYER}.\\pAgora você é o CAMPEÃO da\\nLIGA POKéMON!\\p... Bem, quase, ainda lhe resta um\\núltimo desafio.\\pExiste mais um TREINADOR para\\nenfrentar! Seu nome é...\\p{RIVAL}!\\pEle venceu a ELITE DOS QUATRO\\nantes de você.\\pEle é o verdadeiro CAMPEÃO da\\nLIGA POKéMON.",
  ["g3:08178b6c"] = "{RIVAL}: E aí, {PLAYER}!\\n\\nEu tava ansioso pra te enfrentar.\\n\\nPreciso de um RIVAL como {PLAYER} pra me manter em forma.\\n\\nE você, {PLAYER}, vai ser forte pra isso?",
  ["g3:08178cd4"] = "{RIVAL}: E aí, {PLAYER}!\\n\\nVocê voltou!\\nHaha, isso é ótimo!\\n\\nPreciso de um RIVAL como {PLAYER} pra me manter em forma.\\n\\nE você, {PLAYER}, topa?",
  ["g3:08178e3f"] = "NÃO!\\nNão pode ser!\\pVocê me venceu no meu auge!\\pDepois de todo o trabalho que tive\\npara me tornar CAMPEÃO da LIGA?\\pMeu reinado já acabou?\\nNão é justo!",
  ["g3:08178f2f"] = "Por quê?\\nPor que eu perdi?\\pEu treinei meus POKéMON com\\nperfeiçao!\\pEmbora eu odeie admitir...\\pDroga! Você é o novo CAMPEÃO\\nda LIGA POKéMON!",
  ["g3:08178fc6"] = "CARVALHO: {PLAYER}!",
  ["g3:08178fcf"] = "CARVALHO: Você venceu!\\nOs meus sinceros parabéns!\\pVocê é o novo CAMPEÃO\\nda LIGA POKéMON!\\pVocê cresceu tanto desde que\\npartiu com {STR_VAR_1} para\\ptrabalhar na POKéDEX.\\p{PLAYER}, você já é adulto!",
  ["g3:0817908f"] = "CARVALHO: {RIVAL}...\\nEstou desapontado com você.\\pVim quando soube que tinha\\nderrotado a ELITE DOS QUATRO.\\pMas quando cheguei aqui, você já\\ntinha perdido!\\p{RIVAL}, sabe por que perdeu?\\pVocê esqueceu de tratar os seus\\nPOKéMON com amor e confiança.\\pSem isso, você nunca se tornará\\num CAMPEÃO novamente!",
  ["g3:081791a3"] = "CARVALHO: {PLAYER}.\\pVocê sabe que a sua vitória não\\nfoi só mérito seu.\\pO vínculo que você tem com os\\nseus POKéMON é incrível.\\p{PLAYER}!\\nVenha comigo!",
  ["g3:0817922f"] = "CARVALHO: Ahem!\\nParabéns, {PLAYER}!\\pEste andar é HALL DA FAMA.\\pAqui os CAMPEOES da LIGA POKéMON\\nsão homenageados pelas suas\\pconquistas.\\pOs seus POKéMON também são\\nregistrados no HALL DA FAMA.\\p{PLAYER}!\\pVocê se esforçou muito para se\\ntornar o novo CAMPEÃO da LIGA.\\pParabéns, {PLAYER}, você e os seus\\nPOKéMON agora fazem parte do\\pHALL DA FAMA!",
  ["g3:08179366"] = "Este túnel vai longe, jovem!",
  ["g3:08179388"] = "Droga!\\nVocê venceu!",
  ["g3:08179396"] = "Cuidado com os ONIX. Eles só\\naparecem de vez em quando.\\pOs de nível alto podem apertar\\nvocê pra valer!",
  ["g3:081793f1"] = "Hmm.\\nTalvez eu tenha me perdido aqui...",
  ["g3:0817940e"] = "Calma aí!\\nO que eu estou fazendo?\\pPor onde é a saída?",
  ["g3:0817943a"] = "O POKéMON dormindo na ROTA 12\\nme obrigou a pegar esse desvio.",
  ["g3:0817947b"] = "Forasteiros como você precisam\\nmostrar um pouco de respeito!",
  ["g3:081794ac"] = "Desisto!",
  ["g3:081794b4"] = "Você é hábil o bastante pra\\nencarar uma trilha!",
  ["g3:081794d4"] = "Batalha POKéMON!\\nPreparar, já!",
  ["g3:081794ee"] = "Fim de jogo!",
  ["g3:081794f9"] = "Bom, vou acabar capturando um\\nZUBAT pelo caminho!",
  ["g3:0817951c"] = "Ai!\\pNão tente nenhuma gracinha no\\nescuro!",
  ["g3:08179547"] = "Estava muito escuro...",
  ["g3:08179558"] = "Vi um MACHOP neste túnel.",
  ["g3:08179577"] = "Vim até aqui procurando\\nPOKéMON selvagens.",
  ["g3:081795a1"] = "Estou sem POKéMON!",
  ["g3:081795b5"] = "Parecia ter fofura e que não faria mal a uma mosca.\\nComo eu estava enganada!",
  ["g3:081795e5"] = "Você tem POKéMON!\\nVamos começar!",
  ["g3:08179604"] = "Você joga pesado!",
  ["g3:08179613"] = "Aff!\\nTô toda suada agora.",
  ["g3:0817962d"] = "TÚNEL DA ROCHA\\nCIDADE DE CERULEAN -\\pCIDADE DE LAVENDER",
  ["g3:08179657"] = "Você sabe como evitar se perder\\nnas montanhas?\\pVocê pode dobrar galhos pra\\nmarcar o caminho.",
  ["g3:081796b9"] = "Ahhh!\\nEu dei o meu melhor!",
  ["g3:081796ce"] = "Quero ir pra casa!",
  ["g3:081796e1"] = "Hahaha!\\nVocê consegue vencer o meu poder?",
  ["g3:08179700"] = "Ops!\\nFui superado na força!",
  ["g3:08179712"] = "Eu aposto na força porque odeio\\npensar.",
  ["g3:0817973a"] = "Você tem uma POKéDEX?\\nEu também quero uma!",
  ["g3:0817975f"] = "Droga!\\nEstou morrendo de inveja!",
  ["g3:08179777"] = "Quando você completar sua\\nPOKéDEX, posso ficar com ela?",
  ["g3:081797a4"] = "Hmm... Você sabe o que é cosplay\\nde POKéMON?",
  ["g3:081797cb"] = "Bom, é isso.",
  ["g3:081797de"] = "Cosplay de POKéMON é se vestir\\ncomo POKéMON por diversão.\\pCLEFAIRY é um dos favoritos.",
  ["g3:08179829"] = "Minhas técnicas de POKéMON vão\\nfazer você chorar!",
  ["g3:08179856"] = "Eu desisto!\\nVocê tem técnicas melhores!",
  ["g3:0817987a"] = "Nas montanhas, você costuma\\nencontrar POKéMON do tipo PEDRA.",
  ["g3:081798ad"] = "Não venho muito aqui, mas vou\\nbatalhar com você.",
  ["g3:081798dd"] = "Ah!\\nPerdi!",
  ["g3:081798e9"] = "Gosto de POKéMON pequeninos.\\nOs grandes são muito assustadores!",
  ["g3:08179916"] = "Manda o seu melhor golpe!",
  ["g3:08179932"] = "Mandou ver!",
  ["g3:0817993e"] = "Vou treinar meus POKéMON para\\nderrotar os seus, jovem.",
  ["g3:08179968"] = "Quando estou em casa, faço\\nilustraçoes de POKéMON.",
  ["g3:08179997"] = "Oof...\\nTô exausto...",
  ["g3:081799ac"] = "Sou um artista, não um lutador.\\nVou pra casa desenhar.",
  ["g3:081799e0"] = "Quando você está em uma montanha\\nrochosa como esta, desmoronamentos\\psão uma ameaça.\\pConsegue imaginar?\\nPedras rolando em sua direção?\\pSeria, tipo, waaaaaaaaaaah!\\nTerror total!\\pVocê não parece estar com medo.\\nQuer tentar usar DESMORONAMENTO?\\n",
  ["g3:08179ac0"] = "Ah, então você está com medo.",
  ["g3:08179ae1"] = "Para qual POKéMON devo ensinar\\no movimento DESMORONAMENTO?",
  ["g3:08179b0a"] = "Seria assustador usar isso neste\\ntúnel...",
  ["g3:08179b36"] = "Dica: As pedras podem alterar o\\ncurso da água.",
  ["g3:08179b65"] = "PERIGO\\nCorrenteza rápida!",
  ["g3:08179b7a"] = "A TORRE POKéMON foi erguida em\\nmemória dos POKéMON que morreram.",
  ["g3:08179bb8"] = "Você veio prestar suas homenagens?\\pQue o seu coração amante de\\nPOKéMON seja abençoado, meu\\pjovem.",
  ["g3:08179bfc"] = "Você veio prestar suas homenagens?\\pQue o seu coração amante de\\nPOKéMON seja abençoado, minha\\pjovem.",
  ["g3:08179c41"] = "Vim rezar pela minha querida\\nCLEFAIRY que se foi.\\pSnif!\\nTô inundado em lágrimas...",
  ["g3:08179c8c"] = "Meu GROWLITHE...\\nPor que você morreu?",
  ["g3:08179cab"] = "Sou uma MÉDIUM.\\pTem espíritos aprontando por aqui.\\nSinto a presença deles no alto da\\pTORRE.",
  ["g3:08179cff"] = "{RIVAL}: E aí, {PLAYER}!\\nO que te trouxe aqui?\\pSeus POKéMON morreram?\\pEi! Eles estão vivos!\\pMas pelo menos eu posso fazer\\neles desmaiarem! Vamos lá!",
  ["g3:08179d73"] = "O quê?\\nSua peste!\\pE eu ainda peguei leve com você!",
  ["g3:08179dd4"] = "Como vai sua POKéDEX?\\nAcabei de capturar um CUBONE!\\pNão consigo encontrar um MAROWAK.\\nOnde será que eles estão?\\pAposto que não sobrou nenhum!\\pBom, é melhor eu ir andando.\\nTenho muita coisa pra fazer,\\pdiferente de você.\\pFalou!",
  ["g3:08179eae"] = "Nem a gente consegue identificar\\nos fantasmas errantes.\\pUm VISOR SILPH talvez consiga\\nrevelar quem eles são.",
  ["g3:08179f09"] = "Urrg... Awaa...\\nHuhu... Graa...",
  ["g3:08179f21"] = "Ufa!\\nTô salva!",
  ["g3:08179f31"] = "Os fantasmas podem ser\\nidentificados com o VISOR SILPH.",
  ["g3:08179f62"] = "Kekeke...\\nKwaaah!",
  ["g3:08179f72"] = "Hmm?\\nO que eu estou fazendo?",
  ["g3:08179f88"] = "Desculpa!\\nEu estava possuída!",
  ["g3:08179fa0"] = "Vá embora!\\nEspírito maligno!",
  ["g3:08179fbc"] = "Ufa!\\nO espírito foi embora!",
  ["g3:08179fd3"] = "Os outros lá em cima...\\nEles devem ter sido possuídos.",
  ["g3:0817a004"] = "Fantasma! Não!\\nKwaaah!",
  ["g3:0817a017"] = "Onde está o fantasma?",
  ["g3:0817a02b"] = "Acho que estava sonhando...",
  ["g3:0817a046"] = "Fique com maldição junto de mim!\\nKwaaah!",
  ["g3:0817a061"] = "O quê?!",
  ["g3:0817a067"] = "Não conseguimos determinar a\\nidentidade dos fantasmas...",
  ["g3:0817a096"] = "Huhuhu...\\nNão me derrote!",
  ["g3:0817a0ab"] = "Hã?\\nQuem? O quê?",
  ["g3:0817a0bb"] = "Que os POKéMON que se foram\\ndescansem em paz...",
  ["g3:0817a0e3"] = "Venha, criança!\\nEu purifiquei este lugar.\\pVocê pode descansar aqui.",
  ["g3:0817a11f"] = "Me... dá...\\nsua... alma...",
  ["g3:0817a132"] = "Ah!",
  ["g3:0817a138"] = "Eu estava possuída.",
  ["g3:0817a150"] = "Você... vai...\\nse juntar... a nós...",
  ["g3:0817a164"] = "Que pesadelo!",
  ["g3:0817a176"] = "Eu estava possuída.",
  ["g3:0817a187"] = "Zumbis!",
  ["g3:0817a190"] = "Hã?",
  ["g3:0817a194"] = "Recobrei os sentidos.",
  ["g3:0817a1aa"] = "Urgah...\\nUrff...",
  ["g3:0817a1b7"] = "Uau!",
  ["g3:0817a1bd"] = "Caí nas garras de espíritos malignos,\\napesar do meu treinamento nas\\pmontanhas...",
  ["g3:0817a1fa"] = "Você entrou na área purificada e\\nprotegida.\\pOs POKéMON de {PLAYER} foram\\ntotalmente curados.",
  ["g3:0817a243"] = "Me... dá...\\nsangue...",
  ["g3:0817a253"] = "Grrr!",
  ["g3:0817a25a"] = "Me sinto anêmica e fraca...",
  ["g3:0817a272"] = "Urff...\\nKwaah!",
  ["g3:0817a27f"] = "Alguma coisa caiu!",
  ["g3:0817a293"] = "Meu cabelo não caiu!\\nEra um espírito maligno!",
  ["g3:0817a2c8"] = "Ke... ke... ke...\\nke... ke... ke!",
  ["g3:0817a2dc"] = "Keee!",
  ["g3:0817a2e2"] = "O que está acontecendo aqui?",
  ["g3:0817a2f8"] = "Vão embora...\\nIntrusos...",
  ["g3:0817a30c"] = "O fantasma era o espírito\\ninquieto da mãe do CUBONE!",
  ["g3:0817a342"] = "O espírito da mãe foi acalmado.\\pEle partiu para a vida após a\\nmorte...",
  ["g3:0817a380"] = "O que você quer?\\nPor que está aqui?",
  ["g3:0817a3a4"] = "Desisto!",
  ["g3:0817a3af"] = "Não vou me esquecer disso!",
  ["g3:0817a3cd"] = "Esse velho apareceu de repente\\nno nosso ESCONDERIJO.\\pAí ele começou a reclamar\\ndizendo que a EQUIPE ROCKET\\pmaltrata os POKéMON.\\pEntao estamos só conversando\\nsobre isso como adultos.",
  ["g3:0817a466"] = "Por favor!\\nJá chega!",
  ["g3:0817a477"] = "POKéMON só servem pra ganhar\\ndinheiro. Por que não usá-los?\\pFica fora dos nossos assuntos!",
  ["g3:0817a4cf"] = "Você não vai salvar ninguém,\\njovem!",
  ["g3:0817a4ee"] = "Não lute contra nós, os ROCKETS!",
  ["g3:0817a506"] = "Você não vai sair impune dessa!",
  ["g3:0817a529"] = "SR. FUJI: Ha?\\nVocê veio me salvar?\\pObrigado. Mas eu vim aqui por\\nvontade própria.\\pVim para acalmar o espírito da\\nmae do CUBONE.\\pAcho que o espírito de MAROWAK\\nfinalmente nos deixou.\\pTenho que agradecer pela sua\\npreocupaçao.\\pSiga-me até minha casa, a CASA\\nPOKéMON, que fica ao pé da torre.",
  ["g3:0817a642"] = "Você consegue imaginar? Se este\\nvulcao entrasse em erupção?\\pA explosão seria o nosso fim.\\nAssustador, não é?\\pJá que estamos falando de explosoes,\\nquer que eu te ensine EXPLOSÃO?",
  ["g3:0817a6ed"] = "É, você tem razão.\\nÉ assustador demais.",
  ["g3:0817a717"] = "Você tem muita coragem!\\pPara qual POKéMON devo ensinar\\no movimento EXPLOSÃO?",
  ["g3:0817a756"] = "Usar EXPLOSÃO bem aqui neste\\nvulcao...\\pQue emoção assustadora!",
  ["g3:0817a82a"] = "Por aqui.\\nVamos tentar cavar aqui.\\pO tesouro que os ADMINISTRADORES\\nestavam falando deve estar por aqui.",
  ["g3:0817a88c"] = "Mas o quê...?\\nVocê está no caminho. Cai fora.",
  ["g3:0817a8b4"] = "Ufa, finalmente abrimos caminho.\\nVamos caçar o tesouro!",
  ["g3:0817a8ee"] = "A gente vai levar os tesouros que\\nencontrar pro ARMAZÉM, entendeu?\\p... Ah, e quais são as senhas mesmo?\\nAs senhas do ARMAZÉM ROCKET.",
  ["g3:0817a970"] = "Que foi, esqueceu a senha?\\nSão duas, na verdade.\\pA primeira é “GOLDEEN need\\nlog.”\\pE a segunda é...",
  ["g3:0817a9e1"] = "Ei!\\nTem alguém xeretando a gente!",
  ["g3:0817aa06"] = "Você tava espionando a gente, né?",
  ["g3:0817aa34"] = "Hã, o quê?",
  ["g3:0817aa3f"] = "Por que você tinha que vencer?",
  ["g3:0817aa56"] = "Tá tentando botar as mãos no nosso\\ntesouro? Pode esquecer!",
  ["g3:0817aa8a"] = "Espera!\\nMas como?",
  ["g3:0817aa99"] = "Faz de conta que teve uma amnésia\\ne esqueça tudo o que você ouviu!",
  ["g3:0817aad7"] = "Que baita contratempo...\\nVamos ter que nos reorganizar.\\pVocê aí! Nem pense em dar um\\npasso aqui dentro!\\pSe sabe o que é bom pra você,\\né melhor esquecer tudo isso!",
  ["g3:0817ab73"] = "Um vulcão ativo é aquele que está\\nem erupção, ou prestes a entrar\\pem uma.",
  ["g3:0817abaa"] = "Oof... Isso foi quente! O suor tá\\njorrando de mim como uma erupção!",
  ["g3:0817abd8"] = "Dizem que existem mais de 1.500\\nvulcoes ativos no mundo.\\pSó de pensar nisso, já me sinto todo\\nquente e derretendo por dentro!",
  ["g3:0817ac55"] = "Você sabe como as cavernas se\\nformam dentro dos vulcoes?",
  ["g3:0817ac82"] = "Atchah!\\nVocê é assustadoramente hábil!",
  ["g3:0817aca2"] = "Quando a lava na superfície do\\nmagma endurece, e o magma no\\pinterior escorre para fora,\\pcavernas são formadas.",
  ["g3:0817ad06"] = "Tenho treinado pra curar meu\\ncoraçao partido...\\pPelo menos isso me deixou mais\\nforte fisicamente! Hi-yah!",
  ["g3:0817ad6b"] = "Acho que acabei exagerando...",
  ["g3:0817ad89"] = "O jeito que você batalha me lembra\\no cara que terminou comigo...",
  ["g3:0817adc5"] = "{PLAYER} encontrou um RUBI!",
  ["g3:0817add6"] = "PERDITA: Snif... Snif...\\nAh! Por favor, me ajuda!\\pUm POKéMON assustador apareceu\\nali faz um tempinho.\\pEle não parava de assustar.\\nDeixou a PERDITA com medo.\\pTô com medo demais pra me mexer!\\nMas eu quero ir pra casa...",
  ["g3:0817ae8e"] = "Ah! Lá vem ele de novo!\\nNão! Vai embora! Tô com medo!\\pBuáááááá!\\nEu quero o meu papai!",
  ["g3:0817aee1"] = "Ohh! Isso foi tão assustador!\\nObrigada!\\pPERDITA veio pegar algumas\\nFRUTAS.\\pVocê pode ficar com isso!",
  ["g3:0817af3b"] = "Qual é o seu nome?\\pPERDITA tá assustada, posso ir com\\nvocê até a casa do meu papai?\\pTá bom!\\nVamos pra casa!",
  ["g3:0817af9f"] = "Seu SACO DE FRUTAS está cheio.\\nAcho que você não quer isso.",
  ["g3:0817afd6"] = "Boas-vindas à FLORESTA DE FRUTAS\\pSeja gentil e compartilhe FRUTAS\\ncom outras pessoas e POKéMON.",
  ["g3:0817b029"] = "Cuidado com os POKéMON selvagens\\nque adoram FRUTAS!",
  ["g3:0817b04f"] = "LORELEI: Tirem suas mãos sujas\\ndos POKéMON da caverna!\\pFaçam o que eu digo, ou vão ter\\nque se ver comigo!",
  ["g3:0817b0b9"] = "Ah, cala a boca, senhora, e deixa\\na gente em paz.\\pNão deixa seus óculos embaçarem!",
  ["g3:0817b109"] = "LORELEI: {PLAYER}?!\\nO que você está fazendo aqui?\\pNão, podemos conversar depois.\\nAgora, eu preciso da sua ajuda.\\pMe ajuda a expulsar esses caçadores\\nantes que façam mais alguma coisa.\\pEles têm capturado POKéMON aqui\\ne depois vendido!\\pPreparou-se?\\nVocê pega aquele ali, por favor!",
  ["g3:0817b20b"] = "Q-quê?!\\pQuem disse que não podemos fazer\\no que quisermos com os POKéMON\\pque capturamos?",
  ["g3:0817b251"] = "A gente não planejou isso!",
  ["g3:0817b269"] = "LORELEI: Hmph.\\nTao fracos e desprezíveis.\\pVocê!\\nDiga-me!\\pPara onde vocês levaram os\\nPOKéMON capturados?\\pVou acabar com você de uma\\nvez por todas!",
  ["g3:0817b2ef"] = "N-nem pensar!\\nNão vou te contar nada!",
  ["g3:0817b313"] = "LORELEI: Se você não confessar,\\nvamos congelar vocês.\\pMeu LAPRAS está furioso pelo que\\nvocês fizeram aos amigos dele.\\pVai, LAPRAS!\\nRAIO CONGELANTE...",
  ["g3:0817b399"] = "Uaaaah! Tá bom!\\nEu vou falar!\\pOs POKéMON estão no ARMAZÉM\\nROCKET na ILHA CINCO.\\pPronto! Falei!\\nAgora vamos embora!\\p... Mas duvido que você consiga\\nentrar no ARMAZÉM ROCKET!\\pHeheheheh!",
  ["g3:0817b457"] = "{PLAYER}, obrigada.\\nMas isso é horrível...\\pNasci e cresci aqui nessas ilhas.\\pNão fazia ideia de que aqueles\\ncriminosos terríveis estavam\\psoltos por aqui...",
  ["g3:0817b4e3"] = "Tem muitos POKéMON trancados na\\njaula...",
  ["g3:0817b512"] = "A porta da jaula está destrancada.\\nOs POKéMON parecem ter fugido.",
  ["g3:0817b54d"] = "Você veio aqui sabendo que este\\né o ARMAZÉM da EQUIPE ROCKET?",
  ["g3:0817b585"] = "O que você pensa que está\\nfazendo?!",
  ["g3:0817b5a6"] = "A EQUIPE ROCKET se desfez?\\nDe que planeta você veio?",
  ["g3:0817b5d6"] = "Ah, seus POKéMON parecem fortes.\\nTá a fim de vender?\\pAh?\\nVocê queria batalhar?",
  ["g3:0817b62f"] = "Ah, mas...\\nÉ demais!",
  ["g3:0817b642"] = "Vamos pagar um ótimo preço.\\nVenda seus POKéMON para nós!",
  ["g3:0817b677"] = "Fiquei sabendo de você pelos\\noutros.\\pMas não tem como uma criança como\\nvocê conhecer o nosso CHEFE\\pGIOVANNI!",
  ["g3:0817b6d9"] = "Não...se...atreva...a...rir...",
  ["g3:0817b6ef"] = "Não se meta nos assuntos dos\\nadultos, sua criança metida!",
  ["g3:0817b72d"] = "Não sei, nem me importo, se o que\\nestou fazendo é certo ou errado...\\pSó coloco minha fé em GIOVANNI\\ne faço o que me mandam.",
  ["g3:0817b79c"] = "Não...\\nNão acredito nisso...",
  ["g3:0817b7ae"] = "Você age de acordo com suas\\ncrenças e princípios.\\pAgora eu entendo...",
  ["g3:0817b7fa"] = "Deixei tudo pronto pra que você\\npossa voltar por ali.\\pPor que não vai descansar e se\\npreparar pro que está por vir?\\pO ADMINISTRADOR depois de mim é\\nTREINADOR muito mais experiente.\\pÉ melhor se preparar bem,\\no desafio vai ser duro.",
  ["g3:0817b8da"] = "Já chega de pagar de heroísmo,\\njovem.\\pEspalhando mentiras sobre a\\nEQUIPE ROCKET ter se desfeito...\\pÉ uma tentativa bem óbvia de\\ncausar confusão entre nós.\\pFelizmente, não somos ingênuos a\\nponto de cair nas mentiras de uma\\pcriança!\\pAgora vou te mostrar como um\\nadulto irritado pode ser assustador!",
  ["g3:0817b9fb"] = "Urgh...\\nVocê é forte demais...\\p...\\nI-isso é a INSÍGNIA do GIOVANNI!\\pEntao é verdade?\\nA EQUIPE ROCKET se desfez mesmo?",
  ["g3:0817ba64"] = "Vamos abandonar este ARMAZÉM...\\pMas não pense que isso acabou.\\nNão vou permitir que seja o fim.\\pVou encontrar o GIOVANNI.\\nE vou ressuscitar a EQUIPE ROCKET!\\pEu vou...\\pAté lá, adeus!",
  ["g3:0817bb15"] = "Um relatório com gráficos e textos\\nestá no monitor do PC.\\p“A Influência de Ondas Magnéticas\\nna evolução dos POKéMON”...\\p... ... ... ... ... ...\\pÉ difícil demais de entender...",
  ["g3:0817bbaf"] = "Eu quase consegui vender a\\nSAFIRA por uma grana preta...\\pAí você teve que aparecer e\\narruinar todo o negócio!\\pFufu... Fufufufu...\\nNão vou te perdoar por isso!",
  ["g3:0817bc55"] = "Argh! Droga!\\nDroga! Droga!",
  ["g3:0817bc6c"] = "Se eu não posso vender, então não\\nvale nada! Pode pegar!",
  ["g3:0817bca3"] = "O que você quer agora?\\nSuma daqui e me deixa em paz.",
  ["g3:0817bcd7"] = "O quê, você de novo?\\pVocê... Você não é filho do\\nGIOVANNI, é?\\pNão, não pode ser!\\nO filho do GIOVANNI tem cabelo\\pvermelho.\\pVocê não tem motivo nenhum pra\\nme encher. Me deixa em paz!",
  ["g3:0817bd82"] = "{PLAYER} encontrou uma SAFIRA!",
  ["g3:0817bd97"] = "Fufu... Fufufufu...\\nAcertei em cheio.\\pEu estava certo em te seguir!",
  ["g3:0817bdd4"] = "Sabia que tinha uma SAFIRA\\naqui, então ela é minha!\\pVou vender pra EQUIPE ROCKET e\\nfaturar uma grana.\\p...N-não me encara desse jeito!\\pSe quiser de volta, por que não\\nvai pegar depois que eu vender?\\pVou até te contar uma das\\nsenhas do ARMAZÉM\\pda EQUIPE ROCKET.\\pA senha do ARMAZÉM que eu conheço é\\n“Bom, err, CHANSEY.”\\pTerminei aqui.\\nPor favor não me leve a mal!",
  ["g3:0817bf3a"] = "Tô curiosa, como você cria seus\\nPOKéMON?",
  ["g3:0817bf66"] = "Você cria seus POKéMON com muito\\namor!",
  ["g3:0817bf97"] = "Assim como sua mãe criou você com\\nmuito amor, você também deve criar\\pseus POKéMON.",
  ["g3:0817bfeb"] = "Estou trabalhando para preservar a\\necologia natural dos POKéMON daqui.",
  ["g3:0817c028"] = "Ah, para alguém tão jovem,\\nvocê é incrível!",
  ["g3:0817c056"] = "Não estou dizendo que você não\\ndeve capturar POKéMON.\\pSó quero que as pessoas criem seus\\nPOKéMON com responsabilidade.",
  ["g3:0817c0be"] = "Capturei um POKéMON INSETO\\nque só vive aqui!",
  ["g3:0817c0f2"] = "Heheh...\\nMeu POKéMON não é incrível?",
  ["g3:0817c113"] = "Tem uma garota perto do BOSQUE que\\nmede os HERACROSS dos TREINADORES.",
  ["g3:0817c155"] = "Sabe, só não parece certo se eu\\nnão usar POKéMON INSETO.",
  ["g3:0817c196"] = "Ah, tudo bem, perder também faz\\nparte da graça dos POKéMON!",
  ["g3:0817c1d0"] = "Falando nisso, “apelo” é uma palavra estranha, se parar pra pensar.\\pTipo, é que nem escalpelo?\\nOu é que nem atropelo?",
  ["g3:0817c246"] = "Sim, sim, sim!\\nOlha só todos esses POKéMON INSETO!",
  ["g3:0817c275"] = "Perdi enquanto ainda estava ocupado\\ncomemorando!",
  ["g3:0817c2a4"] = "Da próxima vez, vou trazer meu\\nirmãozinho aqui.",
  ["g3:0817c2d9"] = "Olha, olha!\\nTem marcas engraçadas no chão.",
  ["g3:0817c30d"] = "Superincrível!",
  ["g3:0817c31c"] = "As marcas engraçadas no chão...\\pElas se parecem com os remendos\\ndas roupas do meu avô.",
  ["g3:0817c373"] = "Aposto que você acha que eu sou\\nsó um cara qualquer, não é?",
  ["g3:0817c3a5"] = "Aposto que você acha que eu sou\\nfraco, não é?",
  ["g3:0817c3ce"] = "Pois é... vocês da cidade aparecem\\ntodos arrumadinhos, com chapéus\\pchamativos...\\pQue tal me dar esse aí?",
  ["g3:0817c42b"] = "Respira fundo.\\nNão é delicioso esse ar?",
  ["g3:0817c458"] = "Se quiser, posso te ensinar a\\nrespirar corretamente.",
  ["g3:0817c490"] = "Primeiro, expire.\\nSolte todo o ar.\\pQuando não conseguir mais soltar,\\ninspire o ar puro!\\pNão é revigorante?",
  ["g3:0817c4fe"] = "Eu amo os POKéMON INSETO.\\nÉ por isso que estou sempre aqui.\\pSerá que sou a única garota assim?",
  ["g3:0817c552"] = "Perdi, mas continuo rindo.\\nSerá que sou a única garota assim?",
  ["g3:0817c590"] = "Vou continuar capturando os\\nPOKéMON INSETO.\\pSerá que sou a única garota assim?",
  ["g3:0817c5db"] = "Aqui é um bom lugar.\\nVou montar minha barraca aqui.",
  ["g3:0817c609"] = "Perdi...",
  ["g3:0817c615"] = "Vou observar o céu noturno aqui.",
  ["g3:0817c63e"] = "Ah, que nojo!\\nAcho que um inseto me picou!",
  ["g3:0817c660"] = "Não foi um inseto.\\nCortei a canela na grama.",
  ["g3:0817c68e"] = "Um cortezinho desses...\\nUm pouquinho de saliva já cura!",
  ["g3:0817c6c9"] = "Você notou alguma coisa estranha\\npor estas bandas?",
  ["g3:0817c6fb"] = "Você já deu uma boa olhada ao\\nredor dos seus pés?",
  ["g3:0817c728"] = "Tem lugares aqui no BOSQUE MARCADO\\nonde a grama não cresce.\\pO que poderia causar um fenômeno\\nassim?",
  ["g3:0817c794"] = "Olá!\\pBoas-vindas à TORRE DOS TREINADORES,\\nonde TREINADORES de todos os\\plugares se reúnem!",
  ["g3:0817c7d9"] = "TREINADORES do mundo inteiro\\nse reúnem aqui para batalhar.\\pDeixa eu ver...\\pNo momento, tem TREINADORES só\\naté o Andar {STR_VAR_1}.",
  ["g3:0817c850"] = "Os TREINADORES estão aguardando\\nseu desafio até o oitavo andar.",
  ["g3:0817c88d"] = "Você gostaria de desafiar os\\nTREINADORES que estão esperando?",
  ["g3:0817c8bf"] = "Certo, vou iniciar o cronômetro,\\nentao dê tudo de si.\\pEm suas marcas...\\pPreparar...\\pJá!",
  ["g3:0817c91d"] = "Por favor, volte para nos visitar!",
  ["g3:0817c937"] = "Que pena.\\pAcho que você se esforçou bastante\\nnas batalhas.\\pPor favor, volte e tente novamente!",
  ["g3:0817c9a2"] = "Espero que você dê o seu melhor.",
  ["g3:0817c9c0"] = "Quando os TREINADORES trocam\\nde lugar, o movimento pode ficar\\pcaótico.\\pPara evitar confusão, movemos\\no balcão de recepção para cá.\\pDesculpe pelo transtorno.",
  ["g3:0817ca5a"] = "Olá...\\pSou o dono desta TORRE...\\pComo o céu se estende acima\\ndeste terraço...\\pO toque do vento aqui em cima...\\pTudo é tão perfeito...\\pA forma como você batalhou...\\nTambém foi perfeição...",
  ["g3:0817cb09"] = "Isto é para você...",
  ["g3:0817cb1a"] = "Ah!\\nExtraordinário!\\pÉ maravilhoso como você conseguiu\\nchegar aqui tão rápido.\\pA verdade é que você fez isso\\nem tempo recorde...\\pVou mandar colocar seu recorde\\nno balcão de recepção.",
  ["g3:0817cbc0"] = "Parece que você demorou bastante\\npara chegar até aqui...",
  ["g3:0817cbf5"] = "O que eu gostaria de ver é um\\ntempo melhor da sua parte...\\pEstou contando com você.\\pAté lá, adeus...",
  ["g3:0817cc56"] = "{STR_VAR_1} min. {STR_VAR_2}.{STR_VAR_3} seg.",
  ["g3:0817cc73"] = "Esta é uma batalha dois contra\\ndois.\\pVocê não pode batalhar a menos\\nque tenha pelo menos dois POKéMON.",
  ["g3:0817ccc9"] = "Aqui na TORRE DOS TREINADORES, tem\\num evento chamado CONTRARRELÓGIO.\\pSeu tempo será medido para ver\\nquao rápido você consegue ir do\\pbalcao de recepção até o DONO\\pno terraço.\\pOs melhores tempos serão registrados\\nno Quadro de Tempos.\\pTente competir com seus amigos\\npara ver quem consegue completar\\pmais rápido.\\pVocê não ganhará Pontos de EXP.\\nnem dinheiro ao derrotar os\\pTREINADORES daqui.",
  ["g3:0817ce1f"] = "Obrigado por participar!",
  ["g3:0817ce38"] = "Estou aqui para ver o quão\\nboa eu sou.\\pQue tipo de TREINADORES será que\\nestao me esperando?\\pDá até um frio na barriga!",
  ["g3:0817ce9f"] = "Oof, Oof...\\nOof...\\pEsquece batalha! Essas escadas...\\nSão mais difíceis do que qualquer\\pluta...",
  ["g3:0817cef5"] = "Aaaaaah!\\pAchei que isso fosse uma ruína\\nantiga, mas está cheia de fantasmas!",
  ["g3:0817cf42"] = "Aaaaaah!\\nPiedade!",
  ["g3:0817cf54"] = "Tô tentando sair daqui, mas sempre\\nacabo no mesmo lugar.\\pTalvez a quantidade de rochas\\nseja uma pista...",
  ["g3:0817cfc1"] = "Acho que existe algum tipo de poder\\nmisterioso agindo nesta caverna.",
  ["g3:0817cffb"] = "Se você não entrar no túnel certo,\\nnão vai conseguir avançar.",
  ["g3:0817d037"] = "Mais cedo, uma mulher entrou nas\\ncavernas lá na frente.",
  ["g3:0817d062"] = "O-o que você pretende fazer\\ncomigo?",
  ["g3:0817d086"] = "Ah... Eu pensei que você quisesse\\nme machucar.",
  ["g3:0817d0b2"] = "Que bom que você apareceu por\\naqui.\\pEu já estava ficando entediada\\nde andar e me sentindo cansada.\\pSerá que você pode me levar de\\nvolta pra casa?",
  ["g3:0817d13b"] = "E aí!\\nComo vão as coisas?\\pO que eu estou fazendo aqui, você\\npergunta? Ora, tô garimpando ouro!\\pQuando eu ficar rico, vou comprar\\numa casa em KANTO.",
  ["g3:0817d1c9"] = "E aí! Como vão as coisas?\\nFicou sabendo? Eu encontrei ouro!\\pVocê se lembra que eu estava\\ngarimpando, não é?\\pVocê nem imagina o quanto eu tô\\nfeliz.\\pEntao, vou te mostrar!\\nIsso é pra você!",
  ["g3:0817d28c"] = "É uma PEPITA!\\pJá que não posso te dar uma\\nPITADA de sabedoria, fica com a\\pPEPITA mesmo!",
  ["g3:0817d2dc"] = "Opa, sua MOCHILA tá lotada!\\nVou te entregar isso depois.",
  ["g3:0817d31b"] = "Um estrondo misterioso ecoou em\\nalgum lugar distante.",
  ["g3:0817d34a"] = "Hm!\\nHaaaaaaaaaaah!\\pAaaah! Isso é divino! A água me\\naquece até o fundo da alma!\\pVocê devia entrar também.\\pVai pro meio, relaxa e aproveita\\nesse calor!",
  ["g3:0817d3de"] = "Minha parte favorita do banho\\nvem logo em seguida.\\pAdoro tomar uma tigela de ensopado\\npra me aquecer por dentro também!",
  ["g3:0817d450"] = "A água está na temperatura perfeita.\\nA sensação é maravilhosa...\\p{PLAYER} e seus POKéMON ficaram\\ntotalmente revigorados!",
  ["g3:0817d4aa"] = "Dizem que mergulhar numa fonte\\ntermal é terapêutico.",
  ["g3:0817d4e3"] = "Olha pro meu rosto.\\nVê como minha pele tá macia?\\pA água da fonte termal mantém minha\\npele mais jovem que minha idade.",
  ["g3:0817d550"] = "Depois de um dia de treino puxado,\\nnada é melhor do que um mergulho\\prelaxante na fonte termal.\\pBRUNO, que é mais experiente do\\nque eu, visita o SPA às vezes.\\pEle vem para tratar lesoes, tanto\\nas dele quanto as dos POKéMON.",
  ["g3:0817d622"] = "As fontes termais andam de mãos\\ndadas com vulcoes.\\pO SPA BRASA daqui... bom, fui eu\\nque construí há anos.\\pEscavei a piscina à mão direto\\nde um pedregulho gigante.\\pEu usava isto na época.\\nAcho que não vou precisar mais.",
  ["g3:0817d6f3"] = "Isso despedaça pedras como se\\nnão fossem nada.",
  ["g3:0817d72c"] = "CARVALHO: Ei! Espere!\\nNão saia!",
  ["g3:0817d74a"] = "CARVALHO: É perigoso!\\nOs POKéMON selvagens vivem na\\pgrama alta!\\pVocê precisa de seu próprio\\nPOKéMON para a sua proteção.\\pJá sei!\\nVenha comigo!",
  ["g3:0817d7c8"] = "Também estou criando POKéMON.\\pQuando eles ficarem fortes,\\npoderao me proteger.",
  ["g3:0817d80d"] = "A tecnologia é incrível!\\pAgora você pode armazenar e acessar\\nitens e POKéMON como dados pelo PC.",
  ["g3:0817d866"] = "LABORATÓRIO DE PESQUISA POKéMON\\nDO PROFESSOR CARVALHO",
  ["g3:0817d87f"] = "Casa de {PLAYER}",
  ["g3:0817d88a"] = "Casa de {RIVAL}",
  ["g3:0817d895"] = "CIDADE DE PALLET\\nOs tons de sua jornada aguardam!",
  ["g3:0817d8bf"] = "CARVALHO: Ah, {PLAYER}!\\nVocê está de volta!\\pQuantos POKéMON você já registrou\\nna sua POKéDEX?\\pPosso dar uma olhada?\\pVejamos...",
  ["g3:0817d925"] = "Você registrou {STR_VAR_2}...\\pHmm, parece que você está mesmo\\nse esforçando.\\pQuando registrar mais alguns,\\nvenha me mostrar, por favor.",
  ["g3:0817d9aa"] = "Você registrou... {STR_VAR_2}?!\\nIsso é impressionante!\\pHá algo que eu gostaria de lhe\\npedir, {PLAYER}.\\pVenha.\\nSiga-me.",
  ["g3:0817da16"] = "CARVALHO: Ah, {PLAYER}!\\nVocê parece estar gostando de\\n\\nviajar.\\n\\nConhecendo você, {PLAYER}, posso imaginar você indo para os lugares mais exóticos.",
  ["g3:0817dabb"] = "Essas POKé BOLAS na usa cintura...\\nVocê tem POKéMON, né?\\pÉ ótimo poder carregar e usar\\nPOKéMON a qualquer hora, em\\pqualquer lugar.",
  ["g3:0817db39"] = "Este GINÁSIO POKéMON está sempre\\nfechado.\\pQuem será seu LÍDER?",
  ["g3:0817db78"] = "O LÍDER do GINÁSIO de VIRIDIAN\\nvoltou!",
  ["g3:0817db98"] = "Você quer saber sobre os tipos de\\nPOKéMON lagarta?",
  ["g3:0817dbd5"] = "Ah, tudo bem!",
  ["g3:0817dbe4"] = "CATERPIE não tem veneno;\\nmas WEEDLE tem.\\pCuidado com seu FERRÃO VENENOSO.",
  ["g3:0817dc4e"] = "Ah, vovô!\\nNão seja assim!\\pSinto muito.\\nEle ainda não tomou seu café.",
  ["g3:0817dc99"] = "De vez em quando, faço compras\\nna CIDADE DE PEWTER.\\pQuando vou, tenho que passar pela\\nsinuosa FLORESTA DE VIRIDIAN.",
  ["g3:0817dd03"] = "De jeito nenhum vou permitir que\\nvocê passe por aqui!\\pÉ uma propriedade privada!",
  ["g3:0817dd4e"] = "Agora que tomei meu cafezinho,\\ntô pronto pra começar o dia!\\pHm?\\nO que é essa caixinha vermelha\\pque você tem?\\pAh, você tá trabalhando na sua\\nPOKéDEX.\\pEntao, deixa eu dar um conselho.\\pSempre que captura um POKéMON, a\\nPOKéDEX atualiza automaticamente\\pseus dados.\\p... Você não sabe como capturar um\\nPOKéMON?\\pAcho melhor eu te mostrar como\\nse faz!",
  ["g3:0817de9b"] = "Pronto! Agora me diz, isso foi\\neducativo ou não?\\pPode ficar com isso também.",
  ["g3:0817deeb"] = "Se você não entender algo,\\nassista a isso.\\pVai te ensinar o básico de como\\nvirar TREINADOR POKéMON.",
  ["g3:0817df61"] = "Agora que tomei meu cafezinho,\\ntô pronto pra começar o dia!\\pMas estava muito forte e me deu\\ndor de cabeça...\\pA propósito, você está completando\\nsua POKéDEX?\\pNão se esqueça de enfraquecer o\\nPOKéMON antes de tentar capturá-lo.",
  ["g3:0817e046"] = "Agora que tomei meu cafezinho,\\ntô pronto pra começar o dia!\\pMas estava muito forte e me deu\\ndor de cabeça...\\pA propósito, minha velha POKéTV\\ntá te ajudando?",
  ["g3:0817e0ea"] = "Wahaha!\\nÉ meu neto no programa!\\pJá que ele é quem está ensinando,\\nvocê com certeza vai aprender.",
  ["g3:0817e14e"] = "Hm... Você tá tanto assim nos corres que\\nnem tem tempo pra POKéTV...\\pTempo é dinheiro, e nenhum dos\\ndois deve ser desperdiçado...",
  ["g3:0817e1bb"] = "CIDADE DE VIRIDIAN\\nO eterno paraíso verde",
  ["g3:0817e1e7"] = "DICAS PARA TREINADORES\\pCapture os POKéMON e aumente sua\\ncoleçao.\\pQuanto mais tiver, mais fácil serão\\nas batalhas.",
  ["g3:0817e24d"] = "DICAS PARA TREINADORES\\pOs movimentos de um POKéMON\\nsão limitados pelos seus PONTOS\\pde PODER, ou PP.\\pPara restaurar os PP, deixe seus\\nPOKéMON descansarem em um\\pCENTRO POKéMON.",
  ["g3:0817e2db"] = "GINÁSIO POKéMON de VIRIDIAN",
  ["g3:0817e2f5"] = "As portas do GINÁSIO estão\\ntrancadas...",
  ["g3:0817e316"] = "Uááá!\\nDevo ter cochilado ao sol.\\pTive um sonho estranho com um\\nDROWZEE comendo meu sonho.\\pE...\\nAprendi a devorar sonhos...\\pUgh, isso é muito assustador!\\pDeixa eu ensinar para um\\nPOKéMON, assim poderei esquecer!",
  ["g3:0817e3e9"] = "... Ronc...",
  ["g3:0817e3f1"] = "Para qual POKéMON devo ensinar\\no movimento DEVORA-SONHOS?",
  ["g3:0817e41b"] = "... ZZZ...\\nNão consigo... comer... mais...",
  ["g3:0817e436"] = "Dizem que os CLEFAIRY vieram\\nda lua.\\pEles apareceram depois que PEDRAS\\nDA LUA caíram no MONTE LUA.",
  ["g3:0817e49f"] = "Não tem muitos TREINADORES\\nPOKéMON sérios por aqui.\\pA maioria são como os CAÇA-INSETOS,\\nsabe, só amadores.\\pMas o BROCK do GINÁSIO de PEWTER\\né exceção.",
  ["g3:0817e53e"] = "Você deu uma olhada no MUSEU?",
  ["g3:0817e55c"] = "Aqueles fósseis do MONTE LUA\\nnão são incríveis?",
  ["g3:0817e589"] = "É mesmo?\\nPois você precisa ir!",
  ["g3:0817e5ac"] = "Este é o MUSEU.\\pÉ preciso pagar pra entrar,\\nmas vale a pena. Até mais!",
  ["g3:0817e602"] = "Psssst!\\nSabe o que eu tô fazendo?",
  ["g3:0817e626"] = "Isso aí!\\nÉ um trabalho duro!",
  ["g3:0817e644"] = "Tô jogando REPELENTE no meu\\njardim pra afastar os POKéMON\\pselvagens!",
  ["g3:0817e67e"] = "Você é TREINADOR, né?\\pBROCK está procurando novos\\ndesafiantes. Siga-me!",
  ["g3:0817e6c7"] = "Se confia nas suas habilidades,\\nvá desafiar o BROCK!",
  ["g3:0817e6f6"] = "DICAS PARA TREINADORES\\pTodos os POKéMON que entrarem\\nem batalha, mesmo que brevemente,\\pganharão Pontos de EXP.",
  ["g3:0817e748"] = "ATENÇÃO!\\pLadrões têm roubado fósseis de\\nPOKéMON do MONTE LUA.\\pPor favor, entre em contato com a\\nPOLÍCIA de PEWTER se tiver alguma\\pinformação.",
  ["g3:0817e7c5"] = "MUSEU DE CIÊNCIAS DE PEWTER",
  ["g3:0817e7de"] = "GINÁSIO POKéMON de PEWTER\\nLÍDER: BROCK\\pO TREINADOR de POKéMON inabaláveis!",
  ["g3:0817e824"] = "CIDADE DE PEWTER\\nUma cidade de tom acinzentado",
  ["g3:0817e902"] = "Ah, {PLAYER}{05}!",
  ["g3:0817e90c"] = "Que bom que te alcancei.\\nSou um ASSISTENTE do PROFESSOR\\pCARVALHO.\\pMe pediram para lhe entregar isto,\\naqui está.",
  ["g3:0817e970"] = "{PLAYER} recebeu os TÊNIS\\nDE CORRIDA do ASSISTENTE.",
  ["g3:0817e99d"] = "{PLAYER} calçou os\\nTÊNIS DE CORRIDA.",
  ["g3:0817e9c7"] = "Aperte o Botão B para correr.\\nMas só onde houver espaço!",
  ["g3:0817ea06"] = "Bem, tenho que voltar ao\\nLABORATÓRIO.\\pTchau!",
  ["g3:0817ea36"] = "Tem uma carta anexada...\\n\\Meu bem {PLAYER},\\pTô mandando um par de\\nTÊNIS DE CORRIDA pra você.\\pLembre-se que vou estar sempre\\ntorcendo por você! Nunca desista!\\pCom amor, mamãe",
  ["g3:0817ead7"] = "{RIVAL}: E aí! {PLAYER}!\\pVocê ainda tá por essas bandas?\\pEu já capturei um monte de\\nPOKéMON fortes e inteligentes!\\pDeixa eu ver o que você\\ncapturou, {PLAYER}!",
  ["g3:0817eb71"] = "Ei!\\nCalma!\\pVocê já venceu!",
  ["g3:0817eb95"] = "{RIVAL}: Ei, adivinha?\\pFui na casa do BILL e ele me\\nmostrou seus POKéMON raros.\\pCom isso, várias páginas foram\\nadicionadas à minha POKéDEX!\\pAfinal, o BILL é mundialmente\\nconhecido como um POKéMANÍACO.\\pEle também inventou o Sistema\\nde Armazenamento POKéMON no PC.\\pJá que está usando seu sistema,\\nvocê devia ir agradecê-lo.\\pBem, é melhor eu ir andando.\\nFalou!",
  ["g3:0817ecd4"] = "Ah, é mesmo.\\pSinto pena de você. Não, sério.\\nVocê tá sempre na minha sombra.\\pEntao toma, vou te dar um\\npresentinho.",
  ["g3:0817ed5d"] = "Essa coisa é perfeita pra alguém\\ntagarela como você.\\pEu não preciso disso porque não\\ndou a mínima pros outros.\\pPois bem, agora vou mesmo embora.\\nFalou!",
  ["g3:0817ee0e"] = "Ei! Fique longe!\\nNão é seu quintal!\\p...Ahn?\\neu?\\pSou só um espectador inocente!\\nNão acredita em mim?",
  ["g3:0817ee70"] = "CAPANGA: Já chega! Eu desisto!\\nVou dar o fora daqui!",
  ["g3:0817ee9c"] = "... Tá bom.\\nVou devolver a MT que roubei.",
  ["g3:0817eebf"] = "{PLAYER} recuperou a MT28 do\\nCAPANGA da EQUIPE ROCKET.",
  ["g3:0817eeed"] = "É melhor eu ir nessa!\\nAdeus!",
  ["g3:0817ef07"] = "Arruma um espaço aí! Tenho que\\nte dar isso anter de cair fora!",
  ["g3:0817ef3f"] = "Você também é TREINADOR?\\pCapturar, batalhar...\\nÉ uma vida difícil, não é?",
  ["g3:0817ef89"] = "Você sabia que pode CORTAR\\npequenas árvores?\\pAté aquela árvore em frente\\nà loja pode ser cortada.\\pMas acho que dá pra dar a\\nvolta nela.",
  ["g3:0817f01d"] = "Se aquele SLOWBRO não estivesse lá,\\nvocê podia CORTAR a árvore.\\pE chegar ao outro lado.\\pMas acho que dá pra dar a\\nvolta nela.",
  ["g3:0817f0b2"] = "Você tá criando uma enciclopédia\\nsobre os POKéMON? Parece divertido.",
  ["g3:0817f0f1"] = "As pessoas daqui foram roubadas.\\pÉ óbvio que a EQUIPE ROCKET está\\npor trás deste crime terrível!\\pAté nossa FORÇA POLICIAL tem\\ndificuldades com os ROCKETS!",
  ["g3:0817f183"] = "Muito bem, SLOWBRO!\\nUse BOMBA SÔNICA!",
  ["g3:0817f1a1"] = "Vamos, SLOWBRO, presta atenção!",
  ["g3:0817f1c2"] = "SLOWBRO, soco!",
  ["g3:0817f1d2"] = "Não!\\nVocê errou de novo!",
  ["g3:0817f1e9"] = "SLOWBRO, RETIRADA!",
  ["g3:0817f1fc"] = "Não! Não é isso!\\nÉ tão difícil controlar os POKéMON!\\pA obediência dos seus POKéMON\\ndepende das suas habilidades\\pcomo TREINADOR.",
  ["g3:0817f270"] = "SLOWBRO pegou no sono...",
  ["g3:0817f287"] = "SLOWBRO está enrolando...",
  ["g3:0817f2a2"] = "SLOWBRO se virou...",
  ["g3:0817f2b7"] = "SLOWBRO ignorou as ordens...",
  ["g3:0817f2cf"] = "Quero uma bicicleta vermelha\\nbrilhante.\\pVou guardá-la em casa pra não\\nsujar.",
  ["g3:0817f319"] = "Esta é a CAVERNA DE CERULEAN.\\pLá dentro vivem POKéMON muito\\npoderosos.\\pSó TREINADORES muito especiais\\ntêm permissão para entrar nela.\\pPara começar, você teria que ser\\nforte o bastante para vencer a\\pLIGA POKéMON.\\pE também teria que conquistar\\nalgo notável.",
  ["g3:0817f420"] = "CIDADE DE CERULEAN\\nUma misteriosa aura azul a rodeia",
  ["g3:0817f453"] = "DICAS PARA TREINADORES\\pUm POKéMON pode segurar um item.\\pAlguns itens podem até ser usados\\nem batalha pelo POKéMON.",
  ["g3:0817f4c5"] = "Campos e cavernas não são nada!\\nLOJA DE BICICLETAS",
  ["g3:0817f4ef"] = "GINÁSIO POKéMON de CERULEAN\\nLÍDER: MISTY\\pA sereia durona!",
  ["g3:0817f52e"] = "Você acredita em fantasmas?",
  ["g3:0817f548"] = "Sério?\\nEntão tem gente que acredita...",
  ["g3:0817f568"] = "Hahaha, acho que não.\\pEssa mão branca no seu ombro...\\ndeve ser só imaginação minha.",
  ["g3:0817f5b6"] = "Esta cidade é conhecida como o\\nlocal de descanso dos POKéMON.\\pCerimônias memoriais são realizadas\\nna TORRE POKéMON.",
  ["g3:0817f614"] = "Fantasmas apareceram na TORRE\\nPOKéMON.\\pAcho que são os espíritos dos\\nPOKéMON que os ROCKETS mataram.",
  ["g3:0817f676"] = "CIDADE DE LAVENDER\\nA nobre cidade roxa",
  ["g3:0817f69a"] = "Novo VISOR SILPH!\\nTorne o invisível visível!\\pCOMPANHIA SILPH",
  ["g3:0817f6d6"] = "VOLUNTÁRIOS de LAVENDER\\nCASA POKéMON",
  ["g3:0817f6f7"] = "TORRE POKéMON\\nAcalme os espíritos dos POKéMON",
  ["g3:0817f723"] = "Somos cuidadosos com a poluição\\npor aqui.\\pOuvi dizer que GRIMER se\\nmultiplica em lama tóxica.",
  ["g3:0817f776"] = "Você viu o SANTA ANA ancorado\\nno porto?",
  ["g3:0817f7a6"] = "Entao, o SANTA ANA já partiu?\\pEle vai voltar para VERMILION por\\nvolta dessa época no ano que vem.",
  ["g3:0817f7fd"] = "Estou construindo um prédio neste\\nterreno. Tudo aqui é meu.\\pMeu POKéMON está compactando o\\nsolo para preparar a fundação.",
  ["g3:0817f871"] = "MACHOP: Guoh! Gogogoh!",
  ["g3:0817f888"] = "Um MACHOP está pisoteando o terreno\\npara deixá-lo bem plano.",
  ["g3:0817f8ac"] = "O SANTA ANA é um famoso navio\\nde cruzeiro luxuoso.\\pEle visita VERMILION uma vez por\\nano.",
  ["g3:0817f8fb"] = "CIDADE DE VERMILION\\nO porto de pôr do sol deslumbrante",
  ["g3:0817f928"] = "ATENÇÃO!\\pA ROTA 12 pode estar bloqueada\\npor um POKéMON adormecido.\\pFaça o desvio pelo TÚNEL DE ROCHA\\naté a CIDADE DE LAVENDER.\\pPOLÍCIA de VERMILION",
  ["g3:0817f9a1"] = "FA-CLUBE POKéMON\\nTodos os fãs de POKéMON são\\pbem-vindos!",
  ["g3:0817f9cc"] = "GINÁSIO POKéMON de VERMILION\\nLÍDER: TEN. SURGE\\pO relâmpago americano!",
  ["g3:0817fa11"] = "PORTO DE VERMILION",
  ["g3:0817fa22"] = "Boas-vindas ao SANTA ANA!",
  ["g3:0817fa3c"] = "Boas-vindas ao SANTA ANA!\\pCom licença, você tem o bilhete?",
  ["g3:0817fa77"] = "{PLAYER} pegou o BILHETE do navio!\\pÓtimo!\\nBoas-vindas ao SANTA ANA!",
  ["g3:0817faba"] = "{PLAYER} não tem o BILHETE necessário.\\n\\Sinto muito!\\pPrecisa de um bilhete pra entrar a bordo.",
  ["g3:0817fb10"] = "O navio partiu.",
  ["g3:0817fb23"] = "Ah, você tem o PASSE TRIPLO.\\pGostaria de embarcar na balsa\\nGALOPE MARINHO?",
  ["g3:0817fb67"] = "Certo, está tudo em ordem.\\pA balsa GALOPE MARINHO EXPRESSO 7\\npartirá imediatamente.",
  ["g3:0817fbb8"] = "Ah, você tem o PASSE ARCO-ÍRIS.\\pGostaria de embarcar na balsa\\nGALOPE MARINHO?",
  ["g3:0817fc00"] = "Ah! Isso é um BILHETE MÍSTICO!\\nIsso sim é raro.\\pTeremos prazer em te levar até a\\nROCHA UMBILICAL sempre que quiser.",
  ["g3:0817fc5f"] = "Ah! Isso é um BILHETE AURORA!\\nIsso sim é raro.\\pTeremos prazer em te levar até a\\nILHA DA ORIGEM sempre que quiser.",
  ["g3:0817fcc1"] = "Gostaria de embarcar na balsa\\nGALOPE MARINHO?",
  ["g3:0817fcec"] = "Certo, está tudo em ordem para você\\nembarcar em uma balsa especial.\\pA balsa GALOPE MARINHO EXPRESSO 10\\npartirá imediatamente.",
  ["g3:0817fd5f"] = "Certo, está tudo em ordem para você\\nembarcar em uma balsa especial.\\pA balsa GALOPE MARINHO EXPRESSO 12\\npartirá imediatamente.",
  ["g3:0817fdd2"] = "Ah, olá, {PLAYER}!\\nComo você está?\\pSou eu, um dos ASSISTENTE do\\nPROFESSOR CARVALHO.\\pVocê encontrou o outro\\nASSISTENTE?\\pEle estava com um pacote do\\nPROFESSOR CARVALHO para você,\\p{PLAYER}.\\pEle disse que iria procurar você\\npela ROTA 2, {PLAYER}.\\pSe você estiver pela área da\\nROTA 2, por favor, procure por ele.",
  ["g3:0817fec3"] = "Capturei meu KOFFING em\\nCINNABAR.\\pEle costuma ser bonzinho, mas\\nsolta veneno quando fica irritado.",
  ["g3:0817ff1c"] = "Heheh! Este GINÁSIO é ótimo!\\nTá cheio de mulheres!",
  ["g3:0817ff4a"] = "CELADON se orgulha de seus\\nesforços para manter a cidade\\pbonita.\\pÉ por isso que o novo CASSINO é\\nruim para a imagem da nossa cidade.",
  ["g3:0817ffc5"] = "Ahhh...\\nPerdi tudo nas máquinas!\\pEu sabia que devia ter trocado\\nminhas FICHAS por prêmios!",
  ["g3:0818001b"] = "Este é o meu amigão, POLIWRATH.\\pEle evoluiu de um POLIWHIRL\\nquando usei uma PEDRA DA ÁGUA.",
  ["g3:08180075"] = "POLIWRATH: Ribi ribit!",
  ["g3:0818008c"] = "O que você tá olhando?\\nCai fora se não quiser apanhar.",
  ["g3:081800c2"] = "É melhor ficar fora do caminho\\nda EQUIPE ROCKET!",
  ["g3:081800e1"] = "DICAS PARA TREINADORES\\pPRECISAO X aumenta a precisão\\ndos movimentos.\\pDIRETO aumenta a chance de\\nacertos críticos.\\pCompre seus itens no SHOPPING\\nDE CELADON!",
  ["g3:0818017a"] = "CIDADE DE CELADON\\nA cidade dos sonhos arco-íris",
  ["g3:081801a2"] = "GINÁSIO POKéMON de CELADON\\nLÍDER: ERIKA\\pA princesa amante da natureza!",
  ["g3:081801e5"] = "MANSÃO CELADON",
  ["g3:081801f5"] = "No SHOPPING DE CELADON você\\nencontra tudo de que precisa!",
  ["g3:08180224"] = "DICAS PARA TREINADORES\\pPROTEÇAO X protege os POKéMON\\nde movimentos que diminuem os\\patributos durante a batalha.\\pCompre seus itens no SHOPPING\\nDE CELADON!",
  ["g3:081802a4"] = "Troque FICHAS por prêmios!\\nTROCA de PRÊMIOS",
  ["g3:081802cf"] = "CASSINO ROCKET\\nO parque de diversoes dos adultos!",
  ["g3:08180300"] = "Aaaah, ai...\\nQueimei minha língua!\\pA senhorinha simpática na MANSÃO\\nme deu um pouco de CHÁ.\\pMas tava pegando fogo!\\nTenho que deixar esfriar.",
  ["g3:08180388"] = "Oi!\\pJá te vi por aí, mas a gente nunca\\nteve a chance de conversar.\\pAcho que foi a sorte que fez a\\ngente se encontrar.\\pQuero comemorar ensinando a você\\no movimento COZIDOS.",
  ["g3:0818043f"] = "Vou ficar de olho em você.\\pTomara que a gente possa\\nconversar de novo.",
  ["g3:08180484"] = "E então, qual POKéMON deve\\naprender o movimento COZIDOS?",
  ["g3:081804c4"] = "Desejo a você tudo de bom!",
  ["g3:081804e1"] = "E agora?\\nO que eu vou fazer?\\pAlguém roubou o nosso\\nVISOR SILPH.\\pO ladrão passou por aqui.\\nTenho certeza.\\pMas perdi ele de vista!\\nDroga!",
  ["g3:0818056e"] = "Você já experimentou o\\nJOGO DO SAFÁRI?\\pTem alguns POKéMON raros que só\\npodem ser capturados lá.",
  ["g3:081805c6"] = "A ZONA DE SAFÁRI tem um zoológico\\nbem na frente da entrada.\\pNos fundos fica o JOGO DO SAFÁRI\\npara capturar POKéMON.",
  ["g3:0818062c"] = "ERIK: Cadê a SARA?\\nEu disse que encontraria ela aqui.",
  ["g3:0818065a"] = "Aquela POKé BOLA ali dentro...\\nVocê queria ela?\\pEu também!\\n... Ha? Aquilo é um POKéMON?",
  ["g3:081806ab"] = "CIDADE DE FUCHSIA\\nVeja só! É um rosa apaixonante!",
  ["g3:081806d3"] = "PARAÍSO POKéMON\\nZONA DE SAFÁRI",
  ["g3:081806f0"] = "JOGO DO SAFÁRI\\nCAPTURE SEU POKéMON!",
  ["g3:0818070d"] = "ZONA DE SAFÁRI\\nCASA DO DIRETOR",
  ["g3:08180768"] = "GINÁSIO POKéMON de FUCHSIA\\nLÍDER: KOGA\\pO mestre ninja venenoso",
  ["g3:081807a9"] = "Nome: CHANSEY\\nCapturá-la é questão de sorte.",
  ["g3:081807d9"] = "Nome: VOLTORB\\nA própria imagem de uma POKé BOLA.",
  ["g3:08180806"] = "Nome: KANGASKHAN\\pUm POKéMON maternal que cria seu\\nfilhote em uma bolsa na barriga.",
  ["g3:08180859"] = "Nome: SLOWPOKE\\nAmigável e se move bem devagar.",
  ["g3:08180887"] = "Nome: LAPRAS\\nTambém conhecido como o rei\\pdos mares.",
  ["g3:081808ae"] = "Nome: OMANYTE\\nUm POKéMON extremamente raro que\\pfoi regenerado a partir de um fóssil.",
  ["g3:081808fa"] = "Nome: KABUTO\\nUm POKéMON extremamente raro que\\pfoi regenerado a partir de um fóssil.",
  ["g3:08180948"] = "Ah, eu queria tanto ser um filhote\\nde KANGASKHAN.\\pEu adoraria ser um substituto do\\nbebê...\\pE me aninhar na bolsa na barriga\\nda mãe KANGASKHAN.\\pMas só POKéMON podem usar o\\nmovimento SUBSTITUTO...\\pQuer que eu ensine SUBSTITUTO\\na um dos seus POKéMON?",
  ["g3:08180a32"] = "Ah, é mesmo?\\nSUBSTITUTO parece tão divertido...",
  ["g3:08180a57"] = "Qual POKéMON deve aprender\\no movimento SUBSTITUTO?",
  ["g3:08180a80"] = "Cara, eu daria qualquer coisa pra\\npoder entrar na bolsa na barriga\\pde uma KANGASKHAN...",
  ["g3:08180abd"] = "Meu pai é o LÍDER de GINÁSIO\\ndesta cidade.\\pEstou treinando para usar POKéMON\\ndo tipo VENENO tão bem quanto ele.",
  ["g3:08180b20"] = "A porta está trancada...",
  ["g3:08180b34"] = "BLAINE do GINÁSIO de CINNABAR\\né um cara bem estranho.\\pEle vive na ilha desde muito antes\\ndo LABORATÓRIO ser construído.",
  ["g3:08180ba0"] = "Os cientistas realizam experimentos\\nno prédio incendiado.\\pSabe, aquele que eles chamam de\\nMANSÃO POKéMON.",
  ["g3:08180c0d"] = "ILHA DE CINNABAR\\nA cidade ardente do desejo\\pflamejante",
  ["g3:08180c3e"] = "LABORATÓRIO POKéMON",
  ["g3:08180c4a"] = "GINÁSIO POKéMON de CINNABAR\\nLÍDER: BLAINE\\pO mestre das perguntas impulsivo!",
  ["g3:08180c90"] = "Hein?\\nEi, se não é {PLAYER}!",
  ["g3:08180caa"] = "Olha, sou eu, o BILL.\\nHá quanto tempo!\\pEspero que você ainda esteja\\nusando meu sistema de PC.\\pBem, já que a gente se encontrou\\naqui, que tal passar um tempo\\pcomigo?\\pExiste uma pequena ilha bem ao\\nsul chamada ILHA UM.\\pUm amigo me convidou, então estou\\na caminho de lá.\\pE aí?\\nQuer vir comigo?",
  ["g3:08180ddd"] = "Beleza, então.\\nVamos!",
  ["g3:08180df8"] = "Como é?\\nVocê está nos corres?\\pTudo bem.\\nDe qualquer forma, o barco ainda\\pnão chegou.\\pVou ficar te esperando no CENTRO\\nPOKéMON ali.\\pVenha me ver quando terminar\\nseus afazeres por aqui.",
  ["g3:08180ead"] = "Parece que o barco do meu amigo\\nchegou.\\pEle mandou vir até CINNABAR\\nsó pra me buscar.",
  ["g3:08180f09"] = "E aí, não foi um cruzeiro longo?\\pMeu amigo CELIO pareceu gostar\\nda sua companhia.\\pEle com certeza vai gostar se\\nvocê for visitá-lo de novo.\\pSe você tiver um PASSE TRIPLO,\\npode sempre pegar uma balsa no\\pPORTO de VERMILION.\\pÉ isso, obrigado pela companhia!",
  ["g3:08181003"] = "O que você quer?\\nCai fora!",
  ["g3:0818101f"] = "O CHEFE disse que vai tomar essa\\ncidade em nome da EQUIPE ROCKET!",
  ["g3:0818105a"] = "É melhor não mexer comigo!\\nOu vou ter que te machucar!",
  ["g3:08181087"] = "SAFFRON pertece à EQUIPE ROCKET!",
  ["g3:081810a7"] = "Minha vida de crimes me faz sentir\\ntão vivo!",
  ["g3:081810d5"] = "Ai!\\nOlha por onde anda!",
  ["g3:081810f5"] = "Com a SILPH sob nosso controle,\\npodemos explorar os POKéMON\\pdo mundo todo!\\pVamos ficar podres de ricos, hahaha!",
  ["g3:08181159"] = "Você derrotou a EQUIPE ROCKET\\nsem ajuda de ninguém? Que incrível!",
  ["g3:08181189"] = "Sim! A EQUIPE ROCKET se foi!  \\nÉ seguro sair de novo!",
  ["g3:081811bf"] = "As pessoas fugiram daqui quando\\naqueles ROCKETS apareceram.\\pMas agora todo mundo pode voltar\\npara SAFFRON.",
  ["g3:08181225"] = "Voei pra cá no meu PIDGEOT quando\\nli sobre a SILPH.\\pJá acabou?\\nPerdi toda a ação...",
  ["g3:08181286"] = "PIDGEOT: Bi bibii!",
  ["g3:08181299"] = "Vi o CHEFE da EQUIPE ROCKET\\nfugindo do prédio da SILPH.",
  ["g3:081812ca"] = "Tô de vigia.\\pNão deixo crianças suspeitas\\nentrarem!",
  ["g3:08181302"] = "...\\nRonc...\\pHaha! Ele está tirando um cochilo!",
  ["g3:08181326"] = "CIDADE DE SAFFRON\\nA brilhante e dourada terra do\\pcomércio",
  ["g3:08181354"] = "DOJÔ DE LUTA",
  ["g3:08181362"] = "GINÁSIO POKéMON de SAFFRON\\nLÍDER: SABRINA\\pA mestra dos POKéMON PSÍQUICOS!",
  ["g3:081813aa"] = "DICAS PARA TREINADORES\\pCURA TOTAL cura todos os problemas\\nde status, como queimaduras,\\pparalisia, envenenamento,\\pcongelamento e sono.\\pCusta um pouco mais, mas é melhor\\ndo que comprar outros itens.",
  ["g3:08181452"] = "DICAS PARA TREINADORES\\pA nova GRANDE BOLA oferece\\nmelhores taxas de captura.\\pExperimente naqueles POKéMON\\ndifíceis de capturar.",
  ["g3:081814b9"] = "EDIFÍCIO COMERCIAL DA\\nCOMPANHIA SILPH",
  ["g3:081814d3"] = "CASA do SR. PSÍQUICO",
  ["g3:081814e7"] = "Novo produto da SILPH!\\nAinda será lançado...",
  ["g3:08181519"] = "FA-CLUBE de TREINADORES POKéMON\\pMuitos TREINADORES escreveram\\nseus nomes neste painel.",
  ["g3:08181569"] = "Nesse FA-CLUBE tem gente...\\nque de POKéMON nada entende!\\pComo podem não reconhecer a\\ngenialidade do LANCE?\\pEle luta pela justiça!\\nÉ estiloso e intenso!\\pEle é o melhor de todos, LANCE!",
  ["g3:0818161b"] = "BILL: Chegamos!\\nEsta é a ILHA UM.\\pExistem várias ilhas por aqui,\\ne esta é uma delas.\\pMeu amigo CELIO mandou o barco\\npra me buscar.\\pEle cuida sozinho da rede de PCs\\nda ilha.\\p... Mas por que estou contando isso?\\nVamos logo ver o CELIO!",
  ["g3:08181726"] = "Olá, navegante!\\nPara onde você quer navegar?",
  ["g3:0818174e"] = "Aqui estamos nós, numa ilha bem\\nno meio do nada.\\pTemos sorte de contar com um\\njovem tão íntegro como o CELIO.\\pMinha neta ficou toda empolgada\\npor causa do amigo dele.\\pAlguma coisa sobre um tal de\\nPOKéMANÍACO famoso?\\pNão sei bem o que isso significa,\\nmas o CELIO é um grande homem.",
  ["g3:08181858"] = "Minha neta ficou toda empolgada\\ncom uma nova descoberta.\\pEla disse que agora temos conexão\\nde PC com o pessoal de KANTO.\\pNão sei bem o que isso significa,\\nmas o CELIO é um grande homem!",
  ["g3:08181901"] = "Minha neta ficou toda empolgada\\ncom uma nova descoberta.\\pEla disse que a gente finalmente\\ntem conexão de PC com o pessoal\\pde HOENN.\\pNão sei bem o que isso significa,\\nmas o CELIO é um grande homem.\\pEle seria um ótimo marido para\\nminha neta!",
  ["g3:081819e1"] = "ILHA UM\\nOnde os amigos se reúnem",
  ["g3:08181a0a"] = "Expandindo o mundo POKéMON!\\nCENTRO de REDE POKéMON",
  ["g3:08181a4a"] = "Oi, dando uma volta, né?\\nNão é ótimo o clima quente daqui?",
  ["g3:08181a88"] = "ILHA DOIS\\nIlha do encontro a dois",
  ["g3:08181aa7"] = "Salte e agarre!\\nCASSINO da alegria",
  ["g3:08181ac8"] = "PERIGO! CORRENTEZA FORTE!\\nProibido pescar e surfar!",
  ["g3:08181afe"] = "Ah!\\nOlá, Boas-vindas à minha loja!\\pAbrimos recentemente.\\pNosso estoque ainda é limitado,\\nmas espero conseguir atender\\pàs suas necessidades.",
  ["g3:08181b7c"] = "Nem sei como agradecer por ter\\nresgatado a PERDITA.\\pGraças a você, o pessoal da ILHA\\nTRÊS mudou a maneira como vê\\po povo de KANTO.\\pE eu sou de KANTO, sabe.\\pO pessoal da ILHA TRÊS me ajudou\\na ampliar meus produtos.",
  ["g3:08181c77"] = "Oi! Tô dando o meu melhor aqui.\\nEspero que você também dê o seu,\\p{PLAYER}.",
  ["g3:08181cae"] = "Ah, oi, {PLAYER}!\\nSeja Boas-vindas!\\pComecei a trazer produtos de\\nterras distantes.\\pTambém consegui uns itens raros.\\nDá uma olhada!",
  ["g3:08181d2f"] = "Aquele cara ali se mudou da\\nCIDADE DE CELADON.\\pEle abriu uma loja junto com o\\nirmao mais novo.\\pSerá que ele sabia no que\\nestava se metendo?",
  ["g3:08181dca"] = "O irmão do dono da loja conseguiu\\num emprego no CASSINO.\\pEle está tentando juntar dinheiro\\npara que possam comprar mais\\pmercadorias.",
  ["g3:08181e47"] = "Ei, ei, sabia dessa?\\pUm TREINADOR famoso veio para a\\nILHA há um tempinho.\\pEle é um dos membros da ELITE\\nDOS QUATRO. O nome dele é BRUNO.\\pEle foi embora todo desapontado\\nquando descobriu que os DOCES\\pDA FÚRIA estavam esgotados.",
  ["g3:08181f28"] = "Quem entende do assunto sabe que\\né aqui onde tem os itens mais raros!",
  ["g3:08181f5d"] = "Tem uma senhora que mora numa\\ncabana lá no cabo.\\pEla fica encarando os POKéMON.\\nÉ meio estranho.",
  ["g3:08181fce"] = "Boing! Boing!\\nJá experimentou o jogo de saltar?\\pOs POKéMON podem participar...\\nBoing!\\pAlguns fazem boing!\\pE outros fazem boooooooing!\\pSabia disso?\\nBoing!",
  ["g3:08182061"] = "ILHA TRÊS\\nIlha do laço familiar",
  ["g3:0818208b"] = "Hyahoo!\\pA partir de hoje, esta ilha é nossa!",
  ["g3:081820c0"] = "A gente não quer vocês trazendo\\nbagunça e confusão pra cá!\\pÉ melhor voltarem pra KANTO!",
  ["g3:08182125"] = "Vá chorar em outro lugar.\\nNosso chefe está a caminho.\\pQuando ele chegar, vamos dar a\\nvocês um show de moto que não\\pvao esquecer tão cedo!",
  ["g3:081821a9"] = "O-o quê?! De jeito nenhum!\\nSaia da ilha agora!",
  ["g3:081821dc"] = "Quem vai me obrigar?",
  ["g3:081821f1"] = "Você é o chefe?\\nVolte para KANTO agora mesmo!",
  ["g3:0818221f"] = "Ha?\\pAcabei de chegar, cara.\\pQue atitude hostil é essa?\\nQue recepção mais fria!",
  ["g3:08182275"] = "Sua gangue de motoqueiros tem\\ncausado o maior caos por aqui.\\pVocê faz ideia de quantos problemas\\neles trouxeram pra gente na ilha?",
  ["g3:081822fb"] = "Não, cara, não faço ideia.\\pOlha pra esse lugar.\\nO que vocês fazem pra se divertir?\\pVocês tinham era que agradecer por\\na gente estar dando um pouco de\\pvida pra essa vila parada.\\pMas, se insiste tanto, pode tentar\\ntirar a gente daqui.",
  ["g3:081823c7"] = "Grrr... Seus covardes... Só são\\ncorajosos quando estão em grupo...",
  ["g3:081823ed"] = "Ei, o que você tá olhando?\\nNão sabe que é falta de educação?\\pQuer arrumar encrenca ou o quê?",
  ["g3:08182453"] = "Esperto da sua parte.\\nFique fora disso.",
  ["g3:0818247d"] = "Heh, gostei da sua coragem.\\nVocê vai perder dinheiro, mas...",
  ["g3:081824b7"] = "O quê...\\nQuem é você, jovem?!",
  ["g3:081824cf"] = "Ah, cara...\\nNem pensa em rir!",
  ["g3:081824ef"] = "Você não é de KANTO?\\nDevia estar do nosso lado!",
  ["g3:08182521"] = "Para de brincadeira!",
  ["g3:08182536"] = "Qual é o seu problema, com esse\\nnervosismo todo assim?\\pNão é legal, cara!",
  ["g3:08182582"] = "A gente chamou o chefe pra vir até\\naqui, mas você tinha que estragar\\ptudo!\\pVocê fez a gente passar vergonha,\\ncara!",
  ["g3:081825d4"] = "... ... ...   ... ... ...",
  ["g3:081825e2"] = "Chefe, tô te falando, você tem que\\ndar um jeito nessa criança!",
  ["g3:08182623"] = "Tenho te observado e diria que\\njá fez o bastante.\\ptá de amizade com eles ou o quê?\\pEntao acho que vai batalhar\\ncomigo no lugar deles.",
  ["g3:081826b7"] = "Tá bom, chega!\\nA gente vai embora, como queria!\\pMal posso esperar pra dar o fora\\ndessa ilha chata!",
  ["g3:0818271d"] = "Hmph! É, fica aí mesmo, andando\\ncom esses caipiras!",
  ["g3:0818275a"] = "Obrigado! Aqueles brutamontes só\\ncausavam problema.\\pAh, veja, seus POKéMON se\\nmachucaram por minha causa.",
  ["g3:081827be"] = "{PLAYER} recebeu\\num RESTAURADOR.",
  ["g3:081827db"] = "Ah?\\nSua MOCHILA está cheia.",
  ["g3:081827f1"] = "Os seus POKéMON são mesmo\\nimpressionantes.",
  ["g3:08182823"] = "Seria incrível se alguém tão forte\\nquanto você morasse aqui.\\pEspero que pelo menos fique aqui\\npor um tempo.\\p... Como é?\\nVocê está procurando a PERDITA?\\pA PERDITA foi em direção à\\nPONTE UNIÃO faz um tempo.",
  ["g3:081828eb"] = "A ILHA TRÊS é a mais populosa\\ndas ilhas daqui.\\pMesmo assim, podia ser um pouco\\nmenos parada.\\pMas eu não queria ver brutamontes\\ncomo aqueles MOTOQUEIROS por\\paqui de novo.",
  ["g3:0818298a"] = "Vou treinar meu DODUO na\\nFLORESTA DAS FRUTAS.\\pQuando ele evoluir, vou jogar um\\njogo na ILHA DOIS.",
  ["g3:081829f4"] = "DODUO: Gigiih!",
  ["g3:08182a03"] = "ILHA QUATRO\\nA ilha azul e aconchegante",
  ["g3:08182a2b"] = "LORELEI voltou.\\pSerá que ela achou a vida na\\ncidade estressante demais?",
  ["g3:08182a75"] = "LORELEI voltou para casa.\\pO LAPRAS que ela tem deve ser o\\nmesmo que ela conheceu quando\\pera criança.\\pAcho que ela o capturou na\\nCAVERNA GLACIAL.\\pTalvez esse POKéMON esteja com\\nela desde então.",
  ["g3:08182b37"] = "{RIVAL}: E aí!\\n{PLAYER}!\\pO que você tá fazendo aqui nas\\nILHAS SETII?\\pVocê devia parar de me copiar,\\nsabia?\\pDe qualquer forma, eu já consegui\\nmeu OVO de POKéMON, então não\\ptenho mais nada pra fazer aqui.\\pHehe, aposto que nem sabe direito\\no que são OVOS de POKéMON.\\pDessa forma, você nunca vai\\ncompletar sua POKéDEX NACIONAL.\\pAliás, eu vi alguém que a gente\\nconhece nessa ilha.\\pPor que você não dá uma olhada\\nse estiver com curiosidade?\\pEu não tenho tempo a perder.\\pFalou!",
  ["g3:08182ce3"] = "Ah, você me encontrou! Por favor,\\nnão conte nada a LORELEI.\\pVocê sabia que a LORELEI tem\\nmuitos, muitos bichos de pelúcia?\\pToda vez que ela volta pra ILHA\\nQUATRO, a coleção dela aumenta!",
  ["g3:08182d8e"] = "Uau, que gelado!\\pFiz uma raspadinha usando o\\ngelo que raspei dentro da\\pCAVERNA GLACIAL.\\pTá gelado e gostoso!",
  ["g3:08182deb"] = "CASA DA LORELEI",
  ["g3:08182dfb"] = "ILHA CINCO\\nIlha que marca a passagem do tempo",
  ["g3:08182e26"] = "Ah, que chato.\\nEu queria brincar na CAMPINA.\\pMas construíram um prédio esquisito\\nlá, então não posso mais brincar.",
  ["g3:08182e96"] = "As coisas por aqui andam ficando\\nmais movimentadas ultimamente.\\pE eu também não tenho conseguido\\npescar muitos peixes bons.",
  ["g3:08182f01"] = "Poucas pessoas vêm até aqui.\\pSe eu treinar neste lugar, tenho\\ncerteza de que vou ficar cada\\pvez mais forte.\\pIsso mesmo, cada vez mais forte...\\pQue tal aprender um movimento\\nassim? É o DANÇA DE ESPADAS.",
  ["g3:08182fc1"] = "Ah, tudo bem então.",
  ["g3:08182fd9"] = "Certo, escolha qual POKéMON devo\\nensinar.",
  ["g3:0818300d"] = "Se ao menos pudéssemos continuar\\nficando cada vez mais fortes, hein?",
  ["g3:08183046"] = "ILHA SETE\\nIlha da missão do infinito",
  ["g3:0818306c"] = "Essas ilhas são chamadas de\\nILHAS SETII porque são sete.\\p... Ou pelo menos é isso que os\\njovens acreditam.\\pA verdade é que elas têm esse\\nnome porque dizem que foram\\pcriadas em sete dias.",
  ["g3:08183143"] = "Esta ilha foi deixada praticamente\\nintocada em seu estado natural.\\pPor causa disso, pode ser um pouco\\ndifícil caminhar por aqui.",
  ["g3:081831c6"] = "ILHA SEIS\\nIlha da fortuna e sabedoria ancestral",
  ["g3:081831ef"] = "Continue por este caminho e você\\nchegará à PASSAGEM D'ÁGUA.\\pSiga por ela e chegará ao\\nVALE DAS RUÍNAS.",
  ["g3:08183255"] = "Quando você está tão longe da\\ncidade assim, o céu à noite fica\\pmaravilhoso.",
  ["g3:0818329d"] = "Oi!\\nTrabalho em uma LOJA POKéMON.\\pÉ parte de uma rede conveniente\\nque vende todos os tipos de itens.\\pPor favor, faça uma visita à nossa\\nloja na CIDADE DE VIRIDIAN.\\pJá sei, vou te dar uma amostra.\\nAqui está!",
  ["g3:08183347"] = "Venha à nossa loja se precisar de\\nPOKé BOLAS para capturar POKéMON.",
  ["g3:08183387"] = "{PLAYER} guardou a POÇÃO no\\nBOLSO de ITENS da MOCHILA.",
  ["g3:081833b9"] = "Tá vendo esses barrancos ao longo\\nda estrada?\\pÉ um pouco assustador, mas você\\npode saltar deles.\\pAssim, você chega mais rápido à\\nCIDADE DE PALLET.",
  ["g3:0818343a"] = "ROTA 1\\nCIDADE DE PALLET -\\pCIDADE DE VIRIDIAN",
  ["g3:0818345e"] = "ROTA 2\\nCIDADE DE VIRIDIAN -\\pCIDADE DE PEWTER",
  ["g3:08183482"] = "TÚNEL DOS DIGLETT",
  ["g3:08183491"] = "Oof... Melhor eu fazer uma pausa...\\nOof...\\pAquele túnel para CERULEAN é muito\\ndesgastante!",
  ["g3:081834e6"] = "Ei!\\nEu te vi na FLORESTA DE VIRIDIAN!",
  ["g3:08183509"] = "Você venceu de novo!",
  ["g3:0818351c"] = "Existem outros tipos de POKéMON\\nalém dos que você encontra nas\\pflorestas.",
  ["g3:08183560"] = "Oi!\\nEu gosto de shorts!\\pEles são muito confortáveis e\\nfáceis de vestir!",
  ["g3:081835a0"] = "Não acredito nisso!",
  ["g3:081835b4"] = "Você está usando os PCs dos\\nCENTROS POKéMON para guardar\\pseus POKéMON?\\pCada CAIXA pode armazenar até\\n30 POKéMON.",
  ["g3:08183616"] = "Com licença!\\nVocê olhou pra mim, né?",
  ["g3:0818363f"] = "Que maldade!",
  ["g3:0818364c"] = "Você não deveria ficar me encarando\\nse não quer batalhar!",
  ["g3:08183682"] = "Você é TREINADOR?\\nEntão vamos batalhar!",
  ["g3:081836b3"] = "Se eu tivesse novos POKéMON,\\nteria vencido!",
  ["g3:081836d9"] = "Se uma CAIXA de POKéMON do PC ficar\\ncheia, basta trocar para outra CAIXA.",
  ["g3:0818371b"] = "O jeito que você me olhou...\\nÉ tão intrigante!",
  ["g3:08183746"] = "Seja gentil!",
  ["g3:0818374f"] = "Para evitar batalhas, não deixe\\nos TREINADORES verem você.",
  ["g3:08183786"] = "Ei! Você não tá usando shorts!\\nQual é seu problema?",
  ["g3:081837bd"] = "Eu perdi! \\nPerdi! Perdi!",
  ["g3:081837cf"] = "Eu sempre uso shorts, até no\\ninverno. É a minha norma.",
  ["g3:08183807"] = "Vou batalhar usando os POKéMON \\nque acabei de capturar.",
  ["g3:08183837"] = "Já era, perdi!",
  ["g3:08183849"] = "Os POKéMON treinados são mais\\nfortes do que os selvagens.",
  ["g3:0818387a"] = "Ai!\\nVocê me tocou?",
  ["g3:08183891"] = "É só isso?",
  ["g3:0818389c"] = "A ROTA 4 fica no sopé do\\nMONTE LUA.",
  ["g3:081838c0"] = "ROTA 3\\nMONTE LUA ADIANTE",
  ["g3:081838d7"] = "Ai! Eu tropecei num POKéMON\\nrochoso, GEODUDE!",
  ["g3:08183906"] = "Vim ao MONTE LUA em busca dos\\nPOKéMON cogumelo.",
  ["g3:08183938"] = "Depois de tudo que fiz para\\ncapturá-los!",
  ["g3:08183957"] = "Talvez não haja mais cogumelos\\npor aqui.\\pAcho que peguei todos.",
  ["g3:0818399b"] = "MONTE LUA\\nEntrada do túnel",
  ["g3:081839b4"] = "ROTA 4\\nMONTE LUA - CIDADE DE CERULEAN",
  ["g3:081839d5"] = "Um soco de ferocidade\\nensurdecedora!\\pRepleto de poder destrutivo!\\pQuando a situação aperta, o\\nMEGASSOCO é o ataque mais\\ppoderoso! Você não concorda?\\pVamos!\\nDeixa eu ensiná-lo ao seu POKéMON!",
  ["g3:08183a83"] = "Você vai voltar quando entender\\no valor do MEGASSOCO.",
  ["g3:08183abf"] = "É isso aí!\\nQual POKéMON deve aprender?",
  ["g3:08183ae2"] = "Agora somos camaradas na arte\\nde dar socos!\\pÉ melhor você ir antes que aquele idiota ali, que só treina seus chutes ridículos, te veja.",
  ["g3:08183b74"] = "Um chute de ferocidade brutal!\\pRepleto de poder destrutivo!\\pNo final das contas, o MEGACHUTE\\né o ataque mais poderoso!\\pVocê não concorda?\\pMuito bem!\\nVou ensiná-lo ao seu POKéMON!",
  ["g3:08183c25"] = "Você vai voltar rastejando quando\\nperceber o valor do MEGACHUTE.",
  ["g3:08183c68"] = "Certo!\\nQual POKéMON deve aprender?",
  ["g3:08183c94"] = "Agora somos almas gêmeas na arte\\nde dar chutes!\\pÉ melhor você ir antes que aquele idiota ali, que só treina seus socos simplórios, te veja.",
  ["g3:08183d26"] = "Uau, isso é a INSÍGNIA ROCHA!\\nVocê ganhou ela do BROCK, né?\\pAlém de ser forte, o BROCK é uma\\nboa pessoa. Ele é respeitado e\\padmirado.\\pEu quero ser um LÍDER de GINÁSIO\\ncomo ele.",
  ["g3:08183dd4"] = "PASSAGEM SUBTERRÂNEA\\nCIDADE DE CERULEAN -\\pCIDADE DE VERMILION",
  ["g3:08183e04"] = "Quem está aí?\\nPara de ficar escutando a gente!",
  ["g3:08183e2a"] = "Não consegui vencer!",
  ["g3:08183e3c"] = "Bzzt...\\nBzzt...",
  ["g3:08183e4e"] = "Com licença!\\nÉ uma conversa particular!",
  ["g3:08183e79"] = "Aff!\\nEu odeio perder.",
  ["g3:08183e8d"] = "Bzzt...\\nBzzt...",
  ["g3:08183e9f"] = "Não tem muitos insetos por aqui.",
  ["g3:08183ec0"] = "Não!\\nNão brinca!",
  ["g3:08183ed4"] = "Gosto de insetos, então vou voltar\\npara a FLORESTA DE VIRIDIAN.",
  ["g3:08183f07"] = "Hã?\\nVocê quer falar comigo?",
  ["g3:08183f24"] = "Que droga...\\nNão consegui vencer o seu desafio...",
  ["g3:08183f51"] = "Eu devia trazer mais POKéMON comigo.\\nAssim me sentiria mais seguro.",
  ["g3:08183f90"] = "Eu?\\nAh, tudo bem. Vamos brincar!",
  ["g3:08183fab"] = "As coisas não deram certo...",
  ["g3:08183fc4"] = "Quero ficar mais forte.\\nQual é o seu segredo?",
  ["g3:08183ff0"] = "Nunca te vi por aqui.\\nVocê é hábil?",
  ["g3:0818401a"] = "Você é muito hábil!",
  ["g3:0818402b"] = "Meu POKéMON é fraco?\\nOu eu é que sou ruim?\\pO que você acha?",
  ["g3:08184067"] = "PASSAGEM SUBTERRÂNEA\\nCIDADE DE CERULEAN -\\pCIDADE DE VERMILION",
  ["g3:08184097"] = "PASSAGEM SUBTERRÂNEA\\nCIDADE DE CELADON -\\pCIDADE DE LAVENDER",
  ["g3:081840c5"] = "Você manda bem com os POKéMON,\\nmas como vai sua nota em química?",
  ["g3:08184100"] = "Ai!\\nPerdi!",
  ["g3:0818410e"] = "Sou melhor na escola do que nisso!",
  ["g3:0818412f"] = "Muito bem!\\nVamos jogar um jogo!",
  ["g3:0818414d"] = "Droga!\\nFoi por pouco!",
  ["g3:08184162"] = "As coisas não deram certo hoje.",
  ["g3:0818417c"] = "Você devia saber disso.\\nPrecisa de estratégia para vencer!",
  ["g3:081841b6"] = "Isso não faz sentido!",
  ["g3:081841c8"] = "Comece com GRIMER e depois...\\n... depois...",
  ["g3:081841ed"] = "Eu gosto de NIDORAN, então eu\\ncoleciono eles!",
  ["g3:08184210"] = "Por quê?\\nPor quê?!",
  ["g3:0818421b"] = "Quando os POKéMON crescem, eles\\nficam feios! Eles não deviam evoluir.",
  ["g3:08184257"] = "A escola é divertida, mas os\\nPOKéMON também são!",
  ["g3:0818427a"] = "Você me fez perceber que eu devo\\ncontinuar na escola.",
  ["g3:081842b3"] = "Eu estava pensando em pegar\\num ar fresco pra variar, mas...\\pTô preso aqui por causa dos\\nportoes de SAFFRON.",
  ["g3:08184321"] = "MEOWTH é tão fofo, miau, miau,\\nmiau!",
  ["g3:08184346"] = "Miaaau!",
  ["g3:08184350"] = "Acho que PIDGEY e RATTATA também\\nsão fofos!",
  ["g3:0818437a"] = "A gente deve parecer bobos parados\\naqui desse jeito.",
  ["g3:081843a6"] = "Olha o que você fez com meus\\npobres e fofos POKéMON!",
  ["g3:081843d2"] = "O guarda dos portoes de SAFFRON\\nnão deixa a gente passar.\\pSei que ele está só fazendo seu\\ntrabalho, mas acho que ele é\\pmalvado.",
  ["g3:08184432"] = "Sou um cara que vive falando e\\njogando!",
  ["g3:0818444f"] = "Perdi a grande chance!",
  ["g3:08184466"] = "Jogar e treinar POKéMON é como\\ncomer amendoins! Não consigo parar!",
  ["g3:081844ac"] = "Qual é o POKéMON fofo, redondo\\ne macio?",
  ["g3:081844d6"] = "Para!\\pNão precisa judiar da\\nminha CLEFAIRY!",
  ["g3:081844fd"] = "Li que CLEFAIRY evolui quando é\\nexposta a uma PEDRA DA LUA.\\pLi isso em uma REVISTA POKéMON.\\nSerá que é verdade?",
  ["g3:08184576"] = "PASSAGEM SUBTERRÂNEA\\nCIDADE DE CELADON -\\pCIDADE DE LAVENDER",
  ["g3:081845a4"] = "ELI: O poder das gêmeas é\\nfantástico. Você sabia?",
  ["g3:081845d0"] = "ELI: Mas... A gente usou o nosso\\npoder de gêmeas...",
  ["g3:081845f2"] = "ELI: Eu capturei meus POKéMON\\njunto com a ANNE!",
  ["g3:08184616"] = "ELI: A gente não pode batalhar se\\nvocê não tiver dois POKéMON.",
  ["g3:0818464a"] = "ANNE: Vamos te eletrizar com o\\nnosso poder de gêmeas!",
  ["g3:08184675"] = "ANNE: Nosso poder de gêmeas...",
  ["g3:0818468b"] = "ANNE: Tô treinando meus POKéMON\\njunto com a ELI.",
  ["g3:081846af"] = "ANNE: Oi, oi! Vamos batalhar!\\nMas traga dois POKéMON.",
  ["g3:081846e2"] = "Minha moto tá com problema, cara.",
  ["g3:081846fc"] = "Ah, cara.\\nNão tô a fim disso.",
  ["g3:08184719"] = "Tem grama presa nos meus raios,\\ncara.",
  ["g3:08184742"] = "Sai da frente ou eu te atropelo!",
  ["g3:08184767"] = "Sério mesmo, jovem?",
  ["g3:0818477a"] = "Não pensa que você é especial\\nsó por causa disso.",
  ["g3:081847b7"] = "Você tem POKéMON com você!\\nAgora eu te pego!",
  ["g3:081847df"] = "Você me enganou...",
  ["g3:081847f0"] = "O túnel adiante é totalmente\\nescuro por dentro.\\pVocê vai precisar de CLARÃO pra\\nconseguir passar por lá.",
  ["g3:08184844"] = "Quem é que está com esses\\nPOKéMON bonitos?",
  ["g3:0818487e"] = "Apaguei na hora!",
  ["g3:08184890"] = "Continua andando!",
  ["g3:0818489e"] = "Vou pelo TÚNEL DE ROCHA pra\\nchegar em LAVENDER...",
  ["g3:081848cc"] = "Não estou à altura...",
  ["g3:081848de"] = "Você também está indo para o\\nTÚNEL DE ROCHA?",
  ["g3:081848ff"] = "Não se atreva a me tratar com\\nsuperioridade!",
  ["g3:0818491c"] = "Não!\\nVocê é demais.",
  ["g3:08184931"] = "Você claramente tem talento.\\nBoa sorte pra você!",
  ["g3:0818495e"] = "Bwahaha!\\nÓtimo! Eu tava entediado, sabe!",
  ["g3:0818497f"] = "Manda ver, hein!\\pAh, espera.\\nAcabei ficando sem POKéMON!",
  ["g3:081849b0"] = "Você teve coragem de ficar\\ncara a cara comigo, hein?",
  ["g3:081849df"] = "Hahaha!\\nVocê é tem coragem, hein!",
  ["g3:08184a04"] = "O que foi isso?",
  ["g3:08184a11"] = "Hahaha!\\nAs crianças têm que ser duronas!",
  ["g3:08184a2f"] = "Eu acordava cedo todo dia pra criar\\nmeus POKéMON desde os casulos!",
  ["g3:08184a6a"] = "O QUÊ?!\\pFoi tudo perda de tempo?!",
  ["g3:08184a8c"] = "Tenho que capturar mais do que\\ninsetos pra ficar mais forte...",
  ["g3:08184abe"] = "Hahahaha!\\nPode vir!",
  ["g3:08184ad5"] = "Hahahaha!\\nFoi uma vitória justa!",
  ["g3:08184af1"] = "Hahahaha! Nós, caras duroes,\\nestamos sempre rindo!",
  ["g3:08184b18"] = "Vão, meus super-POKéMON INSETOS!",
  ["g3:08184b32"] = "Meus insetos...",
  ["g3:08184b3b"] = "Se você não gosta de POKéMON\\nINSETO, você me irrita!",
  ["g3:08184b66"] = "ROTA 9\\nCIDADE DE CERULEAN -\\pTÚNEL DE ROCHA",
  ["g3:08184b8a"] = "Uau, você veio até aqui?\\nVocê também é POKéMANÍACO?\\pQuer ver minha coleção?",
  ["g3:08184be5"] = "Humph.\\nEu não estou bravo!",
  ["g3:08184bfb"] = "Tenho POKéMON mais raros em casa!",
  ["g3:08184c1d"] = "Ha-hahah-ah-ha!",
  ["g3:08184c2d"] = "Ha-haha!\\nNão estou rindo!\\pHaha-ha-tchim!",
  ["g3:08184c60"] = "Haha-ha-tchim!\\nHa-tchim!\\pSnif!",
  ["g3:08184c86"] = "Oi, criança!\\nQuer ver meus POKéMON?",
  ["g3:08184ca7"] = "Ah, não!\\nMeus POKéMON!",
  ["g3:08184cbb"] = "Não gosto de você. Não gosto de\\nninguém que é melhor do que eu!",
  ["g3:08184cf1"] = "Já fui em um GINÁSIO POKéMON\\nalgumas vezes.\\p... Mas eu sempre perco.",
  ["g3:08184d31"] = "Ahh!\\nDepois de todo o meu treino!",
  ["g3:08184d4d"] = "Vi alguns POKéMANÍACOS rondando\\npor aqui.\\pConsegue imaginar? Eles?\\nAqui nas montanhas?",
  ["g3:08184daa"] = "Ah!\\nO ar da montanha é delicioso!",
  ["g3:08184dce"] = "Isso clareou minha mente!",
  ["g3:08184de4"] = "Me sento cheio de ar da montanha!",
  ["g3:08184e04"] = "Me sinto um pouco tonta.\\nFaz tempo que não faço trilha.",
  ["g3:08184e3b"] = "Tô muito cansada.\\nNão tava preparada pra isso.",
  ["g3:08184e5e"] = "Os POKéMON aqui nas montanhas\\nsão tão robustos...\\pEu queria que existissem POKéMON\\ncor-de-rosa com estampas florais!",
  ["g3:08184ec5"] = "TÚNEL DE ROCHA\\nDesvio para a CIDADE DE LAVENDER",
  ["g3:08184ee9"] = "TÚNEL DE ROCHA",
  ["g3:08184ef5"] = "USINA ELÉTRICA",
  ["g3:08184f01"] = "Vencer, perder ou empatar!",
  ["g3:08184f15"] = "Atcha!\\nNão foi do jeito que eu queria!",
  ["g3:08184f2e"] = "POKéMON é a vida!\\nE viver é jogar!",
  ["g3:08184f5d"] = "Competição!\\nNão me canso disso!",
  ["g3:08184f7e"] = "Eu tinha uma chance!",
  ["g3:08184f8e"] = "Não dá pra ser covarde no mundo\\ndos POKéMON!",
  ["g3:08184fbd"] = "Vamos lá, mas sem trapacear!",
  ["g3:08184fd8"] = "Hã?\\nIsso não tá certo!",
  ["g3:08184fef"] = "Fiz o meu melhor.\\nNão tenho arrependimentos.",
  ["g3:08185011"] = "Cuidado!\\nEstou passando alguns cabos!",
  ["g3:08185037"] = "Isso foi eletrizante!",
  ["g3:0818504a"] = "Fala pra todo mundo economizar\\nenergia!",
  ["g3:0818506a"] = "Acabei de me tornar um TREINADOR.\\nMas acho que consigo vencer.",
  ["g3:0818509b"] = "Meus POKéMON não venceram...\\nSerá que eles ainda não cresceram\\po suficiente?",
  ["g3:081850cf"] = "E agora?\\nMe deixa em paz!",
  ["g3:081850e9"] = "Fwahaha!\\nEu nunca perdi!",
  ["g3:08185105"] = "Minha primeira derrota!",
  ["g3:08185114"] = "Você só teve sorte, só isso.",
  ["g3:08185135"] = "Eu nunca venci...",
  ["g3:0818514e"] = "Eu já esperava por isso...",
  ["g3:08185161"] = "Tive azar, como sempre.",
  ["g3:0818517b"] = "Sou o melhor da minha turma.\\nTreino todas as manhãs.",
  ["g3:081851ac"] = "Droga!\\nMeus POKéMON precisam ficar\\pmais fortes!",
  ["g3:081851d2"] = "Tem um POKéMON gordinho que\\ndesce das montanhas.\\pAposto que ele seria forte se\\nvocê conseguisse capturá-lo.",
  ["g3:08185236"] = "Cuidado com os fios energizados!",
  ["g3:08185250"] = "Uau!\\nVocê é como uma faísca!",
  ["g3:08185266"] = "Bem, é melhor eu voltar ao\\ntrabalho.",
  ["g3:08185285"] = "Criei meus POKéMON com cuidado.\\nEles devem estar prontos agora!",
  ["g3:081852c1"] = "Tchau!\\nObrigado e até mais!",
  ["g3:081852e3"] = "Tsc...\\nÉ melhor eu procurar uns mais fortes!",
  ["g3:08185308"] = "TÚNEL DOS DIGLETT",
  ["g3:08185317"] = "Um POKéMON está deitado em um\\nsono profundo e confortável.",
  ["g3:08185354"] = "SNORLAX acordou!\\pEle partiu pra cima, cheio de\\nmau humor!",
  ["g3:08185383"] = "SNORLAX se acalmou.\\nDeu um enorme bocejo...\\pE voltou para as montanhas.",
  ["g3:081853cc"] = "Você quer usar a POKéFLAUTA?",
  ["g3:081853e8"] = "{PLAYER} tocou a POKéFLAUTA.",
  ["g3:08185402"] = "Isso aí!\\nAlguma coisa mordeu a isca!",
  ["g3:0818541b"] = "Tsc!\\nEra só um peixinho...",
  ["g3:08185432"] = "Espera aí!\\nMinha linha enroscou!",
  ["g3:0818544e"] = "Tenha calma.\\nPescar é um jogo de paciência.",
  ["g3:08185475"] = "Esse escapou!",
  ["g3:08185488"] = "Com uma VARA melhor, eu poderia\\npegar POKéMON melhores...",
  ["g3:081854b9"] = "Tô procurando uma PEDRA DA LUA.\\nVocê encontrou alguma?",
  ["g3:081854ed"] = "Ai!",
  ["g3:081854f2"] = "Eu poderia ter feito meu POKéMON\\nevoluir com uma PEDRA DA LUA.\\pAí eu aposto que eu teria vencido.",
  ["g3:08185547"] = "Eletricidade é a minha\\nespecialidade.\\pMas eu não sei nada sobre POKéMON\\ndo mar.",
  ["g3:0818559b"] = "Fui desconectado!",
  ["g3:081855a6"] = "A água conduz eletricidade, então\\nvocê deve eletrocutar os POKéMON\\pdo mar.",
  ["g3:081855e1"] = "O MANÍACO POR PESCA contra\\nTREINADOR POKéMON!",
  ["g3:08185606"] = "Peguei pesado demais!",
  ["g3:08185616"] = "Acho que a gente fica bom naquilo\\nque gosta.\\pBem, você me venceu nos POKéMON,\\nmas em pesca, ninguém me supera.",
  ["g3:08185682"] = "Eu amo pescar, não me entenda mal.\\pMas seria melhor se eu também\\ntivesse mais trabalho.",
  ["g3:081856d0"] = "Não é fácil...",
  ["g3:081856df"] = "Tudo bem.\\nPerder não me incomoda mais.",
  ["g3:0818570e"] = "O que vai fisgar?\\nVocê nunca sabe o que pode pegar!",
  ["g3:08185744"] = "Perdi!",
  ["g3:0818574d"] = "O que, MAGIKARP?\\pEu pego eles o tempo todo, claro.\\nMas, cara, como são fraquinhos.",
  ["g3:08185797"] = "ROTA 12\\nAo norte está LAVENDER",
  ["g3:081857b3"] = "ÁREA DE PESCA ESPORTIVA",
  ["g3:081857c5"] = "JES: Se eu vencer, vou pedir a\\nGIA em casamento.",
  ["g3:081857f1"] = "JES: Ah, por favor, por que você\\nnão podia deixar a gente vencer?",
  ["g3:0818581f"] = "JES: Ah, GIA, me perdoa, meu amor!",
  ["g3:08185842"] = "JES: GIA e eu vamos ficar juntos\\npra sempre.\\pNão vamos batalhar a menos que\\nvocê tenha dois POKéMON.",
  ["g3:081858a6"] = "GIA: Ei, JES...\\pSe a gente vencer, eu me caso\\ncom você!",
  ["g3:081858d0"] = "GIA: Ah, mas por quê?",
  ["g3:081858e2"] = "GIA: JES, seu bobo!\\nVocê estragou tudo!",
  ["g3:08185908"] = "GIA: Eu não suporto batalhar sem o\\nmeu JES!\\pVocê não tem mais um POKéMON?",
  ["g3:08185955"] = "Meus POKéMON pássaros querem\\nbatalhar com você!",
  ["g3:0818597e"] = "Minha combinação de PIDGEY e\\nPIDGEOTTO perdeu?",
  ["g3:081859a2"] = "Meus POKéMON parecem felizes,\\nmesmo tendo perdido.",
  ["g3:081859cf"] = "Disseram que eu sou boa pra uma\\ncriança.",
  ["g3:081859ec"] = "Ahh!\\nEu perdi!",
  ["g3:081859f9"] = "Quero me tornar um boa TREINADORA.\\nVou treinar muito, pode apostar.",
  ["g3:08185a37"] = "Uau!\\nSuas INSÍGNIAS são muito legais!",
  ["g3:08185a56"] = "Não foi o bastante!",
  ["g3:08185a62"] = "Você conseguiu essas INSÍGNIAS com\\nos LÍDERES de GINÁSIO. Eu sei!",
  ["g3:08185a91"] = "Meus POKéMON fofos querem conhecer\\nvocê.",
  ["g3:08185ac1"] = "Mandou bem!\\nVocê venceu de lavada!",
  ["g3:08185ade"] = "Você precisa fazer os POKéMON\\nbatalharem pra deixá-los mais fortes.",
  ["g3:08185b12"] = "Encontrei um CARBOIDRATO em uma\\ncaverna uma vez, enquanto explorava.",
  ["g3:08185b48"] = "Ah, que pena!\\nMandei mal!",
  ["g3:08185b67"] = "O CARBOIDRATO aumentou a\\nVELOCIDADE do meu POKéMON.",
  ["g3:08185b8f"] = "Eu não vou perder. Não enquanto\\no vento estiver a meu favor!",
  ["g3:08185bca"] = "O vento mudou!",
  ["g3:08185bdb"] = "Tô acabado.\\nAcho que vou VOAR pra casa.",
  ["g3:08185bfc"] = "Claro, eu brinco com você,\\namorzinho.",
  ["g3:08185c1f"] = "Ah!\\nDanado!",
  ["g3:08185c35"] = "Qual será que é mais forte, os\\nPOKéMON machos ou as fêmeas?",
  ["g3:08185c69"] = "Quer fazer uma batalha POKéMON\\ncomigo?",
  ["g3:08185c95"] = "Já acabou?",
  ["g3:08185ca8"] = "Na verdade, eu não sei nada sobre\\nPOKéMON.\\pOs que eu tenho... eu só escolhi\\npela aparência!",
  ["g3:08185d05"] = "O que cê tá olhando?",
  ["g3:08185d1d"] = "Droga!\\nAs marchas travaram!",
  ["g3:08185d33"] = "Cai fora!",
  ["g3:08185d3d"] = "Sempre uso os POKéMON pássaro.\\nMe dediquei totalmente a eles.",
  ["g3:08185d7b"] = "Tô sem força!",
  ["g3:08185d89"] = "Queria poder voar como PIDGEY\\ne PIDGEOTTO...",
  ["g3:08185db7"] = "DICAS PARA TREINADORES\\pEi, ei!\\nOlhe à esquerda deste cartaz!",
  ["g3:08185def"] = "DICAS PARA TREINADORES\\pUse SELECT para trocar os itens\\nna janela de ITENS.",
  ["g3:08185e2c"] = "ROTA 13\\nAo norte está a PONTE DO SILÊNCIO",
  ["g3:08185e4d"] = "Você precisa usar MTs para ensinar\\nbons movimentos aos POKéMON.",
  ["g3:08185e81"] = "Ainda não são bons o bastante.",
  ["g3:08185e9c"] = "Você tem algumas MOs, certo?\\nOs POKéMON não esquecem esses\\pmovimentos facilmente.",
  ["g3:08185edf"] = "Meus POKéMON pássaros devem estar\\nprontos para a batalha.",
  ["g3:08185f0b"] = "Ainda não estão prontos!",
  ["g3:08185f1a"] = "Meus POKéMON pássaros precisam\\naprender movimentos melhores.",
  ["g3:08185f46"] = "MTs estão sendo vendidas no\\nSHOPPING DE CELADON.\\pMTs não são tão raras, mas poucas\\npessoas têm MOs.",
  ["g3:08185fae"] = "Ah, que chato!",
  ["g3:08185fbb"] = "Tente ensinar aos POKéMON um\\nmovimento do mesmo tipo que eles.\\pParece que isso aumenta o poder\\ndo movimento.",
  ["g3:08186021"] = "Você ensinou seus POKéMON pássaros\\na VOAR?\\pAssim você poderá alçar voo com\\neles pelo céu!",
  ["g3:0818607c"] = "Derrubado em chamas!",
  ["g3:08186091"] = "Os POKéMON pássaros são meu único\\ne verdadeiro amor.\\pNão quero treinar mais nenhum outro\\ntipo.",
  ["g3:081860d9"] = "Você já ouviu a lenda das miragens\\naladas?",
  ["g3:0818610a"] = "Por quê?\\nPor que eu perdi?",
  ["g3:0818611d"] = "Pois bem, as miragens aladas são\\nos POKéMON pássaros lendários.\\pSão três deles: ARTICUNO, ZAPDOS\\ne MOLTRES.",
  ["g3:0818618e"] = "Não é muito a minha praia, mas\\ntudo bem. Vamos lá!",
  ["g3:081861b3"] = "Eu sabia!",
  ["g3:081861be"] = "Vencer, perder... É insignificante\\nsob este céu enorme.",
  ["g3:081861f7"] = "Bora, bora!\\nVamos, vamos, vamos!",
  ["g3:08186223"] = "Arrg!\\nPerdi! Cai fora!",
  ["g3:08186239"] = "O que, o que, o quê?\\nO que você ainda quer?",
  ["g3:08186263"] = "Preciso passar o tempo.\\nCala a boca e vamos batalhar.",
  ["g3:08186291"] = "O quê?\\nVocê?!",
  ["g3:0818629d"] = "Treinar POKéMON é um saco, cara.",
  ["g3:081862bd"] = "A gente anda de moto por aqui\\npor causa dos espaços abertos.",
  ["g3:081862ef"] = "Tombei!",
  ["g3:081862f8"] = "É legal você ter deixado seus\\nPOKéMON tão fortes.\\pO mais forte vence!\\nE você sabe disso!",
  ["g3:08186344"] = "Batalha de POKéMON?\\nLegal! Vamos batalhar!",
  ["g3:08186362"] = "Demais!",
  ["g3:0818636e"] = "Você sabe quem venceria,\\neu e você um contra um!",
  ["g3:08186399"] = "ROTA 14\\nAo oeste está a CIDADE DE FUCHSIA",
  ["g3:081863b7"] = "KIRI: JAN, vamos dar o nosso\\nmáximo juntos!",
  ["g3:081863ea"] = "KIRI: Snif...\\nA gente perdeu, né?",
  ["g3:0818640d"] = "KIRI: A gente perdeu por minha\\ncausa?",
  ["g3:0818642e"] = "KIRI: A gente pode batalhar se\\nvocê tiver dois POKéMON.",
  ["g3:0818645b"] = "JAN: KIRI, lá vamos!\\nA gente tem que se esforçar!",
  ["g3:08186487"] = "JAN: Eeeeh!\\nQue injusto!",
  ["g3:0818649c"] = "JAN: KIRI, não chora! Da próxima\\nvez a gente vai se esforçar mais.",
  ["g3:081864d3"] = "JAN: Você quer batalhar?\\nVocê não tem POKéMON suficiente.",
  ["g3:0818650b"] = "Acabei de conseguir alguns POKéMON\\nem trocas. Posso testá-los com você?",
  ["g3:08186549"] = "Não fui boa o bastante!",
  ["g3:0818655a"] = "Você não pode mudar o apelido de\\nnenhum POKéMON que recebeu em\\puma troca.\\pSó o TREINADOR original pode mudar\\no apelido.",
  ["g3:081865d3"] = "Você parece ser gentil, então acho\\nque posso te vencer.\\pVou tentar!",
  ["g3:08186612"] = "Não, eu errei!",
  ["g3:0818661d"] = "Tenho medo dos MOTOQUEIROS.\\nEles parecem tão feios e malvados!",
  ["g3:0818664f"] = "Quando eu assobio, consigo chamar\\nPOKéMON pássaros.",
  ["g3:0818667a"] = "Ai!\\nTrágico!",
  ["g3:0818668d"] = "Talvez eu não leve jeito para\\nbatalhas. Acho que não é comigo.",
  ["g3:081866d1"] = "Hmm? Meus pássaros estão tremendo!\\nVocê é hábil, não é?",
  ["g3:08186707"] = "Como eu imaginei!",
  ["g3:0818671a"] = "Isso é tão óbvio que você deve\\nsaber, mas...\\pMovimentos como TERREMOTO\\ne FISSURA não têm efeito em\\pPOKéMON pássaros.",
  ["g3:0818678b"] = "Ah, você é uma gracinha! Tão\\nadorável quanto um POKéMON fofinho!",
  ["g3:081867c1"] = "Você também parecia ter tanta fofura!",
  ["g3:081867da"] = "Eu te perdoo.\\nEu aguento.\\pJá sou uma garota grandinha.",
  ["g3:0818680c"] = "Crio POKéMON para me proteger,\\nporque moro sozinha.",
  ["g3:08186841"] = "Para mim, POKéMON não é sobre\\nvencer ou perder.",
  ["g3:0818686f"] = "Adoro quando meus POKéMON me\\nrecebem quando chego em casa.\\pÉ tão reconfortante.",
  ["g3:081868b6"] = "Ei, jovem! Vamos lá!\\nAcabei de pegar esses de um otário!",
  ["g3:081868e8"] = "Por que não?",
  ["g3:081868f1"] = "A vida é curta demais.\\nÉ maneiro viver fora da lei.\\pA EQUIPE ROCKET MANDA!",
  ["g3:08186936"] = "Passa todo o seu dinheiro quando\\nvocê perder pra mim, jovem!",
  ["g3:08186968"] = "Não pode ser verdade!",
  ["g3:0818697c"] = "Só tava brincando sobre o dinheiro.\\nNão precisa me levar tão a sério.",
  ["g3:081869ba"] = "Sabe o que é legal e tá na moda?\\nTrocar POKéMON!",
  ["g3:081869e6"] = "Eu disse trocar!",
  ["g3:081869f4"] = "Eu troco POKéMON com meus amigos\\no tempo todo.",
  ["g3:08186a22"] = "Quer brincar com meus POKéMON?",
  ["g3:08186a40"] = "Fui impaciente demais!",
  ["g3:08186a55"] = "Vou treinar com pessoas mais fracas.",
  ["g3:08186a77"] = "ROTA 15\\nAo oeste está a CIDADE DE FUCHSIA",
  ["g3:08186a95"] = "MYA: Que perfeito. Pode me\\najudar a treinar meu irmãozinho?",
  ["g3:08186acb"] = "MYA: RON, você precisa se concentrar!\\nPresta atenção no que está fazendo!",
  ["g3:08186b0a"] = "MYA: Certo, vamos intensificar.\\nVou aumentar o nosso treino!",
  ["g3:08186b46"] = "MYA: Você quer desafiar a gente?\\nMas você vai precisar de dois\\pPOKéMON.",
  ["g3:08186b89"] = "RON: Minha irmã fica assustadora\\nquando a gente perde.",
  ["g3:08186bb1"] = "RON: Ah, não, não...\\nMana, me desculpa!",
  ["g3:08186bd2"] = "RON: Ah, argh...\\nQueria ter uma irmã legal...",
  ["g3:08186bfe"] = "RON: Você queria batalhar comigo\\ne com a minha irmã?\\pEntao você vai precisar de dois\\nPOKéMON.",
  ["g3:08186c4d"] = "O que você quer?",
  ["g3:08186c5f"] = "Não se atreva a rir!",
  ["g3:08186c75"] = "A gente gosta de ficar aqui.\\nO que você tem a ver com isso?",
  ["g3:08186ca2"] = "Bela BIKE!\\nPassa ela pra cá!",
  ["g3:08186cbb"] = "Foi nocaute!",
  ["g3:08186cc5"] = "Esquece, quem precisa da sua\\nBIKE!",
  ["g3:08186ce5"] = "Vem cá brincar, jovem!",
  ["g3:08186d06"] = "Peste!",
  ["g3:08186d16"] = "Eu odeio perder!\\nSai da minha frente!",
  ["g3:08186d39"] = "Ei, você esbarrou em mim!",
  ["g3:08186d52"] = "Cabum!",
  ["g3:08186d5a"] = "A gente vai continuar por aqui,\\nmesmo que você não goste.\\pVocê pode ir de FUCHSIA até\\nVERMILION seguindo pela costa.",
  ["g3:08186dd9"] = "Tô com fome e de mau humor!\\nPreciso de um saco de pancadas!",
  ["g3:08186e0d"] = "Ruim, ruim, muito ruim!",
  ["g3:08186e1c"] = "Se for pra eu ter POKéMON, que\\neles ao menos sejam ferozes.\\pEu usaria eles pra deixar meus\\ninimigos em pedaços.",
  ["g3:08186e86"] = "E aí!\\nVamos se divertir!",
  ["g3:08186eb4"] = "Não me irrita!",
  ["g3:08186ec7"] = "Me divirto importunando as pessoas\\ncom meus POKéMON fedorentos.\\pEles são ótimos pra assustar a\\ngalera e ainda mordem.",
  ["g3:08186f3d"] = "Um POKéMON está deitado em um\\nsono profundo e confortável.",
  ["g3:08186f7a"] = "Aproveite a descida!\\nCICLOVIA",
  ["g3:08186f98"] = "ROTA 16\\nCIDADE DE CELADON -\\pCIDADE DE FUCHSIA",
  ["g3:08186fbd"] = "JED: Nosso amor não conhece limites.\\nEstamos apaixonados e fazemos\\pquestao de mostrar!",
  ["g3:08186ffa"] = "JED: Ah, não!\\nMeu amor me viu como um perdedor!",
  ["g3:08187027"] = "JED: Escuta, LEA. Você precisa se\\nconcentrar menos em mim.",
  ["g3:08187057"] = "JED: Você só tem um POKéMON?\\nNão existe amor no seu coração?",
  ["g3:08187097"] = "LEA: Às vezes, a intensidade do\\nnosso amor me assusta.",
  ["g3:081870cc"] = "LEA: Ahh! Mas o JED fica incrível\\nmesmo quando perde!",
  ["g3:081870f9"] = "LEA: Ehehe, me desculpa.\\nO JED é tão incrível.",
  ["g3:08187120"] = "LEA: Ah, você não tem dois\\nPOKéMON com você?\\pNão é solitário pra você ou\\npro seu POKéMON?",
  ["g3:0818717e"] = "Não dá pra ficar rico rápido\\nbatalhando contra crianças.",
  ["g3:081871ae"] = "Tô acabado!",
  ["g3:081871ba"] = "Você pode encontrar coisas boas\\nlargadas pela CICLOVIA.\\pDá pra ganhar um bom dinheiro\\npegando e vendendo elas.",
  ["g3:08187228"] = "Tenho muito orgulho do meu corpo,\\njovem. Vamos nessa!",
  ["g3:08187254"] = "Uau!",
  ["g3:0818725a"] = "Posso te empurrar pra fora daqui\\ncom uma barrigada!",
  ["g3:0818727d"] = "Você está indo para FUCHSIA?",
  ["g3:08187295"] = "Capotei feio!",
  ["g3:081872a5"] = "Eu adoro descer a ladeira correndo!",
  ["g3:081872bd"] = "Nós somos MOTOQUEIROS!\\nA gente manda nas estradas, cara!",
  ["g3:081872e3"] = "Fui torrado!",
  ["g3:081872eb"] = "Você está em busca de aventura?",
  ["g3:0818730a"] = "Deixa o VOLTORB te eletrificar!",
  ["g3:08187325"] = "Fui aterrado!",
  ["g3:08187333"] = "Eu consegui meu VOLTORB na\\nUSINA ELÉTRICA abandonada.",
  ["g3:08187362"] = "Eu aumentei o nível do meu POKéMON,\\nmas ele não evolui. Por quê?",
  ["g3:08187395"] = "Mas que droga!",
  ["g3:0818739f"] = "Talvez alguns POKéMON precisem de\\nPEDRAS elementares para evoluir.",
  ["g3:081873d1"] = "Preciso de um pouco de exercício!",
  ["g3:081873eb"] = "Oof!\\nFoi um bom treino!",
  ["g3:081873ff"] = "Eu aposto que perdi peso!",
  ["g3:0818741d"] = "Seja rebelde!",
  ["g3:08187429"] = "Aaaargh!",
  ["g3:08187432"] = "Prepare-se pra lutar pelo que\\nacredita!",
  ["g3:08187456"] = "Bela BIKE!\\nÉ boa de pedalar?",
  ["g3:08187472"] = "Droga!",
  ["g3:08187479"] = "A descida torna difícil controlar a\\ndireção.",
  ["g3:0818749b"] = "Cai fora, jovem!\\nTô exausto!",
  ["g3:081874b6"] = "Você tá com satisfação?",
  ["g3:081874c9"] = "Tenho que tirar um cochilo!",
  ["g3:081874e4"] = "É um aviso.\\pCuidado com itens largados.",
  ["g3:08187512"] = "DICAS PARA TREINADORES\\pTodos os POKéMON são únicos.\\pMesmo POKéMON da mesma espécie e\\nnível crescem em ritmos diferentes.",
  ["g3:0818757b"] = "DICAS PARA TREINADORES\\pAperte o Botao B para ficar parado\\nenquanto estiver em uma ladeira.",
  ["g3:081875be"] = "ROTA 17\\nCIDADE DE CELADON -\\pCIDADE DE FUCHSIA",
  ["g3:081875e3"] = "É um aviso!\\pNão jogue a toalha!\\nJogue POKé BOLAS!",
  ["g3:08187622"] = "CICLOVIA\\nA descida termina aqui!",
  ["g3:08187640"] = "Eu sempre verifico cada área com\\ngrama em busca de novos POKéMON.",
  ["g3:08187672"] = "Tsc!",
  ["g3:08187677"] = "Eu queria ter uma BICICLETA!",
  ["g3:0818768c"] = "Cucuru-cu! E aí, gostou do meu\\ncanto de pássaro?",
  ["g3:081876b3"] = "Pra que fui me meter com você?!",
  ["g3:081876c5"] = "Eu coleciono POKéMON do mar nos fins\\nde semana, já que o mar é tão perto.",
  ["g3:08187704"] = "Esse é o meu território!\\nCai fora daqui!",
  ["g3:08187726"] = "Droga!",
  ["g3:0818772c"] = "Essa é a minha área favorita para\\ncapturar POKéMON.",
  ["g3:08187757"] = "ROTA 18\\nCIDADE DE CELADON -\\pCIDADE DE FUCHSIA",
  ["g3:0818777c"] = "CICLOVIA\\nProibida a entrada de pedestres!",
  ["g3:081877a3"] = "Tenho que me exercitar e me\\naquecer antes de sair para nadar.",
  ["g3:081877df"] = "Tô aquecido!",
  ["g3:081877ee"] = "Obrigado, jovem!\\nTô pronto para nadar.",
  ["g3:08187811"] = "Ei! Vai com calma!\\nVocê vai ter um ataque do coração!",
  ["g3:0818783e"] = "Brr!\\nQue gelado!",
  ["g3:08187852"] = "Cuidado com os TENTACOOL.\\nAs picadas deles doem muito.",
  ["g3:08187884"] = "Eu adoro nadar!\\nE você?",
  ["g3:081878a5"] = "Levei um caldo!",
  ["g3:081878b1"] = "Eu consigo nadar melhor até que\\nos POKéMON marinhos.",
  ["g3:081878dd"] = "O que está além do horizonte?",
  ["g3:081878f8"] = "Glub!",
  ["g3:081878fe"] = "Tô vendo um par de ilhas lá adiante!",
  ["g3:08187925"] = "Tentei mergulhar pra pegar\\nPOKéMON, mas não rolou.",
  ["g3:08187955"] = "Socorro!",
  ["g3:0818795b"] = "Acho que você tem que pescar\\npara conseguir POKéMON do mar.",
  ["g3:08187985"] = "Eu olho pro mar pra esquecer todas\\nas coisas ruins que aconteceram.",
  ["g3:081879c3"] = "Ahh!\\nTraumático!",
  ["g3:081879d3"] = "Tô olhando pro mar pra esquecer\\no que aconteceu de ruim!",
  ["g3:08187a11"] = "Ah, eu adorei o seu POKéMON!\\nPosso ficar com ele se eu vencer?",
  ["g3:08187a44"] = "Ah!\\nPerdi!",
  ["g3:08187a50"] = "Ainda falta muito para chegar nas\\nILHAS ESPUMA...\\pQuero voltar para FUCHSIA...",
  ["g3:08187a9e"] = "Nadar é ótimo!\\nQueimaduras de sol não!",
  ["g3:08187ac1"] = "Que surpresa!",
  ["g3:08187aca"] = "Meu namorado queria nadar até as\\nILHAS ESPUMA.",
  ["g3:08187afa"] = "Olá!\\nEssas águas são traiçoeiras!",
  ["g3:08187b25"] = "Uuuh!\\nPerigoso!",
  ["g3:08187b35"] = "M-minhas pernas! Me deu cãibra!\\nBlub, blub...",
  ["g3:08187b5d"] = "Eu nadei até aqui com meus amigos...\\nTô cansada...",
  ["g3:08187b85"] = "Tô exausta...",
  ["g3:08187b94"] = "Se eu pudesse montar em um POKéMON\\nno mar, eu escolheria um LAPRAS.\\pO LAPRAS é tão grande que aposto\\nque eu nem me molharia na água.",
  ["g3:08187c06"] = "ROTA MARÍTIMA 19\\nCIDADE DE FUCHSIA - ILHAS ESPUMA",
  ["g3:08187c32"] = "LIA: Tô cuidando do meu irmão. Ele\\nacabou de se tornar um TREINADOR.",
  ["g3:08187c6f"] = "LIA: Não é assim que se trata\\no meu irmãozinho!",
  ["g3:08187c9e"] = "LIA: Você tem um irmão mais novo?\\pEspero que esteja ensinando várias\\ncoisas pra ele.",
  ["g3:08187cf2"] = "LIA: Quero batalhar junto com o\\nmeu irmãozinho.\\pVocê não tem dois POKéMON?",
  ["g3:08187d45"] = "LUC: Minha irmã me ensinou a nadar\\ne a treinar POKéMON.",
  ["g3:08187d7e"] = "LUC: Uau!\\nAlguém mais forte que a minha irmã!",
  ["g3:08187dad"] = "LUC: Minha irmã é forte e gentil.\\nAcho ela incrível!",
  ["g3:08187de8"] = "LUC: Não quero batalhar com você\\nse não for junto da minha irmã.\\pVocê não tem dois POKéMON?",
  ["g3:08187e40"] = "A água é rasa por aqui.\\nTem muita gente nadando.",
  ["g3:08187e7b"] = "Splash!",
  ["g3:08187e83"] = "Queria poder montar no meu POKéMON.\\nAposto que você nem se cansa.",
  ["g3:08187ebb"] = "As ILHAS ESPUMA são um lugar\\ntranquilo. Tô passando férias aqui.",
  ["g3:08187eed"] = "Para com isso!",
  ["g3:08187ef6"] = "Tem uma caverna enorme\\nembaixo daquela ilha.",
  ["g3:08187f24"] = "Adoro flutuar com os peixes aqui\\nentre as ondas.",
  ["g3:08187f5a"] = "Ai!",
  ["g3:08187f61"] = "Quer flutuar comigo?",
  ["g3:08187f78"] = "Você também está de férias?",
  ["g3:08187f92"] = "Sem piedade alguma!",
  ["g3:08187fa3"] = "As ILHAS ESPUMA costumavam ser uma\\núnica ilha no passado distante.",
  ["g3:08187fdb"] = "Dá uma olhada no meu físico sarado!",
  ["g3:08187ff7"] = "Tão fraco!",
  ["g3:08187ffe"] = "Eu devia ter fortalecido meu\\nPOKéMON, não a mim!",
  ["g3:0818802e"] = "Por que você montou em um\\nPOKéMON? Você não sabe nadar?",
  ["g3:0818805c"] = "Ai!\\nFui torpedeado!",
  ["g3:0818806d"] = "Montar em um POKéMON parece\\nmuito divertido!",
  ["g3:0818808e"] = "Vim montado no meu POKéMON pássaro\\naté aqui.",
  ["g3:081880ab"] = "Ah, não!\\nO que eu vou fazer agora?",
  ["g3:081880c8"] = "Meus pássaros estão exaustos.\\nEles não podem VOAR comigo de volta!",
  ["g3:081880f8"] = "Meu namorado me deu pérolas\\ngrandes.",
  ["g3:08188119"] = "Ah, não!\\nMinhas pérolas estavam neles!",
  ["g3:08188139"] = "Será que minhas pérolas vão\\ncrescer dentro de CLOYSTER?",
  ["g3:08188165"] = "Vim nadando da ILHA DE CINNABAR.\\nNão foi nada fácil, viu?",
  ["g3:081881a3"] = "Tô muito decepcionada!",
  ["g3:081881b8"] = "Os POKéMON tomaram conta de uma\\nmansao abandonada em CINNABAR.\\pAgora ela é chamada de\\nMANSÃO POKéMON.",
  ["g3:08188218"] = "CINNABAR, no oeste, tem um\\nLABORATÓRIO para POKéMON.\\pMeu papai trabalha lá.",
  ["g3:0818825c"] = "Ei!\\nVocê devia esperar!",
  ["g3:0818827b"] = "CINNABAR é uma ilha vulcânica.\\pOuvi dizer que ela surgiu do mar\\nquando um vulcão entrou em erupção.",
  ["g3:081882d1"] = "ILHAS ESPUMAS",
  ["g3:081882e1"] = "TREINADORES fortes e POKéMON de\\nÁGUA são muito comuns por aqui.\\pDizem que a MISTY do GINÁSIO de\\nCERULEAN treina neste lugar.",
  ["g3:0818835a"] = "Você quer saber se os peixes estão\\nmordendo?",
  ["g3:08188383"] = "Droga!",
  ["g3:08188389"] = "Não consigo pegar nada que preste.\\nNem um único POKéMON bom!",
  ["g3:081883c6"] = "Fiz uma grande pescaria!\\nQuer ver?",
  ["g3:081883e9"] = "Heheh, os MAGIKARP não estão à\\naltura, não é?",
  ["g3:0818841d"] = "Parece que eu só consigo pegar\\nMAGIKARP!",
  ["g3:0818843c"] = "O mar limpa meu corpo e minha alma!",
  ["g3:0818845f"] = "Ayah!",
  ["g3:08188465"] = "O mar é ótimo e tudo mais, mas\\neu também gosto das montanhas.",
  ["g3:081884d4"] = "Eu capturei meu POKéMON no mar.",
  ["g3:081884f0"] = "Tô afundando!",
  ["g3:081884ff"] = "Onde você capturou seus POKéMON?",
  ["g3:0818851f"] = "No momento, estou em uma competição\\nde triatlo.",
  ["g3:08188543"] = "Oof...\\nOof... Oof...",
  ["g3:08188555"] = "Tô exausto! Mas ainda faltam a\\ncorrida de bicicleta e a maratona!",
  ["g3:08188592"] = "Ahh!\\nSinta o sol e o vento!",
  ["g3:081885b2"] = "Ai!\\nPerdi!",
  ["g3:081885bf"] = "Tô queimado de sol até o osso!",
  ["g3:081885d8"] = "Ei, não assuste os peixes!",
  ["g3:081885f8"] = "Foi mal! É que estou frustrado por\\nnão conseguir pegar nada.",
  ["g3:08188632"] = "Poxa, não peguei nada até agora.\\nSerá que esse lugar é na verdade\\puma piscina gigante ou algo assim?",
  ["g3:0818868c"] = "Fica comigo até eu fisgar algo.",
  ["g3:081886ae"] = "Isso ajudou a passar o tempo.",
  ["g3:081886c5"] = "Ah, espera!\\nFisguei um! Isso aí!",
  ["g3:081886e2"] = "LIL: Hã? Uma batalha?\\nIAN, você não dá conta sozinho?",
  ["g3:08188712"] = "LIL: Ah, viu?\\nA gente perdeu. Tá feliz agora?",
  ["g3:08188734"] = "LIL: Tô cansada.\\nA gente já pode ir pra casa?",
  ["g3:0818875e"] = "LIL: Hein? Uma batalha?\\nNão vou me dar ao trabalho\\pde batalhar sozinha.\\pTraga dois POKéMON, tá bem?",
  ["g3:081887b4"] = "IAN: Minha irmã não se exercita\\nmuito, aí trouxe ela comigo.",
  ["g3:081887f1"] = "IAN: Ah, mana!\\nSe liga!",
  ["g3:08188812"] = "IAN: Vamos, mana!\\pVocê não vai emagrecer desse jeito!",
  ["g3:08188850"] = "IAN: A gente quer uma batalha\\ndois contra dois.\\pSerá que você pode trazer dois\\nPOKéMON?",
  ["g3:08188890"] = "{RIVAL}: E aí! {PLAYER}!\\pVocê vai para a LIGA POKéMON?\\nPode esquecer!\\pVocê nem deve ter INSÍGNIAS, né? O\\nguarda não deixar passar sem elas.\\pAliás, seus POKéMON ficaram mais\\nfortes?",
  ["g3:08188959"] = "Ahhh!\\nVocê só teve sorte!",
  ["g3:08188974"] = "Ouvi dizer que a LIGA POKéMON está\\ncheia de TREINADORES fortes.\\pTenho que descobrir como passar\\npor eles.\\pVocê devia parar de enrolar e se\\nmexer!",
  ["g3:08188a3c"] = "{RIVAL}: O quê? {PLAYER}!\\nQue surpresa te ver aqui!\\pEntao você vai para a LIGA\\nPOKéMON?\\pVocê conseguiu todas as INSÍGNIAS\\ntambém? Que legal!\\pEntao eu vou te derrotar, {PLAYER},\\ncomo um aquecimento para a\\pLIGA POKéMON!\\pVamos nessa!",
  ["g3:08188b08"] = "O quê?!\\pEu só fui descuidado!",
  ["g3:08188b29"] = "Era disso que eu precisava.\\nTô pronto pra LIGA POKéMON!\\p{PLAYER}, você tem que treinar\\nmais.\\pMas você já sabe disso!\\nTô indo. Falou!",
  ["g3:08188bff"] = "LIGA POKéMON\\nPortão principal",
  ["g3:08188c19"] = "ENTRADA da ESTRADA DA VITÓRIA -\\nLIGA POKéMON",
  ["g3:08188c3c"] = "Parabéns! Você venceu nossos cinco\\nTREINADORES do concurso!\\pVocê acabou de ganhar um prêmio\\nincrível!",
  ["g3:08188c93"] = "{PLAYER} recebeu uma PEPITA\\ndo TREINADOR misterioso!",
  ["g3:08188cc2"] = "Você não tem mais espaço!",
  ["g3:08188cdb"] = "Aliás, que tal se juntar à\\nEQUIPE ROCKET?\\pSomos um grupo de criminosos\\nprofissionais especializados em\\pPOKéMON!\\pQuer se juntar a nós?\\pTem certeza?\\pVamos lá, junte-se a nós!\\pTô mandando você entrar!\\p... Tá bom, parece que vou ter que\\nte convencer!\\pVou te fazer uma oferta que você\\nnão vai poder recusar!",
  ["g3:08188ddc"] = "Arrgh!\\nVocê é hábil!",
  ["g3:08188df1"] = "Com a sua habilidade, você se\\ntornaria um dos grandes líderes\\pda EQUIPE ROCKET.\\pVamos lá, pense na oportunidade!\\nNão deixe essa chance escapar.",
  ["g3:08188e74"] = "Vi o seu feito aqui do meio da\\ngrama!",
  ["g3:08188e94"] = "Eu já imaginava!",
  ["g3:08188ea3"] = "Me escondi porque as pessoas na\\nponte me assustaram.",
  ["g3:08188ed9"] = "Beleza! Sou o quinto!\\nVou te esmagar!",
  ["g3:08188efa"] = "Uau!\\nDemais!",
  ["g3:08188f0a"] = "Dei o meu melhor.\\nNão me arrependo de nada!",
  ["g3:08188f2c"] = "Sou a quarta!\\nVocê já se cansou?",
  ["g3:08188f46"] = "Eu também perdi!",
  ["g3:08188f53"] = "Dei o meu melhor, então não me\\narrependo!",
  ["g3:08188f76"] = "Sou o terceiro!\\nNão vou pegar leve!",
  ["g3:08188f95"] = "Ai!\\nFui esmagado!",
  ["g3:08188fa7"] = "Dei o meu melhor.\\nNão me arrependo de nada!",
  ["g3:08188fc9"] = "Sou a segunda!\\nAgora é pra valer!",
  ["g3:08188fe7"] = "Como é que eu pude perder?",
  ["g3:08188ff9"] = "Dei o meu melhor.\\nNão me arrependo de nada!",
  ["g3:0818901b"] = "O pessoal chama este lugar de\\nPONTE DA PEPITA!\\pDerrote os cinco TREINADORES e\\nganhe um prêmio incrível!\\pVocê acha que consegue?",
  ["g3:0818908c"] = "Uhul!\\nMandou bem!",
  ["g3:0818909e"] = "Dei o meu melhor.\\nNão me arrependo de nada!",
  ["g3:081890c0"] = "Os TREINADORES da região vêm aqui\\npara treinar.",
  ["g3:081890e6"] = "Você é hábil.",
  ["g3:081890f5"] = "Todo POKéMON tem fraquezas,\\naté os mais fortes.\\pPor isso é melhor treinar\\nPOKéMON de tipos diferentes.",
  ["g3:08189165"] = "Meu pai me levou a uma festa\\nótima no SANTA ANA na CIDADE\\pDE VERMILION.",
  ["g3:081891a6"] = "Não tô bravo!",
  ["g3:081891b3"] = "No SANTA ANA, eu vi TREINADORES\\ndo mundo todo.",
  ["g3:081891eb"] = "Sou um cara descolado.\\nTenho uma namorada!",
  ["g3:08189212"] = "Ah, poxa...",
  ["g3:0818921d"] = "Ah, tudo bem.\\nMinha namorada vai me animar.",
  ["g3:08189247"] = "Oi!\\nMeu namorado é descolado!",
  ["g3:08189261"] = "Minha forma física não é das\\nmelhores...",
  ["g3:08189281"] = "Queria que meu namorado fosse\\ntão bom quanto você.",
  ["g3:081892a9"] = "Tive um pressentimento... Eu sabia\\nque precisava batalhar com você!",
  ["g3:081892d9"] = "Também sabia que ia perder!",
  ["g3:081892ef"] = "Se seu POKéMON ficar confuso,\\ntroque ele.\\pÉ uma boa estratégia.",
  ["g3:08189333"] = "Minha amiga tem muitos POKéMON\\nfofos. Tô morrendo de inveja!",
  ["g3:08189364"] = "Nem tô com tanta inveja assim!",
  ["g3:08189378"] = "Você veio do MONTE LUA?\\nMe dá uma CLEFAIRY?",
  ["g3:081893a7"] = "Acabei de descer do MONTE LUA,\\nmas ainda tenho energia de sobra!",
  ["g3:081893ea"] = "Você se esforçou muito!",
  ["g3:081893fb"] = "Droga!\\nUm ZUBAT me mordeu lá na caverna.",
  ["g3:08189423"] = "Vou visitar a coleção de um\\nPOKéMANÍACO lá no cabo.",
  ["g3:08189459"] = "Você me pegou direitinho!",
  ["g3:0818947e"] = "Aquele POKéMANÍACO faz jus ao\\nnome.\\pA coleção dele tem várias espécies\\nraras de POKéMON.",
  ["g3:081894de"] = "Vai ver o BILL?\\nEntão primeiro, vamos batalhar!",
  ["g3:0818950a"] = "Você é hábil, hein.",
  ["g3:0818951c"] = "A trilha ali embaixo é um atalho\\npara a CIDADE DE CERULEAN.",
  ["g3:0818954c"] = "CABANA À BEIRA-MAR\\nBILL mora aqui!",
  ["g3:08189569"] = "Este cabo é um lugar famoso para\\nencontros.\\pMISTY, a LÍDER de GINÁSIO, adora\\neste lugar.",
  ["g3:081895c2"] = "Oi, você veio aqui só?\\pSe veio até o cabo de CERULEAN...\\nBom, devia estar com uma companhia.",
  ["g3:0818961f"] = "O tempo está maravilhoso!\\nPerfeito para uma batalha!",
  ["g3:0818964d"] = "Aiyeeeeh!",
  ["g3:08189657"] = "Por favor, não molhe meu rosto!\\nVocê vai estragar a maquiagem.",
  ["g3:0818968c"] = "Tô começando a ficar queimada...\\nde sol...",
  ["g3:081896ac"] = "Ah, você é cruel.",
  ["g3:081896c1"] = "Gostei do que está usando na cabeça.\\nTalvez eu devesse usar um também...",
  ["g3:081896f9"] = "Olhando daqui, parece que o\\nMONTE BRASA vai até o céu.",
  ["g3:08189728"] = "Não é que você é forte mesmo, hein?",
  ["g3:08189740"] = "O céu é imenso por essas bandas.",
  ["g3:08189767"] = "Dei uma pausa na natação,\\ne você vem me desafiar?",
  ["g3:081897a4"] = "Ei, mas que coisa...\\nVocê é hábil, hein!",
  ["g3:081897c5"] = "Em vez de SURFAR o tempo todo,\\nvocê devia nadar um pouco.",
  ["g3:081897ff"] = "Espera! Espera um pouco!\\nAcho que fisguei um grandão!",
  ["g3:08189833"] = "Perdi tudo de novo...",
  ["g3:0818984b"] = "Além de perder a batalha,\\no grandão também fugiu!",
  ["g3:08189883"] = "Será que você pode me ajudar\\nno meu treinamento?",
  ["g3:081898ab"] = "Você foi muito melhor do que eu.",
  ["g3:081898c4"] = "Tá claro que você é hábil.\\nEu gostei de você!",
  ["g3:081898f0"] = "Não tem um só dia em que a gente\\nnão treine!",
  ["g3:0818991b"] = "Sou uma idiota!",
  ["g3:0818992c"] = "Vou treinar ainda mais a partir\\nde agora!",
  ["g3:08189950"] = "Todas as manhãs, antes do café,\\neu nado em volta desta ilha.",
  ["g3:0818998c"] = "Oof...\\nOof...",
  ["g3:08189998"] = "Perdi porque estou exausto de\\ntanto correr...",
  ["g3:081899ce"] = "Vista-se de forma apropriada para\\na batalha! Tire essa roupa fútil!",
  ["g3:08189a0a"] = "Por que eu?!",
  ["g3:08189a13"] = "Até os artistas marciais estão\\nficando vaidosos com moda hoje\\pem dia...",
  ["g3:08189a53"] = "Sabe, tudo fica com um gosto ótimo\\nquando você tá no meio na natureza.",
  ["g3:08189a92"] = "Aaaaah, me dei mal!",
  ["g3:08189a9f"] = "A água nas regioes vulcânicas\\né deliciosa.",
  ["g3:08189acb"] = "Tô de barriga cheia do almoço,\\nque tal uma batalha para gastar\\pas energias?",
  ["g3:08189b0b"] = "Fiquei toda suada.",
  ["g3:08189b24"] = "O que eu faço?\\nJá tô morrendo de fome de novo.",
  ["g3:08189b4d"] = "KIA: Eu e meu irmão fazemos uma\\ncombinação incrível!",
  ["g3:08189b84"] = "KIA: Hã?!\\nNão acredito!",
  ["g3:08189ba3"] = "KIA: Como pode existir alguém\\nmelhor que meu irmão?",
  ["g3:08189bde"] = "KIA: Se quiser batalhar com a\\ngente, você tem que trazer pelo\\pmenos dois POKéMON.",
  ["g3:08189c33"] = "MIK: Junto com a KIA, eu não tenho\\nmedo de nada!",
  ["g3:08189c62"] = "MIK: Uau!\\nIsso é demais!",
  ["g3:08189c7e"] = "MIK: Como a minha combinação\\ncom a KIA pôde falhar?",
  ["g3:08189cab"] = "MIK: Ei, você quer batalhar com a\\ngente?\\pEntao traga dois ou mais POKéMON.",
  ["g3:08189d02"] = "Esta é a ESTRADA INCANDESCENTE.\\pEm frente está o MONTE BRASA.",
  ["g3:08189d32"] = "Acenda o fogo no seu coração!\\nSPA BRASA",
  ["g3:08189d5a"] = "Deitar e deixar-se levar pelas\\nondas... É maravilhoso.",
  ["g3:08189d8b"] = "Eu perdi...\\nÉ uma sensação horrível.",
  ["g3:08189da3"] = "O mar é agradavelmente quente\\npor aqui.",
  ["g3:08189dce"] = "As coisas boas são trazidas pela\\ncorrente do oceano até a praia.\\pÉ por isso que eu costumo vir aqui\\nprocurar o que aparece na areia.",
  ["g3:08189e42"] = "O sabor salgado do mar...\\nEle faz cócegas no meu coração.",
  ["g3:08189e72"] = "... Snif, snif...\\nSinto um cheiro desagradável...",
  ["g3:08189e9e"] = "Talvez esse fedor seja o cheiro\\nde suor do seu POKéMON...",
  ["g3:08189ed4"] = "Pra onde você tá indo com tanta\\npressa?",
  ["g3:08189efa"] = "Você está criando POKéMON\\nmaravilhosos.",
  ["g3:08189f21"] = "Se continuar por esse caminho,\\nvai acabar chegando à FLORESTA\\pDAS FRUTAS.",
  ["g3:08189f63"] = "Minha mamãe disse que eu não\\nposso nadar sem a minha boia.",
  ["g3:08189f9a"] = "Buááá!\\nBuááá!",
  ["g3:08189fa8"] = "Esse ano eu vou finalmente\\naprender a nadar!",
  ["g3:08189fdb"] = "Eba, eba!\\nPOKéMON!",
  ["g3:08189fee"] = "E agora, o que acontece?",
  ["g3:0818a000"] = "Eu acabei de vencer?\\nOu perdi?",
  ["g3:0818a01f"] = "Ah, não, não venha aqui!\\nPor favor, fique longe de mim!",
  ["g3:0818a053"] = "Tá bom, você venceu!\\nAgora pode ir embora, por favor?",
  ["g3:0818a082"] = "Um POKéMON rasgou meu maiô.\\nNão posso sair da água!",
  ["g3:0818a0c4"] = "JOY: A gente vai te mostrar qual\\né o nosso POKéMON favorito!",
  ["g3:0818a0f7"] = "JOY: Ahh...\\nMEG!",
  ["g3:0818a106"] = "JOY: Não foi divertido? Tomara que\\na gente possa batalhar de novo!",
  ["g3:0818a138"] = "JOY: Quero muito batalhar com a\\nMEG.\\pSó um POKéMON não é o bastante.",
  ["g3:0818a179"] = "MEG: A gente vai te mostrar o nosso\\nPOKéMON favorito.",
  ["g3:0818a1a3"] = "MEG: Ahh...\\nJOY!",
  ["g3:0818a1b2"] = "MEG: JOY, não foi divertido?",
  ["g3:0818a1cd"] = "MEG: Quero batalhar junto com a\\nJOY.\\pSó um POKéMON não é o bastante.",
  ["g3:0818a210"] = "FLORESTA DAS FRUTAS ADIANTE",
  ["g3:0818a223"] = "PONTE UNIÃO\\nPor favor, atravesse fazendo\\psilêncio.\\pFLORESTA DAS FRUTAS ADIANTE",
  ["g3:0818a261"] = "Somos a FEDERAÇÃO DE MOTOS de\\nKANTO! Vrum! Vavavavooom! Vrum!\\pMinha moto é fraquinha, então eu\\nmesmo tenho que fazer os barulhos\\pdo escapamento!",
  ["g3:0818a2d8"] = "Ei, ei, moça!\\nPassa um trocado pra cá!",
  ["g3:0818a307"] = "Aiyeeh!\\pQuem é você?!\\nEu... vou chamar a polícia!",
  ["g3:0818a339"] = "Aqueles MOTOQUEIROS...\\nEles foram embora?\\pAh, graças a Deus!\\nEles me deixaram apavorada!",
  ["g3:0818a38b"] = "Os MOTOQUEIROS fugiram e a PERDITA\\nfoi encontrada em segurança.\\pNo final, tudo acabou bem!",
  ["g3:0818a3e2"] = "Com estas mãos, vou criar minha\\nvitória!",
  ["g3:0818a40e"] = "Que vergonha...\\nFiquei até vermelha...",
  ["g3:0818a430"] = "Ah não, meus tubos de tinta se\\nespalharam por todo lado!",
  ["g3:0818a461"] = "Com licença!\\nEstou tentando pintar.\\pPor favor, fique fora do meu campo\\nde visão!",
  ["g3:0818a49e"] = "Essa derrota...\\nSinto como se eu fosse apagar...",
  ["g3:0818a4c6"] = "GILLIAN?\\nIncline um pouco a cabeça,\\ppor favor... Aí! É essa a\\pexpressao que eu quero!",
  ["g3:0818a50e"] = "Hmm...\\nO ângulo ainda não está certo...",
  ["g3:0818a535"] = "Ah...\\nMeus sentimentos estão tão tristes...",
  ["g3:0818a555"] = "O céu e o mar...\\nSão tão volúveis.\\pSuas expressoes mudam tanto que\\né difícil capturá-las.",
  ["g3:0818a5b9"] = "Se quer saber, estou visitando\\no retiro de uma amiga.",
  ["g3:0818a5ee"] = "Ah, nossa, que força.",
  ["g3:0818a601"] = "Acho muito prazeroso batalhar\\nrelaxando na brisa suave do mar.",
  ["g3:0818a645"] = "Tô pensando em mandar construir\\numa piscina especial para os meus\\pPOKéMON.",
  ["g3:0818a67f"] = "Oh, meu Deus do céu!",
  ["g3:0818a699"] = "Uma piscina seria ótima, mas devo\\ndizer que uma sala de sol talvez\\pfosse ainda mais sublime.",
  ["g3:0818a6da"] = "Sou um bom corredor.\\nSou muito rápido!",
  ["g3:0818a6fe"] = "Opa!\\nMe apressei demais!",
  ["g3:0818a715"] = "Quando corro com o vento,\\nparece que eu poderia voar!",
  ["g3:0818a74a"] = "Eu diria que a vida marinha aqui\\nneste resort combina comigo.",
  ["g3:0818a786"] = "Que choque!\\nVocê só pode estar brincando.",
  ["g3:0818a7ac"] = "Levando isso tão a sério...\\nQue absurdo.",
  ["g3:0818a7db"] = "SELPHY: Obrigada.\\pVocê já pode ir.",
  ["g3:0818a7fe"] = "CASA DA SELPHY",
  ["g3:0818a80d"] = "Você viaja por todos os lugares,\\nné?\\pNão está forçando demais seus\\nPOKéMON, não é?\\pDeixa eu dar uma olhada.\\n... ... ...   ... ... ...",
  ["g3:0818a88f"] = "Ah, hmm...\\nEntendo, entendo...",
  ["g3:0818a8a6"] = "Ah, impressionante.\\nVocê trata bem seus POKéMON.\\pAcho que posso confiar isto\\na você.\\pPor favor, quero que fique\\ncom isto.",
  ["g3:0818a91f"] = "{PLAYER} recebeu um OVO\\ndo homem!",
  ["g3:0818a940"] = "... Infelizmente, você não tem\\nespaço na sua equipe.\\pÉ melhor voltar para pegá-lo\\noutra hora.",
  ["g3:0818a9c0"] = "Recebi esse OVO enquanto viajava.\\pFico feliz por ter conhecido alguém\\ncomo você.",
  ["g3:0818aa0c"] = "Ah, oi.\\nQue {STR_VAR_2} fofo.\\pVê-lo me faz lembrar de uma\\ngarotinha adorável que conheci\\pdurante minhas viagens.\\pEla cuidava dos POKéMON com\\ntanto carinho... Era um anjinho.\\pO nome dela...\\nAcho que era DAISY.",
  ["g3:0818aad5"] = "Este é um ótimo lugar para criar\\nPOKéMON.",
  ["g3:0818ab0b"] = "Seus POKéMON estão crescendo\\nmuito bem!",
  ["g3:0818ab37"] = "Sabe, acho que você tem talento\\nnato para criar POKéMON.",
  ["g3:0818ab8e"] = "{PLAYER} digitou uma senha.\\p“GOLDEEN need log.”\\p... ...  ... ...  ... ...\\pOutra senha é necessário para\\nabrir a porta...",
  ["g3:0818abf4"] = "{PLAYER} digitou duas senhas.\\p“GOLDEEN need log.”\\n“Yes, nah, CHANSEY.”\\p... ...  ... ...  ... ...\\pA porta do ARMAZÉM se abriu!",
  ["g3:0818ac62"] = "A porta do ARMAZÉM já está aberta.",
  ["g3:0818ac88"] = "Esta área é estritamente proibida!\\nFora daqui!",
  ["g3:0818acb3"] = "Sério mesmo?",
  ["g3:0818acc5"] = "Você não tem nada pra fazer aqui!\\nVá pra casa!",
  ["g3:0818acf0"] = "Não tem nada além do nosso\\nARMAZÉM depois daqui.\\pEntao, o que te traz aqui?",
  ["g3:0818ad39"] = "Não era pra isso ter acontecido...",
  ["g3:0818ad59"] = "Você quer saber o que tem dentro\\ndesse ARMAZÉM?\\pÉ melhor que não saiba.\\nDigo isso pro seu próprio bem.",
  ["g3:0818adc6"] = "Mesmo se passar por mim, só vai\\nestar perdendo tempo.",
  ["g3:0818adfb"] = "Ah, isso me deixa furiosa!",
  ["g3:0818ae16"] = "Você não vai conseguir entrar\\nsem as senhas mesmo.",
  ["g3:0818ae50"] = "Sou o mais velho dos IRMÃOS\\nPÁSSARO.\\pA melhor coisa sobre as aves...\\nCom certeza é o bico.",
  ["g3:0818aea8"] = "Ah, tão afiado!",
  ["g3:0818aeb6"] = "Você pode voar para a\\nILHA QUATRO daqui.",
  ["g3:0818aedc"] = "Sou o irmão do meio dos IRMÃOS\\nPÁSSARO.\\pA melhor coisa sobre as aves...\\nCom certeza são as asas.",
  ["g3:0818af39"] = "Flap-flap!",
  ["g3:0818af45"] = "Tinha um cara bem cabisbaixo\\npor ali.",
  ["g3:0818af72"] = "Sou o mais novo dos IRMÃOS\\nPÁSSARO.\\pA melhor coisa sobre as aves...\\nCom certeza é a penugem.",
  ["g3:0818afcc"] = "A penugem é tão macia...\\nMe dá até sono...",
  ["g3:0818aff2"] = "Fico cheio de alegria quando os\\nPOKéMON pássaro pedem pra brincar\\pde forma tão fofa...",
  ["g3:0818b02e"] = "Snif, snif...",
  ["g3:0818b03c"] = "Olá...\\nSeus POKéMON parecem saudáveis...",
  ["g3:0818b05e"] = "Foi aqui que eu enterrei meu ONIX...\\nEle se chamava TECTONIX...",
  ["g3:0818b095"] = "As palavras “Aqui jaz TECTONIX” estão esculpidas em uma pedra.\\pUma LIMONADA foi colocada aqui como uma oferenda, em frente à tumba.",
  ["g3:0818b105"] = "Você gostaria de deixar outra\\nLIMONADA como oferenda?",
  ["g3:0818b13e"] = "{PLAYER} colocou uma lata de\\nLIMONADA em frente ao túmulo.",
  ["g3:0818b171"] = "O-obrigado...\\pEssa era a bebida favorita do\\nmeu TECTONIX...\\pEu nem te conheço, mas esse\\nseu gesto de bondade...\\pMe animou um pouco.\\pPor favor, aceite isto como\\nforma de agradecimento.",
  ["g3:0818b219"] = "Por favor, cuide bem dos seus\\nPOKéMON também.",
  ["g3:0818b23e"] = "Se você não tiver espaço agora,\\neu fico guardando pra você.",
  ["g3:0818b282"] = "Ah, é você daquela vez...\\pAinda tenho aquilo que queria\\nte dar como agradecimento.",
  ["g3:0818b2da"] = "Snif, snif...\\p... ... ...\\nTECTONIX...",
  ["g3:0818b2f8"] = "Pedras e rochas estão organizadamente empilhadas formando um marco de pedras.\\pAs palavras “Aqui jaz TECTONIX” estão esculpidas em uma pedra.",
  ["g3:0818b35a"] = "Não tem POKéMON raros por essas\\nbandas! Nem unzinho!\\pIsso me deixa furioso, cara.\\nVou descontar em você!",
  ["g3:0818b3c2"] = "... Hã?",
  ["g3:0818b3c8"] = "Me fala, você não viu nenhum\\nPOKéMON raro, viu?",
  ["g3:0818b400"] = "Não estou tendo sorte nenhuma.\\nUma batalha seria uma boa\\pmudança de ritmo!",
  ["g3:0818b43b"] = "Nada, sem sorte nenhuma...",
  ["g3:0818b451"] = "Mas também não posso simplesmente\\nvoltar pra casa sem capturar nada.",
  ["g3:0818b48f"] = "Oof... Oof...\\pEu nadei até aqui direto do\\nPORTO DA ILHA SEIS.",
  ["g3:0818b4c5"] = "Oof...\\nOof...",
  ["g3:0818b4d1"] = "Ainda estou só na metade do\\ncaminho... estou exausto...",
  ["g3:0818b4fa"] = "Não é tão fácil mandar os POKéMON\\npra fora enquanto se nada, sabia?",
  ["g3:0818b539"] = "Não perdi pra você na natação.\\nIsso não me incomoda.",
  ["g3:0818b573"] = "Você está indo para a ilha logo\\nadiante?\\pNão vi nada de interessante por lá.",
  ["g3:0818b5c8"] = "AVA: Vamos fazer uma batalha\\nmarítima de dois contra dois!",
  ["g3:0818b5f4"] = "AVA: Ah, você é incrível!\\nE melhor ainda, está só!",
  ["g3:0818b62e"] = "AVA: Sabe, eu prefiro o mar a\\nqualquer piscina.",
  ["g3:0818b660"] = "AVA: Você vai desafiar a gente\\npara uma batalha?\\pVocê vai precisar de pelo menos\\ndois POKéMON se quiser fazer isso.",
  ["g3:0818b6c1"] = "GEB: Maninha, me ajuda!\\nPor favor, batalha comigo!",
  ["g3:0818b6ef"] = "GEB: Uau, maninha, que jovem hábil!",
  ["g3:0818b720"] = "GEB: Tô me segurando na minha\\nirmã porque não alcanço o fundo.",
  ["g3:0818b762"] = "GEB: Por favor, batalhe contra mim\\ne minha irmã!\\p... Ah, você não tem dois POKéMON?",
  ["g3:0818b7b0"] = "... Ha?\\pEu estava pensando na minha casa,\\nmas foi pra cá que me TELEPORTEI?",
  ["g3:0818b7f0"] = "Dei mole!",
  ["g3:0818b7fd"] = "Sou tão distraída!\\pTenho que me concentrar pra poder\\nTELEPORTAR pra minha casa!",
  ["g3:0818b84d"] = "PASSAGEM VERDE\\nBOSQUE MARCADO ADIANTE",
  ["g3:0818b86b"] = "PASSAGEM VERDE\\nPense verde, mantenha a natureza\\plimpa!",
  ["g3:0818b896"] = "Deixei uma brisa agradável me guiar\\naté aqui.",
  ["g3:0818b8c8"] = "Hehe... Você fica com tanta fofura quando\\nestá com determinação.",
  ["g3:0818b8f7"] = "Quero ir para o bosque ali, mas...\\pTem muitos POKéMON INSETO.\\nEles me assustam um pouco.",
  ["g3:0818b959"] = "Estou treinando em segredo para\\nque ninguém me veja.",
  ["g3:0818b988"] = "Ninguém me viu perdendo, né?",
  ["g3:0818b9a5"] = "Como artista, não quero que as\\npessoas saibam do esforço que\\peu coloco no que faço.",
  ["g3:0818b9ec"] = "Como é? Você tá dizendo que já\\ncansou de ver NADADORES como eu?\\pAhh, deixa de implicância!",
  ["g3:0818ba47"] = "Ah, não, não, não.",
  ["g3:0818ba57"] = "Não consegui me livrar do estigma\\nde ser um NADADOR...",
  ["g3:0818ba86"] = "Meu namorado está sempre ocupado,\\nentão venho nadar sozinha.",
  ["g3:0818bac0"] = "Ahhh, sabia que isso ia acontecer!",
  ["g3:0818bae0"] = "Quando não posso estar com meu\\nnamorado, passo um tempo com os\\pPOKéMON que ele me deu.",
  ["g3:0818bb2d"] = "Me fala, onde ficam as montanhas\\npor aqui?",
  ["g3:0818bb62"] = "Me perdi enquanto estava ocupado\\nbatalhando!",
  ["g3:0818bb8b"] = "Não tem montanhas por aqui?",
  ["g3:0818bbba"] = "MIU: Oi, POKéMON!\\nÉ hora de brincar!",
  ["g3:0818bbe2"] = "MIU: Ah, não!\\nMamãe!",
  ["g3:0818bbf6"] = "MIU: Fico toda triste por dentro\\nquando a gente perde...",
  ["g3:0818bc24"] = "MIU: A MIA e eu somos GÊMEAS.\\nA gente quer batalhar juntas.",
  ["g3:0818bc5a"] = "MIA: Oi, POKéMON!\\nÉ hora de batalhar!",
  ["g3:0818bc84"] = "MIA: Que maldade!\\nVocê é terrível por ter vencido!\\n",
  ["g3:0818bcae"] = "MIA: Ahh...\\nSinto muito, meu POKéMON...",
  ["g3:0818bccf"] = "MIA: Ah, você só tem um POKéMON?\\pVocê não se sente só?",
  ["g3:0818bd0c"] = "Procura-se!\\nO chifre definitivo!",
  ["g3:0818bd27"] = "PASSAGEM D'ÁGUA\\nLeva ao VALE DAS RUÍNAS",
  ["g3:0818bd47"] = "Não consigo descobrir como faço\\npara entrar.",
  ["g3:0818bd7a"] = "Olha, eu que encontrei este lugar.\\pNão fica com muita inveja, tá?",
  ["g3:0818bdc0"] = "A porta não se mexe nem um pouco.\\nQuer dar uma olhada mais de perto?",
  ["g3:0818bdf9"] = "{PLAYER} deixou a porta quieta.",
  ["g3:0818be11"] = "Ao olhar mais de perto, tem vários\\npontinhos na porta...",
  ["g3:0818be4b"] = "A porta está aberta.",
  ["g3:0818be5d"] = "Parece que ainda existem muitos\\nsegredos não resolvidos neste mundo.",
  ["g3:0818be9b"] = "Hmm...",
  ["g3:0818bea0"] = "Que tal, pelo menos uma vez por\\ndia, parar um pouquinho e pensar\\pnos segredos e mistérios do nosso\\pmundo?",
  ["g3:0818bf05"] = "Fiquei curioso, o que fez você vir\\naqui?",
  ["g3:0818bf33"] = "Faz tanto tempo que batalhei que\\nmeus instintos estão enferrujados.",
  ["g3:0818bf6c"] = "Tem várias ruínas nas ILHAS SETII.\\pA maioria delas é muito antiga.",
  ["g3:0818bfc5"] = "Dizem que há pedras misteriosas\\nnesta ilha.\\pDesconfio que tenham alguma\\nligaçao com as ruínas daqui.",
  ["g3:0818c03b"] = "Ah, interessante.",
  ["g3:0818c04c"] = "Aquelas ruínas ali...\\pNão tive sorte em descobrir como\\nentrar.",
  ["g3:0818c09c"] = "Uma batalha com você, nas alturas!",
  ["g3:0818c0bb"] = "Ah, que desgosto perder tão fácil\\npra você!",
  ["g3:0818c0ea"] = "Sinta a alegria de escalar!",
  ["g3:0818c10a"] = "Conheço bem esta região.",
  ["g3:0818c140"] = "Não precisa ser tão insistente.\\nVou te contar com prazer.",
  ["g3:0818c17a"] = "A porta das ruínas...\\nTem padroes estranhos gravados\\pdo lado de fora.\\pMas eu não sei o que significam.",
  ["g3:0818c1ed"] = "Senti sua aproximação.",
  ["g3:0818c205"] = "Desisto...",
  ["g3:0818c20e"] = "No seu futuro, sinto que você vai\\nconhecer muitas outras pessoas.\\pAcho que todos vocês estarão\\nligados por um poder misterioso.",
  ["g3:0818c283"] = "Em algum lugar desta ilha, POKéMON\\npeculiares estão dormindo.",
  ["g3:0818c2bc"] = "Que TREINADOR incrível!",
  ["g3:0818c2d5"] = "Em algum lugar desta ilha, POKéMON\\npeculiares estão dormindo.\\pSerá que eles estão esperando por\\nvocê?",
  ["g3:0818c338"] = "ENTRADA da TORRE DOS TREINADORES\\nAceitem o desafio, TREINADORES!",
  ["g3:0818c370"] = "TORRE DOS TREINADORES ADIANTE",
  ["g3:0818c3bc"] = "Kyahaha!\\nVou te derrotar num piscar de olhos!",
  ["g3:0818c3e7"] = "Tsc!\\nÉ muito forte pra mim!",
  ["g3:0818c3ff"] = "Como é?\\nEu não ajo do jeito que pareço?\\pHeh, isso faz parte da minha\\nestratégia!",
  ["g3:0818c44b"] = "Olá!\\nVocê é membro do meu fã-clube?",
  ["g3:0818c473"] = "Ah, então você não é fã...\\pBem, posso mudar isso.\\nDeixa eu cantar pra você!",
  ["g3:0818c4ba"] = "Lalalá...\\nMeus POKéMON eu mando batalhar,\\pe as garotas começam a gritar!",
  ["g3:0818c500"] = "Esta ilha é grande demais...\\nNão é fácil patrulhar tudo por aqui.",
  ["g3:0818c543"] = "Aham...",
  ["g3:0818c54b"] = "TREINADORES como você, que vêm\\nda cidade, são muito fortes.\\pVocê vai seguir para a TORRE,\\nnão é?",
  ["g3:0818c5aa"] = "Eu castigo quem maltrata os\\nPOKéMON!",
  ["g3:0818c5cd"] = "Você não parece ser problemático como TREINADOR.",
  ["g3:0818c5f5"] = "Se você tratar seus POKéMON com\\ngentileza, eles vão entender.",
  ["g3:0818c632"] = "EVE: Vou me juntar ao JON e\\nbatalhar junto com ele.",
  ["g3:0818c662"] = "EVE: Eu e JON, a gente perdeu.\\nEhehe.",
  ["g3:0818c683"] = "EVE: Vou me esforçar mais\\njunto ao JON.",
  ["g3:0818c6ab"] = "EVE: Quero me juntar ao JON quando\\nfor batalhar com você.\\pVolte com dois POKéMON, tá bem?",
  ["g3:0818c700"] = "JON: Quando estou com a EVE, parece\\nque a gente nunca vai perder.",
  ["g3:0818c73b"] = "JON: Quando estou com a EVE,\\nnem parece que eu perdi!",
  ["g3:0818c773"] = "JON: Quando estou com a EVE, fico\\nanimado, ganhando ou perdendo.\\pÉ mágico!",
  ["g3:0818c7bd"] = "JON: Se for com a EVE, vou ficar\\nfeliz em batalhar com você.\\pEntao, queria que fosse uma\\nbatalha de dois contra dois.",
  ["g3:0818c82d"] = "ENTRADA DO CÂNION SETEOROS\\pPedimos aos TREINADORES que evitem\\ndanificar as plantas do CÂNION.",
  ["g3:0818c887"] = "Minha forma física está no auge!",
  ["g3:0818c8a6"] = "Hã?\\nTem alguma coisa errada...",
  ["g3:0818c8c2"] = "Do jeito que estou agora,\\ntalvez eu precise adiar a\\pTORRE DOS TREINADORES...",
  ["g3:0818c8fd"] = "Não importa se você por acaso\\ntem os POKéMON mais fortes...\\pNão significa nada se você não\\nsouber usá-los direito!",
  ["g3:0818c980"] = "Você é especialista.",
  ["g3:0818c999"] = "De vez em quando você vê isso,\\nTREINADORES com POKéMON incríveis\\pque não fazem ideia do que estão\\pfazendo.\\pAntes de treinar POKéMON, os próprios\\nTREINADORES precisam amadurecer.",
  ["g3:0818ca2f"] = "Eu trabalho para proteger o meio\\nambiente.\\pEm troca, a natureza me protege!",
  ["g3:0818ca6f"] = "Uau! Você é forte!\\nQue tal me proteger também?",
  ["g3:0818ca9c"] = "Lá de longe, entre as estrelas, nosso\\nplaneta é só uma gota d'água.\\pMas queremos proteger essa gota\\nd'água por todos.",
  ["g3:0818cb16"] = "Esses tênis que você está usando\\nsão bem estilosos.",
  ["g3:0818cb3e"] = "Você é impressionante, apesar da\\nsua aparência fofa.",
  ["g3:0818cb6c"] = "Sua mãe comprou esses TÊNIS DE\\nCORRIDA estilosos pra você?\\pEla deve gostar muito de você.",
  ["g3:0818cbb4"] = "Você parece forte. Por favor,\\nme deixa batalhar com você!",
  ["g3:0818cbe0"] = "Eu sabia! Você é tão forte quanto\\neu imaginava!",
  ["g3:0818cc09"] = "Seu jeito de batalhar me deu\\nmuitos dados úteis.\\pMuito obrigado!",
  ["g3:0818cc4f"] = "Recebi a melhor educação possível\\npara me tornar tão forte.\\pNão quero perder para ninguém!",
  ["g3:0818ccae"] = "Obrigada. Sinto como se tivesse\\nsido libertada ao perder para você.",
  ["g3:0818ccea"] = "Por algum motivo, eu fico furiosa\\npor qualquer coisinha.\\pVou me acalmar respirando fundo.",
  ["g3:0818cd49"] = "LEX: Minha querida NYA, juntos a\\ngente pode vencer!",
  ["g3:0818cd75"] = "LEX: Acho que fui descuidado\\ndemais...",
  ["g3:0818cd9c"] = "LEX: Acho que foi uma boa\\nexperiência para NYA.\\pVocê tem a minha gratidão.",
  ["g3:0818cde2"] = "LEX: Posso te pedir para batalhar\\ncontra a gente ao mesmo tempo?",
  ["g3:0818ce20"] = "NYA: Vou dar o meu melhor para\\nnão atrapalhar meu mentor, LEX!",
  ["g3:0818ce5a"] = "NYA: Ah, não...\\nMe desculpa, eu...",
  ["g3:0818ce78"] = "NYA: Acho que ainda vou precisar de\\nmuito mais experiência e orientação\\pcom LEX...\\p... Entao, LEX, por favor... posso\\ncontinuar ao seu lado assim?",
  ["g3:0818cef4"] = "NYA: Desculpa, mas será podemos\\nbatalhar no estilo dois contra dois?",
  ["g3:0818cf2b"] = "CÂNION SETEOROS\\nRUÍNAS CATABONI ADIANTE",
  ["g3:0818cf4d"] = "Treinar sozinho certamente não é\\numa coisa ruim.\\pMas também não é nada mal buscar\\no topo com um parceiro.\\pAté o BRUNO...\\nEle já treinou com um cara\\pchamado BRAWLY antes.",
  ["g3:0818cffb"] = "Você sabe alguma coisa sobre\\nessa câmara de pedra?",
  ["g3:0818d02a"] = "Isso foi desnecessário.\\nVocê não precisava de tanta grosseria.",
  ["g3:0818d061"] = "As RUÍNAS CATABONI têm pelo\\nmenos 1.500 anos.\\pMas é um mistério intrigante por que\\nforam construídas em primeiro lugar.",
  ["g3:0818d0d9"] = "Dizem que um POKéMON místico\\ndorme aqui dentro.",
  ["g3:0818d108"] = "Não sou muito bom em batalhas.",
  ["g3:0818d125"] = "Ouvi dizer que existem outras\\nruínas como esta aqui.\\pSerá que elas são o local de\\ndescanso de outros POKéMON\\pmísticos?",
  ["g3:0818d18f"] = "CLIFFORD está me ensinando a pintar.",
  ["g3:0818d1b5"] = "Podemos arranjar encrenca se\\nfizermos barulho aqui.",
  ["g3:0818d1e3"] = "Eu disse que queria pintar uma\\nconstruçao antiga.\\pEntao CLIFFORD me trouxe pra cá.",
  ["g3:0818d22f"] = "Hoje, além da nossa aula, viemos\\nconhecer a câmara.",
  ["g3:0818d26d"] = "Nossa, que extraordinário.",
  ["g3:0818d284"] = "Ah, então você está estudando\\nPOKéMON por conta própria...\\pSim, você é mesmo uma pessoa\\nmuito extraordinária.",
  ["g3:0818d2f0"] = "MAMÃE: Enfim... Todos os garotos\\nsaem de casa um dia.\\pFoi o que disseram na TV.\\pAh, sim. O PROFESSOR CARVALHO,\\nnosso vizinho, estava te procurando.",
  ["g3:0818d360"] = "MAMÃE: Enfim... Todas as garotas\\nsonham em viajar.\\pFoi o que disseram na TV.\\pAh, sim. O PROFESSOR CARVALHO,\\nnosso vizinho, estava te procurando.",
  ["g3:0818d3d1"] = "MAMÃE: {PLAYER}!\\nVocê deveria descansar um pouco.",
  ["g3:0818d3f8"] = "MAMÃE: Ah, que bom! Você e seus\\nPOKéMON estão ótimos. Cuide-se!",
  ["g3:0818d43e"] = "Está passando um filme na TV.\\nQuatro garotos estão caminhando\\psobre trilhos de trem.\\p... É melhor eu ir também.",
  ["g3:0818d492"] = "Está passando um filme na TV.\\nUma garota com o cabelo trançado\\pestá caminhando por uma estrada\\pde tijolos.\\p... É melhor eu ir também.",
  ["g3:0818d4f9"] = "Ops, lado errado...",
  ["g3:0818d50b"] = "{PLAYER} jogava no NES.\\p... Certo!\\nÉ hora de ir!",
  ["g3:0818d53b"] = "É um aviso fixado...\\pSe estiver com confusão, peça AJUDA!\\nAperte o Botao L ou R.",
  ["g3:0818d58c"] = "DAISY: Oi, {PLAYER}!\\pMeu irmão, {RIVAL}, está no\\nLABORATÓRIO do vovô.",
  ["g3:0818d5c4"] = "DAISY: {PLAYER}, ouvi dizer que\\nvocê batalhou contra o {RIVAL}.\\pEu adoraria ter visto isso!",
  ["g3:0818d60a"] = "O vovô te pediu pra ajudá-lo?\\pNossa, como ele é preguiçoso.\\nAqui, isto vai te ajudar.",
  ["g3:0818d661"] = "{PLAYER} recebeu um\\nMAPA DA REGIÃO de DAISY!",
  ["g3:0818d684"] = "Você não tem espaço pra isso na\\nsua MOCHILA.",
  ["g3:0818d6af"] = "Você pode usar o MAPA DA REGIÃO\\npara descobrir onde você está ou\\pverificar os nomes dos lugares.",
  ["g3:0818d701"] = "DAISY: Assim como as pessoas,\\nos POKéMON são seres vivos.\\pQuando eles ficarem cansados,\\nvocê deve deixá-los descansar.",
  ["g3:0818d763"] = "É um grande mapa da região de\\nKANTO. Isto seria útil!",
  ["g3:0818d7a1"] = "As prateleiras estão cheias de\\nlivros sobre os POKéMON.",
  ["g3:0818d7d3"] = "DAISY: Oi, {PLAYER}!\\nVocê chegou numa boa hora.\\pTô prestes a tomar um chá.\\nGostaria de se juntar a mim?\\pAh, mas veja. Seus POKéMON estão\\num pouco sujos.\\pQuer que eu cuide de um deles\\npra você?",
  ["g3:0818d875"] = "Não quer que eu cuide de nenhum?\\nTudo bem, vamos só tomar chá.",
  ["g3:0818d8b2"] = "Qual deles devo cuidar?",
  ["g3:0818d8cc"] = "DAISY: Certo, vou deixá-lo\\nimpecável rapidinho.",
  ["g3:0818d8fe"] = "{STR_VAR_1} parece sonhadoramente satisfeito...\\pDAISY: Tá aí! Feito.\\nViu? Não te parece legal?\\pHi hi...\\nÉ um POKéMON bem fofinho.",
  ["g3:0818d97b"] = "Ah, desculpa. Não posso cuidar\\nde um OVO.",
  ["g3:0818d9a5"] = "DAISY: Quando você cria seus\\nPOKéMON com amor, eles também\\paprendem a te amar.\\p{PLAYER}, posso ver seu primeiro\\nPOKéMON?",
  ["g3:0818da16"] = "Ele não poderia te amar mais!\\pNão tem palavras pra expressar\\no quanto ele gosta de você!",
  ["g3:0818da73"] = "Ele parece muito feliz.\\pQueria que o {RIVAL} pudesse ver\\ne aprender algo com isso.",
  ["g3:0818dabe"] = "Ele gosta muito de você.\\nContinue cuidando bem dele!",
  ["g3:0818daf3"] = "Ele está se apegando a você.\\nA confiança entre vocês está\\pcrescendo.",
  ["g3:0818db2e"] = "Ele ainda não está totalmente\\nfamiliarizado com você.\\pOs POKéMON são muito cautelosos\\nquando você os captura.",
  ["g3:0818db88"] = "{PLAYER}, não gosto do jeito que\\nele olha pra você.\\pVocê pode tentar ser um pouco\\nmais gentil com ele?",
  ["g3:0818dbdd"] = "... Não sei como dizer isso, mas...\\pTem algum motivo pra seu POKéMON\\nte odiar tanto?",
  ["g3:0818dc47"] = "“O doce e amável\\nCLEFAIRY”",
  ["g3:0818dc67"] = "{RIVAL}: Ah, é você, {PLAYER}.\\nO vovô não tá aqui.",
  ["g3:0818dc94"] = "{RIVAL}: Vovô!\\nTô cansado de esperar!",
  ["g3:0818dcb9"] = "{RIVAL}: Ei! Vovô! Não é justo!\\nE quanto a mim?",
  ["g3:0818dce2"] = "{RIVAL}: Não sou egoísta como\\nvocê!\\pPode escolher primeiro, {PLAYER}!",
  ["g3:0818dd34"] = "{RIVAL}: Entao eu vou ficar com\\neste!",
  ["g3:0818dd52"] = "{RIVAL} recebeu o {STR_VAR_1}\\ndo PROFESSOR CARVALHO!",
  ["g3:0818dd75"] = "{RIVAL}: Meu POKéMON parece\\nmuito mais forte do que o seu.",
  ["g3:0818dda4"] = "{RIVAL}: Espera, {PLAYER}!\\nVamos testar nossos POKéMON!\\pEu te desafio para uma batalha!",
  ["g3:0818ddea"] = "O QUÊ?\\nInacreditável!\\pEu escolhi o POKéMON errado!",
  ["g3:0818de1a"] = "{RIVAL}: É isso aí!\\nSou ou não sou o melhor?",
  ["g3:0818de38"] = "{RIVAL}: Tudo bem! Vou batalhar com\\nmeu POKéMON para fortalecê-lo!\\p{PLAYER}! Vovô!\\nFalou!",
  ["g3:0818de8d"] = "{RIVAL}: Vovô!",
  ["g3:0818de99"] = "{RIVAL}: Eu quase esqueci!\\nPor que você me chamou?",
  ["g3:0818dec8"] = "{RIVAL}: Não se preocupe, vovô!\\nPode deixar comigo!",
  ["g3:0818def3"] = "{PLAYER}, odeio ter que dizer isso,\\nmas não precisamos de você!\\n\\nJá sei!\\nVou pedir um MAPA DA REGIÃO\\n\\npra minha irmã!\\n\\nE vou dizer a ela pra não te dar, {PLAYER}! Hahaha!",
  ["g3:0818dfbc"] = "CARVALHO: {RIVAL}?\\nDeixa eu pensar...\\pAh, sim, eu disse para você vir!\\nEspere um pouco...\\p{PLAYER}, há três POKéMON aqui.\\pHaha!\\pOs POKéMON estão dentro dessas\\nPOKé BOLAS.\\pQuando era jovem, eu era um bom\\nTREINADOR POKéMON.\\pMas agora, na minha velhice, só me\\nrestaram esses três.\\pVocê pode ficar com um.\\nVá em frente, escolha!",
  ["g3:0818e0ea"] = "CARVALHO: Tenha paciência, {RIVAL}.\\nVocê também vai ganhar um!",
  ["g3:0818e116"] = "CARVALHO: {PLAYER}, cada uma dessas\\nPOKé BOLAS tem um POKéMON dentro.\\pQual você vai escolher?",
  ["g3:0818e177"] = "CARVALHO: Ei!\\nNão vá embora ainda!",
  ["g3:0818e194"] = "Ah! CHARMANDER é a sua escolha.\\nVocê deve criá-lo com paciência.\\pEntao, {PLAYER}, você quer o POKéMON\\ndo tipo FOGO, CHARMANDER?",
  ["g3:0818e207"] = "Hm! SQUIRTLE é a sua escolha.\\nVale muito a pena criá-lo.\\pEntao, {PLAYER}, você quer o POKéMON\\ndo tipo ÁGUA, SQUIRTLE?",
  ["g3:0818e272"] = "Entendo! BULBASAUR é a sua escolha.\\nÉ muito fácil criá-lo.\\pEntao, {PLAYER}, você quer o POKéMON\\ndo tipo PLANTA, BULBASAUR?",
  ["g3:0818e2e5"] = "Este POKéMON tem muita energia!",
  ["g3:0818e30d"] = "{PLAYER} recebeu o {STR_VAR_1}\\ndo PROFESSOR CARVALHO!",
  ["g3:0818e330"] = "CARVALHO: Se um POKéMON selvagem\\naparecer, o seu POKéMON poderá\\pbatalhar contra ele.\\pCom ele ao seu lado, não será\\ndifícil chegar à próxima cidade.",
  ["g3:0818e3ad"] = "CARVALHO: {PLAYER}, treine o seu\\njovem POKéMON batalhando com ele.",
  ["g3:0818e405"] = "CARVALHO: {PLAYER}!\\nComo está o meu velho POKéMON?\\pBem, acho que ele gosta muito de\\nvocê.\\pVocê deve ter talento como\\nTREINADOR POKéMON!\\pO que é isso?\\nVocê tem algo para mim?",
  ["g3:0818e4af"] = "{PLAYER} entregou o\\nPACOTE DO CARVALHO!",
  ["g3:0818e4ca"] = "Ah!\\nÉ a minha POKé BOLA personalizada!\\pEu tinha encomendado.\\nObrigado!",
  ["g3:0818e508"] = "CARVALHO: Ah, sim!\\nTenho um pedido para vocês dois.",
  ["g3:0818e536"] = "Na mesa está a minha invenção,\\na POKéDEX!\\pEla registra automaticamente os\\ndados dos POKéMON que você viu\\pou capturou.\\pÉ uma enciclopédia de alta\\ntecnologia!",
  ["g3:0818e5c5"] = "CARVALHO: {PLAYER} e {RIVAL}.\\nLevem isto com vocês.",
  ["g3:0818e5ea"] = "{PLAYER} recebeu uma POKéDEX\\ndo PROFESSOR CARVALHO.",
  ["g3:0818e612"] = "CARVALHO: Para obter dados\\ndetalhados dos POKéMON, não\\pbasta só vê-los.\\pÉ preciso capturá-los.\\pAqui estão algumas ferramentas\\npara capturar POKéMON selvagens.",
  ["g3:0818e6b3"] = "{PLAYER} recebeu cinco POKé BOLAS.",
  ["g3:0818e6d0"] = "Quando aparecer um POKéMON\\nselvagem, é hora de batalhar\\pcontra ele.\\pVocê deve jogar uma POKé BOLA\\npara capturá-lo!\\pMas isso nem sempre funciona.\\pUm POKéMON saudável pode fugir.\\nTambém é preciso ter sorte!",
  ["g3:0818e784"] = "Eu queria fazer um guia completo\\nde todos os POKéMON do mundo...\\pEsse era o meu sonho!\\pMas estou velho demais. Não\\nconsigo mais fazer isso sozinho.\\pEntao, quero que vocês dois\\nrealizem o meu sonho por mim.\\pVamos, mexam-se!\\pSerá um grande feito na história\\ndos POKéMON!",
  ["g3:0818e871"] = "Os POKéMON ao redor do mundo estão\\nte esperando, {PLAYER}!",
  ["g3:0818e89c"] = "Ah, {PLAYER}!\\nComo está a sua POKéDEX?\\p{RIVAL} já capturou alguns POKéMON\\ne registrou seus dados.\\pVenha, {PLAYER}, deixa eu dar uma\\nolhada na sua POKéDEX.\\p... O que houve? Você não adicionou\\nnenhum dado novo.\\pVamos, esforce-se um pouco mais.",
  ["g3:0818e98e"] = "CARVALHO: Venha me ver de vez em\\nquando.\\pAfinal, quero saber como está se\\nsaindo com a sua POKéDEX.",
  ["g3:0818e9e5"] = "É como uma enciclopédia, mas as\\npáginas estão em branco.",
  ["g3:0818ea19"] = "Isto são POKéBOLAS.\\nDentro delas tem POKéMON!",
  ["g3:0818ea45"] = "Este é o último POKéMON do\\nPROFESSOR CARVALHO.",
  ["g3:0818ea66"] = "Aperte START para abrir o MENU!",
  ["g3:0818ea84"] = "A opção SALVAR está no MENU.\\nUse-a regularmente.",
  ["g3:0818eab6"] = "Todos os tipos de POKéMON têm\\npontos fortes e fracos em relação\\paos outros.",
  ["g3:0818eaf4"] = "Tem uma mensagem de e-mail aqui.\\p...\\pFinalmente!\\nOs melhores TREINADORES da LIGA\\pPOKéMON estão prontos para\\penfrentar todos os desafiantes!\\pTraga os seus melhores POKéMON\\ne teste as suas habilidades como\\pTREINADOR!\\pQG da LIGA POKéMON\\nPLANALTO ÍNDIGO\\pPS: PROFESSOR CARVALHO, visite-nos,\\npor favor!\\p...",
  ["g3:0818ebe6"] = "Estudo os POKéMON, sou ASSISTENTE\\ndo PROFESSOR CARVALHO.",
  ["g3:0818ec0b"] = "Oi, {PLAYER}. Aposto que você e seus\\nPOKéMON se tornaram bons amigos.\\pAliás, você conhece a DAISY?\\pSe mostrar seus POKéMON para a\\nDAISY, ela dirá o quanto eles\\pgostam de você.\\pÀs vezes, ela até vai cuidar de\\num POKéMON para você.\\pIsso é segredo, então, por favor,\\nnão conta pra ninguém.",
  ["g3:0818ed15"] = "Em breve, o PROFESSOR CARVALHO\\nterá seu próprio programa de rádio.\\pO programa se chamará SEMINÁRIO\\nPOKéMON do PROFESSOR CARVALHO.",
  ["g3:0818ed81"] = "Pode não parecer, mas o PROFESSOR\\nCARVALHO é especialista em\\pPOKéMON.\\pEle é admirado por muitos\\nTREINADORES POKéMON.",
  ["g3:0818edf5"] = "Ah, uma coisa importante!\\p{PLAYER}, tenho outro favor\\nimportante para lhe pedir.\\pPreciso que você escute atentamente.",
  ["g3:0818ee60"] = "Recentemente, têm sido avistadas\\nmuitas espécies raras de POKéMON.\\pEstou falando de POKéMON que nunca\\nforam vistos em KANTO.\\pEu adoraria ir ver tudo pessoalmente,\\nmas estou velho demais para isso.\\pComo não posso fazer isso, {PLAYER},\\ngostaria que fosse em meu lugar.",
  ["g3:0818ef59"] = "{RIVAL}: Ei, eu ouvi isso!\\pVovô, por que você sempre prefere\\n{PLAYER} em vez de mim?\\pEu capturei mais POKéMON, e em\\nmenos tempo.\\pVocê devia deixar tudo comigo.",
  ["g3:0818f004"] = "CARVALHO: Eu sei, eu sei. Claro\\nque também preciso da sua ajuda.\\pAgora, preciso ver as suas\\nPOKéDEXES.",
  ["g3:0818f062"] = "O PROFESSOR CARVALHO pegou\\nas POKéDEXES.",
  ["g3:0818f085"] = "... ... ...  ... ... ...\\p... ... ...  ... ... ...\\p... E pronto!\\pAgora essas POKéDEXES podem\\nregistrar dados de muito mais\\pPOKéMON.",
  ["g3:0818f0e8"] = "A POKéDEX de {PLAYER} foi melhorada!",
  ["g3:0818f103"] = "{PLAYER} e {RIVAL}, desta vez, vocês\\nterao que se esforçar muito para\\pcompletar as suas POKéDEXES.\\pVamos torná-las as melhores e mais\\ncompletas de todos os tempos!\\pDaremos um grande passo na história\\ndos POKéMON!",
  ["g3:0818f1db"] = "{RIVAL}: Vovô, se acalma.\\nNão precisa se agitar tanto.\\pVou completar a POKéDEX, não se\\npreocupa com nada.\\pAcho que vou dar uma olhada na\\nILHA UM primeiro...\\pEnfim, tô indo nessa!",
  ["g3:0818f292"] = "Inventar apelidos é divertido,\\nmas não é uma tarefa fácil.\\pNomes inteligentes são legais, mas\\nnomes simples são mais fáceis de\\plembrar.",
  ["g3:0818f30f"] = "O papai também ama os POKéMON.",
  ["g3:0818f32c"] = "SPEARY: Tetweet!",
  ["g3:0818f33d"] = "SPEAROW\\nNome: SPEARY",
  ["g3:0818f352"] = "Fwahahaha!\\nBoas-vindas ao meu esconderijo!\\pFicará assim até eu conseguir restaurar a EQUIPE ROCKET à sua antiga glória.\\pMas, você me achou de novo.\\nQue assim seja.\\pDessa vez, não vou pegar leve!\\pMais uma vez, você há de enfrentar\\nGIOVANNI, o maior de todos os TREINADORES!",
  ["g3:0818f43f"] = "Haha!\\nFoi uma batalha muito intensa.\\pE você venceu!\\pComo prova, aqui está a\\nINSÍGNIA TERRA!\\n",
  ["g3:0818f4a2"] = "Depois de perder dessa forma, não\\nconsigo encarar meus subordinados.\\pTraí a confiança deles.\\pA partir de hoje, a EQUIPE ROCKET\\nestá acabada para sempre!\\pQuanto a mim, dedicarei minha vida\\não treinamento dos POKéMON.\\pNos reencontraremos algum dia!\\nAdeus!",
  ["g3:0818f586"] = "A INSÍGNIA TERRA faz com que\\nos POKéMON de qualquer nível\\pobedeçam sem questionar.\\pÉ a prova da sua maestria como\\nTREINADOR POKéMON.\\pCom ela, você pode desafiar a\\nLIGA POKéMON.\\pAlém disso, pegue esta MT.\\pConsidere como um presente para\\no seu desafio na LIGA POKéMON.",
  ["g3:0818f675"] = "{PLAYER} recebeu a MT26\\nde GIOVANNI.",
  ["g3:0818f695"] = "A MT26 contém TERREMOTO.\\pÉ um ataque poderoso que provoca\\num tremor gigante.\\pEu a criei há muito tempo, quando\\nliderava este GINÁSIO...",
  ["g3:0818f71b"] = "Você não tem espaço para isso!",
  ["g3:0818f73b"] = "Hehe!\\nVocê já deve estar se cansando!",
  ["g3:0818f769"] = "Fiquei sem forças!",
  ["g3:0818f77b"] = "Você vai precisar de muita energia\\npara enfrentar nosso LÍDER de\\pGINÁSIO.",
  ["g3:0818f7ad"] = "Arrrggh!\\nTô perdendo a cabeça!",
  ["g3:0818f7d6"] = "Argh!",
  ["g3:0818f7dd"] = "Ainda não estou à altura!",
  ["g3:0818f7f3"] = "Eu e os POKéMON fazemos um som\\nmaneiro juntos!",
  ["g3:0818f824"] = "Vocês estão em perfeita harmonia!",
  ["g3:0818f840"] = "Você sabe a identidade do nosso\\nLÍDER de GINÁSIO?",
  ["g3:0818f86c"] = "O caratê é a forma definitiva\\ndas artes marciais!",
  ["g3:0818f899"] = "Aiyah!",
  ["g3:0818f8a0"] = "Se meus POKéMON fossem tão bons\\nno caratê quanto eu...",
  ["g3:0818f8cb"] = "Quem é talentoso de verdade,\\nvence com estilo.",
  ["g3:0818f8ee"] = "Perdi o jeito da coisa!",
  ["g3:0818f8fe"] = "O LÍDER vai me dar uma bronca\\npor perder dessa forma...",
  ["g3:0818f92c"] = "Sou o REI do CARATÊ!\\nSeu destino está nas minhas mãos!",
  ["g3:0818f95a"] = "Ayah!",
  ["g3:0818f960"] = "A LIGA POKéMON?\\nVocê? Não fica se achando!",
  ["g3:0818f98a"] = "Seus POKéMON se acovardarão diante\\ndo estalo do meu chicote!",
  ["g3:0818f9bb"] = "Plaft!\\nTchuac!",
  ["g3:0818f9cc"] = "Espera!\\nEu me descuidei!",
  ["g3:0818f9e7"] = "O GINÁSIO de VIRIDIAN esteve\\nfechado durante muito tempo.\\pMas agora, nosso LÍDER voltou!",
  ["g3:0818fa2d"] = "Eu fui derrotado?",
  ["g3:0818fa3b"] = "Você só pode ir para a LIGA\\nPOKéMON se derrotar o nosso\\pLÍDER de GINÁSIO!",
  ["g3:0818fa81"] = "E aí!\\nCAMPEÃO em ascensão!\\pNem mesmo eu sei a identidade do\\nLÍDER do GINÁSIO de VIRIDIAN.\\pMas uma coisa é certa.\\nEle é o mais forte entre todos os\\pLÍDERES de GINÁSIO.\\pAlém disso, ouvi dizer que os\\nTREINADORES daqui gostam de\\pPOKéMON do tipo TERRA.",
  ["g3:0818fb56"] = "Tá brincando?! GIOVANNI era o\\nLÍDER do GINÁSIO de VIRIDIAN?",
  ["g3:0818fb8d"] = "GINÁSIO POKéMON de VIRIDIAN\\nLÍDER: ?\\pTREINADORES VENCEDORES:\\n{RIVAL}",
  ["g3:0818fbc1"] = "GINÁSIO POKéMON de VIRIDIAN\\nLÍDER: GIOVANNI\\pTREINADORES VENCEDORES:\\n{RIVAL} e {PLAYER}",
  ["g3:0818fc00"] = "Oof! Tô tentando memorizar todas\\nas minhas anotaçoes.",
  ["g3:0818fc2b"] = "Muito bem!\\pNão se esqueça de ler com atenção\\no que está escrito no quadro-negro!",
  ["g3:0818fc65"] = "Vejamos o que está escrito no\\ncaderno...\\pPrimeira página...\\pAs POKé BOLAS são usadas para\\ncapturar os POKéMON.\\pVocê pode ter até seis POKéMON\\nna sua equipe.\\pAs pessoas que treinam e batalham\\ncom os POKéMON são chamadas de\\pTREINADORES.",
  ["g3:0818fd23"] = "Segunda página...\\pUm POKéMON saudável pode ser\\ndifícil de capturar, então é melhor\\penfraquecê-lo primeiro.\\pEnvenenamentos, queimaduras e\\noutros problemas de status são\\pmuito eficazes.",
  ["g3:0818fda8"] = "Terceira página...\\pOs TREINADORES batalham uns contra\\nos outros com seus POKéMON.\\pPara os TREINADORES, a vitória é\\nmuito gratificante.\\pNos GINÁSIOS POKéMON, batalhas\\nsão constantemente travadas.",
  ["g3:0818fe5c"] = "Quarta página...\\pO objetivo principal de todos os\\nTREINADORES POKéMON é derrotar os\\poito melhores LÍDERES de GINÁSIO.\\pSe conseguirem, poderão enfrentar...\\pA ELITE DOS QUATRO na\\nLIGA POKéMON!",
  ["g3:0818ff19"] = "Passar a página?",
  ["g3:0818ff28"] = "GAROTA: Ei!\\nNão olha minhas anotaçoes!",
  ["g3:0818ff4b"] = "O quadro-negro lista os PROBLEMAS\\nde STATUS dos POKéMON durante as\\pbatalhas.",
  ["g3:0818ff88"] = "Qual tópico gostaria de ler?",
  ["g3:0818ffa9"] = "Um POKéMON não pode atacar se\\nestiver dormindo.\\pOs POKéMON continuarão dormindo\\nmesmo após as batalhas.\\pPara acordar um POKéMON,\\nuse DESPERTAR.",
  ["g3:08190025"] = "Uma queimadura diminui o ATAQUE.\\nTambém causa perda contínua de PS.\\pAs queimaduras permanecem após\\nas batalhas.\\pPara curar um POKéMON queimado,\\nuse ANTIQUEIMADURA.",
  ["g3:0819009f"] = "Quando envenenado, a saúde de um\\nPOKéMON diminui constantemente.\\pOs envenenamentos permanecem\\napós as batalhas.\\pPara curar um POKéMON envenenado,\\nuse ANTÍDOTO!",
  ["g3:0819010f"] = "Um POKéMON congelado ficará\\ncompletamente imóvel.\\pE continuará congelado mesmo\\napós a batalha.\\pPara descongelar um POKéMON\\naflito, use ANTICONGELANTE.",
  ["g3:08190199"] = "As paralisias diminuem a VELOCIDADE\\ne podem impedir os movimentos do\\pPOKéMON.\\pAs paralisias permanecem após\\nas batalhas.\\pPara desparalisar um POKéMON,\\nuse ANTIPARALISANTE.",
  ["g3:0819021a"] = "Ei!\\nVocê veio da CIDADE DE PALLET?",
  ["g3:0819023a"] = "Você conhece o PROFESSOR\\nCARVALHO, não é?\\pTenho uma encomenda pra ele.\\nVocê pode entregar?",
  ["g3:08190289"] = "{PLAYER} recebeu a ENCOMENDA\\ndo funcionário da LOJA POKéMON.",
  ["g3:081902bf"] = "Muito obrigado! Cumprimente o\\nPROFESSOR CARVALHO por mim!",
  ["g3:081902f5"] = "Dizem que essa loja vende muitos\\nANTÍDOTOS.",
  ["g3:0819032c"] = "Tenho que comprar algumas POÇOES.\\pNunca se sabe quando seus\\nPOKéMON vão precisar.",
  ["g3:08190384"] = "Sinta-se à vontade para usar\\naquele PC ali no canto.\\pA recepcionista me disse isso.\\nFoi muito gentil da sua parte!",
  ["g3:081903e5"] = "Tem um CENTRO POKéMON em todas\\nas cidades.\\pEles são gratuitos, então não hesite\\nem curar seus POKéMON.",
  ["g3:08190450"] = "Os CENTROS POKéMON curam seus\\nPOKéMON feridos ou desmaiados.\\pEles deixam todos os seus POKéMON\\ncompletamente restaurados.",
  ["g3:081904b5"] = "Sim, sim.\\nO ingresso infantil custa $50.\\pVocê gostaria de entrar?",
  ["g3:081904f9"] = "Até a próxima!",
  ["g3:08190505"] = "Certo, $50!\\nObrigado!",
  ["g3:0819051c"] = "Você não tem dinheiro suficiente.",
  ["g3:08190539"] = "Por favor, divirta-se.",
  ["g3:08190550"] = "Boa tentativa, jovem, mas você\\nnão pode entrar pelo fundo!\\pAh, tanto faz!\\nVocê sabe o que é um ÂMBAR?",
  ["g3:081905b1"] = "Em um ÂMBAR contém o material\\ngenético de POKéMON antigos.\\pTem um LABORATÓRIO em algum lugar\\ntentando ressuscitar os POKéMON\\pa partir do ÂMBAR.",
  ["g3:08190627"] = "O ÂMBAR é na verdade seiva,\\naquela substância pegajosa que\\pescorre das árvores.\\pA seiva antiga fossilizou ao longo\\ndo tempo, se tornando um ÂMBAR,\\pque é duro como pedra.",
  ["g3:081906b4"] = "Só tenho a agradecer pela minha\\nvida longa.\\pNunca pensei que veria os ossos\\nde um dragão!",
  ["g3:08190717"] = "Shhh! Vou te contar um segredo.\\pAcho que esse pedaço de ÂMBAR\\ncontém o DNA de um POKéMON!\\pSeria uma grande descoberta\\ncientífica se fosse possível\\pressuscitar um POKéMON a partir\\pdele.\\pMas meus colegas não estão nem\\naí pra mim.\\pPor isso, quero te pedir um favor!\\pVocê pode levar isso para ser\\nexaminado em algum LABORATÓRIO\\pPOKéMON?",
  ["g3:08190866"] = "{PLAYER} recebeu o ÂMBAR ANTIGO\\ndo homem.",
  ["g3:0819088e"] = "Shhh!\\nLeve o ÂMBAR ANTIGO para ser\\panalisado!",
  ["g3:081908ae"] = "Você não tem mais espaço.",
  ["g3:081908cd"] = "Temos dois fósseis de raros\\nPOKéMON pré-históricos em exibição.",
  ["g3:0819090a"] = "É um lindo pedaço de ÂMBAR em\\numa cor dourada translúcida.",
  ["g3:08190945"] = "Fóssil de AERODACTYL\\nUm POKéMON primitivo e raro.",
  ["g3:08190975"] = "Fóssil de KABUTOPS\\nUm POKéMON primitivo e raro.",
  ["g3:081909a3"] = "Os segredos do espaço...\\nOs mistérios da terra...\\pTem tantas coisas sobre as quais\\nsabemos tão pouco.\\pMas isso não deve nos abalar, e\\nsim nos incentivar a estudar mais\\pe não desistir.\\pFalando em abalar...\\pVocê conhece o movimento ATAQUE\\nSÍSMICO? Quer que eu o ensine\\pa um POKéMON?",
  ["g3:08190aa9"] = "Ah, não?\\nAposto que vai mudar de ideia.",
  ["g3:08190ad5"] = "Para qual POKéMON devo ensinar\\no movimento ATAQUE SÍSMICO?",
  ["g3:08190b00"] = "Espero que você não se deixe\\nabalar. Continue assim.",
  ["g3:08190b30"] = "A PEDRA DA LUA?\\pO que tem de tão especial nela? \\nMe parece uma pedra comum.",
  ["g3:08190b80"] = "20 de julho de 1969!\\pNesse dia, a humanidade pisou\\nna lua pela primeira vez.\\pComprei uma TV colorida só para\\nassistir isso!",
  ["g3:08190bf3"] = "Este mês, estamos realizando\\numa exposição sobre o espaço.",
  ["g3:08190c1e"] = "Quero um PIKACHU!\\nEles são tão fofinhos!\\pPedi pro papai capturar um\\npra mim!",
  ["g3:08190c60"] = "Sim, em breve você terá seu\\nPIKACHU, eu prometo!",
  ["g3:08190c81"] = "Ônibus Espacial Columbia",
  ["g3:08190c8f"] = "Acredita-se que um meteorito que\\ncaiu no MONTE LUA seja uma\\pPEDRA DA LUA.",
  ["g3:08190cd4"] = "Meu nome é BROCK, sou o\\nLÍDER do GINÁSIO de PEWTER.\\pMinha determinação inabalável\\nse reflete nos meus POKéMON.\\pTodos os meus POKéMON são \\nresistentes como pedras e têm\\pmuita determinação.\\pIsso mesmo! Todos os meus\\nPOKéMON são do tipo PEDRA!\\pFuahaha! Você quer me desafiar\\nsabendo que vai perder?\\pVocê se move pelo orgulho dos\\nTREINADORES POKéMON.\\pMuito bem!\\nMe mostre do que é capaz!",
  ["g3:08190e4f"] = "Não dei-lhe o devido valor, e por isso perdi.\\pComo prova de sua vitória, eu lhe confiro isto...\\pa INSÍGNIA ROCHA DA LIGA POKéMON.\\p{PLAYER} recebeu a INSÍGNIA ROCHA\\nde BROCK!\\pSó de ter a INSÍGNIA ROCHA, deixa seus POKéMON mais fortes.\\pTambém permite que usem o movimento CLARÃO fora das batalhas.\\pMas claro, um POKéMON deve aprender o movimento CLARÃO antes para usá-lo.",
  ["g3:08190fc1"] = "Espera!\\nFica com isto.",
  ["g3:08190fdb"] = "{PLAYER} recebeu a MT39\\nde BROCK.",
  ["g3:08190ff8"] = "Uma MT ou Máquina-Técnica, contém\\numa técnica para POKéMON.\\pAo usar uma MT, o movimento que ela\\ncontém é ensinado a um POKéMON.\\pUma MT só pode ser usada uma vez.\\pPortanto, quando for usá-la,\\nescolha o POKéMON com cuidado.\\pEnfim...\\nA MT39 é TUMBA DE ROCHAS.\\pAtira rochas no oponente e\\ndiminui sua VELOCIDADE.",
  ["g3:0819110f"] = "Neste mundo existe todo tipo\\nde TREINADORES.\\pVocê parece ter muito talento como TREINADOR POKéMON.\\pPor isso, sugiro que vá para o\\nGINÁSIO de CERULEAN e teste suas\\phabilidades.",
  ["g3:081911ce"] = "Você não tem espaço para isso.",
  ["g3:081911ec"] = "Pare aí, jovem!\\pVocê está a dez mil anos-luz\\nde enfrentar o BROCK!",
  ["g3:08191237"] = "Droga!\\pOs anos-luz não medem tempo,\\ne sim distância!",
  ["g3:0819126b"] = "Até que você é forte.\\n... Mas não tanto quanto o BROCK!",
  ["g3:08191298"] = "Oi!\\nVocê sonha alto?\\pVocê sonha em se tornar\\nCAMPEÃO POKéMON?\\pNão sou TREINADOR, mas posso\\nte dar conselhos de como vencer.\\pDeixa eu te levar ao topo!",
  ["g3:0819133c"] = "Muito bem!\\nVamos lá!",
  ["g3:0819135c"] = "O primeiro POKéMON numa batalha fica\\nà esquerda na LISTA de POKéMON.\\pAo alterar a ordem dos POKéMON,\\nvocê pode ganhar uma vantagem.\\pExperimente diferentes ordens para\\nse adequar à equipe do seu oponente.",
  ["g3:08191412"] = "É de graça!\\nVamos!",
  ["g3:0819143c"] = "Eu sabia!\\nVocê tem jeito de CAMPEÃO!",
  ["g3:0819146e"] = "GINÁSIO POKéMON de PEWTER\\nLÍDER: BROCK\\pTREINADORES VENCEDORES:\\n{RIVAL}",
  ["g3:081914a4"] = "GINÁSIO POKéMON de PEWTER\\nLÍDER: BROCK\\pTREINADORES VENCEDORES:\\n{RIVAL} e {PLAYER}",
  ["g3:081914de"] = "Um cara suspeito me passou a\\nperna e me vendeu este estranho\\pPOKéMON peixe!\\pÉ totalmente inútil e custou $500!",
  ["g3:08191541"] = "Coisas boas acontecerão se treinar\\nseus POKéMON com dedicação.\\pAté os mais fracos podem surpreender\\nse você não desistir deles.",
  ["g3:081915bb"] = "NIDORAN♂: Bowbow!",
  ["g3:081915cd"] = "NIDORAN, senta!",
  ["g3:081915db"] = "Nosso POKéMON é forasteiro, por\\nisso ele não é muito obediente.\\pUm forasteiro é um POKéMON que\\nfoi conseguido por troca.\\pEles crescem rápido, mas podem\\nnão obedecer os TREINADORES\\pnovatos em batalha.\\pSe pelo menos tivéssemos algumas\\nINSÍGNIAS...",
  ["g3:081916a9"] = "O quê?!\\pA EQUIPE ROCKET está no\\nMONTE LUA? Como?\\pTô numa ligação!\\nCai fora!",
  ["g3:081916ea"] = "JIGGLYPUFF: Puu pupuu!",
  ["g3:08191701"] = "Uááá!\\pQuando JIGGLYPUFF canta, os\\nPOKéMON ficam sonolentos...\\p... E eu também...\\nRonc...",
  ["g3:08191743"] = "Quero muito um PIKACHU, por isso\\ntô trocando meu CLEFAIRY por um.",
  ["g3:08191780"] = "Tô trocando POKéMON com esse\\ngaroto.\\pEu tinha dois PIKACHU, então achei\\numa boa ideia trocar um deles.",
  ["g3:081917e4"] = "Os POKéMON aprendem novas\\ntécnicas à medida que crescem.\\pMas alguns movimentos precisam\\nser ensinados a eles.",
  ["g3:08191840"] = "É mais fácil capturar um POKéMON\\nse ele estiver com algum problema\\pde status.\\pSono, envenenamento, queimadura\\nou paralisia... São todos eficazes.\\pMas a captura nunca é garantida!",
  ["g3:081918e7"] = "Só os TREINADORES mais\\nhabilidosos têm INSÍGNIAS.\\pVejo que você tem pelo menos uma.\\pSabia que essas INSÍGNIAS guardam\\nsegredos incríveis?",
  ["g3:08191967"] = "Entao...\\pDevo explicar sobre qual das\\noito INSÍGNIAS?",
  ["g3:0819199e"] = "Venha me visitar sempre que quiser.",
  ["g3:081919be"] = "O atributo de ATAQUE de todos os\\nseus POKéMON aumenta um pouco.\\pTambém permite usar o movimento\\nCLARAO fora de batalhas.",
  ["g3:08191a31"] = "Os POKéMON até o Nv. 30 vão te\\nobedecer.\\pIsso inclui os forasteiros, que\\nforam conseguidos em trocas.\\pNo entanto, os POKéMON de níveis\\nmais altos serão desobedientes\\pem batalha.\\pTambém permite usar o movimento\\nCORTAR fora de batalhas.",
  ["g3:08191af9"] = "O abributo de VELOCIDADE de todos\\nos seus POKéMON aumenta um pouco.\\pTambém permite usar o movimento\\nVOAR fora de batalhas.",
  ["g3:08191b69"] = "Os POKéMON até o Nv. 50 vão te\\nobedecer.\\pIsso inclui os forasteiros, que\\nforam conseguidos em trocas.\\pNo entanto, os POKéMON de níveis\\nmais altos serão desobedientes\\pem batalha.\\pTambém permite usar o movimento\\nSUPERFORÇA fora de batalhas.",
  ["g3:08191c36"] = "O atributo de DEFESA de todos os\\nseus POKéMON aumenta um pouco.\\pTambém permite usar o movimento\\nSURFAR fora de batalhas.",
  ["g3:08191ca9"] = "Os POKéMON até o Nv. 70 vão te\\nobedecer.\\pIsso inclui os forasteiros, que\\nforam conseguidos em trocas.\\pNo entanto, os POKéMON de níveis\\nmais altos serão desobedientes\\pem batalha.\\pTambém permite usar o movimento\\nESMAGA-PEDRAS fora de batalhas.",
  ["g3:08191d78"] = "Os abributos de ATQ. ESP. e DEF.\\nESP de todos os seus POKéMON\\paumentam um pouco.\\pTambém permite usar o movimento\\nCACHOEIRA fora de batalhas.",
  ["g3:08191df8"] = "Todos os POKéMON vão te obedecer!",
  ["g3:08191e13"] = "Aqueles ROCKETS miseráveis!\\pOlha o que fizeram com minha\\ncasa!\\pEles roubaram uma MT que ensina\\num POKéMON a CAVAR buracos!\\pEu ia usá-la num MANKEY ou num\\nSANDSHREW...\\pEla custou uma fortuna!",
  ["g3:08191ed8"] = "Acho que não adianta chorar pelo\\nleite derramado...\\pDecidi que vou ensinar ao DIGLETT\\ncomo CAVAR sem usar uma MT.",
  ["g3:08191f2a"] = "A EQUIPE ROCKET deve estar tentando\\nCAVAR um jeito de aprontar!",
  ["g3:08191f64"] = "A EQUIPE ROCKET abriu uma nova\\nsaída!",
  ["g3:08191f80"] = "Meu marido gosta de trocar\\nPOKéMON.\\pVocê tá capturando POKéMON pra\\nsua POKéDEX, não é?\\pSe importaria em trocar com ele?",
  ["g3:08191ffb"] = "Aquele BILL!\\pOuvi dizer que ele faz de tudo\\npara conseguir POKéMON raros.\\pPelo que dizem, não tem limites\\npara o que ele é capaz de fazer.",
  ["g3:08192079"] = "Você já ouviu falar do BILL?\\pTodo mundo chama ele de\\nPOKéMANÍACO!\\pMas acho que as pessoas têm\\ninveja dele.\\pQuem não gostaria de poder se\\ngabar dos seus POKéMON?",
  ["g3:08192116"] = "O BILL tem muitos POKéMON!\\nE alguns deles são bem raros!",
  ["g3:0819214c"] = "Que tal subir as escadas e tentar\\ntrocar POKéMON com seus amigos?\\pTrocando, você pode conseguir\\numa grande variedade de POKéMON.\\pAlém disso, os POKéMON conseguidos\\nem trocas crescem mais rápido.",
  ["g3:081921ef"] = "Oi, você não é daqui!\\pSó os TREINADORES que têm um\\nmétodo pra treinar seus POKéMON\\ppodem se tornar profissionais.\\pQual é sua tática pra capturar e\\ntreinar POKéMON?\\pMinha tática é ofensiva total com\\nos POKéMON do tipo ÁGUA!",
  ["g3:081922bf"] = "A MT03 contém PULSO D'ÁGUA.\\pUse num POKéMON aquático!",
  ["g3:081922f7"] = "A INSÍGNIA CASCATA faz com que\\ntodos os POKéMON até o Nv. 30\\pobedeçam.\\pAté mesmo os forasteiros, que\\nforam conseguidos em trocas.\\pE tem mais, agora você pode\\nusar CORTAR a qualquer hora,\\pmesmo fora de batalhas.\\pVocê pode CORTAR árvores pequenas\\npara abrir novos caminhos.\\pTambém pode ficar com minha\\nMT favorita.",
  ["g3:081923f1"] = "{PLAYER} recebeu a MT03\\nda MISTY.",
  ["g3:0819240e"] = "É melhor arrumar um espaço aí!",
  ["g3:0819242d"] = "Uau!\\nVocê é demais!\\pTudo bem!\\pPode ficar com a INSÍGNIA CASCATA\\npra mostrar que me derrotou.",
  ["g3:08192481"] = "Como assim? Você?\\nSou boa demais pra você!\\pA MISTY não precisa se incomodar.",
  ["g3:081924d0"] = "Você me surpreendeu!",
  ["g3:081924e4"] = "Você tem que enfrentar outros\\nTREINADORES pra descobrir a\\psua força.",
  ["g3:08192524"] = "Splash!\\pSou o primeiro!\\nVamos lá!",
  ["g3:08192547"] = "Não pode ser!",
  ["g3:08192556"] = "A MISTY é uma TREINADORA que\\nestá sempre melhorando.\\pEla não vai perder pra alguém\\ncomo você!",
  ["g3:081925ac"] = "E aí!\\nCAMPEÃO em ascensão!\\pDeixa eu te dar um conselho!\\pA LÍDER, MISTY, é uma profissional\\nque usa POKéMON do tipo ÁGUA.\\pVocê pode drenar toda a água\\ndeles com POKéMON do tipo PLANTA.\\pOu pode usar POKéMON do tipo\\nELÉTRICO para eletrizá-los!",
  ["g3:08192688"] = "Você derrotou a MISTY!\\nViu, o que eu te disse?\\pVocê e eu, jovem, formamos\\numa equipe e tanto!",
  ["g3:081926e1"] = "GINÁSIO POKéMON de CERULEAN\\nLÍDER: MISTY\\pTREINADORES VENCEDORES:\\n{RIVAL}",
  ["g3:08192719"] = "GINÁSIO POKéMON de CERULEAN\\nLÍDER: MISTY\\pTREINADORES VENCEDORES:\\n{RIVAL} e {PLAYER}",
  ["g3:08192755"] = "Olá!\\nBoas-vindas à nossa LOJA DE\\pBICICLETAS.\\pTemos a BICICLETA perfeita para\\nvocê!",
  ["g3:08192796"] = "Sinto muito!\\nVocê não pode pagar por ela!",
  ["g3:081927b2"] = "Ah, isso é...\\pUm VALE-BICICLETA!\\pCerto!\\nAqui está!",
  ["g3:081927e1"] = "{PLAYER} trocou o VALE-BICICLETA\\npor uma BICICLETA.",
  ["g3:0819280e"] = "Obrigado!\\nVolte sempre!",
  ["g3:08192833"] = "O que achou da sua nova BICICLETA?\\nGosta de como ela anda?\\pVocê pode usá-la na CICLOVIA e\\naté mesmo em cavernas!",
  ["g3:081928cf"] = "Uma bicicleta da cidade já serve\\npra mim.\\pJá que não dá pra colocar uma\\ncestinha numa bicicleta de montanha.",
  ["g3:08192937"] = "Essas bicicletas são legais, mas\\ncustam os olhos da cara!",
  ["g3:08192968"] = "Uau.\\nSua BICICLETA é muito legal!",
  ["g3:081929ad"] = "Uma BICICLETA novinha em folha!",
  ["g3:081929c2"] = "Os REPELENTES não só afastam os\\ninsetos, mas também funcionam\\pcontra POKéMON fracos.\\pColoque seu POKéMON mais forte\\nno topo da LISTA de POKéMON.\\pSe seu primeiro POKéMON for forte,\\no efeito do REPELENTE será ampliado.",
  ["g3:08192a79"] = "Você já ouviu falar em DOCE RARO?\\nEles não são vendidos em lojas.\\pAcho que faz os POKéMON crescerem\\nbem rápido.",
  ["g3:08192af0"] = "Ai-ai...\\nTenho tanto tempo e tão pouca\\pcoisa pra fazer...\\pNão tem nada divertido acontecendo\\npor aí?",
  ["g3:08192b43"] = "Ah!\\nUma notícia fresquinha!\\pHmm...\\pEntendi!\\nFoi muito informativo!\\pMuito bem, é ótimo que jovens\\nse interessem pelas notícias.\\pQuero agradecer por me trazer\\nessa notícia, pegue isso.",
  ["g3:08192c07"] = "Ah!\\nUma nova notícia!\\pHmm...\\pIncrível!\\nQue notícia incrível!\\pNão via uma história assim há\\nmuito tempo!\\pObrigado por me trazer essa\\nnotícia fantástica. Aqui estão\\palgumas FRUTAS!",
  ["g3:08192cd5"] = "Seria uma pena não compartilhar\\nessas notícias...\\pEu adoraria poder compartilhá-las\\ncom alguém...",
  ["g3:08192d4b"] = "Ah, você espalhou as notícias?\\pBoas notícias se tornam valiosas\\nquando são compartilhadas.\\pPor ter espalhado as notícias,\\npegue isso!",
  ["g3:08192de3"] = "Você espalhou as notícias ainda\\nmais? Magnífico!\\pAquela notícia deve estar\\nadorando ser tão compartilhada.\\pSim, com certeza!\\pEm meu nome e em nome das\\nnotícias, pegue isso!\\pVou te dar mais FRUTAS do que\\no normal.",
  ["g3:08192ec5"] = "Tô me divertindo muito com tantas\\nnotícias diferentes.\\pSim, tô satisfeito! Não vou ficar\\nentediado por um tempo.",
  ["g3:08192f2a"] = "Hã? Seu SACO DE FRUTAS está cheio.\\nNão tem onde colocar meu presente.",
  ["g3:08192f67"] = "Eu preparo vários remédios a\\npartir do PÓ DE FRUTA.\\pCom um bom PÓ DE FRUTA, posso\\nfazer qualquer tipo de remédio.\\pBem, você tem interesse em\\nFRUTAS?",
  ["g3:08193003"] = "Ah, que bom! Tenho uma coisa\\nperfeita pra você.",
  ["g3:08193033"] = "No segundo andar dos CENTROS\\nPOKéMON, na SALA DIRETA, tem\\puma coisa nova.\\pFoi instalada uma máquina para\\nAdaptadores Sem Fio, que permite\\ptriturar FRUTAS.\\pE é aí que você entra.\\pQuero te pedir um favor, algo\\nque só posso confiar a você.\\pVocê pode fazer PÓ DE FRUTA\\npra mim usando essa máquina?\\pNão se esqueça, a máquina tá na\\nSALA DIRETA dos CENTROS POKéMON.\\pSe me trouxer PÓ DE FRUTA, farei\\nremédios pra você.\\pNão se esqueça de triturar FRUTAS\\ne me trazer o PÓ DE FRUTA.",
  ["g3:0819321d"] = "Por que tem que mentir pra mim?\\pQuantas FRUTAS você tem?\\nNenhuma!",
  ["g3:0819325e"] = "Você não tem interesse em\\nFRUTAS?\\pJovem, é importante se interessar\\npor todo tipo de coisas.",
  ["g3:081932c5"] = "Ahem! Você trouxe PÓ DE FRUTA\\npra mim?",
  ["g3:081932f4"] = "Pelo que você gostaria de trocar?",
  ["g3:0819331e"] = "Você quer trocar seu PÓ DE\\nFRUTA por uma unidade de\\p{STR_VAR_1}?",
  ["g3:08193352"] = "Hã? Você não tem PÓ DE FRUTA\\nsuficiente.",
  ["g3:0819337a"] = "Este PÓ DE FRUTA é de qualidade.\\nSerá ótimo pra fazer remédios.\\pQuer trocar mais PÓ DE FRUTA por\\noutras coisas?",
  ["g3:081933fb"] = "Tudo bem.\\nEspero que volte logo.",
  ["g3:0819342f"] = "Venha me ver se quiser trocar\\nseu PÓ DE FRUTA.",
  ["g3:08193465"] = "A EQUIPE ROCKET faz qualquer\\ncoisa por dinheiro!\\pNão existe trabalho sujo demais,\\nato cruel demais, nem crime\\pperverso demais!",
  ["g3:081934de"] = "Vi a mãe do CUBONE tentando\\nescapar da EQUIPE ROCKET.\\pEla foi morta ao tentar fugir...",
  ["g3:0819353a"] = "Você sabe que a espécie CUBONE\\nusa crânios, não é?\\pAs pessoas pagam muito por um\\ndeles.",
  ["g3:0819358e"] = "Mudei para esta cidade\\nrecentemente.\\pOuvi dizer que o SR. FUJI também\\nnão é nativo daqui.",
  ["g3:081935ed"] = "Que estranho, o SR. FUJI não\\nestá aqui. Para onde ele foi?",
  ["g3:0819361d"] = "O SR. FUJI estava rezando sozinho\\npela mãe do CUBONE.",
  ["g3:08193652"] = "Esta é mesmo a casa do SR. FUJI.\\pEle é muito bondoso.\\pEle cuida de POKéMON abandonados\\ne órfãos.",
  ["g3:081936b4"] = "É tão quentinho!\\nPOKéMON são tão bons de abraçar.",
  ["g3:081936de"] = "NIDORINO: Gaoo!",
  ["g3:081936ee"] = "PSYDUCK: Gwappa!",
  ["g3:081936ff"] = "SR. FUJI: {PLAYER}...\\pSua jornada da POKéDEX exige\\ngrande dedicação.\\pSem um amor profundo pelos\\nPOKéMON, sua jornada pode\\pfracassar.\\pNão sei se vai ajudar, mas\\ngostaria que ficasse com isto.",
  ["g3:081937bd"] = "{PLAYER} recebeu uma POKéFLAUTA\\ndo SR. FUJI.",
  ["g3:081937e5"] = "Ao ouvir a POKéFLAUTA, os POKéMON\\nadormecidos vão acordar na hora.\\pTente usá-la em POKéMON que\\nestejam dormindo e bloqueando\\po caminho.",
  ["g3:0819385b"] = "Você não tem mais espaço!",
  ["g3:08193878"] = "SR. FUJI: A minha POKéFLAUTA\\nfoi útil para você?",
  ["g3:081938a0"] = "REVISTA do FA POKéMON\\nSorteio mensal do grande prêmio!\\pO formulário de inscrição está...\\pSumiu! Foi recortado.\\nAlguém já deve ter se inscrito.",
  ["g3:0819392b"] = "Revistas de POKéMON enchem a\\nestante.\\pINSIDER POKéMON...\\pFA POKéMON...",
  ["g3:0819396b"] = "CUBONE: Kyarugoo!",
  ["g3:0819397d"] = "Aqueles ROCKETS horríveis!\\nEles não merecem misericórdia!\\pA pobre mãe do CUBONE...\\pEla foi morta tentando escapar da\\nEQUIPE ROCKET.",
  ["g3:081939f8"] = "O fantasma da TORRE POKéMON\\nsumiu!\\pAlguém deve ter acalmado seu\\nespírito inquieto!",
  ["g3:08193a4b"] = "Olá, olá!\\nSou o AVALIADOR de NOMES oficial!\\pQuer que eu avalie os apelidos dos\\nseus POKéMON?",
  ["g3:08193aa6"] = "De qual POKéMON você quer que\\neu avalie o apelido?",
  ["g3:08193ad2"] = "{STR_VAR_1}, é isso?\\nÉ um apelido até que bom!\\pMas você gostaria que eu desse\\num nome melhor?\\pO que acha?",
  ["g3:08193b36"] = "Ah, ótimo. Então, qual vai ser\\no novo apelido?",
  ["g3:08193b66"] = "Pronto! A partir de agora, este\\nPOKéMON será conhecido como\\p{STR_VAR_1}!\\pÉ um nome bem melhor!\\nQue sorte a sua!",
  ["g3:08193bd4"] = "Entendo.\\nVolte sempre para visitar.",
  ["g3:08193bf0"] = "Pronto! A partir de agora, este\\nPOKéMON será conhecido como\\p{STR_VAR_1}!\\pParece não ter mudado nada, e\\nainda assim é muito superior!\\pQue sorte a sua!",
  ["g3:08193c82"] = "{STR_VAR_1}, é isso?\\nÉ um nome realmente impecável!\\pCuide bem de {STR_VAR_1}!",
  ["g3:08193cc4"] = "Ora, ora.\\nÉ só um OVO!",
  ["g3:08193ce5"] = "Tô procurando itens que aumentam\\nos atributos dos POKéMON.\\pEles funcionam só durante uma\\núnica batalha.\\pATAQUE X, DEFESA X, VELOCIDADE X\\ne ESPECIAL X são o que procuro.\\pVocê sabe onde posso consegui-los?",
  ["g3:08193db6"] = "Você comprou alguns REANIMADORES?\\nEles reanimam um POKéMON desmaiado!",
  ["g3:08193df1"] = "Às vezes, uma dupla de TREINADORES\\nvai te desafiar com dois POKéMON\\pao mesmo tempo.\\pSe isso acontecer, você também\\nterá que mandar dois POKéMON\\ppara a batalha.",
  ["g3:08193ec1"] = "Sou o MESTRE DA PESCA!\\pEu simplesmente aaaaamo pescar!\\nNão consigo ficar sem pescar.\\pMe fala, você gosta de pescar?",
  ["g3:08193f2a"] = "Ótimo! Gosto do seu jeito.\\nAcho que podemos ser amigos.\\pPegue isto e vá pescar,\\njovem camarada!",
  ["g3:08193f81"] = "{PLAYER} recebeu uma VARA ANTIGA\\ndo MESTRE DA PESCA.",
  ["g3:08193faf"] = "Pescar é um estilo de vida!\\nÉ como a mais fina poesia.\\pDos mares aos rios, vá lá fora e\\nfisgue um grandão, camarada.",
  ["g3:08194028"] = "Ah...\\nQue decepção...",
  ["g3:08194045"] = "Olá, {PLAYER}!\\pOs peixes estão mordendo?",
  ["g3:0819406f"] = "Ah, não!\\pEu tinha um presente para você,\\nmas você não tem mais espaço!",
  ["g3:081940af"] = "Mesmo que estejam no mesmo nível,\\nos POKéMON podem ter status e\\phabilidades muito diferentes.\\pUm POKéMON criado por um TREINADOR\\né mais forte do que um que está na\\pnatureza.",
  ["g3:08194145"] = "Meu POKéMON foi envenenado! Ele\\ndesmaiou enquanto a gente andava!",
  ["g3:08194180"] = "É verdade que um POKéMON de nível\\nmais alto será mais poderoso...\\pMas todo POKéMON tem pontos fracos\\ncontra tipos específicos.\\pPortanto, não existe um POKéMON\\nque seja forte em todos os casos.",
  ["g3:08194234"] = "A vontade de batalhar com alguém\\ncom quem você já cruzou antes...\\pVocê já sentiu essa vontade?\\nTenho certeza de que sim.\\pEu também queria batalhar com\\ncertas pessoas de novo e de novo.\\pEntao, tenho distribuído isto.\\nPor favor, pegue um!",
  ["g3:0819430f"] = "Use esse dispositivo e você vai\\nencontrar TREINADORES procurando\\puma revanche.\\pMas é preciso carregar a bateria\\ndele para poder usá-lo.",
  ["g3:08194381"] = "Como se usa o BUSCA-LUTAS?\\nNão tem segredo.\\pEle dá uns bip-bip-bip, e os\\nTREINADORES ao seu redor vão\\pouvir.\\pSe algum TREINADOR quiser uma\\nrevanche, ele vai avisar na hora.\\pCarregue a bateria e use-o\\nenquanto estiver em uma estrada.",
  ["g3:0819446f"] = "Você não vai admirar a cauda\\nfofa do meu PIKACHU?",
  ["g3:0819449c"] = "Humph!\\pMeu PIKACHU é duas vezes mais\\nfofo!",
  ["g3:081944cc"] = "Eu amo o meu SEEL!\\nÉ tão adorável!\\pEle faz “Kyuuuh,” quando eu abraço ele!",
  ["g3:08194518"] = "Minha nossa!\\pMeu SEEL é muito mais encantador.\\nDiria que o dobro!",
  ["g3:0819455a"] = "PIKACHU: Chu! Pikachu!",
  ["g3:08194571"] = "SEEL: Kyuoo!",
  ["g3:0819457e"] = "Sou o presidente do FA-CLUBE\\nPOKéMON!\\pEu crio mais de cem POKéMON!\\pSou muito exigente quando o assunto\\né POKéMON! Com certeza!\\pEntao...\\pVocê veio me visitar para ouvir\\nsobre os meus POKéMON?",
  ["g3:08194628"] = "Ótimo!\\nEntao preste atenção!\\pMeu RAPIDASH favorito...\\pÉ...fofo...adorável...inteligente...\\nalém de...incrível...você não acha?...\\pah, sim...é...deslumbrante...\\pgentil...amável!\\pAbraçá-lo...quando...dorme...é quente\\ne aconchegante...espetacular...\\pdeslumbrante...\\p... Ops! Que horas são!\\pFalei demais com você!\\pObrigado por me ouvir!\\nQuero que você fique com isto!",
  ["g3:0819474e"] = "{PLAYER} recebeu um VALE-BICICLETA\\ndo PRESIDENTE.",
  ["g3:0819477c"] = "Leve esse VALE-BICICLETA à\\nLOJA DE BICICLETAS na CIDADE\\pDE CERULEAN.\\pTroque-o por uma BICICLETA\\ntotalmente de graça!\\pNão se preocupe, meu FEAROW\\nfavorito pode me levar voando\\ppara qualquer lugar que eu\\pprecise ir.\\pEntao, não preciso de uma\\nBICICLETA.\\pEspero que você curta pedalar!",
  ["g3:08194860"] = "Ah. Volte quando quiser ouvir a\\nminha história!",
  ["g3:0819488e"] = "Olá, {PLAYER}!\\pVocê veio me ver sobre os meus\\nPOKéMON de novo?\\pNão?\\nQue pena!",
  ["g3:081948d2"] = "Arrume um espaço aí para isso!",
  ["g3:081948e6"] = "Nosso PRESIDENTE fala com muita\\npaixão sobre os POKéMON.",
  ["g3:08194910"] = "Vamos todos ouvir com educação\\nos outros TREINADORES!",
  ["g3:0819493d"] = "Se alguém se gabar, retribua na\\nmesma moeda!",
  ["g3:08194960"] = "Nosso PRESIDENTE adora mesmo\\nseus POKéMON.\\pMas acho que a pessoa que mais\\nconquista os POKéMON é a DAISY.",
  ["g3:081949cb"] = "Oi!\\nVocê tem um {STR_VAR_1}?\\pQuer trocar pelo meu\\n{STR_VAR_2}?",
  ["g3:081949fd"] = "Que pena.",
  ["g3:08194a0d"] = "... Isso não é um {STR_VAR_1}.\\pSe você conseguir um, troque\\ncomigo por favor!",
  ["g3:08194a44"] = "Obrigada!",
  ["g3:08194a4f"] = "Como está o meu velho {STR_VAR_2}?\\nO meu {STR_VAR_1} vai muito bem!",
  ["g3:08194a77"] = "Existem pessoas cruéis que usam\\nPOKéMON para cometer crimes.\\pA EQUIPE ROCKET trafica POKéMON\\nraros, por exemplo.\\pEles também abandonam POKéMON que\\nconsideram impopulares ou inúteis.\\pEsse é o tipo de gente horrível\\nque eles são: a EQUIPE ROCKET.",
  ["g3:08194b65"] = "Acho que os POKéMON podem ser bons\\nou maus. Depende do TREINADOR.",
  ["g3:08194ba4"] = "Ei, jovem! O que você acha que\\nestá fazendo aqui?\\pVocê não vai durar muito em combate!\\nNão com essa força ridícula!\\pEu te digo, jovem, os POKéMON\\nelétricos me salvaram durante a\\pguerra!\\pEles eletrocutaram meus inimigos\\naté deixá-los paralisados!\\pVou fazer o mesmo com você!",
  ["g3:08194c8e"] = "Um pequeno conselho, jovem!\\pA eletricidade é muito poderosa!\\pMas é inútil contra POKéMON do\\ntipo TERRA!",
  ["g3:08194cfa"] = "A INSÍGNIA TROVÃO aumenta a\\nVELOCIDADE dos seus POKéMON!\\pEla também permite que seus\\nPOKéMON voem a qualquer hora,\\prápido como um relâmpago, jovem!\\pVocê é especial, jovem!\\nPegue isto!",
  ["g3:08194d87"] = "{PLAYER} recebeu a TM34\\ndo TEN. SURGE.",
  ["g3:08194da8"] = "A TM34 contém ONDA DE CHOQUES!\\pEnsine a um POKéMON do tipo\\nELÉTRICO!",
  ["g3:08194de3"] = "Ei, jovem, abra espaço na sua\\nMOCHILA!",
  ["g3:08194e03"] = "Isso sim foi chocante!\\pVocê mandou bem, jovem!\\pMuito bem, então, pegue esta\\nINSÍGNIA TROVÃO!",
  ["g3:08194e57"] = "Quando eu estava no Exército, o\\nTEN. SURGE era meu comandante\\prígido.\\pEle era um chefe durão.",
  ["g3:08194ea5"] = "Já chega!\\nVocê é muito hábil!",
  ["g3:08194ebd"] = "Não é fácil abrir essa porta.\\pO TEN. SURGE sempre foi famoso por\\nsua natureza cautelosa no Exército.",
  ["g3:08194f1f"] = "Sou peso-leve, mas mando bem\\ncom eletricidade!\\pFoi por isso que entrei neste\\nGINÁSIO.",
  ["g3:08194f6f"] = "Frito!",
  ["g3:08194f76"] = "Tá, eu falo!\\pO TEN. SURGE disse que escondeu os\\ninterruptores das portas dentro de\\palguma coisa.",
  ["g3:08194fbd"] = "Este não é lugar para crianças!\\nNem mesmo se você for hábil!",
  ["g3:08194ff1"] = "Uau!\\nVocê me surpreendeu!",
  ["g3:08195004"] = "O TEN. SURGE instalou as armadilhas\\nno GINÁSIO pessoalmente.\\pEle colocou travas duplas por todo\\nlado. Deixa eu te dar uma dica.\\pQuando você abre a primeira trava,\\na segunda está bem ao lado dela.",
  ["g3:081950b4"] = "E aí!\\nCAMPEÃO em ascensão!\\pO TEN. SURGE tem um apelido.\\pAs pessoas chamam ele de o\\nRelâmpago Americano!\\pEle é um especialista em POKéMON\\nelétricos.\\pOs POKéMON do tipo VOADOR e ÁGUA\\nse dão mal contra o tipo ELÉTRICO.\\pCuidado também com a paralisia.\\pO TEN. SURGE é muito cauteloso.\\pEle se trancou lá dentro, então\\nnão vai ser fácil chegar até ele.",
  ["g3:081951ec"] = "Oof!\\nEssa batalha foi eletrizante!",
  ["g3:0819520b"] = "GINÁSIO POKéMON de VERMILION\\nLÍDER: TEN. SURGE\\pTREINADORES VENCEDORES:\\n{RIVAL}",
  ["g3:08195248"] = "GINÁSIO POKéMON de VERMILION\\nLÍDER: TEN. SURGE\\pTREINADORES VENCEDORES:\\n{RIVAL} e {PLAYER}",
  ["g3:08195289"] = "Não!\\nSó tem lixo aqui.",
  ["g3:081952a8"] = "Ei! Tem um interruptor embaixo\\ndo lixo! Vamos ativá-lo!\\pA primeira trava elétrica abriu!",
  ["g3:08195330"] = "A segunda trava elétrica abriu!\\nA porta motorizada se abriu!",
  ["g3:0819536c"] = "Não!\\nSó tem lixo aqui.\\pEi!\\nAs travas elétricas foram reiniciadas!",
  ["g3:081953af"] = "Vou fazer meu PIDGEY levar uma\\ncarta para SAFFRON, no norte.",
  ["g3:081953ee"] = "PIDGEY: Kurukkoo!",
  ["g3:08195400"] = "Querida PIPPI,\\nEspero te ver em breve.\\pOuvi dizer que SAFFRON está tendo\\nproblemas com a EQUIPE ROCKET.\\pVERMILION parece estar segura.",
  ["g3:08195471"] = "Quero trocar CARTAS com todo\\ntipo de pessoa.\\pEnvio meu PIDGEY para uma SALA\\nUNIAO para trocar as CARTAS\\ppor mim.",
  ["g3:081954dd"] = "Olá!\\nBoas-vindas ao SHOPPING DE CELADON.\\pO quadro à direita mostra como\\nas lojas estão organizadas.",
  ["g3:08195537"] = "P1: RECEPÇÃO\\pP2: LOJA DOS TREINADORES\\pP3: VIDEOGAMES\\pP4: PRESENTES\\pP5: FARMÁCIA\\pTERRAÇO: MÁQUINAS DE VENDAS\\nAUTOMÁTICAS",
  ["g3:081955b3"] = "P1: RECEPÇÃO",
  ["g3:0819560f"] = "Para jornadas longas, você tem\\nque comprar REANIMAR.",
  ["g3:08195638"] = "Os melhores itens para\\nTREINADORES!\\pP2: LOJA DOS TREINADORES",
  ["g3:0819566b"] = "Temos um cliente, LANCE, que\\naparece de vez em quando.\\pEle sempre compra capas.\\pSerá que ele tem muitas capas\\niguais em casa?",
  ["g3:081956e9"] = "POKéMON capturados são registrados com um número de ID, e o seu TO.\\pTO significa “TREINADOR Original” -\\no TREINADOR que o pegou primeiro.",
  ["g3:08195769"] = "Beleza!\\pMeu amigo vai trocar comigo seu\\nKANGASKHAN pelo meu HAUNTER!",
  ["g3:081957b0"] = "Vamos, HAUNTER!\\pAdoro HAUNTER!\\nEu coleciono eles!\\pHa?\\pO HAUNTER se transformou num\\nPOKéMON diferente durante a troca!",
  ["g3:08195823"] = "Você pode identificar os POKéMON\\nque recebe em trocas pelo N.ºID\\pdeles.",
  ["g3:08195863"] = "É um Super Nintendo.",
  ["g3:08195875"] = "Um RPG!\\nNão tenho tempo para isso!",
  ["g3:08195897"] = "Um jogo de esportes!\\nO papai vai gostar disso!",
  ["g3:081958b8"] = "Um jogo de quebra-cabeça!\\nParece viciante!",
  ["g3:081958d8"] = "Um jogo de luta!\\nParece difícil!",
  ["g3:081958f6"] = "P3: VIDEOGAMES",
  ["g3:08195907"] = "Vermelho e Verde!\\nOs dois são POKéMON!",
  ["g3:08195928"] = "Ah, oi!\\nFinalmente terminei POKéMON.\\pAinda não terminou? Que tal eu\\nte ensinar um bom movimento?\\pO movimento que eu tenho em\\nmente é CONTRA-ATAQUE.\\pToda ação tem uma reação!",
  ["g3:081959cc"] = "Não tem interesse?\\nVenha me ver se mudar de ideia.",
  ["g3:08195a08"] = "Para qual POKéMON devo ensinar\\no movimento CONTRA-ATAQUE?",
  ["g3:08195a31"] = "Você tá usando o movimento\\nCONTRA-ATAQUE que eu ensinei\\pao seu POKéMON?",
  ["g3:08195a68"] = "Tô comprando um presente pra\\nminha namorada.\\pAcho que vai ser um POKéBONECO.\\nÉ o que tá na moda.",
  ["g3:08195ac9"] = "Ouvi uma coisa interessante.\\pSe um POKéMON selvagem aparecer,\\nvocê pode distraí-lo com um\\pPOKéBONECO.\\pVocê pode fugir enquanto o\\nPOKéMON selvagem está distraído.",
  ["g3:08195b5b"] = "Expresse-se com presentes!\\nP4: PRESENTES\\pEspecial de evolução!\\nPEDRAS elementais à venda!",
  ["g3:08195bba"] = "Os aprimoradores de atributos dos\\nPOKéMON só podem ser comprados\\paqui.\\pMAIS PS aumenta os PS base de\\num POKéMON.\\pCÁLCIO aumenta o atributo de\\nATQ. ESP. base de um POKéMON.\\pZINCO aumenta o atributo de\\nDEF. ESP. base de um POKéMON.\\pCARBOIDRATO aumenta o atributo\\nde VELOCIDADE base.",
  ["g3:08195ca0"] = "Vim aqui comprar os aprimoradores\\nde atributos dos POKéMON.\\pPROTEÍNA aumenta o poder de\\nATAQUE base.\\pFERRO aumenta o atributo de\\nDEFESA base.",
  ["g3:08195d14"] = "P5: FARMÁCIA",
  ["g3:08195d22"] = "Tô com sede!\\nQuero alguma coisa pra beber!\\pDar uma bebida pra ela?",
  ["g3:08195d5f"] = "Dar a ela qual bebida?",
  ["g3:08195d75"] = "Eba!\\pÁGUA MINERAL!\\pObrigada!\\nVocê pode ficar com isto!",
  ["g3:08195dad"] = "{PLAYER} recebeu {STR_VAR_2}\\nda garotinha.",
  ["g3:08195dd4"] = "A MT16 contém TELA DE LUZ.\\pÉ um movimento que enfraquece\\no poder de ataques especiais do\\poponente.",
  ["g3:08195e33"] = "Eba!\\pREFRI!\\pObrigada!\\nVocê pode ficar com isto!",
  ["g3:08195e68"] = "A MT20 contém SALVAGUARDA.\\pÉ um movimento que previne\\nproblemas de status nos seus\\pPOKéMON.",
  ["g3:08195ebf"] = "Eba!\\pLIMONADA!\\pObrigada!\\nVocê pode ficar com isto!",
  ["g3:08195ef4"] = "A MT33 contém REFLETIR.\\pÉ um movimento que diminui o poder\\ndos ataques físicos do oponente.",
  ["g3:08195f4f"] = "Você não tem espaço para isto!",
  ["g3:08195f6e"] = "Não, valeu!\\nNem tô com tanta sede!",
  ["g3:08195f98"] = "Minha irmã é uma TREINADORA,\\nacredite ou não.\\pMas ela é tão imatura que me\\ndeixa louco!",
  ["g3:08195fef"] = "Tô com sede!\\nQuero alguma coisa pra beber!",
  ["g3:08196017"] = "TERRAÇO: MÁQUINAS DE VENDAS\\nAUTOMÁTICAS",
  ["g3:08196038"] = "Uma máquina de venda automática!\\nO que ela tem?",
  ["g3:0819605e"] = "Ops, dinheiro insuficiente!",
  ["g3:08196076"] = "Uma lata de {STR_VAR_1} saiu!",
  ["g3:0819608e"] = "Não há mais espaço para itens!",
  ["g3:081960ae"] = "Não tô com sede!",
  ["g3:081960bb"] = "MEOWTH: Miau!",
  ["g3:081960c9"] = "Você não devia gastar todo o seu\\ndinheiro com bebidas.\\pExperimente isto aqui.",
  ["g3:08196109"] = "Nada mata a sede como um bom\\nCHÁ quente.\\pÉ o melhor.",
  ["g3:08196148"] = "Meus queridos POKéMON me fazem\\ncompanhia.\\pMEOWTH até traz dinheiro pra casa!",
  ["g3:08196188"] = "Ah, olá, amorzinho.\\nVocê gostou do meu CHÁ?\\pAliás, amorzinho, você é da\\nCIDADE DE PALLET?\\pUma garota da CIDADE DE PALLET,\\nDAISY, gosta de tomar CHÁ todos\\pos dias.\\pEla visita o SHOPPING DE CELADON\\npra comprar CHÁ.",
  ["g3:0819625b"] = "CLEFAIRY: Pi pippippi!",
  ["g3:08196272"] = "NIDORAN♀: Kya kyaoo!",
  ["g3:08196287"] = "MANSÃO CELADON\\nSuíte da gerente",
  ["g3:081962a7"] = "Sala de reunioes da GAME FREAK",
  ["g3:081962bf"] = "Eu?\\nSou o programador!",
  ["g3:081962d7"] = "Sou o artista gráfico!\\nEu desenhei você!",
  ["g3:081962fb"] = "Eu escrevi a história!\\nA ERIKA não é uma gracinha?\\pTambém gosto muito da MISTY!\\nAh, e também da SABRINA!",
  ["g3:08196356"] = "É mesmo?\\pSou o designer do jogo!\\pCompletar sua POKéDEX é difícil,\\nmas não desista!\\pQuando terminar, venha me contar!",
  ["g3:081963cd"] = "Uau! Muito bem!\\nVocê completou sua POKéDEX!\\pParabéns!\\p...",
  ["g3:0819640c"] = "É o programa do jogo! Mexer nele\\npode causar falhas no jogo!",
  ["g3:0819644b"] = "Alguém está jogando um jogo\\nem vez de trabalhar!",
  ["g3:08196478"] = "É o roteiro!\\nÉ melhor não olhar o final!",
  ["g3:081964a8"] = "Sala de desenvolvimento da\\nGAME FREAK",
  ["g3:081964c4"] = "EU SEI TUDO!",
  ["g3:081964d7"] = "Não há nada que eu não saiba,\\ncomo escrevi no quadro-negro.\\pConheço o mundo dos POKéMON\\nno seu GAME BOY ADVANCE!\\pJunte-se aos seus amigos e\\naproveite para trocar POKéMON!",
  ["g3:08196591"] = "{PLAYER} obteve um EEVEE!",
  ["g3:081965c2"] = "Palestra sobre POKéMON\\pJogando com o Adaptador Sem Fio",
  ["g3:081965f4"] = "Qual título você gostaria de ler?",
  ["g3:08196617"] = "O CLUBE SEM FIO POKéMON fica\\nno andar de cima dos CENTROS\\pPOKéMON.\\pVisite um para se conectar com\\nseus amigos usando o Adaptador\\pSem Fio.",
  ["g3:08196695"] = "Para se conectar com um amigo,\\nvá até a SALA DIRETA.\\pÉ o balcão da direita no\\nCLUBE SEM FIO POKéMON.\\pEntre na SALA DE TROCAS ou\\nno COLISEU com seu amigo.",
  ["g3:0819673c"] = "Para se conectar com qualquer\\npessoa, vá até a SALA UNIÃO.\\pÉ o balcão da esquerda no\\nCLUBE SEM FIO POKéMON.\\pVá até a SALA UNIÃO e divirta-se\\nconhecendo outros TREINADORES.",
  ["g3:081967e3"] = "É um folheto sobre MTs.\\p... ...\\pExistem cinquenta MTs no total.\\pTambém há sete MOs que podem\\nser usadas mais de uma vez.",
  ["g3:0819685b"] = "Uma POKéFLAUTA desperta os\\nPOKéMON adormecidos.\\pEla faz isso com um som que\\nsó eles conseguem ouvir.",
  ["g3:081968c2"] = "Vim de FUCHSIA.\\pÉ uma bela subida pela CICLOVIA,\\npor isso tô exausta.",
  ["g3:08196913"] = "Se eu tivesse uma BICICLETA,\\niria para a CICLOVIA!",
  ["g3:08196940"] = "Boas-vindas!\\pVocê pode trocar suas FICHAS por\\nprêmios incríveis na sala ao lado.",
  ["g3:08196984"] = "Boas-vindas ao CASSINO ROCKET!\\pPrecisa de algumas FICHAS?\\nQuer comprar algumas?",
  ["g3:081969dc"] = "Não?\\nVenha jogar quando quiser!",
  ["g3:081969fb"] = "Ah, sinto muito.\\nVocê não tem um PORTA-FICHAS.",
  ["g3:08196a26"] = "Ops!\\nSeu PORTA-FICHAS está cheio.",
  ["g3:08196a46"] = "Você não tem FICHAS suficientes.",
  ["g3:08196a62"] = "Obrigado.\\nAqui estão suas FICHAS.",
  ["g3:08196a82"] = "Dizem que este lugar é controlado\\npela EQUIPE ROCKET.\\pMas não fala isso pra ninguém.",
  ["g3:08196ac7"] = "Acho que essas máquinas têm\\nprobabilidades diferentes.",
  ["g3:08196af3"] = "Você quer jogar, jovem?",
  ["g3:08196b0d"] = "{PLAYER} recebeu 10 FICHAS\\ndo homem.",
  ["g3:08196b30"] = "Você não precisa das minhas\\nFICHAS!",
  ["g3:08196b49"] = "As vitórias parecem ir e vir.\\nNada é garantido.",
  ["g3:08196b7b"] = "Nesses jogos de caça-níqueis...\\nGanhar ou perder é questão de\\psorte.",
  ["g3:08196bad"] = "Ei!\\pVocê tem mais o que fazer,\\nCAMPEÃO em ascensão!\\pA LÍDER do GINÁSIO de CELADON\\né a ERIKA.\\pEla usa POKéMON do tipo PLANTA e\\nestá em sintonia com a natureza.\\pEla pode parecer dócil por causa\\nde seus arranjos de flores...\\pMas é melhor não subestimá-la!\\n",
  ["g3:08196ca1"] = "Eles oferecem POKéMON raros que\\npodem ser trocados por suas\\pFICHAS.\\pMas não consigo ganhar de jeito\\nnenhum!",
  ["g3:08196cfe"] = "Jogos são assustadores!\\nÉ tão fácil se viciar!",
  ["g3:08196d2b"] = "O que foi?\\nQuer algumas FICHAS?",
  ["g3:08196d47"] = "{PLAYER} recebeu 20 FICHAS\\ndo bom rapaz.",
  ["g3:08196d6f"] = "Você tem muitas FICHAS!",
  ["g3:08196d87"] = "Droga! Preciso de mais FICHAS\\npara o POKéMON que eu quero!",
  ["g3:08196db7"] = "O que foi? Você tá me atrapalhando!\\nToma algumas FICHAS e cai fora!",
  ["g3:08196df8"] = "{PLAYER} recebeu 20 FICHAS\\ndo homem.",
  ["g3:08196e1b"] = "Você já tem muitas FICHAS!",
  ["g3:08196e40"] = "O segredo é observar bem os rolos.",
  ["g3:08196e69"] = "Tô protegendo este pôster!\\nÉ melhor cair fora!",
  ["g3:08196e95"] = "Droga!",
  ["g3:08196e9b"] = "O ESCONDERIJO da EQUIPE ROCKET\\npode ser descoberto!\\pÉ melhor eu avisar o CHEFE!",
  ["g3:08196edc"] = "Ei!\\pUm botão atrás do cartaz?!\\nVamos apertar!",
  ["g3:08196f0d"] = "É necessário um PORTA-FICHAS...",
  ["g3:08196f26"] = "Ops!\\nVocê não tem um PORTA-FICHAS!",
  ["g3:08196f46"] = "Uma máquina caça-níquel!\\nQuer jogar?",
  ["g3:08196f64"] = "FORA DE SERVIÇO\\nEsta está quebrada.",
  ["g3:08196f81"] = "FORA PARA ALMOÇO\\nEsta está reservada.",
  ["g3:08196fa0"] = "As chaves de alguém!\\nVão voltar.",
  ["g3:08196fc1"] = "Quero muito aquele PORYGON!\\nMas é difícil ganhar nas máquinas\\pcaça-níqueis!",
  ["g3:08196fff"] = "Gahaha! Eu ganhei muito hoje!\\nSe todos os dias fossem assim...",
  ["g3:0819703e"] = "É necessário um PORTA-FICHAS...",
  ["g3:08197057"] = "Trocamos suas FICHAS por prêmios.",
  ["g3:0819707a"] = "Qual prêmio você quer?",
  ["g3:0819709d"] = "Entao, você quer {STR_VAR_1}?",
  ["g3:081970b2"] = "Certo, você quer uma MT de\\n{STR_VAR_2}?",
  ["g3:081970d5"] = "Desculpe, você vai precisar de\\nmais FICHAS do que isso.",
  ["g3:08197114"] = "Olá...\\nClima adorável, não acha?\\pÉ tão agradável...\\p...Ah, céus...\\nComo estou distraída. Boas-vindas.\\pMeu nome é ERIKA.\\Sou a LÍDER do GINÁSIO DE CELADON.\\pSou uma estudante da arte de criar flores.\\pMeus POKéMON são todos do tipo GRAMA.\\p...Ah, desculpa, não fazia ideia que você queria me desafiar.\\pMuito bem, mas não vou perder.",
  ["g3:08197260"] = "Oh!\\nEu aceito minha derrota.\\pVocê é muito forte.\\pVocê merece ganhar a\\nINSÍGNIA ARCO-ÍRIS.",
  ["g3:081972b8"] = "Você está catalogando POKéMON?\\nAdmito que estou impressionada.\\pEu nunca colecionaria POKéMON\\nse eles não fossem bonitos.",
  ["g3:08197327"] = "A INSÍGNIA ARCO-ÍRIS fará com\\nque os POKéMON de até Nv. 50\\pobedeçam.\\pEla também permite que os\\nPOKéMON usem SUPERFORÇA dentro\\pe fora de batalhas.\\pPor favor, fique com isto também.",
  ["g3:081973ba"] = "{PLAYER} recebeu a MT19\\nde ERIKA.",
  ["g3:081973d7"] = "A MT19 contém GIGADRENO.\\pA metade do dano causado é\\nrevertida para curar seu POKéMON.\\pVocê não acha que é um\\nmovimento incrível?",
  ["g3:0819745d"] = "Você precisa de mais espaço.",
  ["g3:0819747c"] = "Deixa eu te falar uma coisa sobre\\neste GINÁSIO.\\pSó mulheres de verdade podem\\nentrar aqui!",
  ["g3:081974c4"] = "Mas isso foi muito brusco!",
  ["g3:081974d6"] = "Bleh!\\nTomara que a ERIKA acabe com você!",
  ["g3:081974fa"] = "Ah, seja Boas-vindas.\\nEstava ficando entediada.",
  ["g3:0819751c"] = "Minha maquiagem!",
  ["g3:08197527"] = "Os POKéMON do tipo PLANTA são\\nresistentes contra o tipo ÁGUA.\\pEles também têm uma vantagem\\nsobre os POKéMON do tipo PEDRA\\pe os POKéMON do tipo TERRA.",
  ["g3:08197595"] = "... Não era você quem estava\\nespiando aqui mais cedo?",
  ["g3:081975bb"] = "Você é surpreendente!",
  ["g3:081975d1"] = "Ah, você tava olhando pra ERIKA...\\nNão tava olhando pra mim...",
  ["g3:0819760b"] = "Olha, olha!\\nVeja meus POKéMON!\\pEu gosto do tipo PLANTA.\\nGosto de como são fáceis de treinar.",
  ["g3:08197660"] = "Não!",
  ["g3:08197664"] = "No nosso GINÁSIO, só usamos\\nPOKéMON do tipo PLANTA.\\pPor quê? Também usamos eles\\npara fazer arranjos de flores!",
  ["g3:081976c5"] = "Ah, oi!\\pAqui a gente não gosta de\\nPOKéMON do tipo INSETO ou FOGO!",
  ["g3:081976ff"] = "Ah!\\nVocê!",
  ["g3:08197708"] = "A nossa LÍDER ERIKA pode ser\\ndiscreta, mas ela é famosa por aqui.",
  ["g3:08197747"] = "Prazer em te conhecer.\\nMeu passatempo é treinar POKéMON.",
  ["g3:0819777a"] = "Oh!\\nEsplêndido!",
  ["g3:08197788"] = "Vou ter um encontro às cegas.\\nTenho que aprender a ser educada,\\pespecialmente se tiver que batalhar.",
  ["g3:081977e5"] = "Boas-vindas ao GINÁSIO de\\nCELADON!\\pÉ melhor não subestimar as lindas\\nmulheres daqui.",
  ["g3:08197832"] = "Oh!\\nDerrotada!",
  ["g3:0819783e"] = "Não trouxe meus melhores POKéMON.\\nEspere até a próxima vez!",
  ["g3:08197874"] = "GINÁSIO POKéMON de CELADON\\nLÍDER: ERIKA\\pTREINADORES VENCEDORES:\\n{RIVAL}",
  ["g3:081978ab"] = "GINÁSIO POKéMON de CELADON\\nLÍDER: ERIKA\\pTREINADORES VENCEDORES:\\n{RIVAL} e {PLAYER}",
  ["g3:081978e6"] = "Oi!\\pDesculpa, mas a gente tá fazendo\\numa pausa agora.",
  ["g3:08197915"] = "Meus POKéMON são fracos, por isso\\ntenho que ir à FARMÁCIA sempre.",
  ["g3:08197952"] = "Psss! Ouvi dizer que tem um porão\\nembaixo do CASSINO.",
  ["g3:0819798a"] = "Nhec...\\pO homem naquela mesa perdeu tudo\\nnas máquinas.",
  ["g3:081979c1"] = "Vai em frente! Pode rir!\\nTô totalmente quebrado!\\pChega de máquinas pra mim!\\nVou me endireitar!\\pAqui!\\nNão vou mais precisar disso!",
  ["g3:08197a38"] = "{PLAYER} recebeu um PORTA-FICHAS\\ndo homem.",
  ["g3:08197a5e"] = "Arrume um espaço aí para isso!",
  ["g3:08197a72"] = "Eu achava que ia conseguir\\nrecuperar tudo...",
  ["g3:08197a9f"] = "Hehehe!\\pÉ grana que não acaba mais nos\\ncaça-níqueis!",
  ["g3:08197ad3"] = "CHEFE!\\pHoje já enviamos mais dois mil\\nPOKéMON como prêmios das máquinas!",
  ["g3:08197b20"] = "Não toque no pôster no CASSINO!\\pNão tem nenhum botão secreto\\natrás dele!",
  ["g3:08197b77"] = "POKéMON?\\nNão, este é um hotel para pessoas.\\pEstamos lotados, infelizmente.",
  ["g3:08197bbe"] = "Tô de férias com meu irmão e\\nmeu namorado.\\pCELADON é uma cidade muito\\nbonita!",
  ["g3:08197c0c"] = "Por quê?\\nPor que ela trouxe o irmão dela?",
  ["g3:08197c30"] = "Eba! Tô de férias! Minha irmã\\nme trouxe junto! Que demais!",
  ["g3:08197c6b"] = "Boas-vindas à ZONA DE SAFÁRI!",
  ["g3:08197c87"] = "Por apenas $500, você pode jogar\\no JOGO DO SAFÁRI.\\pVocê pode explorar livremente a\\nárea do safári e capturar o que\\pquiser.\\pGostaria de jogar?",
  ["g3:08197d07"] = "Vai dar $500, por favor!\\pAqui usamos apenas um tipo especial\\nde POKé BOLAS.",
  ["g3:08197d50"] = "{PLAYER} recebeu 30 BOLAS SAFÁRI\\ndo atendente.",
  ["g3:08197d80"] = "Vamos te chamar pelo alto-falante\\nquando seu tempo acabar ou quando\\pas BOLAS SAFÁRI acabarem.\\pBem, desejo a você boa sorte!",
  ["g3:08197de9"] = "Certo.\\nVolte sempre!",
  ["g3:08197e02"] = "Ops!\\nDinheiro insuficiente!",
  ["g3:08197e1a"] = "Você vai sair da ZONA DE SAFÁRI\\nantes da hora?",
  ["g3:08197e48"] = "Por favor, devolva quaisquer\\nBOLAS SAFÁRI que ainda tenha.",
  ["g3:08197e7a"] = "Boa sorte!",
  ["g3:08197e85"] = "Você conseguiu capturar muitos?\\nVolte sempre!",
  ["g3:08197eb0"] = "Olá! É sua primeira vez aqui na\\nZONA DE SAFÁRI?",
  ["g3:08197ee3"] = "A ZONA DE SAFÁRI na verdade tem\\nquatro áreas.\\pCada área tem tipos diferentes de\\nPOKéMON, inclusive alguns raros.\\pUse as BOLAS SAFÁRI fornecidas\\npara capturá-los.\\pAlém das BOLAS SAFÁRI, você também\\npode jogar ISCAS ou PEDRAS.\\pSe você jogar ISCAS, o POKéMON\\nfica menos propenso a fugir, mas\\pmais difícil de capturar.\\pSe você jogar PEDRAS, o POKéMON\\nfica mais propenso a fugir, mas\\pmais fácil de capturar.\\pQuando seu tempo ou as BOLAS\\nSAFÁRI acabarem, é fim de jogo\\ppra você!",
  ["g3:0819809e"] = "Desculpa, você já é de casa!",
  ["g3:081980bc"] = "Eles não têm nenhuma bandeirola\\npromovendo a ZONA DE SAFÁRI?\\pE que tal umas lanternas de papel?\\nNão tem nem calendários?",
  ["g3:08198134"] = "Você já usou VELOCIDADE X?\\nAumenta a velocidade de um\\pPOKéMON em batalha.",
  ["g3:0819816b"] = "A gente apelidou o DIRETOR de\\n“SLOWPOKE”.\\pSabe, ele tem uma cara de paisagem, que nem um SLOWPOKE.",
  ["g3:081981c2"] = "O DIRETOR SLOWPOKE sabe muito\\nsobre POKéMON.\\pEle até tem alguns fósseis de\\nPOKéMON raros e extintos.",
  ["g3:0819822a"] = "O DIRETOR SLOWPOKE veio aqui,\\nmas não consegui entendê-lo.\\pAcho que ele tem algum problema\\nna fala!",
  ["g3:08198285"] = "O DIRETOR SLOWPOKE está\\nrealizando uma campanha\\ppromocional agora mesmo.\\pTente chegar ao canto mais\\ndistante da ZONA DE SAFÁRI.\\pSe você conseguir, ganhará um\\nprêmio muito útil.",
  ["g3:0819832e"] = "KOGA: Fwahahaha!\\pUma simples criança como você\\nousa me desafiar?\\pSó essa ideia já me faz tremer de\\nalegria.\\pMuito bem, vou lhe mostrar o\\nterror de um mestre ninja.\\pO veneno leva à derrota pouco a\\npouco. O sono deixa os oponentes\\pcompletamente indefesos.\\pDesespere diante do horror dos\\nPOKéMON do tipo VENENO!",
  ["g3:08198444"] = "Hmph!\\nVocê provou o seu valor!\\pAqui!\\nPegue a INSÍGNIA ALMA!",
  ["g3:08198481"] = "Quando atingido por TÓXICO, um\\nPOKéMON sofre cada vez mais.\\pO dano vai piorando conforme a\\nbatalha continua!\\pCom certeza isso vai causar terror\\nnos oponentes!",
  ["g3:0819850e"] = "Agora que você tem a INSÍGNIA\\nALMA, a DEFESA dos seus POKéMON\\paumenta.\\pEla também permite SURFAR fora\\nde batalha.\\pAh!\\nLeve isto também!",
  ["g3:0819858f"] = "{PLAYER} recebeu a MT06\\nde KOGA.",
  ["g3:081985ab"] = "Selado dentro da MT06 está\\nTÓXICO!\\pÉ uma técnica secreta que remonta\\na cerca de quatrocentos anos.",
  ["g3:0819860d"] = "Você não tem mais espaço,\\ncriança!",
  ["g3:08198629"] = "Força não é a chave em POKéMON.\\nVocê entende isso?\\pPOKéMON é sobre estratégia!\\pVou te mostrar como a estratégia\\npode vencer a força bruta.",
  ["g3:081986b4"] = "O quê?\\nExtraordinário!",
  ["g3:081986c9"] = "Entao você mistura força com\\ninteligência? Boa estratégia!\\pÉ impressionante para alguém tão jovem como TREINADOR.",
  ["g3:0819871e"] = "Já fui um mágico, muito tempo\\natrás.\\pMas eu sonhava em me tornar um\\nninja, aí entrei para este GINÁSIO.",
  ["g3:08198779"] = "Tô acabado!",
  ["g3:08198787"] = "Mesmo tendo perdido, vou continuar\\ntreinando seguindo os ensinamentos\\pde KOGA, meu mestre ninja.",
  ["g3:081987e8"] = "Quero ver você superar minhas\\ntécnicas especiais!",
  ["g3:08198812"] = "Você me enganou direitinho!",
  ["g3:08198825"] = "Gosto de técnicas de veneno e sono,\\njá que elas continuam fazendo\\pefeito mesmo depois da batalha!",
  ["g3:08198866"] = "Pare aí mesmo!\\pAs famosas paredes invisíveis do\\nGINÁSIO de FUCHSIA estão te\\pfrustrando?",
  ["g3:081988b6"] = "Uau!\\nVocê conseguiu!",
  ["g3:081988cb"] = "Você me impressionou!\\nAqui vai uma dica!\\pOlhe bem de perto para encontrar\\nas brechas nas paredes invisíveis!",
  ["g3:0819891f"] = "Também estudo o caminho ninja com\\no MESTRE KOGA!\\pNinjas têm uma longa história de\\nusar animais!",
  ["g3:0819897f"] = "Auuu!",
  ["g3:08198985"] = "Ainda tenho muito a aprender.",
  ["g3:081989a1"] = "O MESTRE KOGA vem de uma longa\\nlinhagem de ninjas.\\pE você, de quem descende?",
  ["g3:081989ea"] = "Você é mais hábil do que\\neu pensava!",
  ["g3:08198a10"] = "Onde existe luz, existe sombra!\\pLuz e sombra!\\nQual você escolhe?",
  ["g3:08198a5e"] = "E aí!\\nCAMPEÃO em ascensão!\\pO GINÁSIO de FUCHSIA é cheio de\\ntruques. Está tomado por paredes\\pinvisíveis!\\pPode parecer que o KOGA está\\nperto, mas ele está isolado.\\pVocê precisa encontrar as brechas\\nnas paredes para chegar até ele.",
  ["g3:08198b1d"] = "É incrível como os ninjas conseguem\\nassustar, mesmo hoje em dia!",
  ["g3:08198b4b"] = "GINÁSIO POKéMON de FUCHSIA\\nLÍDER: KOGA\\pTREINADORES VENCEDORES:\\n{RIVAL}",
  ["g3:08198b81"] = "GINÁSIO POKéMON de FUCHSIA\\nLÍDER: KOGA\\pTREINADORES VENCEDORES:\\n{RIVAL} e {PLAYER}",
  ["g3:08198bbb"] = "O DIRETOR da ZONA DE SAFÁRI\\né velho, mas ainda é bem ativo.\\pMas os dentes dele são falsos.",
  ["g3:08198c1f"] = "Hmm?\\nVocê conheceu o BILL?\\pEle é meu neto!\\pEle sempre gostou de colecionar\\ncoisas, até quando era criança!",
  ["g3:08198c7b"] = "O BILL registra os próprios dados\\ndos POKéMON no PC dele.\\pEle te mostrou?",
  ["g3:08198cb7"] = "Não dá pra se tornar um bom\\nTREINADOR com só um POKéMON\\pforte.\\pMas treinar vários POKéMON de\\nforma equilibrada também não é\\ptarefa fácil.",
  ["g3:08198d2e"] = "Tem uma trilha estreita a oeste da\\nCIDADE DE VIRIDIAN.\\pEla leva à SEDE da LIGA POKéMON.\\nA SEDE comanda todos os\\pTREINADORES.",
  ["g3:08198d9b"] = "Se você estiver trabalhando em uma\\nPOKéDEX, visite a ZONA DE SAFÁRI.\\pTodo tipo de POKéMON raro se\\nreproduz por lá.",
  ["g3:08198df9"] = "DIRETOR: Fou o difetô!\\pPefi mia denfadula na fona\\nde fafáfi! Pof favô, me ajufa!",
  ["g3:08198e3f"] = "Pehdi em afgum fugá da fona\\nde fafári!",
  ["g3:08198e63"] = "Hã? Fofê não fai ajufá um\\nfelinho?",
  ["g3:08198e84"] = "{PLAYER} entregou a DENTADURA\\não DIRETOR.",
  ["g3:08198eaa"] = "O DIRETOR colocou a dentadura!",
  ["g3:08198eca"] = "DIRETOR: Obrigado, rapaz!\\nVocê salvou a minha vida!\\pNinguém conseguia entender uma\\npalavra do que eu dizia, nadinha!\\pEu tinha até vergonha de aparecer\\nno ESCRITÓRIO.\\pDeixa eu lhe dar algo pelo seu\\ntrabalho.",
  ["g3:08198f96"] = "DIRETOR: Obrigado, mocinha!\\nVocê salvou a minha vida!\\pNinguém conseguia entender uma\\npalavra do que eu dizia, nadinha!\\pEu tinha até vergonha de aparecer\\nno ESCRITÓRIO.\\pDeixa eu lhe dar algo pelo seu\\ntrabalho.",
  ["g3:08199068"] = "{PLAYER} recebeu a MO04\\ndo DIRETOR.",
  ["g3:0819908a"] = "DIRETOR: Dentro da MO04 você vai\\nencontrar SUPERFORÇA.\\pEla permite que POKéMON movam\\nrochas fora de batalha.\\pAh, sim, você encontrou a CASA\\nSECRETA na ZONA DE SAFÁRI?",
  ["g3:0819913c"] = "Fotos e fósseis de POKéMON estão\\nem exposição.",
  ["g3:08199167"] = "Produtos antigos de POKéMON estão\\nem exposição.",
  ["g3:0819918e"] = "Sou o irmão mais velho do\\nMESTRE DA PESCA.\\pEu simplesmente aaaaamo pescar!\\nNão consigo ficar sem pescar.\\pMe fala, você gosta de pescar?",
  ["g3:08199207"] = "Ótimo! Gosto do seu jeito.\\nAcho que podemos ser amigos.\\pPegue isto e vá pescar,\\njovem camarada!",
  ["g3:0819925e"] = "{PLAYER} recebeu a VARA BOA\\ndo irmão do MESTRE DA PESCA.",
  ["g3:08199296"] = "Pescar é um estilo de vida!\\nÉ como a mais fina poesia.\\pUma VARA ANTIGA meia-boca só\\nconsegue pegar MAGIKARP, né?\\pMas com uma VARA BOA, você pode\\ncapturar POKéMON muito melhores.",
  ["g3:08199337"] = "Ah...\\nQue decepção...",
  ["g3:08199354"] = "Olá, {PLAYER}!\\pOs peixes estão mordendo?",
  ["g3:0819937e"] = "Ah, não!\\pEu tinha um presente pra você,\\nmas você não tem mais espaço!",
  ["g3:081993b9"] = "Uh...\\nAh, sim, sou o APAGA-MOVIMENTOS.\\pPosso fazer um POKéMON esquecer\\nseus movimentos.\\pVocê gostaria que eu fizesse isso?",
  ["g3:08199421"] = "Qual POKéMON deve esquecer um\\nmovimento?",
  ["g3:08199445"] = "Qual movimento deve ser\\nesquecido?\\p",
  ["g3:08199465"] = "Parece que {STR_VAR_1} só\\nconhece um movimento...",
  ["g3:08199485"] = "Hm! {STR_VAR_2} de {STR_VAR_1}?\\nEsse movimento deve ser esquecido?",
  ["g3:081994b1"] = "Funcionou perfeitamente!\\p{STR_VAR_1} esqueceu\\n{STR_VAR_2} completamente.",
  ["g3:081994ea"] = "Volte sempre que quiser esquecer\\noutros movimentos.",
  ["g3:0819951f"] = "O quê?\\nUm OVO não conhece movimentos.",
  ["g3:08199543"] = "Hah!\\pEu sou BLAINE, o LÍDER ardente\\ndo GINÁSIO de CINNABAR!\\pMeus POKéMON de fogo são todos\\ncasca-grossa e estão sempre\\pprontos pra esquentar as coisas!\\pEles incineram qualquer desafiante!\\pHah!\\nÉ melhor você ter ANTIQUEIMADURAS!",
  ["g3:081995fa"] = "Eu queimei até não sobrar nada!\\nNão sobrou nem as cinzas!\\pVocê conquistou a INSÍGNIA VULCÃO.",
  ["g3:08199652"] = "RAJADA DE FOGO é o movimento de\\nfogo definitivo.\\pNão desperdice ele em um POKéMON\\nde ÁGUA.",
  ["g3:0819969e"] = "Hah!\\pA INSÍGNIA VULCÃO aumenta os\\natributos ESPECIAIS dos seus\\pPOKéMON.\\pAqui, você pode ficar com isto\\ntambém!",
  ["g3:081996ff"] = "{PLAYER} recebeu a MT38\\nde BLAINE.",
  ["g3:0819971d"] = "A MT38 contém RAJADA DE FOGO.\\nUse em um POKéMON do tipo FOGO.\\pVULPIX ou CHARMELEON são boas\\nopçoes para esse movimento.",
  ["g3:08199789"] = "Você não tem mais espaço,\\ncriança!",
  ["g3:081997a5"] = "Você sabe o quão quente o sopro\\nde fogo de um POKéMON pode ficar?",
  ["g3:081997d6"] = "Ai!\\nQuente, quente, quente!",
  ["g3:081997ea"] = "Fogo, ou para ser mais preciso,\\ncombustao...\\p... Oxigênio no ar...\\nBlá, blá, blá, blá...",
  ["g3:0819983f"] = "Eu era um ladrão, mas larguei essa\\nvida e virei um TREINADOR.",
  ["g3:08199870"] = "Eu me rendo!",
  ["g3:0819987d"] = "Eu sinto uma vontade incontrolável\\nde roubar os POKéMON dos outros.",
  ["g3:081998bd"] = "Eu estudei POKéMON a fundo.\\nVocê não tem chance!",
  ["g3:081998ed"] = "Aaah!\\nMeus estudos foram insuficientes!",
  ["g3:08199911"] = "Minhas teorias são complicadas\\ndemais para você entender.",
  ["g3:08199948"] = "Gosto de usar POKéMON do tipo FOGO.\\nSimples assim.",
  ["g3:08199973"] = "Quente demais pra aguentar!",
  ["g3:08199986"] = "Queria que existisse um POKéMON\\nladrão. Eu ia usar ele!",
  ["g3:081999b7"] = "Eu sei por que o BLAINE se tornou\\num TREINADOR.",
  ["g3:081999db"] = "Ai!",
  ["g3:081999df"] = "Nosso LÍDER, BLAINE, se perdeu\\npra valer nas montanhas.\\pQuando anoiteceu, um POKéMON\\npássaro flamejante apareceu.\\pA luz dele permitiu que BLAINE\\nencontrasse o caminho de volta\\pem segurança.",
  ["g3:08199a7f"] = "Já fui a muitos GINÁSIOS, mas este\\ncombina melhor com o meu estilo.",
  ["g3:08199ab9"] = "Uau!\\nQuente demais!",
  ["g3:08199ac9"] = "PONYTA, NINETALES...\\nSão POKéMON de FOGO populares.",
  ["g3:08199afc"] = "O fogo é fraco contra H2O.",
  ["g3:08199b16"] = "Ah!\\nApaguei!",
  ["g3:08199b27"] = "A água vence o fogo, é claro.\\pMas o fogo derrete o gelo, então\\no tipo FOGO vence POKéMON do\\ptipo GELO.",
  ["g3:08199b81"] = "E aí!\\nCAMPEÃO em ascensão!\\pO esquentadinho BLAINE é um\\nprofissional de POKéMON de FOGO.\\pApague o espírito dele com água!\\pÉ melhor levar ANTIQUEIMADURAS\\ntambém.",
  ["g3:08199c0c"] = "{PLAYER}!\\nVocê derrotou aquele incendiário!",
  ["g3:08199c29"] = "GINÁSIO POKéMON de CINNABAR\\nLÍDER: BLAINE\\pTREINADORES VENCEDORES:\\n{RIVAL}",
  ["g3:08199c62"] = "GINÁSIO POKéMON de CINNABAR\\nLÍDER: BLAINE\\pTREINADORES VENCEDORES:\\n{RIVAL} e {PLAYER}",
  ["g3:08199c9f"] = "Questionário POKéMON!\\pSe acertar, a porta abre para a\\npróxima sala.\\pSe errar, enfrenta um TREINADOR!\\pSe você quer poupar seus POKéMON\\npara o LÍDER de GINÁSIO...\\pÉ melhor acertar!\\nLá vamos nós!",
  ["g3:08199d5a"] = "CATERPIE evolui para METAPOD?",
  ["g3:08199d79"] = "Existem nove INSÍGNIAS certificadas\\nda LIGA POKéMON?",
  ["g3:08199da9"] = "POLIWAG evolui três vezes?",
  ["g3:08199dc6"] = "Os movimentos elétricos são eficazes\\ncontra POKéMON do tipo TERRA?",
  ["g3:08199e00"] = "Os POKéMON do mesmo tipo e nível\\nnão são idênticos?",
  ["g3:08199e36"] = "A MT28 contém TUMBA-PEDRADA?",
  ["g3:08199e4f"] = "Você acertou!\\pPode prosseguir!",
  ["g3:08199e79"] = "Desculpe!\\nResposta errada!",
  ["g3:08199e8a"] = "É uma foto de BLAINE e do\\nSR. FUJI.\\pEles estão lado a lado, sorrindo\\nde orelha a orelha.",
  ["g3:08199ee5"] = "Nós estudamos POKéMON a fundo\\ntodos os dias.\\pAs pessoas estão sempre trazendo\\nPOKéMON raros para examinarmos.",
  ["g3:08199f41"] = "Uma foto do fundador do\\nLABORATÓRIO... DR. FUJI?!",
  ["g3:08199f6a"] = "LABORATÓRIO POKéMON\\nSala de reunioes",
  ["g3:08199f83"] = "LABORATÓRIO POKéMON\\nSala de pesquisa e desenvolvimento",
  ["g3:08199f9a"] = "LABORATÓRIO POKéMON\\nSala de testes",
  ["g3:08199fb3"] = "Encontrei este fóssil extraordinário\\ndentro do MONTE LUA.\\pAcho que é de um POKéMON raro e\\npré-histórico.",
  ["g3:0819a015"] = "EEVEE pode evoluir para três tipos\\ndiferentes de POKéMON.",
  ["g3:0819a04a"] = "Há uma mensagem de e-mail.\\p... ... ...\\pExistem três POKéMON pássaros\\nlendários.\\pSão eles: ARTICUNO, ZAPDOS e\\nMOLTRES.\\pO paradeiro deles é desconhecido.\\pPlanejamos explorar a caverna\\nperto de CERULEAN.\\pDe: EQUIPE de PESQUISA POKéMON...",
  ["g3:0819a128"] = "Um tubo de âmbar!",
  ["g3:0819a137"] = "Tsc-tsc-tsc!\\nVou te ensinar um movimento bem\\plegal.\\pEnsine a um POKéMON e veja a\\ndiversao acontecer!\\pÉ um movimento chamado METRÔNOMO.\\nTe interessa?",
  ["g3:0819a1cb"] = "Eu garanto, é muito divertido!",
  ["g3:0819a1ea"] = "Muito bem!\\nPara qual POKéMON devo ensinar?",
  ["g3:0819a20e"] = "Tsc-tsc-tsc!\\nEsse é o som de um METRÔNOMO.\\pEle dá uma mexida no cérebro\\ndo seu POKéMON e faz ele usar\\pmovimentos que ele nem conhece.",
  ["g3:0819a282"] = "Oi!\\pSou um doutor importante.\\nSim, muito importante, de fato.\\pEstudo fósseis raros de POKéMON.\\nEstou o tempo todo estudando.\\pVocê tem um fóssil para mim?",
  ["g3:0819a314"] = "Não!\\nQue pena!",
  ["g3:0819a34f"] = "Você demorou.\\nOnde você estava?\\pSeu fóssil voltou à vida! Era um\\n{STR_VAR_1}, como eu imaginei!",
  ["g3:0819a39e"] = "{PLAYER} recebeu o {STR_VAR_1}\\ndo doutor.",
  ["g3:0819a3d4"] = "Oh!\\nÉ um {STR_VAR_2}, sim!\\pÉ o fóssil de {STR_VAR_1}, um\\nPOKéMON que já está extinto!\\pMinha Máquina de Ressurreiçao vai\\nfazer esse POKéMON viver de novo!",
  ["g3:0819a45d"] = "Entao!\\nMe dá logo isso aí, rápido!\\p{PLAYER} entregou o\\n{STR_VAR_2} para o doutor estranho.",
  ["g3:0819a4ab"] = "Vai levar um tempinho! Vá dar uma\\nvoltinha por aí enquanto isso!",
  ["g3:0819a4e1"] = "Ah!\\nVocê de novo!",
  ["g3:0819a4f8"] = "Vim visitar o GINÁSIO de CINNABAR,\\nmas a porta está trancada.\\pTem que ter uma chave para abrir\\nele em algum lugar.\\pSerá que está naquela mansão\\nqueimada?\\pDizem que o amigo do LÍDER de\\nGINÁSIO morava lá.",
  ["g3:0819a5be"] = "Você tem muitos amigos?\\pJogar com os mesmos amigos é\\ndivertido, claro.\\pMas que tal visitar a SALA UNIÃO\\nde vez em quando?\\pVai saber, talvez você acabe\\nfazendo novos amigos.\\pAcho que vale a pena você dar\\numa passada na SALA UNIÃO.",
  ["g3:0819a6b1"] = "Os POKéMON ainda podem aprender\\nmovimentos mesmo depois de\\pcancelar a evolução.\\pA evolução pode esperar até que\\nnovos movimentos sejam aprendidos.",
  ["g3:0819a725"] = "BILL: Ei, você me deixou esperando!\\nPreparou-se para zarpar para a ILHA UM?",
  ["g3:0819a766"] = "Ah, você ainda não se preparou?",
  ["g3:0819a785"] = "Bem, é isso.\\nVamos!",
  ["g3:0819a7a0"] = "Aqui não vende ATAQUE X?\\pGosto dele porque aumenta o\\natributo de ATAQUE na batalha.",
  ["g3:0819a7f1"] = "Não faz mal ter itens de sobra.\\nNunca se sabe o que pode acontecer.",
  ["g3:0819a837"] = "E aí!\\nCAMPEÃO em ascensão!\\pNa LIGA POKéMON, você vai\\nenfrentar a ELITE DOS QUATRO\\pum após o outro.\\pSe perder, terá que começar tudo\\nde novo!\\pÉ isso!\\nVai com tudo!",
  ["g3:0819a8d8"] = "Daqui em diante, você enfrentará\\na ELITE DOS QUATRO um por um.\\pSe vencer, uma porta se abrirá\\npara o próximo TREINADOR.\\pBoa sorte!",
  ["g3:0819a943"] = "Sinto muito, mas você perdeu\\nseu tempo vindo até aqui.\\pLORELEI da ELITE DOS QUATRO\\nestá ausente, sabe.\\pComo resultado, a LIGA POKéMON\\nestá fechada por enquanto.",
  ["g3:0819a9e7"] = "Os POKéMON do tipo FANTASMA\\nda AGATHA são terrivelmente\\passustadores de tão resistentes.\\pPeguei meus POKéMON do tipo\\nLUTADOR e treinei eles até o\\plimite.\\pEnfrentei a AGATHA me sentindo\\nbem confiante, mas ela acabou\\pcom a gente.\\pAquela velha também tem o pavio\\nbem curto.\\pNão precisa de quase nada pra\\nfazer aquela mulher assustadora\\pcomeçar a gritar.",
  ["g3:0819ab16"] = "Talvez virar membro da ELITE\\nDOS QUATRO seja coisa de família.\\pPelo que ouvi dizer, o LANCE tem\\num primo que é LÍDER de GINÁSIO\\pem algum lugar bem distante.",
  ["g3:0819ab9b"] = "Minha filha é tão egocêntrica.\\nEla tem poucos amigos.",
  ["g3:0819abd7"] = "Minha filha gosta de imitar as\\npessoas. É muito irritante.\\pSuas imitaçoes lhe renderam o\\napelido de COPIONA por aqui.",
  ["g3:0819ac4b"] = "CHANSEY: Chaan! Sii!",
  ["g3:0819ac60"] = "{PLAYER}: Oi!\\nVocê gosta de POKéMON?\\p{PLAYER}: Ah, não, só perguntei.\\p{PLAYER}: Ha?\\nVocê é estranha!\\pCOPIONA: Hmm? Parar de imitar?\\nMas esse é meu passatempo favorito!",
  ["g3:0819acf1"] = "{PLAYER}: Oi.\\nVocê deve gostar de POKéMON.\\p{PLAYER}: Não, eu não.\\nEu perguntei pra você.\\p{PLAYER}: Como?\\nVocê é esquisita!\\pCOPIONA: Hmm? Parar de imitar?\\nMas esse é meu passatempo favorito!",
  ["g3:0819ad85"] = "Uau!\\nUm POKéBONECO!\\pÉ pra mim?\\nObrigada!\\pSabe de uma coisa?\\nPosso ensinar o movimento MÍMICA.",
  ["g3:0819add8"] = "Você não gosta de MÍMICA?",
  ["g3:0819adee"] = "Eu adoro MÍMICA!\\nQuem vai aprender?",
  ["g3:0819ae1c"] = "{PLAYER}: Oi!\\nObrigada pela ajuda mais cedo!\\p{PLAYER}: Como?  \\p{PLAYER}: É tão divertido imitar\\ncada um dos meus movimentos?\\pCOPIONA: Com certeza!\\nPura diversão!",
  ["g3:0819ae90"] = "{PLAYER}: Oi!\\nObrigada pelo que fez pela gente.\\p{PLAYER}: Como?\\p{PLAYER}: É realmente tão divertido\\ncopiar o que eu digo e faço?\\pCOPIONA: Com certeza!\\nPura diversão!",
  ["g3:0819b030"] = "DODUO: Giiih!\\pESPELHO, ESPELHO MEU, EXISTE\\nALGUÉM MAIS BELA DO QUE EU?",
  ["g3:0819b071"] = "Este é um POKéMON raro!\\nHã? É só um boneco!",
  ["g3:0819b0a0"] = "Um jogo com o MARIO usando um\\nbalde na cabeça!",
  ["g3:0819b0d0"] = "...\\pMeus segredos!\\pHabilidade: Imitaçao!\\nPassatempo: Colecionar bonecos!\\pPOKéMON favorito: CLEFAIRY!",
  ["g3:0819b12c"] = "Grrrr!\\pSou o MESTRE de CARATÊ!\\nSou o LÍDER aqui!\\pVocê quer desafiar a gente?\\nNão espere misericórdia!\\pFwaaa!",
  ["g3:0819b193"] = "Hwa!\\nArrgh! Perdi!",
  ["g3:0819b1a7"] = "É verdade, eu perdi!\\pMas eu imploro, não leve nosso\\nemblema como seu troféu!\\pEm troca, te darei um valoroso\\nPOKéMON LUTADOR!\\pEscolha o que você quiser!",
  ["g3:0819b24c"] = "Grrrr!\\nFique e treine caratê com a gente!",
  ["g3:0819b275"] = "Hoargh!\\nTire seus sapatos!",
  ["g3:0819b292"] = "Desisto!",
  ["g3:0819b29d"] = "Espere até ver nosso MESTRE!\\nSou café-pequeno comparado a ele!",
  ["g3:0819b2e0"] = "Soube que você é forte!\\nDeixa eu ver se é verdade!",
  ["g3:0819b2fd"] = "Muito bom!\\nUm ponto!",
  ["g3:0819b30f"] = "Nosso MESTRE é um lutador\\nprofissional. Prepare-se para perder!",
  ["g3:0819b341"] = "Hiyah!\\nNão tenho medo de nada!\\pQuebro pedras no treinamento todos\\nos dias!",
  ["g3:0819b396"] = "Ai!\\nMachuquei meus dedos!",
  ["g3:0819b3ac"] = "A única coisa que assusta a gente\\né o poder psíquico!",
  ["g3:0819b3df"] = "Hwaah!\\pVocê está invadindo nosso\\nDOJÔ DE LUTA!",
  ["g3:0819b40f"] = "Oof!\\nDesisto!",
  ["g3:0819b41f"] = "Os melhores lutadores de toda a\\nregião treinam aqui.",
  ["g3:0819b44e"] = "Você quer HITMONLEE,\\nque dá chutes poderosos?",
  ["g3:0819b473"] = "{PLAYER} recebeu {STR_VAR_1}\\ndo MESTRE de CARATÊ.",
  ["g3:0819b49e"] = "Você quer HITMONCHAN,\\nque dá socos rápidos?",
  ["g3:0819b4e1"] = "É melhor não ter tanta gana...",
  ["g3:0819b4f8"] = "Inimigos de todos os lados!",
  ["g3:0819b50f"] = "Tudo que vai, volta.",
  ["g3:0819b52e"] = "DOJÔ DE LUTA",
  ["g3:0819b53c"] = "Tive uma visão da sua chegada.\\pTenho poderes psíquicos desde\\ncriança.\\pTudo começou quando entortei uma\\ncolher sem querer.\\pNão gosto de batalhas, mas se você\\nquiser, mostrarei meus poderes!",
  ["g3:0819b602"] = "Esta derrota me pegou de surpresa...\\nMas uma derrota é uma derrota.\\pAdmito que não me esforcei o\\nsuficiente para vencer.\\pCom sua vitória, você conquistou a\\nINSÍGNIA PÂNTANO.",
  ["g3:0819b685"] = "O poder psíquico não é algo que\\napenas algumas pessoas têm.\\pTodo mundo tem poder psíquico.\\nAs pessoas só não percebem isso.",
  ["g3:0819b6fa"] = "A INSÍGNIA PÂNTANO faz com que\\nos POKéMON de até o Nv. 70 te\\pobedeçam.\\pOs POKéMON mais fortes podem ficar\\ndesobedientes e ignorar suas ordens\\pem batalha.\\pEntao, para evitar esse problema,\\nnão treine demais seus POKéMON.\\pEspere, leve esta MT com você.",
  ["g3:0819b7d3"] = "{PLAYER} recebeu a MT04 de\\nSABRINA.",
  ["g3:0819b7f2"] = "A MT04 é MENTE CALMA.\\pFaz o POKéMON se concentrar para\\naumentar seu ATQ. ESP. e DEF. ESP.",
  ["g3:0819b849"] = "Sua MOCHILA está cheia de outros\\nitens.",
  ["g3:0819b86a"] = "A SABRINA é bem mais jovem do\\nque eu, mas ganhou meu respeito.",
  ["g3:0819b8a8"] = "Não fui boa o bastante!",
  ["g3:0819b8b9"] = "Em uma batalha de igual para igual,\\nvence quem tiver mais determinação.\\pSe quiser derrotar a SABRINA,\\nmantenha o foco e acredite na\\psua vitória.",
  ["g3:0819b936"] = "O nosso poder invisível te assusta?",
  ["g3:0819b957"] = "Não previ isso!",
  ["g3:0819b96d"] = "Os POKéMON PSÍQUICOS só temem os\\nfantasmas e insetos!",
  ["g3:0819b998"] = "Os POKéMON acabam se parecendo\\ncom seus TREINADORES.\\pEntao, seus POKéMON devem ser\\nfortes!",
  ["g3:0819b9ec"] = "Eu sabia!",
  ["g3:0819b9f7"] = "Ainda tenho muito a aprender...\\pPreciso dominar os poderes PSÍQUICOS\\ne ensiná-los aos meus POKéMON...",
  ["g3:0819ba45"] = "Você entende, não é?\\pQue só poder não é suficiente para\\nvencer no mundo dos POKéMON?",
  ["g3:0819ba9e"] = "Não acredito nisso!",
  ["g3:0819bab4"] = "A SABRINA acabou de derrotar o\\nMESTRE de CARATÊ ao lado.",
  ["g3:0819bae8"] = "Você e eu, nossos POKéMON vão\\nbatalhar!",
  ["g3:0819bb0d"] = "Acabei perdendo!",
  ["g3:0819bb1f"] = "Eu sabia que isso ia acontecer.",
  ["g3:0819bb49"] = "A SABRINA é jovem, mas também é\\nnossa LÍDER altamente habilidosa.\\pVocê não vai derrotá-la facilmente!",
  ["g3:0819bba1"] = "Ai!\\nFui derrotado!",
  ["g3:0819bbb3"] = "Antes tinha dois GINÁSIOS POKéMON\\nem SAFFRON.\\pMas o DOJÔ DE LUTA ao lado perdeu\\nseu estatuto de GINÁSIO.\\pA gente acabou com eles quando\\ndecidimos que teria só um GINÁSIO.",
  ["g3:0819bc57"] = "O GINÁSIO POKéMON de SAFFRON\\né famoso por treinar psíquicos.\\pVocê quer ver a SABRINA, não é?\\nEu sabia!",
  ["g3:0819bcbc"] = "Arrrgh!",
  ["g3:0819bcc4"] = "Isso mesmo! Usei telepatia para\\nler sua mente!",
  ["g3:0819bcf6"] = "E aí!\\nCAMPEÃO em ascensão!\\pOs POKéMON da SABRINA usam\\npoder psíquico em vez de força.\\pOs POKéMON LUTADORES são fracos\\ncontra os POKéMON PSÍQUICOS.\\pEles serão nocauteados antes mesmo\\nde conseguir dar um soco!",
  ["g3:0819bdbb"] = "Poder psíquico, é?\\pSe eu tivesse isso, faria uma grana\\nnas máquinas de caça-níqueis!",
  ["g3:0819bdfe"] = "GINÁSIO POKéMON de SAFFRON\\nLÍDER: SABRINA\\pTREINADORES VENCEDORES:\\n{RIVAL}",
  ["g3:0819be37"] = "GINÁSIO POKéMON de SAFFRON\\nLÍDER: SABRINA\\pTREINADORES VENCEDORES:\\n{RIVAL} e {PLAYER}",
  ["g3:0819be74"] = "... Obrigada por escrever.\\nEspero te ver em breve!\\p... Ei!\\nNão olha a minha carta!",
  ["g3:0819bec3"] = "PIDGEY: Kurukkoo!",
  ["g3:0819bed5"] = "A COPIONA é uma fofa!\\nVou comprar um POKéBONECO pra ela.",
  ["g3:0819bf07"] = "Ganhei um MAIS PP de presente.\\pEle é usado para aumentar os PP\\nde um movimento de um POKéMON.\\pDevo usá-lo em um movimento\\npoderoso com poucos PP.",
  ["g3:0819bf8f"] = "O REPELENTE MÁXIMO impede que\\nPOKéMON mais fracos apareçam.\\pUm REPELENTE MÁXIMO dura mais do\\nque um SUPER-REPELENTE.",
  ["g3:0819bff1"] = "Um REANIMADOR é caro, mas reanima\\nPOKéMON desmaiados!",
  ["g3:0819c023"] = "A velocidade de crescimento dos\\nPOKéMON varia de uma espécie\\ppara outra.",
  ["g3:0819c058"] = "A COMPANHIA SILPH é muito\\nconhecida por todos.\\pEla é uma vítima de sua própria\\nfama, que atraiu a EQUIPE ROCKET.",
  ["g3:0819c0b4"] = "Ai-ai...\\nNão seria ótimo?\\pSe a ELITE DOS QUATRO viesse e\\nacabasse a EQUIPE ROCKET?",
  ["g3:0819c102"] = "A EQUIPE ROCKET fugiu! Podemos sair\\ncom segurança de novo! Que ótimo!",
  ["g3:0819c142"] = "... Espera!\\nNão diga uma só palavra!\\pVocê queria isso!",
  ["g3:0819c16c"] = "{PLAYER} recebeu a MT29\\ndo SR. PSÍQUICO.",
  ["g3:0819c18f"] = "Você já sabe, não é?\\nA MT29 é PSÍQUICO.\\pÉ um ataque que também pode diminuir\\nos atributos especiais do alvo.",
  ["g3:0819c1fc"] = "Onde você planeja colocar isto?\\nVocê não tem espaço.",
  ["g3:0819c22b"] = "Hã?\\nVocê...",
  ["g3:0819c235"] = "Por acaso você é...\\n... ...\\pSim!\\nVocê é {PLAYER}!\\pEstávamos falando de você!\\pEstávamos falando de alguém\\nincrível em treinar POKéMON.\\pE esse alguém é você!  \\nVocê é demais!\\pNós decidimos que seremos seu\\nFA-CLUBE!\\pTodos esperamos que você continue\\nbatalhando e mostrando como é\\pincrível.\\pDessa forma, talvez outras pessoas\\nse tornem fãs assim como eu.",
  ["g3:0819c390"] = "Vou sempre torcer por você!\\pVai, {PLAYER}, vai!",
  ["g3:0819c3bd"] = "Vou sempre acreditar em você,\\n{PLAYER}.\\pPor favor, mostre aos outros como\\nvocê é quando batalha a sério.",
  ["g3:0819c420"] = "Desculpe.\\nEu era seu fã.\\pMas agora, parece que você perdeu\\no ímpeto que tinha antes.\\pUltimamente, acho que {STR_VAR_1}\\ntem sido muito melhor.",
  ["g3:0819c4a5"] = "Ah!\\n{PLAYER}!\\pTodos estão empolgados com você\\nrecentemente.\\pPosso entender o motivo.\\nSei que você é forte.\\pMas, sabe de uma coisa?\\pEu me tornei fã de {STR_VAR_1},\\ne não pretendo voltar atrás.",
  ["g3:0819c55c"] = "Acho muito legal quando os\\nTREINADORES estão batalhando.\\pVocê também acha?",
  ["g3:0819c5a9"] = "Minha nossa!\\nÉ {PLAYER}!\\pUau!\\nQue legal!\\pPode autografar alguma coisa?\\nQue tal meu short?",
  ["g3:0819c600"] = "Por mais quente que tenha sido...\\pE por mais frio que possa ficar...\\pSempre acreditei, e sempre usei,\\nshorts!\\pConto com você para continuar\\nvencendo!\\pAcredito em você tanto quanto\\nacredito em shorts!",
  ["g3:0819c6ba"] = "BROCK é meu herói!\\nÉ o mais machao de todos os machos!\\pHehe, pedi pra minha mãe fazer uma coisa pra mim.\\pFiz ela bordar “BROCK”\\nno meu short!",
  ["g3:0819c73a"] = "...  ...\\p...  ...\\nSou fã do BROCK!\\pMesmo que eu fosse seu único fã,\\nserei fã até o fim!\\pJuro pela minha vontade inabalável,\\ne pelo meu short!",
  ["g3:0819c7c8"] = "O BROCK é o cara mais legal que\\nexiste, sem discussão!\\pQuero ser igual a ele!",
  ["g3:0819c81e"] = "{PLAYER}, tive o prazer de assistir\\nsuas batalhas.\\pIsso me traz boas lembranças da\\nminha juventude.\\pQue você continue progredindo.\\nSaiba que sou seu fã!",
  ["g3:0819c8c1"] = "Viajei por terras distantes e\\ndiversas.\\pMas nunca vi um TREINADOR com a\\nsua magnificência.\\pTenha confiança em suas habilidades\\ne continue batalhando!\\pMe prometa isso, jovem ídolo!",
  ["g3:0819c986"] = "Hmm...  \\nE você é?\\pVocê quer se inscrever como membro\\ndo nosso FA-CLUBE?",
  ["g3:0819c9d5"] = "Ah, então você é {PLAYER}, TREINADOR famoso.\\pVocê tem mesmo a pinta de alguém\\nvencedor.\\pMas pra mim... bem...\\p... ...\\pVocê ainda tem um longo caminho\\npela frente!",
  ["g3:0819ca7c"] = "Todos que estão aqui são fãs de\\nTREINADORES POKéMON.\\pA forma como eles batalham...\\nÉ o exemplo perfeito de estilo.\\pSe continuar vencendo, talvez a\\ngente fale de você também.",
  ["g3:0819cb32"] = "É {PLAYER}!\\nÉ {PLAYER}!\\pQuero ser como {PLAYER} um dia!",
  ["g3:0819cb62"] = "Todo mundo deixou de ser fã de\\n{PLAYER}...\\n\\nMas isso significa que agora posso ter {PLAYER} só pra mim!\\n\\nYay! Força, {PLAYER}!",
  ["g3:0819cbd3"] = "Sabe de uma coisa?\\nQuero ser como a SABRINA!\\pQuero ser uma garota psíquica igual\\na ela!",
  ["g3:0819cc2b"] = "Mesmo que eu seja a única, nunca\\nvou deixar de ser fã da SABRINA.\\pMeu sonho é ser como a SABRINA:\\nfofa, mas descolada.\\pQuero ser uma garota psíquica igual\\na ela!",
  ["g3:0819ccc2"] = "Será que um dia vou me tornar uma\\ngrande TREINADORA?",
  ["g3:0819ccf3"] = "Uau! Que legal!\\nMuito legal!\\p... Ha?\\nNão, não você.\\pSó o jeito como você batalha que\\né legal.",
  ["g3:0819cd4e"] = "E aí, {PLAYER}!\\pAcho que sou o único fã que ainda\\nresta.\\pMas, sabe, gosto de ser seu único\\nfa... É menos estressante.\\pContinue assim!",
  ["g3:0819cdda"] = "O {STR_VAR_1} é legal, né?\\nAdoro o jeito que ele fala.\\pQueria ter a chance de conhecê-lo\\npessoalmente alguma vez.",
  ["g3:0819ce3a"] = "Ha, será possível?\\nTodo mundo virou seu fã.\\pEntao, depois de tudo isso, sou o\\núnico fã de {STR_VAR_1}?\\pAh, ser o único fã de {STR_VAR_1}\\ncombina comigo, afinal.",
  ["g3:0819cedf"] = "Meu Deus!\\nÉ realmente você, {PLAYER}?\\pVou te dizer, adoro a forma como\\nvocê batalha.\\pEspero que continue assim.\\nSerei sua maior fã!",
  ["g3:0819cf6d"] = "Meu Deus!\\nSe não é {PLAYER}!\\pQue decepção... Descobri que sou\\nsua única e maior fã!\\pBom, não tem jeito!\\nPelo menos vou torcer por você!\\pVai, {PLAYER}, vai!",
  ["g3:0819d01f"] = "Ultimamente, {STR_VAR_1} está\\narrasando.\\pO jeito que ele batalha... é\\nexatamente do jeito que eu gosto!",
  ["g3:0819d075"] = "Ah, olá!\\nSe não é {PLAYER}!\\pUltimamente, todo mundo só fala\\nde você.\\pMe sinto solitária porque prefiro\\n{STR_VAR_1}.",
  ["g3:0819d0e3"] = "Incrível!\\n{PLAYER}, você é mesmo incrível!\\pEm vez de só assistir, talvez eu\\ntambém devesse me tornar uma\\pTREINADORA.",
  ["g3:0819d148"] = "Sou sua única fã...\\nE... tô tão solitária...\\pNão dá pra se esforçar mais e\\nfazer os outros te perceberem?",
  ["g3:0819d1ae"] = "O Mestre {STR_VAR_1} é tão\\nelegante... Ele faz meu tipo.\\pPor que os outros não conseguem\\nver como ele é incrível?",
  ["g3:0819d211"] = "Acredito no Mestre {STR_VAR_1}\\nde todo o meu coração.\\pMesmo que eu seja a única a\\nacreditar nele, nunca vou me\\psentir sozinha.\\pNão enquanto eu continuar pensando\\nno Mestre {STR_VAR_1}.",
  ["g3:0819d2b4"] = "Hiyah!\\pSeu estilo de batalha é inspirador.\\pEspero que continue se esforçando\\npara alcançar o sucesso, hiyah!",
  ["g3:0819d31f"] = "Em vez de só assistir os outros\\nbatalharem, batalhe você mesmo!\\p... O MESTRE do meu DOJÔ me deu\\nesse sermão...\\pMas isso não vai me impedir de\\nser seu fã!\\pNão consigo deixar de ser seu fã!",
  ["g3:0819d3d2"] = "Hiyah! Só existe um TREINADOR\\nque eu respeito.\\pE não poderia ser outro senão\\nmeu MESTRE do DOJÔ DE LUTA.\\pVocê deveria virar fã do meu\\nMESTRE, assim como eu! Hiyah!",
  ["g3:0819d477"] = "Hiyah! Tenho muito respeito pelo\\nmeu MESTRE do DOJÔ DE LUTA.\\pNunca serei fã de mais ninguém,\\nsó do meu MESTRE!\\pVou até sair escondido do DOJÔ\\npra dizer por aí como ele é bom.\\pHiyah!",
  ["g3:0819d52c"] = "Você vai para a FLORESTA DE\\nVIRIDIAN?\\pEla é um labirinto natural.\\nCuidado para não se perder.",
  ["g3:0819d58b"] = "RATTATA pode ser pequeno, mas\\nnão subestime sua mordida.\\pVocê já capturou um?",
  ["g3:0819d5e7"] = "Um POKéMON desmaiado não tem\\nmais energia para batalhar.\\pMas ainda pode usar movimentos\\ncomo CORTAR fora de batalha.",
  ["g3:0819d64f"] = "Oi! Lembra de mim?\\nSou um dos ASSISTENTES do\\pPROFESSOR CARVALHO.\\pSe a sua POKéDEX tiver dados\\ncompletos de pelo menos dez\\pespécies, vou te dar uma\\precompensa.\\pO PROFESSOR CARVALHO me pediu\\npara te entregar a MO05.\\pEntao, {PLAYER}, deixa eu\\nperguntar.\\pVocê já registrou os dados de pelo\\nmenos dez espécies de POKéMON?",
  ["g3:0819d74e"] = "Ótimo! Você capturou ou ganhou\\n{STR_VAR_3} tipos de POKéMON!\\pParabéns!\\nAqui está seu prêmio!",
  ["g3:0819d7a1"] = "{PLAYER} recebeu a MO05\\ndo ASSISTENTE.",
  ["g3:0819d7c1"] = "A MO05 contém o movimento oculto\\nCLARAO.\\pCLARAO ilumina até as cavernas e\\nmasmorras mais escuras.",
  ["g3:0819d81e"] = "Se você ensinar CLARÃO para um\\nPOKéMON, poderá atravessar o\\pTÚNEL DE ROCHA.",
  ["g3:0819d85c"] = "Muitos POKéMON vivem só em\\nflorestas e cavernas.\\pVocê precisa ser persistente e\\nprocurar em todos os lugares.",
  ["g3:0819d8d0"] = "Você reparou nas árvores finas\\nna beira da estrada?\\pOuvi dizer que elas podem ser\\ncortadas com um movimento\\pespecial de POKéMON.",
  ["g3:0819d93b"] = "Você conhece a técnica de cancelar\\na evolução?\\pQuando um POKéMON está evoluindo,\\nvocê pode interromper o processo.\\pÉ uma técnica para criar os POKéMON\\ndo jeito que eles são.",
  ["g3:0819d9d4"] = "Tenho seis POKé BOLAS no meu\\ncinto.\\pVocê só pode carregar até seis\\nPOKéMON, no máximo.",
  ["g3:0819da3a"] = "A EQUIPE ROCKET ataca os cidadãos\\nde CERULEAN...\\pNão passa um dia sem que a EQUIPE\\nROCKET esteja nas notícias.",
  ["g3:0819da9a"] = "HOMEM: Como vai, rapaz! Tenho\\numa oferta especial pra você!\\pVocê pode ter um POKéMON secreto...\\num MAGIKARP... por só $500!\\pVocê vai comprar, não é?",
  ["g3:0819db34"] = "HOMEM: Como vai, docinho! Tenho\\numa oferta especial pra você!\\pVocê pode ter um POKéMON secreto...\\num MAGIKARP... por só $500!\\pVocê vai comprar, não é?",
  ["g3:0819dbd3"] = "{PLAYER} pagou exorbitantes $500\\ne comprou o MAGIKARP...",
  ["g3:0819dc07"] = "Não? Você disse não?\\nTô te fazendo um favor!",
  ["g3:0819dc3e"] = "Parece que não tem mais espaço\\npara nenhum POKéMON.",
  ["g3:0819dc78"] = "Você vai precisar de mais dinheiro!",
  ["g3:0819dc9a"] = "HOMEM: Bem, não faço reembolsos.\\nVocê sabia o que estava comprando!",
  ["g3:0819dcdb"] = "Se você tiver muitos POKéMON e não\\npuder carregar mais nenhum, guarde\\palguns no PC.",
  ["g3:0819dd54"] = "É um jornal.",
  ["g3:0819dd66"] = "Eu administro o serviço de CRECHE.\\pGostaria que eu cuidasse de um\\ndos seus POKéMON?",
  ["g3:0819ddb2"] = "Volte sempre.",
  ["g3:0819ddbe"] = "Devo cuidar de qual POKéMON?",
  ["g3:0819dddc"] = "Tudo bem.\\nVolte quando quiser.",
  ["g3:0819ddf9"] = "Tudo bem, vou cuidar do seu\\n{STR_VAR_1} por um tempo.",
  ["g3:0819de24"] = "Volte daqui a algum tempo.",
  ["g3:0819de3c"] = "Já voltou?\\pSeu {STR_VAR_1} ainda precisa\\npassar mais um tempo comigo.",
  ["g3:0819de80"] = "Você me deve ${STR_VAR_2} para pegar\\nseu POKéMON de volta.",
  ["g3:0819deaf"] = "Obrigado!\\nAqui está seu POKéMON.",
  ["g3:0819decf"] = "{PLAYER} pegou {STR_VAR_1} de volta\\ncom o HOMEM da CRECHE.",
  ["g3:0819def5"] = "Ah? Você só tem um POKéMON\\ncom você.",
  ["g3:0819df1d"] = "Se você deixar esse POKéMON\\ncomigo, vai batalhar com o quê?",
  ["g3:0819df56"] = "Seu {STR_VAR_1} cresceu muito.\\nSim, muito mesmo, eu diria.\\pDeixa eu ver...\\nDe nível, ele subiu {STR_VAR_2}.\\pNão sou ótimo?",
  ["g3:0819dfc2"] = "Você não pode pegar este POKéMON de\\nvolta se não tiver espaço para ele.",
  ["g3:0819e001"] = "Você não tem dinheiro suficiente.",
  ["g3:0819e04b"] = "Estou de guarda.\\nCara, que sede...\\pEi, espera aí, a estrada está\\nfechada.",
  ["g3:0819e09b"] = "Ah, esse CHÁ...\\nParece uma delícia...",
  ["g3:0819e0c1"] = "Ha? Posso ficar com essa bebida?\\nPoxa, valeu!\\p... ...\\pGlup, glup...\\p... ...\\pGulp...\\pSe quer ir pra CIDADE DE SAFFRON...\\p... ...\\pPode passar.\\pVou dividir esse CHÁ com os outros\\nguardas!",
  ["g3:0819e16d"] = "Oi, como vão as coisas?",
  ["g3:0819e181"] = "Estou de guarda.\\nCara, que sede...\\pEi, espera aí, a estrada está\\nfechada.",
  ["g3:0819e1d1"] = "Ah, esse CHÁ...\\nParece uma delícia...",
  ["g3:0819e1f7"] = "Ha? Posso ficar com essa bebida?\\nPoxa, valeu!\\p... ...\\pGlup, glup...\\p... ...\\pGulp...\\pSe quer ir pra CIDADE DE SAFFRON...\\p... ...\\pPode passar.\\pVou dividir esse CHÁ com os outros\\nguardas!",
  ["g3:0819e2a3"] = "Oi, como vão as coisas?",
  ["g3:0819e2b7"] = "Estou de guarda.\\nCara, que sede...\\pEi, espera aí, a estrada está\\nfechada.",
  ["g3:0819e307"] = "Ah, esse CHÁ...\\nParece uma delícia...",
  ["g3:0819e32d"] = "Ha? Posso ficar com essa bebida?\\nPoxa, valeu!\\p... ...\\pGlup, glup...\\p... ...\\pGulp...\\pSe quer ir pra CIDADE DE SAFFRON...\\p... ...\\pPode passar.\\pVou dividir esse CHÁ com os outros\\nguardas!",
  ["g3:0819e3d9"] = "Oi, como vão as coisas?",
  ["g3:0819e3ed"] = "Estou de guarda.\\nCara, que sede...\\pEi, espera aí, a estrada está\\nfechada.",
  ["g3:0819e43d"] = "Ah, esse CHÁ...\\nParece uma delícia...",
  ["g3:0819e463"] = "Ha? Posso ficar com essa bebida?\\nPoxa, valeu!\\p... ...\\pGlup, glup...\\p... ...\\pGulp...\\pSe quer ir pra CIDADE DE SAFFRON...\\p... ...\\pPode passar.\\pVou dividir esse CHÁ com os outros\\nguardas!",
  ["g3:0819e50f"] = "Oi, como vão as coisas?",
  ["g3:0819e523"] = "Os tipos de POKéMON combinam\\nde maneiras diferentes entre si.\\pCada tipo é mais forte contra alguns\\ntipos e mais fraco contra outros.",
  ["g3:0819e59d"] = "Uma PEPITA é totalmente inútil.\\nAí eu vendi por $5000.",
  ["g3:0819e5d2"] = "Ouvi dizer que fantasmas assombram\\na CIDADE DE LAVENDER.",
  ["g3:0819e5fb"] = "Ah... {PLAYER}!\\nEu estava te procurando!\\pSou eu, um dos ASSISTENTES do\\nPROFESSOR CARVALHO.\\pSe a sua POKéDEX tiver dados\\ncompletos de vinte espécies, devo\\pentregar a você uma recompensa\\pdo PROFESSOR CARVALHO.\\pEle me confiou esta PEDRETERNA.\\pEntao, {PLAYER}, deixa eu te\\nperguntar.\\pVocê já reuniu dados de pelo\\nmenos vinte tipos de POKéMON?",
  ["g3:0819e733"] = "Ótimo! Você capturou ou ganhou\\n{STR_VAR_3} tipos de POKéMON!\\pParabéns!\\nAqui está seu prêmio!",
  ["g3:0819e786"] = "{PLAYER} recebeu a PEDRETERNA\\ndo ASSISTENTE.",
  ["g3:0819e7af"] = "Fazer os POKéMON evoluírem ajuda\\na completar a POKéDEX.\\pMas às vezes você pode não querer\\nque um certo POKéMON evolua.\\pNesse caso, dê a PEDRETERNA para\\nesse POKéMON.\\pEla impedirá a evolução, de acordo\\ncom o PROFESSOR.",
  ["g3:0819e8a6"] = "Você não acha difícil inventar bons\\nnomes para os POKéMON?\\pEspecialmente se você capturou um\\nmonte?\\pNa CIDADE DE LAVENDER, tem um homem\\nque avalia apelidos de POKéMON.\\pEle também pode ajudar você a\\ndar novos nomes aos seus POKéMON.",
  ["g3:0819e97b"] = "Se você quer chegar à CIDADE DE\\nLAVENDER, vá pelo TÚNEL DE ROCHA.\\pVocê pode chegar ao TÚNEL DE ROCHA\\nsaindo da CIDADE DE CERULEAN.",
  ["g3:0819e9e5"] = "Oi! Lembra de mim?\\nSou um dos ASSISTENTES do\\pPROFESSOR CARVALHO.\\pSe a sua POKéDEX tiver dados\\ncompletos de {STR_VAR_1} espécies, eu\\pdevo te dar uma recompensa.\\pO PROFESSOR CARVALHO me confiou\\no {STR_VAR_2} para você.\\pEntao, {PLAYER}, deixa eu te\\nperguntar.\\pVocê reuniu dados de pelo menos\\n{STR_VAR_1} tipos de POKéMON?",
  ["g3:0819eae4"] = "Ótimo! Você capturou ou ganhou\\n{STR_VAR_3} tipos de POKéMON!\\pParabéns!\\nAqui está seu prêmio!",
  ["g3:0819eb37"] = "{PLAYER} recebeu o {STR_VAR_2}\\ndo ASSISTENTE.",
  ["g3:0819eb59"] = "Existem itens no chão que podem\\nestar escondidos.\\pUse o BUSCA-ITENS para detectar\\nquaisquer itens ocultos próximos\\pa você.\\pA máquina é um pouco limitada.\\nEla não consegue indicar a\\plocalizaçao exata dos itens.\\pO que ela faz é mostrar a direção\\nem que o item está.\\pUse-a para se orientar e depois\\nprocure pela área suspeita.",
  ["g3:0819ec8a"] = "Vamos ver o que os binóculos\\nmostram...\\pUm grande POKéMON está dormindo\\nna estrada!",
  ["g3:0819ecd9"] = "Vamos ver o que os binóculos\\nmostram...\\pQue vista de tirar o fôlego!",
  ["g3:0819ed1f"] = "Vamos ver o que os binóculos\\nmostram...\\pPara chegar à CIDADE DE LAVANDER\\na partir da CIDADE DE CERULEAN...\\pO TÚNEL DE ROCHA parece ser uma\\nboa rota a seguir.",
  ["g3:0819eda7"] = "Tem um observatório no andar de\\ncima. A vista é magnífica.",
  ["g3:0819ede1"] = "As cinzas do meu POKéMON estão\\nguardadas na TORRE POKéMON.\\pVocê pode ficar com esta MT.\\nEu não preciso mais dela...",
  ["g3:0819ee40"] = "As cinzas do meu POKéMON estão\\nguardadas na TORRE POKéMON.\\pVocê pode ficar com esta MT.\\nEu não preciso mais dela...",
  ["g3:0819ee9f"] = "{PLAYER} recebeu a MT27\\nda garotinha.",
  ["g3:0819eec6"] = "A MT27 é um movimento chamado\\nRETORNO...\\pSe você tratar bem o seu POKéMON,\\nele retribuirá seu amor lutando com\\ptodas as suas forças nas batalhas.",
  ["g3:0819ef3f"] = "Você não tem espaço para isso.",
  ["g3:0819ef5d"] = "Vamos ver o que os binóculos\\nmostram...\\pTem um homem pescando!",
  ["g3:0819efa0"] = "Vamos ver o que os binóculos\\nmostram...\\pÉ a TORRE POKéMON!",
  ["g3:0819efe0"] = "Sou o irmão mais novo do\\nMESTRE DA PESCA.\\pEu simplesmente aaaaamo pescar!\\nNão consigo ficar sem pescar.\\pMe diga, você gosta de pescar?",
  ["g3:0819f05b"] = "Ótimo! Gosto do seu jeito.\\nAcho que podemos ser amigos.\\pPegue isto e vá pescar,\\njovem camarada!",
  ["g3:0819f0b2"] = "{PLAYER} recebeu uma SUPERVARA\\ndo irmão do MESTRE DA PESCA.",
  ["g3:0819f0eb"] = "Pescar é um modo de vida!\\nÉ como a mais bela poesia.\\pDos mares aos rios, vá e fisgue\\num grandão, camarada.\\pAgora, tenho um pedido.\\pSe você pegar um grande MAGIKARP\\ncom essa vara, eu quero vê-lo.\\pPor mais que eu ame pescar, também\\nadoro ver MAGIKARP gigantes!",
  ["g3:0819f1fa"] = "Ah...\\nQue decepção...",
  ["g3:0819f217"] = "Oi, {PLAYER}!\\nTem pescado ultimamente?\\pTente pescar com a SUPERVARA\\nem qualquer poça d'água.\\pVocê vai encontrar POKéMON\\ndiferentes em lugares diferentes.\\pAh, e não se esqueça de me trazer\\num MAGIKARP gigantesco.",
  ["g3:0819f2db"] = "Ah? {PLAYER}?\\nOra, mas se não é um MAGIKARP!\\pDeixa eu ver rapidinho!",
  ["g3:0819f31b"] = "... ... ... Uau!\\n{STR_VAR_2} centímetros!\\pVocê aprecia mesmo os belos e\\npoéticos aspectos da pesca!\\pVocê tem que aceitar isto.\\nEu insisto!",
  ["g3:0819f395"] = "Estou ansioso para ver recordes\\nainda maiores seus!",
  ["g3:0819f3cb"] = "Ha?\\n{STR_VAR_2} centímetros?\\pEste tem o mesmo tamanho daquele\\nque vi antes.",
  ["g3:0819f40a"] = "Hmm...\\nO tamanho desse aqui é {STR_VAR_2} polegadas.\\pNão se compara ao de\\n{STR_VAR_3} polegadas que cê trouxe antes.",
  ["g3:0819f468"] = "Ah... Isso não parece muito com\\num MAGIKARP.",
  ["g3:0819f494"] = "Ah, não!\\pEu tinha um presente para você,\\nmas você não tem espaço para ele.",
  ["g3:0819f4cf"] = "A maior MAGIKARP\\nque já testemunhei...\\p{STR_VAR_3} polegadas!",
  ["g3:0819f50c"] = "É algum tipo de quadro em branco.\\pTem espaços para anotar certos\\ntipos de registros.",
  ["g3:0819f560"] = "Você é quem está\\ntrabalhando na POKéDEX?\\pO ASSISTENTE do PROFESSOR CARVALHO\\npassou por aqui.",
  ["g3:0819f5ab"] = "Oi! Lembra de mim?\\nSou um dos ASSISTENTES do\\pPROFESSOR CARVALHO.\\pSe a sua POKéDEX tiver dados\\ncompletos de {STR_VAR_1} espécies, eu\\pdevo te dar uma recompensa.\\pO PROFESSOR CARVALHO me confiou\\no {STR_VAR_2} para você.\\pEntao, {PLAYER}, deixa eu te\\nperguntar.\\pVocê reuniu dados de pelo menos\\n{STR_VAR_1} tipos de POKéMON?",
  ["g3:0819f6aa"] = "Ótimo! Você capturou ou ganhou\\n{STR_VAR_3} tipos de POKéMON!\\pParabéns!\\nAqui está seu prêmio!",
  ["g3:0819f6fd"] = "{PLAYER} recebeu o {STR_VAR_2}\\ndo ASSISTENTE.",
  ["g3:0819f71f"] = "O COMPARTILHADOR DE EXP. é um item\\npara ser segurado por um POKéMON.\\pO POKéMON vai receber uma parte dos\\nPontos de EXP. sem precisar batalhar.",
  ["g3:0819f79c"] = "Vamos ver o que os binóculos\\nmostram...\\pUma grande ave brilhante está\\nvoando em direção ao mar.",
  ["g3:0819f7f8"] = "Vamos ver o que os binóculos\\nmostram...\\pParece uma pequena ilha no\\nhorizonte!",
  ["g3:0819f851"] = "Ah, puxa... Você descobriu meu\\nesconderijo secreto.\\pPor favor, não conta pra ninguém\\nque eu estou aqui.\\pVou te compensar com isto!",
  ["g3:0819f8c0"] = "{PLAYER} recebeu a MO02\\nda garota.",
  ["g3:0819f8e0"] = "A MO02 é VOAR.\\nÉ um movimento muito útil.\\pPor favor, use com sabedoria.",
  ["g3:0819f92d"] = "Você não tem espaço para isso.",
  ["g3:0819f94f"] = "FEAROW: Kyueen!",
  ["g3:0819f95f"] = "Nenhum pedestre é permitido na\\nCICLOVIA!",
  ["g3:0819f98b"] = "A CICLOVIA é uma descida à\\nbeira-mar. É um passeio e tanto.",
  ["g3:0819f9cc"] = "Com licença!\\nEspera, por favor!",
  ["g3:0819f9e8"] = "Como você entrou aqui?\\nBom trabalho!",
  ["g3:0819fa07"] = "Tô dando um passeio tranquilo na\\nminha nova bicicleta com minha\\pnamorada.",
  ["g3:0819fa41"] = "A gente vai pedalar juntos nas\\nnossas novas bicicletas.",
  ["g3:0819fa6f"] = "Vamos ver o que os binóculos\\nmostram...\\pÉ o SHOPPING DE CELADON!",
  ["g3:0819fab9"] = "Vamos ver o que os binóculos\\nmostram...\\pTem um longo caminho sobre a\\nágua, bem longe daqui.",
  ["g3:0819fb0e"] = "Oi! Lembra de mim?\\pSou um dos ASSISTENTES do\\nPROFESSOR CARVALHO.\\pSe a sua POKéDEX tiver dados\\ncompletos de 40 espécies, eu\\pdevo te dar uma recompensa.\\pO PROFESSOR CARVALHO me confiou\\na MOEDA-AMULETO para você.\\pEntao, {PLAYER}, deixa eu te\\nperguntar.\\pVocê reuniu dados de pelo menos\\n40 tipos de POKéMON?",
  ["g3:0819fc15"] = "Ótimo! Você capturou ou ganhou\\n{STR_VAR_3} tipos de POKéMON!\\pParabéns!\\nAqui está seu prêmio!",
  ["g3:0819fc68"] = "{PLAYER} recebeu a MOEDA-AMULETO\\ndo ASSISTENTE.",
  ["g3:0819fc93"] = "A MOEDA-AMULETO é um item para\\num POKéMON segurar.\\pSe o POKéMON participar de uma\\nbatalha e vencer, você vai ganhar\\pmais dinheiro.",
  ["g3:0819fd0c"] = "Você precisa de uma BICICLETA\\npara entrar na CICLOVIA!",
  ["g3:0819fd3a"] = "Daqui pra frente, a CICLOVIA é só\\nsubida.",
  ["g3:0819fd60"] = "Com licença!",
  ["g3:0819fd6b"] = "Vamos ver o que os binóculos\\nmostram...\\pA CIDADE DE PALLET fica a oeste.",
  ["g3:0819fdb3"] = "Vamos ver o que os binóculos\\nmostram...\\pTem pessoas nadando.",
  ["g3:0819fdfa"] = "E aí! Sou um POKéMON...\\n... Quer dizer, não sou não!\\pPode me chamar de BILL!\\nSou um verdadeiro POKéMANÍACO!\\pEi!\\pQual é desse olhar de\\ndesconfiança?\\pTô falando sério, cara.\\pEstraguei um experimento e acabei\\nme fundindo com um POKéMON!\\pEntao, que tal me dar uma ajudinha\\naqui?",
  ["g3:0819fee6"] = "E aí! Sou um POKéMON...\\n... Quer dizer, não sou não!\\pPode me chamar de BILL!\\nSou um verdadeiro POKéMANÍACO!\\pEi!\\pQual é desse olhar de\\ndesconfiança?\\pTô falando sério, moça.\\pEstraguei um experimento e acabei\\nme fundindo com um POKéMON!\\pEntao, que tal me dar uma ajudinha\\naqui?",
  ["g3:0819ffd3"] = "Espera eu entrar no\\nTELETRANSPORTADOR.\\pQuando eu estiver lá dentro, vá\\naté meu PC e ative o Sistema de\\pSeparaçao Celular.",
  ["g3:081a0035"] = "Não?!\\nPoxa, não seja tão frio!\\pVamos lá, você tem que ajudar um\\ncara em apuros, e dos grandes!\\pO que me diz, parceiro?\\nPor favor?\\pTá bem?\\pBeleza!",
  ["g3:081a00b6"] = "Não?!\\nAh, não seja tão fria!\\pVamos lá, você tem que ajudar um\\ncara em apuros, e dos grandes!\\pO que me diz, lindinha?\\nPor favor?\\pTá bem?\\pBeleza!\\n",
  ["g3:081a013b"] = "BILL: Uhul!\\nValeu, cara! Tô te devendo uma!\\pEntao, você veio ver minha\\ncoleçao de POKéMON?\\pNão veio?\\nQue pena.\\pTenho que te agradecer de algum\\njeito...\\pAh, toma isso, talvez será útil.",
  ["g3:081a01e4"] = "BILL: Uhul!\\nValeu, moça! Tô te devendo uma!\\pEntao, você veio ver minha\\ncoleçao de POKéMON?\\pNão veio?\\nQue pena.\\pTenho que te agradecer de algum\\njeito...\\pAh, toma isso, talvez será útil.",
  ["g3:081a028e"] = "{PLAYER} recebeu um\\nBILHETE DO NAVIO de BILL.",
  ["g3:081a02b4"] = "Você tá carregando coisa demais!",
  ["g3:081a02cf"] = "Aquele navio de cruzeiro, o SANTA\\nANA, está na CIDADE DE VERMILION.\\pOuvi dizer que tem muitos\\nTREINADORES a bordo também.\\pEles me convidaram pra festa, mas eu\\nnão suporto esses eventos chiques.\\pPor que você não vai no meu lugar?\\nVai lá e se diverta!",
  ["g3:081a03ab"] = "BILL: Quer dar uma olhada em alguns\\ndos meus POKéMON raros no meu PC?\\pVai lá, pode olhar no meu PC.",
  ["g3:081a0402"] = "O TELETRANSPORTADOR está exibido\\nna tela do PC.",
  ["g3:081a042d"] = "{PLAYER} ativou o Separador\\nCelular do TELETRANSPORTADOR.",
  ["g3:081a045b"] = "A lista dos POKéMON favoritos do\\nBILL!",
  ["g3:081a0479"] = "Qual POKéMON você quer ver?",
  ["g3:081a049b"] = "Posso não parecer grande coisa\\nagora, mas quando eu era mais\\pjovem...\\pEu voava por toda parte, desafiando\\nTREINADORES sempre que encontrava\\pum.\\pHoje, minha única diversão é\\nrelembrar o passado enquanto\\passisto às batalhas.",
  ["g3:081a0567"] = "Tem uma leve brisa soprando ao\\nredor da caixa.",
  ["g3:081a0598"] = "Ah!\\nBoas-vindas, camarada!\\pDeixa eu te contar uma coisa.\\nTem uma sala secreta no porão.\\pUm TREINADOR chamado {STR_VAR_1}\\nestá te esperando lá agora.\\pMe fala, você veio desafiar\\n{STR_VAR_1}, não é?\\n",
  ["g3:081a064e"] = "Ah...\\nVocê não vai batalhar...\\pEntendo, entendo.\\n... ...\\pBem, talvez, se mudar de ideia,\\nvolte aqui.",
  ["g3:081a06ab"] = "Ah!\\nVocê vai batalhar por mim?\\pEntao valeu a pena eu ter movido\\na caixa.\\p... ...\\nMas tem um pequeno problema.\\pEsta sala secreta não foi construída\\nde forma muito resistente.\\pVocê pode limitar a batalha a\\ntrês POKéMON de cada lado?",
  ["g3:081a0788"] = "Certo! Antes da batalha, você\\ngostaria de salvar seu jogo?",
  ["g3:081a07c4"] = "Muito bem.\\nNão se segura!",
  ["g3:081a07ec"] = "A batalha terminou em empate.",
  ["g3:081a0807"] = "Um empate, é?\\pMas devo dizer que foi um\\nespetáculo digno.\\pDiria que foi uma batalha\\nmaravilhosa, com um verdadeiro\\psenso de profundidade!",
  ["g3:081a088c"] = "Bravo!\\pBravo, de verdade!\\nQue batalha incrível!\\pFoi tão incrível que, veja só,\\nenche meus olhos de lágrimas!\\pO ataque e a defesa de técnicas\\nusadas com maestria!\\pO choque de poder contra poder!\\pSim!\\nFoi pura magnificência!",
  ["g3:081a0971"] = "Que pena!\\nSinto a sua decepção.\\pMas é justamente essa decepção\\nque vai te tornar melhor.\\pUse-a, aprenda com ela e deixe que\\nte motive a buscar a grandeza.\\pNão esqueça essa decepção e\\nredobre seu treinamento!",
  ["g3:081a0a4f"] = "Os POKéMON têm personalidades\\npróprias, assim como as pessoas.\\pMeu PIKACHU tem uma natureza\\nAPRESSADA, então acabou se\\ptornando um POKéMON veloz.",
  ["g3:081a0acc"] = "Certo, estou pronto para explorar\\nas RUÍNAS.",
  ["g3:081a0b09"] = "Tenho que pescar na ILHA SETE.\\pAssim vou completar minha turnê\\nde pesca pelas ILHAS SETII.\\pMas é melhor eu estocar algumas\\nPOKé BOLAS antes disso.",
  ["g3:081a0b98"] = "Nesta ilha, acontecem diferentes\\neventos dependendo das conexoes.\\pQuais conexoes são essas?\\pIsso cabe a você descobrir por\\nconta própria.",
  ["g3:081a0c1f"] = "Você veio até aqui com a balsa\\nGALOPE MARINHO?\\pExistem pelo menos dez desses\\nnavios de alta velocidade.\\pMas eu não sei exatamente para onde\\ntodos eles vão.",
  ["g3:081a0ca5"] = "Se está confiante, deveria dar uma\\npassada na TORRE DOS TREINADORES.",
  ["g3:081a0cde"] = "BILL: E aí!\\nCELIO!",
  ["g3:081a0cf7"] = "CELIO: BILL!\\nNão acredito que você veio até aqui.",
  ["g3:081a0d27"] = "BILL: Ora, com certeza!\\nComo vai sua pesquisa?\\p... Ah, espera um pouco.",
  ["g3:081a0d72"] = "{PLAYER}, este é meu amigo CELIO.\\nEle é um MANÍACO por PCs\\psuperdedicado!",
  ["g3:081a0dac"] = "CELIO, aqui está {PLAYER}, forte\\ncandidato ao título de CAMPEÃO\\pPOKéMON!",
  ["g3:081a0de8"] = "CELIO, aqui está {PLAYER}, atual\\nCAMPEÃO POKéMON!",
  ["g3:081a0e17"] = "CELIO: Isso é muito impressionante.\\pOdeio dizer isso, mas não tenho\\nnenhuma aptidão para batalhas.\\pDe qualquer forma, fico feliz em\\nte conhecer.",
  ["g3:081a0e90"] = "BILL: Certo, me conta.\\nComo anda a sua máquina?",
  ["g3:081a0ecc"] = "CELIO: Está funcionando bem, mas\\nestamos muito isolados aqui.\\pOs PCs desta ilha não conseguem\\nse conectar ao seu PC, BILL.",
  ["g3:081a0f40"] = "BILL: Ah, é?\\nDeixa eu dar uma olhada.\\p... Espera aí...\\nAcho que dá pra fazer funcionar.\\pVou te dar uma força, tá?",
  ["g3:081a0fb1"] = "{PLAYER}, você pode esperar um\\npouco por mim?\\p... Na verdade, pode me fazer um\\nfavor?\\pA ilha ao lado desta se chama\\nILHA DOIS.\\pTem um cara lá que cuida de um\\nCASSINO.\\pEle é fissurado em rochas e\\npedras raras.\\pA gente mantém contato, já que\\ntemos interesses parecidos.\\pSerá que você pode entregar este\\nMETEORITO pra ele?",
  ["g3:081a10ee"] = "{PLAYER} aceitou o METEORITO\\nde BILL.",
  ["g3:081a1113"] = "CELIO: {PLAYER}, se você for para\\na ILHA DOIS, por favor, leve isto.",
  ["g3:081a1150"] = "É um PASSE para o serviço de\\nbalsa que atende as ilhas locais.\\pEle vai permitir que você viaje\\nentre as ILHAS UM, DOIS e TRÊS.\\pAh, você também deve ficar com\\nisto.",
  ["g3:081a11ec"] = "{PLAYER} recebeu uma página extra\\npara o MAPA DA REGIÃO!",
  ["g3:081a1218"] = "{PLAYER} recebeu um\\nMAPA DA REGIÃO!",
  ["g3:081a1230"] = "BILL: Te vejo depois!\\nManda um oi pro cara por mim!",
  ["g3:081a1266"] = "Hmm...\\pQue tal se a gente tentar assim...",
  ["g3:081a128c"] = "Ah, oi, {PLAYER}!\\pViu só?\\nA gente fez o PC funcionar!\\pAinda tenho algumas coisas para\\nmostrar ao CELIO.\\pSerá que você pode dar mais umas\\nvoltinhas por aí?",
  ["g3:081a1321"] = "Desculpe por ocupar tanto o tempo\\ndo BILL.\\pE também peço desculpas por não\\nter sido um bom anfitrião durante\\pa sua visita aqui.",
  ["g3:081a1390"] = "Os serviços normais do PC não estão\\ndisponíveis...",
  ["g3:081a13b8"] = "BILL: Ah, oi!\\n{PLAYER}!",
  ["g3:081a13cb"] = "BILL: Por que demorou tanto?\\nEstava se divertindo por aí?\\pConseguimos terminar.\\nOs PCs já estão funcionando!",
  ["g3:081a1431"] = "CELIO: O trabalho foi muito rápido.\\pO BILL é um cara incrível...",
  ["g3:081a1470"] = "BILL: Que nada! Não sobrou quase\\nnada pra eu fazer.\\pCELIO, tenho que admitir.\\nVocê aprendeu muito.",
  ["g3:081a14e1"] = "CELIO: Sério?\\nEhehe...",
  ["g3:081a14fb"] = "BILL: Bom, é isso aí.\\nTerminei o trabalho.\\pÉ melhor voltarmos para KANTO.\\pCELIO, até a próxima.",
  ["g3:081a1574"] = "CELIO: {PLAYER}, sinto muito por ter\\ndeixado você ir só hoje.\\pPrometo que um dia vou te levar\\npara conhecer essas ilhas.",
  ["g3:081a15ec"] = "CELIO: Oi!\\nAs coisas parecem corridas pra você como sempre.\\pComo eu estou?\\pBem, estou modificando minha\\nMáquina de Rede.\\pQuando eu terminar o trabalho nela,\\nespero que você seja a primeira pessoa a\\pusá-la, {PLAYER}.",
  ["g3:081a169b"] = "CELIO: {PLAYER}, como vão as\\ncoisas?\\pAh, é mesmo?\\nVocê capturou mais POKéMON.\\pSabe de uma coisa?\\nTalvez eu possa ser útil para você.",
  ["g3:081a1723"] = "Estou modificando a Máquina de Rede\\nagora mesmo.\\pEstou ajustando ela para que\\nconsiga lidar com trocas a longas\\pdistâncias.\\pQuando eu terminar, você vai poder\\ntrocar POKéMON exóticos com\\pTREINADORES de lugares distantes.",
  ["g3:081a17df"] = "Mas tem um pequeno problema.\\pPara a conexão funcionar, a máquina\\nprecisa de uma pedra preciosa\\pespecial.\\pDizem que ela está na ILHA UM,\\nmas eu ainda não encontrei.\\pQuem sabe onde ela pode estar.",
  ["g3:081a1896"] = "Eu estava tentando encontrar a\\npedra mesmo enquanto estudava.\\pComo resultado, não avancei nem\\nna pesquisa nem nos estudos...\\pCom a ajuda do BILL, tenho certeza\\nde que minha pesquisa andaria.\\pMas quero tentar fazer as coisas\\npor conta própria desta vez.",
  ["g3:081a197e"] = "Ah!\\nI-isso é...",
  ["g3:081a198d"] = "{PLAYER} entregou o RUBI\\npara CELIO.",
  ["g3:081a19aa"] = "Obrigado!\\n{PLAYER}, você é simplesmente\\pincrível.\\p... ... ...  ... ... ...\\pHmm... Posso te pedir mais um grande\\nfavor?",
  ["g3:081a1a08"] = "N-não é nada demais.\\nPor favor, eu preciso da sua ajuda.",
  ["g3:081a1a3f"] = "Enquanto eu estudava as pedras\\npreciosas, descobri algo importante.\\pExiste outra joia que forma um par\\ncom este RUBI.\\pEssa outra pedra preciosa deve\\nestar nas ILHAS SETII.\\p{PLAYER}, por favor, preciso que\\nvocê vá encontrar a outra joia.\\p{PLAYER}, pode me dar o seu PASSE\\nda balsa e o MAPA DA REGIÃO?",
  ["g3:081a1b56"] = "{PLAYER} entregou o PASSE TRIPLO e\\nrecebeu o PASSE ARCO-ÍRIS.",
  ["g3:081a1b8e"] = "Obteve uma página extra para o\\nMAPA DA REGIÃO!",
  ["g3:081a1bb7"] = "Este é o meu próprio PASSE da\\nbalsa.\\pEle vai permitir que você viaje\\npara todas as ILHAS SETII.\\p{PLAYER}, por favor, não consigo\\nfazer isso sem a sua ajuda.",
  ["g3:081a1c2d"] = "{PLAYER} entregou a SAFIRA\\npara CELIO.",
  ["g3:081a1c4e"] = "CELIO: Entao esta é a joia que\\nforma um par com o RUBI...\\p{PLAYER}, você passou por muita\\ncoisa para conseguir isso, não foi?\\pNão precisa me dizer.\\nEu sei que não foi fácil.\\pMuito obrigado!\\pAgora é a minha vez de trabalhar\\npor você! Espera só um pouquinho.",
  ["g3:081a1d45"] = "Certo, está ótimo...",
  ["g3:081a1d59"] = "Consegui!\\nConsegui me conectar com a LANETTE!",
  ["g3:081a1d7d"] = "{PLAYER}...\\n{PLAYER}, eu consegui!\\pConsegui me conectar com\\nTREINADORES da região de HOENN!\\pFinalmente, a Máquina de Rede\\nestá totalmente operacional!\\p{PLAYER}, eu devo tudo a você!\\pGraças a você, meu sonho se tornou\\nrealidade...",
  ["g3:081a1e39"] = "E-eu... não estou chorando.\\pChega de falar de mim!\\p{PLAYER}, você vai continuar\\nprocurando POKéMON exóticos, né?\\pTe desejo muita sorte!",
  ["g3:081a1ebd"] = "CELIO: Oi!\\p{PLAYER}, tenho ouvido alguns\\nrumores sobre você.",
  ["g3:081a1ef3"] = "{PLAYER}, qual é o seu tipo favorito\\nde POKéMON?\\pO BILL é um POKéMANÍACO, então\\nele ama todos os tipos.\\pParece que o primeiro que ele\\ncapturou foi um ABRA.",
  ["g3:081a1f7c"] = "A propósito, {PLAYER}, você é da\\nCIDADE DE PALLET, não é?\\pOuvi dizer que é um lugar\\ntranquilo e agradável.\\pA cidade natal do BILL é GOLDENROD,\\nonde os pais dele ainda moram.\\pOuvi dizer que é uma cidade bem\\nmovimentada e cheia de vida.\\pGostaria de visitá-la um dia.\\n",
  ["g3:081a2076"] = "{PLAYER}, tem alguma coisa que\\nvocê não suporta?\\pDizem que o BILL não suporta leite\\nde jeito nenhum.",
  ["g3:081a20d5"] = "Ah, chegou agora por aqui!\\nOi! De onde você veio?\\p... CIDADE DE PALLET?\\nNunca ouvi falar!",
  ["g3:081a212d"] = "Tem um vulcão enorme nesta ilha.\\pEle não entra em erupção faz tempo,\\nentao por que não aproveitar e\\pfazer uma caminhada?",
  ["g3:081a218d"] = "Eu queria poder trocar POKéMON com\\no meu namorado que mora longe...",
  ["g3:081a21d0"] = "Eu troquei POKéMON com o meu\\nnamorado que mora longe!\\pTodo mundo está dizendo que isso\\nsó foi possível graças a você e\\pao CELIO.\\pEntao, obrigada!",
  ["g3:081a223f"] = "Máquina de Rede\\nNível de Conexao 0\\p... Sistema de Armazenamento POKéMON\\nem ajuste...",
  ["g3:081a2286"] = "Máquina de Rede\\nNível de Conexao 1\\pConexao estabelecida com a região\\nde KANTO.",
  ["g3:081a22cb"] = "Máquina de Rede\\nNível de Conexao 2\\pConexao estabelecida com as regioes\\nde KANTO e HOENN.",
  ["g3:081a231b"] = "Obteve o PASSE TRIPLO!",
  ["g3:081a2332"] = "Nos dias ensolarados, eu saio e fico\\nolhando para o vulcão.\\pEssa é a minha rotina diária.",
  ["g3:081a2380"] = "Hmm... Quando foi mesmo a última\\nvez que o MONTE BRASA entrou em\\perupçao?",
  ["g3:081a23b8"] = "Todos os jovens querem ir embora\\npara as grandes cidades.\\pMas eu quero ficar aqui pra sempre!",
  ["g3:081a2408"] = "Onde será que a PERDITA se meteu\\nhoje?\\pEla sempre me traz o almoço\\npor volta dessa hora...",
  ["g3:081a2465"] = "Hm? Você aí!\\nTem amizade com a PERDITA?\\pVocê viu ela por aí? Não faço\\nideia de onde ela possa estar.\\pEla já devia ter voltado faz\\ptempo.\\pA PERDITA é uma gracinha, puxou\\na minha beleza, e se alguém...\\pE se alguma coisa aconteceu\\ncom a minha PERDITA?!\\pPor favor, me ajuda a encontrá-la!\\nVá procurar na ILHA TRÊS, por favor!",
  ["g3:081a259a"] = "Ha? Que história é essa de CASSINO?\\nNão dá pra ficar mais deprimente\\pdo que isso.\\pAqueles palhaços...\\pDisseram que estariam esperando\\nna ilha, então onde eles estão?\\pEi, você! Essa é a única\\nILHA TRÊS por aqui?",
  ["g3:081a2658"] = "Tenta acordar antes de sair da\\ncama, seu moleque.\\pAqui é a ILHA DOIS!\\pSai daqui! Tira essa sua moto\\nimunda do meu estabelecimento!",
  ["g3:081a26d5"] = "Ha...\\nAh, ah, entendi.\\pTsc...\\nEssas ilhas são confusas...",
  ["g3:081a270c"] = "Olha só pra isso... Aquele moleque\\narranhou todo o meu piso.",
  ["g3:081a2743"] = "Ei, mas escuta! Eu imploro, você\\ntem que ir para a ILHA TRÊS.\\pSe alguma coisa acontecer\\ncom a minha PERDITA...\\pMinha casa é a de telhado vermelho\\nna ILHA TRÊS.\\pEla pode aparecer por aqui, então\\neu não posso sair pra procurar.\\pPor isso preciso que você me faça\\nesse grande favor.",
  ["g3:081a285c"] = "Desculpe.\\nNão estamos realizando jogos hoje.",
  ["g3:081a288a"] = "Em breve vamos colocar os jogos\\npra funcionar pra você!",
  ["g3:081a28b2"] = "Entao você resgatou a PERDITA?\\nComo posso te agradecer?\\pPERDITA, querida, me perdoe!\\pO papai não sabia que você estava\\nassustada e em apuros!",
  ["g3:081a2931"] = "PERDITA: Tá tudo bem, papai.\\nEu fiz amizade com {PLAYER}!",
  ["g3:081a296a"] = "Oh, o que é isso? Você tá dizendo\\nque isso é pra mim?\\pComo você sabia que eu adoro\\nrochas e joias raras?\\pVocê sabe mesmo como deixar\\num cara feliz.",
  ["g3:081a29f7"] = "{PLAYER} entregou o METEORITO\\npara o pai de PERDITA.",
  ["g3:081a2a24"] = "Ah, entendi, isso é do BILL!\\nAgradeça a ele por mim!\\pSabe, que fantástico.\\nQuero que fique com isto.",
  ["g3:081a2a9a"] = "{PLAYER} recebeu uma PEDRA DA LUA\\ndo pai de PERDITA.",
  ["g3:081a2aca"] = "Sua MOCHILA não vai caber mais\\nnada...",
  ["g3:081a2af5"] = "Certo, vou colocar o CASSINO\\npra funcionar agora mesmo.\\pVocê tem que vir visitar a gente\\ncom um amigo.",
  ["g3:081a2b53"] = "Ei, ei!\\pQuero ver você sendo incrível\\nde novo!",
  ["g3:081a2b88"] = "Sou o MANÍACO por MOVIMENTOS\\nPOKéMON.\\pConheço todos os movimentos que\\nos POKéMON aprendem enquanto\\pcrescem.\\pTambém sou um maníaco por\\ncogumelos.\\pTraga-me dois MINICOGUMELOS\\nou um COGUMELO GRANDE.\\pSe fizer isso, vou ensinar um\\nmovimento a um dos seus POKéMON.",
  ["g3:081a2c63"] = "Snif, snif...\\nHm! Você tem cheiro de COGUMELOS!\\pQuer que eu ensine um movimento a\\num dos seus POKéMON?",
  ["g3:081a2cc3"] = "Qual POKéMON precisa de treinamento?",
  ["g3:081a2ce1"] = "Qual movimento devo ensinar?",
  ["g3:081a2cfc"] = "Desculpe...\\pAcho que não tem nenhum movimento\\nque eu possa ensinar a esse POKéMON.",
  ["g3:081a2d43"] = "Então, vou precisar de um ou dois\\nCOGUMELOS. O que você vai me dar?",
  ["g3:081a2d85"] = "{PLAYER} entregou dois\\nMINICOGUMELOS em troca.",
  ["g3:081a2db3"] = "{PLAYER} entregou um\\nCOGUMELO GRANDE em troca.",
  ["g3:081a2de0"] = "Se seus POKéMON precisarem aprender\\num movimento, vou precisar de um\\pou dois COGUMELOS.",
  ["g3:081a2e20"] = "Hã? Não tem nenhum movimento\\nque eu possa ensinar a um OVO.",
  ["g3:081a2e59"] = "Você já visitou o CASSINO?\\pNão é bom ir só.\\nVocê precisa levar um amigo junto.",
  ["g3:081a2ebe"] = "Não mora muita gente na ILHA DOIS.\\pTem uma senhora que vive lá no\\ncabo.\\pEla está lá desde... sei lá quando.",
  ["g3:081a2f3e"] = "PERDITA: Oi, {PLAYER}!\\nVocê é sempre tão legal!\\pUm dia eu vou preparar o almoço\\npra você, {PLAYER}.",
  ["g3:081a2f92"] = "Pedras e joias raras estão em\\nexposição.",
  ["g3:081a2fb5"] = "Ei, você ouviu a novidade?\\pOs PCs daqui agora pode se\\nconectar com os PCs de KANTO.\\pNão sei como isso aconteceu,\\nmas é fantástico!",
  ["g3:081a303b"] = "É impossível SURFAR entre as ilhas\\ndessa região.\\pAs marés são muito rápidas e\\ntraiçoeiras.",
  ["g3:081a30a3"] = "Vamos esmagar FRUTAS!\\n... Isso seria desperdiçar FRUTAS?\\pVocê sempre pode encontrar algumas\\nFRUTAS no chão da FLORESTA DAS\\pFRUTAS.",
  ["g3:081a3114"] = "É verdade?\\pO SHOPPING DE CELADON é muito\\nmaior do que esta loja?",
  ["g3:081a315c"] = "Às vezes eu compro remédios aqui.\\pMas muita gente cura os POKéMON com\\nFRUTAS da FLORESTA DAS FRUTAS.\\pAfinal, as FRUTAS são de graça e\\nnunca acabam.",
  ["g3:081a31f0"] = "Aqueles MOTOQUEIROS estavam prestes\\na destruir esta LOJA POKéMON.\\pAinda bem que decidiram ir embora!",
  ["g3:081a3245"] = "Urrrrrrrrgggghhhh...\\nKwaaaaah!\\p... Não adianta! Não consigo entortar\\nessa colher com a mente.\\pTalvez eu não tenha mesmo nenhum\\npoder psíquico.",
  ["g3:081a32ca"] = "Você conhece a LÍDER de GINÁSIO\\nda CIDADE DE SAFFRON?\\pEla usa POKéMON do tipo PSÍQUICO,\\nné?\\pEu admiro ela, de verdade.\\pOuvi dizer que ela é muito calma\\ne ainda por cima muito bonita.",
  ["g3:081a3379"] = "Comprei essa casa porque queria\\nmorar em um lugar tranquilo.\\pAcho que hoje vou sair pra pescar.",
  ["g3:081a33db"] = "Você nunca, jamais deve ir só\\npara a FLORESTA DAS FRUTAS.\\pSabe por quê?\\nPorque tem fantasmas lá.",
  ["g3:081a342f"] = "O papai vive mentindo pra mim e\\nnão me deixa sair pra brincar!",
  ["g3:081a3469"] = "Eu?\\nEu não sou a PERDITA.\\pAcho que ela deve ter ido pra\\nFLORESTA DAS FRUTAS.\\pEla costuma pegar FRUTAS lá pra\\npreparar o almoço.",
  ["g3:081a34db"] = "Acho que vou brincar com a\\nPERDITA hoje.",
  ["g3:081a3505"] = "Pronto?\\nBoing!\\pEstamos tendo uma disputa de\\nPANCADA CORPORAL pra ver quem\\pdesiste primeiro!\\pSe você entrasse no meio, te\\nesmagariam como um inseto...\\pQue tal eu ensinar PANCADA CORPORAL\\na um dos seus POKéMON em vez disso?",
  ["g3:081a35c7"] = "Volte sempre!\\nBoing!",
  ["g3:081a35da"] = "Para qual POKéMON devo ensinar\\no movimento PANCADA CORPORAL?",
  ["g3:081a3609"] = "Boioing!",
  ["g3:081a3627"] = "Existe um tipo raro de POKéMON de\\nGELO que vive na caverna.\\pMuita gente vem até aqui na\\nesperança de ver esse POKéMON.",
  ["g3:081a3697"] = "Ah? Um OVO de POKéMON?\\n... Não faço ideia.\\p...Ah, espera. O pessoal da CRECHE\\nna cidade comentou algo sobre isso.\\pDisseram que já encontraram OVOS\\nna propriedade deles.",
  ["g3:081a3734"] = "O que é isso?\\pO novo JORNAL POKéMON ainda não\\nchegou nesta ilha?",
  ["g3:081a3802"] = "Lá vai! Boing!\\nVocê é bem forte!",
  ["g3:081a3826"] = "LORELEI: Tem uma coisa que não\\nsai da minha mente.\\pSe acontecesse alguma coisa na\\nilha onde nasci...\\pEu não saberia se estivesse na\\nLIGA POKéMON.\\pSerá que eu estaria sendo\\ndescuidada com meu lar...?",
  ["g3:081a390c"] = "LORELEI: Quer dizer que você\\nresolveu todos os problemas daqui?\\pQue ótimo!\\pIsso quer dizer que não preciso\\nmais ficar aqui o tempo todo.\\pObrigada...\\pEm breve, vou voltar para a\\nLIGA POKéMON.",
  ["g3:081a39d8"] = "Não sei o que vai acontecer no\\nfuturo, mas...\\pFarei o que puder aqui e agora.\\nÉ tudo o que posso fazer.",
  ["g3:081a3a42"] = "Um monte de pelúcias de POKéMON!",
  ["g3:081a3a60"] = "Uma TREINADORA incrível e\\npoderosa cresceu nesta ilha.\\pAposto que até você conhece ela.\\nÉ a LORELEI da ELITE DOS QUATRO!\\pQuando a LORELEI ainda era só\\numa criança, eu lhe ensinei sobre\\pos POKéMON.",
  ["g3:081a3b14"] = "As ILHAS SETII ficam em uma região\\nque é normalmente quente.\\pMas há uma exceção que você\\nprecisa conhecer.\\pA CAVERNA GLACIAL é muito fria por\\ncausa dos POKéMON que vivem lá.",
  ["g3:081a3bba"] = "Estou indo preparar o jantar para\\numa pessoa da alta sociedade.",
  ["g3:081a3bfd"] = "Você está em uma jornada para\\ncapturar todos os tipos de\\pPOKéMON?\\p... Incrível. Me avise se capturar\\num bem forte!",
  ["g3:081a3cac"] = "Não precisa comprar nada pro\\njantar hoje!\\p... Foi o que meu marido disse\\nquando saiu pra pescar.\\pNão sei se dá pra contar muito\\ncom essa promessa dele.",
  ["g3:081a3d5e"] = "Aquela CAMPINA pertence à nossa\\nfamília há geraçoes.\\pEu devia ter mandado construir\\numa mansão enorme lá.\\pSeria bem melhor do que deixar\\naqueles bandidos fazerem o que\\pquerem por lá!",
  ["g3:081a3e02"] = "Por dez anos, procurei pelas\\nRUÍNAS.\\pNão, melhor dizendo, há vinte anos.\\pTenho a sensação de que há algo\\nescondido nesta ilha.",
  ["g3:081a3e87"] = "Você sabe que alguns POKéMON só\\nevoluem quando são trocados, né?\\pMas sabia que existem outros\\ncasos?\\pAlguns POKéMON só evoluem se\\nforem trocados segurando itens\\pespecíficos.",
  ["g3:081a3f30"] = "{RIVAL}: Ei, {PLAYER}!\\nComo está indo a sua POKéDEX?\\pParece ser impossível conseguir\\ntodos os POKéMON só ficando\\ppor aqui.\\pTalvez existam POKéMON que ainda\\nnão conhecemos em algum lugar\\pdistante...\\p... ... ...  ... ... ...  ... ... ...\\pBom, se eu não consigo, você\\ntambém não vai conseguir.\\pNão vou me desesperar por isso.\\pVou continuar capturando POKéMON\\nno meu próprio ritmo enquanto\\ptreino eles.\\pÉ assim que vou seguir.\\nEntao não adianta ficar aqui.\\pÉ melhor eu voltar pra casa.\\pÉ isso!\\nFalou!",
  ["g3:081a412e"] = "Não tem nada que os jovens\\nachariam empolgante nesta ilha.\\pMas aqui é um ótimo lugar em\\ntermos de natureza e história.\\pRelaxa e aproveita sua estadia.",
  ["g3:081a41ca"] = "Brinque bastante com os POKéMON\\ne tenha uma vida longa!\\pPegue a AGATHA como exemplo.\\pEla detém o recorde de ser a\\nintegrante mais velha da\\pELITE DOS QUATRO.\\pEla me inspira a ir mais longe.",
  ["g3:081a4271"] = "Acho que vou comprar uma\\nCARTA e escrever pra ele...",
  ["g3:081a42a0"] = "SELPHY: Ah?\\nSerá que a gente se conhece?\\pMas isso não importa.\\pEstou superentediada.\\nPor favor, ouça meu pedido.",
  ["g3:081a4315"] = "Quero ver um POKéMON.\\nUm adorável {STR_VAR_1}.\\pQuero ver um agora mesmo.\\nPor favor, realize meu desejo.",
  ["g3:081a437a"] = "SELPHY: Ah, me cansei disso.\\nCansei de esperar por você.\\pVou te perdoar desta vez, mas por\\nfavor, não me decepcione de novo.",
  ["g3:081a43f7"] = "SELPHY: Ah, olá!\\pOh, meu Deus. Esse deve ser o\\n{STR_VAR_1} que você capturou\\ppra mim.\\pHihihi...\\nParece um pouco com você.\\pMuito obrigada.\\p... ...  ... ...  ... ...\\nTem algum problema?\\pVocê já pode ir.\\p... ...  ... ...  ... ...\\nAh, tudo bem. Agora entendi.\\pSEBASTIAN!\\nPreciso de você aqui imediatamente!",
  ["g3:081a450b"] = "Mordomo: Sim, minha senhora.",
  ["g3:081a4521"] = "SELPHY: Garanta que essa pessoa\\nreceba um presente em agradecimento.",
  ["g3:081a4566"] = "Mordomo: Farei como desejar,\\nminha senhora.",
  ["g3:081a458e"] = "Mordomo: Agradeço sinceramente\\npor agradar a senhorita SELPHY.\\pPor favor, aceite isto como forma\\nde agradecimento dela...",
  ["g3:081a45e8"] = "Mordomo: Sua MOCHILA parece\\nestar cheia, infelizmente.",
  ["g3:081a461b"] = "Ah...\\nQue decepção.",
  ["g3:081a4632"] = "SELPHY: Desejo a você boa sorte.",
  ["g3:081a4657"] = "Mordomo: O sorriso da senhorita\\nSELPHY tem o brilho do sol.\\pPor favor, eu lhe peço, traga\\nalegria para a senhorita SELPHY.",
  ["g3:081a46c6"] = "Eu aperfeiçoei o movimento\\ndefinitivo desse tipo...\\pMas e agora?\\nPara quem devo ensiná-lo?\\p... Hm? Hmmm!\\pE-esse {STR_VAR_1}...",
  ["g3:081a4737"] = "... Não...\\nEu me enganei.",
  ["g3:081a4751"] = "Ah! É ele!\\nEste é o POKéMON!\\pEste {STR_VAR_1} é digno de aprender\\no meu movimento definitivo.\\pVocê está de acordo?\\pQuer que seu {STR_VAR_1} aprenda\\n{STR_VAR_2}?",
  ["g3:081a47e5"] = "Gaah! Vai recusar?\\nNão, não vou desistir disso!",
  ["g3:081a4814"] = "Você vai deixar?\\pEntao, deixa eu ensinar o meu\\nmovimento {STR_VAR_2}\\pao seu {STR_VAR_1}.\\pGgggrah-awooo!",
  ["g3:081a4865"] = "Oof... oof... oof...\\pNão achei que conseguiria ensinar\\nesse movimento antes de morrer...",
  ["g3:081a48b3"] = "Eu te imploro: faça bom uso desse\\nmovimento e fique ainda mais forte!",
  ["g3:081a48f3"] = "Oof... oof... oof...\\pNão tenho mais arrependimentos.\\nPassei adiante tudo o que eu sabia.\\pPosso viver o resto da minha vida\\nem paz, sabendo que meu trabalho\\pestá completo.",
  ["g3:081a4972"] = "Depois que passei meu conhecimento\\npara você, senti um alívio enorme.\\pNa verdade, me sinto rejuvenescida,\\ncomo se fosse jovem outra vez!",
  ["g3:081a49e9"] = "Hera, hera, HERACROSS! Grande e\\nimponente, é o chefão mais feroz!\\pAdoro, preciso, HERACROSS!",
  ["g3:081a4a3f"] = "Aaaaah!\\nÉ um HERACROSS!\\pPor favor, por favor, posso medir\\no tamanho dele?",
  ["g3:081a4a88"] = "Aaaaah, {STR_VAR_2} centímetros!\\nNunca vi nada assim!\\pVocê merece uma recompensa!",
  ["g3:081a4ad9"] = "Quero ver um HERACROSS muito,\\nmuito maior do que aquele.\\pAh, como eu adoro HERACROSS\\ngrandes!",
  ["g3:081a4b39"] = "Ha? {STR_VAR_2} centímetros...\\nAh, poxa! É igual ao de antes.",
  ["g3:081a4b7a"] = "Ah, esse só tem {STR_VAR_2} polegadas.\\nO HERACROSS de antes era maior.\\pTinha {STR_VAR_3} polegadas, o maior\\nHERACROSS que cê já me trouxe.",
  ["g3:081a4bef"] = "Ah, não! Assim não dá!\\pHERACROSS parece muito mais macho e\\nestiloso, e ainda tem um chifre lindo!",
  ["g3:081a4c47"] = "Sua MOCHILA está cheia.\\nMinha recompensa não vai caber.",
  ["g3:081a4c6e"] = "O maior HERACROSS que eu já medi até agora tem:\\p{STR_VAR_3} polegadas!",
  ["g3:081a4cb9"] = "É algum tipo de quadro em branco.\\pTem espaços para anotar certos\\ntipos de registros.",
  ["g3:081a4d0d"] = "Tenho exatamente 1,70 de altura.\\pSei disso com precisão porque\\nminha vizinha me mediu.",
  ["g3:081a4d72"] = "Dance, dance!\\nDance, CHANSEY!\\pJunte-se a nós também!\\nDance, dance!",
  ["g3:081a4daf"] = "Você quer dançar?",
  ["g3:081a4dc8"] = "Vamos lá, dance!",
  ["g3:081a4dd8"] = "{PLAYER} dançou a Dança de CHANSEY!",
  ["g3:081a4df5"] = "Ahahahaha!\\pPronto, agora você está com tudo!\\nQue sorte!",
  ["g3:081a4e26"] = "CHANSEY: Chansi! Chansi!",
  ["g3:081a5075"] = "{PLAYER} ligou o PC.",
  ["g3:081a508a"] = "Qual PC deve ser acessado?",
  ["g3:081a50a7"] = "Acessou o PC de Alguém.",
  ["g3:081a50be"] = "O Sistema de Armazenamento\\nPOKéMON foi aberto.",
  ["g3:081a50dd"] = "Acessou o PC de {PLAYER}.",
  ["g3:081a50ef"] = "Acessou o PC do BILL.",
  ["g3:081a5190"] = "Volte sempre!",
  ["g3:081a51f6"] = "Obteve {STR_VAR_2}!",
  ["g3:081a5207"] = "A MOCHILA está cheia...",
  ["g3:081a5218"] = "{PLAYER} colocou {STR_VAR_2}\\nna {STR_VAR_3}.",
  ["g3:081a5231"] = "{PLAYER} encontrou {STR_VAR_2}!",
  ["g3:081a5242"] = "Que pena!\\nA MOCHILA está cheia...",
  ["g3:081a52f0"] = "Obteve {STR_VAR_2}!",
  ["g3:081a532f"] = "{STR_VAR_2} foi transferido\\npara o PC.",
  ["g3:081a535c"] = "Qual andar deseja ir?",
  ["g3:081a5420"] = "{PLAYER} ligou o PC.",
  ["g3:081a5483"] = "Boas-vindas ao nosso CENTRO POKéMON!\\pGostaria que eu curasse seus POKéMON até estarem totalmente recuperados?",
  ["g3:081a54e1"] = "Certo, cuidarei dos seus POKéMON por alguns segundos.",
  ["g3:081a5511"] = "Esperamos te ver novamente!",
  ["g3:081a552b"] = "Obrigada por esperar. Recuperamos a saúde total dos seus POKéMON.",
  ["g3:081a561a"] = "Sinto muito mesmo.\\nO CLUBE WIRELESS POKéMON\\pestá passando por ajustes no momento.",
  ["g3:081a5667"] = "Parece estar passando por ajustes...",
  ["g3:081a56a7"] = "Deseja dar um apelido para este {STR_VAR_1}?",
  ["g3:081a572a"] = "Só os TREINADORES muito habilidosos\\ntêm permissão para passar.\\pVocê ainda não tem a\\n{STR_VAR_1}!",
  ["g3:081a5776"] = "Regras são regras.\\nNão posso deixar você passar.",
  ["g3:081a579d"] = "Ah! Essa é a {STR_VAR_1}!\\nPode passar.",
  ["g3:081a57c1"] = "Você só pode passar por aqui se\\ntiver a {STR_VAR_1}.\\pVocê ainda não tem a\\n{STR_VAR_1}.\\pÉ preciso tê-la para chegar\\nà LIGA POKéMON.",
  ["g3:081a5839"] = "Você só pode passar por aqui se\\ntiver a {STR_VAR_1}.\\pAh! Essa é a {STR_VAR_1}!\\pCerto, então.\\nPor favor, pode passar.\\n",
  ["g3:081a58a7"] = "Vejamos...\\nOps! Você só capturou\\p{STR_VAR_3} tipos de POKéMON!\\pVocê precisa de {STR_VAR_1} tipos\\nse quiser ganhar {STR_VAR_2}.",
  ["g3:081a5909"] = "... Ah, entendi.\\pQuando você tiver {STR_VAR_1} tipos de\\nPOKéMON, volte para pegar\\po item {STR_VAR_2}.",
  ["g3:081a594d"] = "Ah! Vejo que você não tem espaço\\npara o item {STR_VAR_2}.",
  ["g3:081a597b"] = "Estou procurando o POKéMON\\n{STR_VAR_1}!\\pQuer trocar um pelo meu\\n{STR_VAR_2}?",
  ["g3:081a59b6"] = "Aaah!\\nTudo bem...",
  ["g3:081a59c6"] = "O quê?\\nIsso não é um {STR_VAR_1}!",
  ["g3:081a59da"] = "Puxa, valeu!",
  ["g3:081a59e7"] = "Meu velho {STR_VAR_2} não é\\ndemais?",
  ["g3:081a59fe"] = "Olá! Você por acaso tem um\\n{STR_VAR_1}?\\pAceita trocar pelo meu\\n{STR_VAR_2}?",
  ["g3:081a5a4e"] = "Bem, se você não quer...",
  ["g3:081a5a6a"] = "Hmmm?\\nIsso não é um {STR_VAR_1}.\\pLembre-se de mim se conseguir um.",
  ["g3:081a5a9d"] = "Valeu!",
  ["g3:081a5aa5"] = "O {STR_VAR_2} que eu troquei com\\nvocê ficou mais forte?",
  ["g3:081a5ad6"] = "Oi!\\nVocê tem um {STR_VAR_1}?\\pQuer trocar pelo meu\\n{STR_VAR_2}?",
  ["g3:081a5b08"] = "Que pena.",
  ["g3:081a5b18"] = "... Isso não é um {STR_VAR_1}.\\pSe conseguir um, troque comigo.",
  ["g3:081a5b4a"] = "Valeu, você é demais!",
  ["g3:081a5b60"] = "Como está o meu velho {STR_VAR_2}?\\nO meu {STR_VAR_1} vai muito bem!",
  ["g3:081a5b88"] = "Bingo!\\nO CARTÃO-CHAVE abriu a porta!",
  ["g3:081a5bad"] = "Não!\\nPrecisa de um CARTÃO-CHAVE!",
  ["g3:081a5bc6"] = "Acessou o PC do PROF. CARVALHO...\\pAcessou o Sistema de Avaliçao da POKéDEX...",
  ["g3:081a5c03"] = "Gostaria de ter sua POKéDEX avaliada?",
  ["g3:081a5c2e"] = "Desconectou do PC do PROF. CARVALHO.",
  ["g3:081a5cdf"] = "A porta está aberta...",
  ["g3:081a5cf1"] = "{STR_VAR_2} foi transferido para o PC de alguém.\\pFoi colocado na \\nCAIXA “{STR_VAR_1}.”",
  ["g3:081a5d31"] = "{STR_VAR_2} foi transferido para o PC do BILL.\\pFoi colocado na \\nCAIXA “{STR_VAR_1}.”",
  ["g3:081a5d6e"] = "A CAIXA “{STR_VAR_3}” no PC de alguém, estava cheia.\\p{STR_VAR_2} foi transferido para a\\nCAIXA “{STR_VAR_1}.”",
  ["g3:081a5db1"] = "A CAIXA “{STR_VAR_3}” no PC do BILL estava cheia.\\p{STR_VAR_2} foi transferido para a\\nCAIXA “{STR_VAR_1}.”",
  ["g3:081a5df1"] = "{PLAYER} obteve\\n{STR_VAR_1}!",
  ["g3:081a5e31"] = "Não há mais espaço para POKéMON!\\pAs CAIXAS de POKéMON estão cheias\\ne não podem receber mais nenhum!",
  ["g3:081a5e89"] = "Primeiro, é melhor curar totalmente\\nseus POKéMON.",
  ["g3:081a5ec0"] = "Seus POKéMON foram curados e\\nestao em ótima forma.\\pSe a energia dos seus POKéMON, (PS),\\nestiver baixa, venha nos procurar.\\pSe você pretende ir longe em sua\\njornada, é bom comprar algumas\\pPOÇOES na LOJA POKéMON.\\pBoa sorte!",
  ["g3:081a5f9b"] = "Seus POKéMON foram curados e\\nestao em ótima forma.\\pBoa sorte!",
  ["g3:081a5fdf"] = "MÃE: {PLAYER}!\\nBoas-vindas de volta.\\pParece que você passou por\\npoucas e boas.\\pTalvez seja melhor dar uma\\ndescansada.",
  ["g3:081a6046"] = "MÃE: Ah, que bom! Você e seus\\nPOKéMON estão com ótima aparência.\\pAcabei de receber notícias do\\nPROFESSOR CARVALHO.\\pEle disse que a energia dos\\nPOKéMON é medida em PS.\\pSe seus POKéMON perderem PS,\\nvocê pode curá-los em qualquer\\pCENTRO POKéMON.\\pSe for viajar para longe, \\nTREINADORES espertos se preparam\\pcomprando POÇOES na LOJA POKéMON.\\pDeixe a mamãe orgulhosa,\\namor!\\pSe cuida!",
  ["g3:081a6211"] = "Olá!\\nEm que posso ajudar?",
  ["g3:081a622c"] = "Tem um questionário.\\nVocê gostaria de preenchê-lo?",
  ["g3:081a6265"] = "Obrigado por dedicar um tempo\\npara preencher nosso questionário.\\pSua avaliação será usada como\\nreferência no futuro.",
  ["g3:081a62d3"] = "Ah, olá!\\nVocê conhece essas palavras?\\pIsso quer dizer que você sabe\\nsobre o PRESENTE MISTERIOSO.\\pA partir de agora, você vai começar\\na receber PRESENTES MISTERIOSOS!",
  ["g3:081a6359"] = "Depois de salvar o jogo, você poderá\\nacessar o PRESENTE MISTERIOSO.",
  ["g3:081a6393"] = "Obrigado por acessar o Sistema\\nde PRESENTE MISTERIOSO.",
  ["g3:081a63c4"] = "O {STR_VAR_1} fugiu!",
  ["g3:081a63e8"] = "{PLAYER} achou uma {STR_VAR_2}!\\nNela contém {STR_VAR_1}.",
  ["g3:081a641b"] = "Tudo bem! Todos a bordo da balsa\\nGALOPE MARINHO EXPRESSO {STR_VAR_1}!",
  ["g3:081a6448"] = "Gyaoo!",
  ["g3:081a644f"] = "Este movimento só pode ser aprendido uma vez. Tudo bem?",
  ["g3:081a6c51"] = "CARVALHO: Que bom te ver!\\nComo está indo a sua POKéDEX?\\pAqui, deixa eu dar uma olhada.",
  ["g3:081a6ca3"] = "A quantidade de progresso que fez na sua POKéDEX é:\\p{STR_VAR_1} POKéMON vistos e\\n{STR_VAR_2} POKéMON capturados.\\pAvaliaçao do PROF. CARVALHO:",
  ["g3:081a71aa"] = "E a sua POKéDEX NACIONAL é:\\p{STR_VAR_1} POKéMON vistos e\\n{STR_VAR_2} POKéMON capturados.",
  ["g3:081a71ee"] = "Estou ansioso para ver você\\ncompletar a POKéDEX NACIONAL!",
  ["g3:081a722f"] = "Finalmente...\\pVocê finalmente completou a\\nPOKéDEX!\\pÉ magnífico!\\nDe verdade, esta é uma conquista\\pfantástica!",
  ["g3:081a7291"] = "Rooooooaaarrrr!",
  ["g3:081a72ad"] = "Obrigado, {PLAYER}!\\nDe coração, muito obrigado!\\pVocê tornou meu sonho realidade!",
  ["g3:081a72f2"] = "CARVALHO: Ah, Boas-vindas!\\pDiga-me, como anda a sua POKéDEX?\\pWahaha!\\pNa verdade, eu já sei como ela\\nestá, mas adoro vê-la mesmo assim!\\pVamos ver...",
  ["g3:081b146a"] = "JORNAL POKéMON\\pEdiçao Especial: LÍDER do\\nGINÁSIO de PEWTER, BROCK!\\pBROCK raramente ri, mas dizem que\\nele não consegue parar se começar.",
  ["g3:081b14e8"] = "JORNAL POKéMON\\pEdiçao Especial: LÍDER do\\nGINÁSIO de CERULEAN, MISTY!\\pDizem que MISTY idolatra LORELEI,\\nda ELITE DOS QUATRO.",
  ["g3:081b1558"] = "JORNAL POKéMON\\pEdiçao Especial: LÍDER do\\nGINÁSIO de VERMILION, TEN. SURGE!\\pDizem que o TEN. SURGE foi piloto\\nenquanto vivia nos Estados Unidos.\\pEle usava a eletricidade gerada por\\nPOKéMON para mover seu avião.",
  ["g3:081b161b"] = "JORNAL POKéMON\\pEdiçao Especial: LÍDER do\\nGINÁSIO de CELADON, ERIKA!\\pDizem que, se você espiar o GINÁSIO\\nde CELADON, poderá ver ERIKA\\ptirando um cochilo.",
  ["g3:081b16a8"] = "JORNAL POKéMON\\pEdiçao Especial: LÍDER do\\nGINÁSIO de FUCHSIA, KOGA!\\pDizem que KOGA possui um grande\\nconhecimento sobre medicina.\\pEle até prepara remédios para\\ncurar seus POKéMON.",
  ["g3:081b1753"] = "JORNAL POKéMON\\pEdiçao Especial: LÍDER do\\nGINÁSIO de SAFFRON, SABRINA!\\pDizem que SABRINA consegue se\\ncomunicar com seus POKéMON em\\pbatalha sem falar nada.",
  ["g3:081b17e9"] = "JORNAL POKéMON\\pEdiçao Especial: LÍDER do\\nGINÁSIO de CINNABAR, BLAINE!\\pDizem que BLAINE só tira os seus\\nóculos escuros quando está bolando\\pnovas perguntas para o questionário.",
  ["g3:081b187f"] = "JORNAL POKéMON\\pEdiçao Especial:\\nLORELEI da ELITE DOS QUATRO!\\pConhecida por seu estilo de batalha\\nlógico, calculado e frio, LORELEI\\ptem um segredo surpreendente!",
  ["g3:081b1913"] = "JORNAL POKéMON\\pEdiçao Especial:\\nBRUNO da ELITE DOS QUATRO!\\pParece que BRUNO se juntou à\\nELITE DOS QUATRO por sua ambição\\pde batalhar contra os melhores\\pTREINADORES.",
  ["g3:081b19a8"] = "JORNAL POKéMON\\pEdiçao Especial:\\nAGATHA da ELITE DOS QUATRO!\\pEm sua juventude, AGATHA e o\\nPROFESSOR CARVALHO eram rivais\\pque lutavam pela supremacia como\\pTREINADORES.",
  ["g3:081b1a31"] = "JORNAL POKéMON\\pEdiçao Especial:\\nLANCE da ELITE DOS QUATRO!\\pDizem que o avô de LANCE é o\\nanciao de um famoso clã de\\pmestres de dragoes.",
  ["g3:081b1ab9"] = "JORNAL POKéMON\\pEdiçao Especial: PROFESSOR\\nCARVALHO, o Pesquisador POKéMON!\\pO PROFESSOR CARVALHO vive com\\nseus netos, DAISY e {RIVAL}.",
  ["g3:081b1b3d"] = "Este é um JORNAL POKéMON de\\nanos atrás...\\pJORNAL POKéMON\\nEspecial de CONCURSO!\\pA Grande Campeã do CONCURSO\\nPOKéMON de Primavera é a DAISY\\pCARVALHO da CIDADE DE PALLET!",
  ["g3:081b1bd1"] = "JORNAL POKéMON\\pEdiçao Especial:\\nSR. FUJI da CASA POKéMON!\\pEditor: O tímido SR. FUJI recusou\\nnossos pedidos de entrevista.\\pEle é um homem bondoso, adorado e\\nrespeitado na CIDADE DE LAVENDER.",
  ["g3:081b1c8b"] = "Hmm...\\nÉ isso mesmo...",
  ["g3:081b1c9f"] = "Ah!\\nOlha, olha!",
  ["g3:081b1caf"] = "Lê, lê isso!",
  ["g3:081b1cc1"] = "DICAS PARA TREINADORES\\pAperte START para abrir o MENU!",
  ["g3:081b1cec"] = "Placas são úteis, não são?",
  ["g3:081b1d0b"] = "Olha, olha!\\pEu copiei o que dizia em uma\\ndaquelas placas de DICAS PARA\\pTREINADORES!",
  ["g3:081b1d51"] = "DICAS PARA TREINADORES\\pAperte START para abrir o MENU!",
  ["g3:081b1d7d"] = "É uma IMPRESSORA POKéMON!\\pEla pode imprimir seu POKéMON no\\nverso do seu CARTÃO DE TREINADOR.\\pCusta apenas $50.\\nGostaria de experimentar?",
  ["g3:081b1e07"] = "Você não tem dinheiro suficiente.",
  ["g3:081b1e24"] = "Por favor, escolha o tipo de\\nimpressão.",
  ["g3:081b1e42"] = "Dá um sorrisão para a foto!\\nTrês... Dois... Um...\\pFlash!",
  ["g3:081b1e7d"] = "A impressão do seu POKéMON está\\npronta!\\pConfira seu CARTÃO DE TREINADOR.",
  ["g3:081b1eb3"] = "Hehe...\\nEu juntei um monte de ADESIVOS.\\pQueria poder exibi-los...",
  ["g3:081b1ef8"] = "Ah, excelente!\\nVocê veio ao lugar certo!\\pOlha, olha! Viu? Viu?\\nEsses são meus ADESIVOS!\\pOlha quantos eu tenho!\\pAposto que você quer alguns.\\nTenho certeza que quer!\\pEu te dou um ADESIVO se você me\\ncontar algo incrível sobre você.\\pDo que você vai se gabar?",
  ["g3:081b1fef"] = "Conte algo de que você se orgulha.\\nEu te dou um ADESIVO.",
  ["g3:081b2025"] = "Ah! Você é a pessoa intrometida que\\nestava escutando a nossa conversa!",
  ["g3:081b206e"] = "Ah, uau, você entrou para o\\nHALL DA FAMA.\\pSim, é bem impressionante!\\nVou te dar um desses.",
  ["g3:081b20cf"] = "Ah, uau, você entrou várias\\nvezes no HALL DA FAMA!\\pSim, é muito impressionante!\\nVou te dar um desses.",
  ["g3:081b2133"] = "Uau! Você entrou no HALL DA FAMA\\ntantas vezes assim?\\pSim, é realmente incrível!\\pVocê domina a LIGA POKéMON!\\nVou te dar um desses.",
  ["g3:081b21c4"] = "Não acredito! Você entrou no\\nHALL DA FAMA tantas vezes assim?\\pVocê é simplesmente inacreditável!\\nÉ isso, eu tenho que te dar isto.",
  ["g3:081b2242"] = "O ADESIVO do HALL DA FAMA foi\\ncolado no CARTÃO DE TREINADOR.",
  ["g3:081b227c"] = "Hmm...\\pVolte com uma história melhor da\\npróxima vez, tá?",
  ["g3:081b22b0"] = "Ah, não, não dá mais.\\pVocê é praticamente uma lenda viva.\\nNão tenho mais ADESIVOS para dar.",
  ["g3:081b2308"] = "Ah, uau, existem OVOS de POKéMON?\\nEu não sabia disso!\\pSim, é bem legal!\\nVou te dar um desses.",
  ["g3:081b2372"] = "Você chocou tantos OVOS assim?\\nVocê deve mesmo gostar deles!\\pSim, é impressionante!\\nVou te dar um desses.",
  ["g3:081b23e0"] = "Uau! Você chocou um monte de\\nOVOS!\\pVocê é uma máquina de chocar ovos!\\nVou te dar um desses.",
  ["g3:081b2448"] = "O qu... Você chocou tantos OVOS\\nassim?\\pO que está por trás desse seu amor\\npor OVOS? Sim, é inacreditável!\\pTô dizendo, você é muito incrível.\\nÉ isso, eu tenho que te dar isto.",
  ["g3:081b24ea"] = "O ADESIVO OVO foi colado no\\nCARTÃO DE TREINADOR.",
  ["g3:081b251b"] = "Hmm...\\pVolte com uma história melhor da\\npróxima vez, tá?",
  ["g3:081b254f"] = "Ah, não, não dá mais.\\pVocê é praticamente uma lenda viva.\\nNão tenho mais ADESIVOS para dar.",
  ["g3:081b25a7"] = "Ah, uau, você teve sucesso em\\nbatalhas por link?\\pSim, você é bem forte!\\nVou te dar um desses.",
  ["g3:081b2609"] = "Você derrotou seus amigos muitas\\nvezes em batalhas por link, hein?\\pSim, você é incrivelmente forte!\\nVou te dar um desses.",
  ["g3:081b267b"] = "Uau! Você derrotou seus amigos\\num número assustador de vezes.\\pPerdeu amigos por causa disso?\\nVou te dar um desses.",
  ["g3:081b26f6"] = "O qu... Uau, que absurdo! Você venceu\\ntantas vezes, é de cair o queixo!\\pSó de pensar em como você é\\nforte já me deixa atordoado.\\pVocê dá pesadelos em qualquer um!\\nÉ isso, eu tenho que te dar isto.",
  ["g3:081b27a6"] = "O ADESIVO da VITÓRIA foi colado\\nno CARTÃO DE TREINADOR.",
  ["g3:081b27db"] = "Hmm...\\pVolte com uma história melhor da\\npróxima vez, tá?",
  ["g3:081b280f"] = "Ah, não, não dá mais.\\pVocê é praticamente uma lenda viva.\\nNão tenho mais ADESIVOS para dar.",
  ["g3:081bc311"] = "Boas-vindas ao CLUBE do CABO\\nPOKéMON.\\pQual de nossos serviços deseja\\nutilizar?",
  ["g3:081bc409"] = "Para uma BATALHA DUPLA, você tem\\ndeve ter pelo menos dois POKéMON.",
  ["g3:081bc442"] = "Para trocas, você deve ter pelo\\nmenos dois POKéMON com você.",
  ["g3:081bc47c"] = "Um POKéMON segurando a FRUTA\\n{STR_VAR_1} não pode ser trocado.",
  ["g3:081bc4ac"] = "Por favor, aguarde.\\n... ... Botão B: Cancelar",
  ["g3:081bc590"] = "Por favor, entre.",
  ["g3:081bc59e"] = "Vou levar você à sua sala agora.",
  ["g3:081bc5c0"] = "Alguém não está pronto para a\\nconexao.\\pPor favor, volte quando todos\\ntiverem feito os preparativos.",
  ["g3:081bc615"] = "Desculpe, houve um erro de...\\nconexao...\\pReinicie e tente novamente.",
  ["g3:081bc64e"] = "Os jogadores conectados parecem\\nter feito seleçoes diferentes.",
  ["g3:081bc68a"] = "Por favor, visite-nos novamente.",
  ["g3:081bc6a1"] = "O número de participantes está\\nincorreto.",
  ["g3:081bc6ca"] = "O modo BATALHA INDIVIDUAL não pode\\nser jogado por {STR_VAR_1} jogadores.",
  ["g3:081bc700"] = "O modo BATALHA DUPLA não pode ser\\njogado por {STR_VAR_1} jogadores.",
  ["g3:081bc736"] = "Devem haver quatro jogadores para\\njogar este Modo de Batalha.",
  ["g3:081bc76b"] = "Confirme o número de jogadores\\ne comece novamente.",
  ["g3:081bc7a1"] = "A conexão será encerrada se você\\nsair da sala. Tudo bem?",
  ["g3:081bc7e2"] = "Encerrando conexão…\\nA equipe acompanhará você para fora\\lda sala. Por favor, aguarde.",
  ["g3:081bc827"] = "Este TREINADOR está ocupado\\ndemais para notar...",
  ["g3:081bc84b"] = "Legal! Consegui ver o CARTÃO\\nDE TREINADOR de {STR_VAR_1}!",
  ["g3:081bc874"] = "Legal! Consegui ver o CARTÃO\\nDE TREINADOR de {STR_VAR_1}!\\pÉ um cartão {STR_VAR_2}!",
  ["g3:081bc8ad"] = "Por favor, tome seu lugar e\\ncomece sua batalha.",
  ["g3:081bc8da"] = "Por favor, tome seu lugar e\\ncomece sua troca.",
  ["g3:081bc918"] = "Os dados do CARTÃO DE TREINADOR\\nserão substituídos.",
  ["g3:081bc943"] = "Espero ver você novamente!",
  ["g3:081bc95c"] = "Sinto muitíssimo.\\pAinda não estamos preparados para\\nrealizar trocas com TREINADORES\\pde outras regioes distantes...",
  ["g3:081bc9c0"] = "O outro TREINADOR não está\\npronto.",
  ["g3:081bc9e0"] = "Você tem pelo menos um POKéMON\\nque não pode ser levado.",
  ["g3:081bca13"] = "O Adaptador Sem Fio não está\\nconectado corretamente.",
  ["g3:081bca43"] = "Pedimos aos participantes que se\\naproximem do balcão de recepção.",
  ["g3:081bcb81"] = "Para usar o serviço de ESMAGAR\\nFRUTAS, você deve ter pelo menos\\puma FRUTA.",
  ["g3:081bcbc3"] = "Para entrar na SALA UNIÃO, você\\nvocê deve ter pelo menos dois\\pPOKéMON.",
  ["g3:081bcc00"] = "Nenhum POKéMON segurando a FRUTA\\n{STR_VAR_1} pode entrar na SALA\\pUNIAO.",
  ["g3:081bcc3a"] = "Esta é a SALA UNIÃO do CLUBE\\nSEM FIO POKéMON.\\pInfelizmente, seu Adaptador Sem\\nFio não está conectado de forma\\pcorreta.\\pPor favor, venha novamente.",
  ["g3:081bccca"] = "Parece que {STR_VAR_1} está\\njogando agora.\\pManda ver!",
  ["g3:081bccff"] = "Eu posso explicar as regras dos\\njogos para você, se desejar.\\pQual jogo devo descrever?",
  ["g3:081bcd4d"] = "“SALTO POKéMON\\pFaça seu POKéMON pular a corda de CHICOTE DE VINHA com o Botao A.\\pApenas mini-POKéMON com cerca de 28 polegadas ou menos podem participar.\\pPOKéMON que apenas nadam, cavam ou voam não são bons em pular.\\pComo resultado, esses POKéMON não podem participar.\\pCoisas boas acontecem se todos pulam no tempo certo.",
  ["g3:081bce73"] = "“DODRIO PEGA-FRUTAS”\\pComande as três cabeças do DODRIO para pegar FRUTAS que caem.\\pAperte direita, cima ou esquerda no\\n/&lt;/Ç D-Pad para mover as cabeças.\\pPara jogar, você deve ter um DODRIO.",
  ["g3:081bcf2e"] = "Se você quiser jogar um jogo,\\nfale com o homem ao meu lado.",
  ["g3:081bcf69"] = "Olá, Boas-vindas!\\nVocê pode jogar jogos pelo\\pSistema de Comunicaçao Sem Fio.\\pVocê pode esperar um pouquinho?",
  ["g3:081bcfd1"] = "Tudo bem, volte sempre!",
  ["g3:081bcfe8"] = "O Adaptador Sem Fio não está\\nconectado.\\pVolte quando estiver instalado!",
  ["g3:081bd02d"] = "Tudo bem, qual jogo você gostaria\\nde jogar?",
  ["g3:081bd059"] = "Qual POKéMON você gostaria de\\ninscrever?",
  ["g3:081bd080"] = "Tudo certo, você já pode ir.\\nNão deixe os outros vencerem!",
  ["g3:081bd0cf"] = "Não parece que você tem algum\\nPOKéMON que possa inscrever...\\pGostaria que eu explicasse que\\ntipos de POKéMON podem entrar?",
  ["g3:081bd14b"] = "“SALTO POKéMON” está aberto para POKéMON de cerca de 28 polegadas ou menos.\\pMas não dá pra participar com POKéMON que não conseguem pular.\\pSabe, tipo POKéMON que apenas nadam, cavam ou voam.\\pÉ só o que precisa saber.",
  ["g3:081bd213"] = "“DODRIO PEGA-FRUTAS”...\\nBom, o nome do jogo já diz tudo.\\pPrecisa ter um DODRIO para jogar esse jogo.",
  ["g3:081bd28d"] = "Boas-vindas à SALA DIRETA do\\nCLUBE SEM FIO POKéMON.\\pAqui você pode interagir\\ndiretamente com seus amigos.\\pEm qual sala você gostaria de\\nentrar?",
  ["g3:081bd317"] = "Gostaria de trocar POKéMON?",
  ["g3:081bd338"] = "Qual Modo de Batalha você\\ngostaria de jogar?",
  ["g3:081bd362"] = "Gostaria de usar o Sistema\\nESMAGA-FRUTAS?",
  ["g3:081bd390"] = "Existem três Modos de Batalha.\\pBATALHA INDIVIDUAL é para dois\\nTREINADORES com um ou mais\\pPOKéMON cada.\\pCada TREINADOR pode ter um\\nPOKéMON em batalha por vez.\\pBATALHA DUPLA é para dois\\nTREINADORES com dois ou mais\\pPOKéMON cada.\\pCada TREINADOR enviará dois\\nPOKéMON para a batalha por vez.\\pBATALHA MÚLTIPLA é para quatro\\nTREINADORES com um ou mais\\pPOKéMON cada.\\pCada TREINADOR pode ter um\\nPOKéMON em batalha por vez.",
  ["g3:081bd51b"] = "Por favor, decidam qual de vocês\\ndois se tornará o LÍDER.\\pO outro jogador deve então\\nescolher “UNIR-SE AO GRUPO”.",
  ["g3:081bd582"] = "Por favor, decidam qual de vocês quatro se tornará o LÍDER DO GRUPO.\\pOs outros jogadores devem, então, escolher a opção “ENTRAR NO GRUPO.”",
  ["g3:081bd5f1"] = "Por favor, decidam qual de vocês se tornará o LÍDER DO GRUPO.\\pOs outros jogadores devem, então, escolher a opção “ENTRAR NO GRUPO.”",
  ["g3:081bd65b"] = "Esta é a SALA UNIÃO do\\nCLUBE SEM FIO POKéMON.\\pVocê pode interagir diretamente\\ncom outros TREINADORES, até mesmo\\ncom alguns que talvez não conheça.\\pGostaria de entrar na SALA?",
  ["g3:081bd706"] = "Os TREINADORES na SALA UNIÃO\\nserao os jogadores ao seu redor\\pque também entraram na SALA.\\pVocê pode fazer todo tipo de\\ncoisa aqui, como saudaçoes.\\pPode inscrever dois POKéMON até\\no Nv. 30 para uma batalha 1x1.\\pPode participar de uma conversa\\ncom duas a cinco pessoas.\\pOu, pode registrar um POKéMON\\npara troca.\\pGostaria de entrar na SALA?",
  ["g3:081bd86a"] = "Espero que aproveite seu tempo\\nna SALA UNIÃO.",
  ["g3:081bd898"] = "Olá!\\nMeu nome é TEALA.\\pEsta deve ser sua primeira vez\\naqui em cima.\\pVou mostrar como o Sistema de\\nComunicaçao Sem Fio funciona.\\pPrimeiro, preciso lhe mostrar este\\nandar do nosso CENTRO POKéMON.\\pPor aqui, por favor.",
  ["g3:081bd966"] = "No andar superior, existem duas\\nsalas.\\pPrimeiro, a sala à esquerda.\\nÉ a SALA UNIÃO.\\pVocê pode se conectar com\\nTREINADORES ao seu redor que\\ptambém entraram nela.\\pCom eles, você pode conversar,\\nbatalhar e trocar.\\pSegundo, a sala à direita é a\\nSALA DIRETA.\\pVocê pode trocar ou batalhar\\ncom seus amigos nesta sala.\\pSe o Adaptador Sem Fio não estiver\\nconectado, você ainda pode se\\pconectar usando um cabo Link.\\pNesse caso, você deve ir à\\nSALA DIRETA.\\pEspero que goste do Sistema de\\nComunicaçao Sem Fio.",
  ["g3:081bdb85"] = "Olá, {PLAYER}!\\pSou eu, TEALA, a atendente do\\nP2 do CENTRO POKéMON.\\pTinha algo que você precisava me\\nperguntar sobre a conexão?",
  ["g3:081bdbf8"] = "Deixe-me explicar como o CLUBE\\nSEM FIO POKéMON funciona.\\pNeste andar superior, existem\\nduas salas.\\pPrimeiro, a sala à esquerda.\\nÉ a SALA UNIÃO.\\pVocê pode se conectar com\\nTREINADORES ao seu redor que\\ptambém entraram nela.\\pCom eles, você pode conversar,\\nbatalhar e trocar.\\pSegundo, a sala à direita é a\\nSALA DIRETA.\\pVocê pode trocar ou batalhar\\ncom seus amigos nesta sala.\\pÀs vezes, você pode não encontrar\\nseus amigos na SALA UNIÃO ou na\\pSALA DIRETA.\\pNesse caso, por favor, aproxime-se\\nmais dos seus amigos.\\pSe o Adaptador Sem Fio não estiver\\nconectado, você ainda pode se\\pconectar usando um cabo Link.\\pNesse caso, você deve ir à\\nSALA DIRETA.\\pEspero que goste do Sistema de\\nComunicaçao Sem Fio.",
  ["g3:081bdedf"] = "Espero que goste do Sistema de\\nComunicação Sem Fio.",
  ["g3:081bdf94"] = "Parece que dá para CORTAR\\nesta árvore!\\pGostaria de usar CORTAR?",
  ["g3:081bdfd7"] = "{STR_VAR_1} usou {STR_VAR_2}!",
  ["g3:081bdfe3"] = "Parece que dá para CORTAR\\nesta árvore!",
  ["g3:081be09d"] = "Esta pedra pode ser quebrada.\\nGostaria de usar ESMAGA-PEDRAS?",
  ["g3:081be0e2"] = "É uma pedra dura, mas um POKéMON\\npode ser capaz de esmagá-la.",
  ["g3:081be19a"] = "É uma grande rocha, mas um POKéMON\\npode ser capaz de empurrá-la.\\pGostaria de usar SUPERFORÇA?",
  ["g3:081be1fa"] = "{STR_VAR_1} usou SUPERFORÇA!\\pA SUPERFORÇA de {STR_VAR_1} tornou\\npossível mover rochas em volta!",
  ["g3:081be244"] = "É uma grande rocha, mas um POKéMON\\npode ser capaz de empurrá-la.",
  ["g3:081be284"] = "SUPERFORÇA tornou possível mover\\nrochas em volta.",
  ["g3:081bef88"] = "Oi, prazer em te conhecer!\\p...Não foi legal da sua parte. Que tal cumprimentar de volta?\\pEntao, vamos lá, fale-me sobre você.\\pAdoraria ouvir o seu perfil!",
  ["g3:081bf017"] = "Diga-me algo bom sobre você.\\nQual é o seu perfil?",
  ["g3:081bf053"] = "Um perfil é escrito usando quatro palavras ou frases.\\pHá várias palavras que pode escolher para o seu perfil.\\pAs palavras e frases são colocadas em vários grupos convenientes.\\pPrimeiro, escolha um grupo, e então escolha uma palavra ou frase.\\p...É mais fácil do que parece.\\nPor que não experimenta?",
  ["g3:081bf166"] = "Qual é o seu perfil?",
  ["g3:081bf17b"] = "Ahh... Não seja assim. Pode me dizer o seu perfil.",
  ["g3:081bf1b2"] = "Ah, decidiu não dizer?\\nCê é meio piegas, não acha?",
  ["g3:081bf1e8"] = "Oi!\\nNos encontramos de novo!",
  ["g3:081bf1fb"] = "Gostaria de mudar o seu perfil?",
  ["g3:081bf222"] = "O que você gosta agora?\\nEu quero muito saber.",
  ["g3:081bf252"] = "Certo, gosta do seu perfil do jeito que está..\\pEu também acho.",
  ["g3:081bf28e"] = "Hmhm...\\pSeu perfil realmente fala muito sobre quem você é.\\pAgora que te conheço melhor, isso nos torna amigos mais próximos do que nunca!",
  ["g3:081bf30d"] = "Ah, já ouvi isso antes...\\pMeu primo, que mora longe, sempre dizia isso, eu acho.",
  ["g3:081bf36a"] = "Por favor, me conta mais sobre você da próxima vez!",
  ["g3:081bf555"] = "Sou o HOMEM da CRECHE.\\pEu ajudo a cuidar dos preciosos\\nPOKéMON dos TREINADORES.\\pSe você quiser que eu treine seu\\nPOKéMON, fale com a minha esposa.",
  ["g3:081bf5e3"] = "Ah, é você!\\pEstávamos cuidando do seu POKéMON\\ne, nossa, que surpresa tivemos!\\pO seu POKéMON estava com um OVO!\\pNão sabemos como isso aconteceu,\\nmas o seu POKéMON estava com ele.\\pVocê quer ficar com ele, não quer?",
  ["g3:081bf69a"] = "Ah, é você! Que bom te ver.\\nSeu {STR_VAR_1} vai muito bem.",
  ["g3:081bf6cf"] = "Então está bem, vou ficar com ele.\\nObrigado!",
  ["g3:081bf6f0"] = "Você não tem espaço para ele...\\nVolte quando tiver aberto espaço.",
  ["g3:081bf72a"] = "{PLAYER} recebeu o OVO do\\nHOMEM da CRECHE.",
  ["g3:081bf755"] = "Cuide bem dele.",
  ["g3:081bf789"] = "Ah, é você! Seu {STR_VAR_1} e seu\\n{STR_VAR_2} vão muito bem.",
  ["g3:081bf7b6"] = "Vou mesmo ficar com ele.\\nVocê quer isto, não quer?",
  ["g3:081bf7e4"] = "Sou a SENHORA da CRECHE.\\pNós podemos cuidar dos seus\\nPOKéMON para você.\\pGostaria que criássemos um para\\nvocê?",
  ["g3:081bf839"] = "Qual POKéMON devemos criar para\\nvocê?",
  ["g3:081bf860"] = "Certo, vamos cuidar do seu\\n{STR_VAR_1} por um tempo.\\pVolte depois para buscá-lo.",
  ["g3:081bf89f"] = "Podemos cuidar de dois dos seus\\nPOKéMON.\\pGostaria que criássemos mais\\num POKéMON para você?",
  ["g3:081bf8f6"] = "Meu marido estava procurando\\npor você.",
  ["g3:081bf916"] = "Ah, tudo bem, então.\\nVolte sempre.",
  ["g3:081bf932"] = "Você não tem dinheiro suficiente...",
  ["g3:081bf94f"] = "Você vai levar o outro também?",
  ["g3:081bf976"] = "Certo.\\nVolte sempre.",
  ["g3:081bf988"] = "Ah, é você!\\nQue bom te ver.\\pSeus POKéMON vão bem!",
  ["g3:081bf9cc"] = "Em níveis, seu {STR_VAR_1}\\ncresceu {STR_VAR_2}.",
  ["g3:081bf9ef"] = "Sua equipe de POKéMON está cheia.\\nAbra espaço e depois venha me ver.",
  ["g3:081bfa3b"] = "Se quiser seu {STR_VAR_1} de volta,\\nvai custar ${STR_VAR_2}.",
  ["g3:081bfa67"] = "Perfeito!\\nAqui está o seu POKéMON.",
  ["g3:081bfa85"] = "{PLAYER} recebeu {STR_VAR_1} de\\nvolta da SENHORA da CRECHE.",
  ["g3:081bfaad"] = "Ah? Mas você só tem um POKéMON.\\pVolte outra hora.",
  ["g3:081bfae8"] = "Você vai pegar seu POKéMON de\\nvolta?",
  ["g3:081bfb09"] = "Se você deixar esse POKéMON comigo,\\nvai batalhar com o quê?\\pVolte outra hora.",
  ["g3:081bfeac"] = "Com licença!\\nSua CAIXA do PC está cheia.",
  ["g3:081c0db0"] = "Está repleto de livros sobre\\nPOKéMON.",
  ["g3:081c0df1"] = "Um MAPA DA REGIÃO.",
  ["g3:081c0dfd"] = "Uau!\\nTem um monte de coisas de POKéMON!",
  ["g3:081c0e19"] = "Pratos e louças estão bem\\norganizados em fila.",
  ["g3:081c0e40"] = "Está com um cheiro delicioso!\\nAlguém andou cozinhando por aqui.",
  ["g3:081c0e73"] = "É uma cômoda bem feita.\\nDá para guardar muita coisa nela.",
  ["g3:081c0eac"] = "Tem uma pilha de lanches aqui.",
  ["g3:081c0ecb"] = "Todos os itens em um só lugar!\\nLOJA POKéMON",
  ["g3:081c0ef7"] = "Cure os seus POKéMON!\\nCENTRO POKéMON",
  ["g3:081c0f19"] = "PLANALTO ÍNDIGO\\pO objetivo final dos TREINADORES!\\nSEDE da LIGA POKéMON",
  ["g3:081c0f59"] = "PLANALTO ÍNDIGO\\pA maior autoridade em POKéMON!\\nSEDE da LIGA POKéMON",
  ["g3:081c0f99"] = "Deve estar cheio de todo tipo\\nde coisa deliciosa para comer.",
  ["g3:081c0fd8"] = "É uma espécie de planta.\\nEstá cheia de diagramas e texto.",
  ["g3:081c101b"] = "É uma bela imagem de um POKéMON.\\nParece que ele está feliz.",
  ["g3:081c1060"] = "Que máquina será essa?\\nMelhor não mexer nela!",
  ["g3:081c109c"] = "É um telefone.\\nMelhor não usar.",
  ["g3:081c10c1"] = "São só palavras complicadas e\\nnúmeros que não fazem sentido...",
  ["g3:081c10fc"] = "É um pôster publicitário sobre\\ntodo tipo de produto.",
  ["g3:081c1134"] = "Ah, que cheiro gostoso!\\nDá até um ronco no estômago!",
  ["g3:081c116e"] = "Dentro disso...\\n......\\pNão tem nada!",
  ["g3:081c1194"] = "É um copo com o símbolo de um\\nPOKéMON.",
  ["g3:081c11ba"] = "A janela está muito bem polida.",
  ["g3:081c11dc"] = "Do lado de fora da janela...\\pO céu parece incrivelmente\\nbonito.",
  ["g3:081c1217"] = "Luzes de cores diferentes estão\\npiscando sem parar.",
  ["g3:081c124b"] = "Todo tipo de ferramenta está\\norganizado em ordem.",
  ["g3:081c1273"] = "É algum tipo de máquina.\\nCom certeza é impressionante.",
  ["g3:081c12a7"] = "É o videogame mais recente!\\nParece bem divertido!",
  ["g3:081c12d6"] = "Há sinais claros de arrombamento\\naqui...",
  ["g3:081c1300"] = "Tem um POKéMON na TV!\\nParece que ele está se divertindo.",
  ["g3:081c147a"] = "Ei!\\nEu te vi na FLORESTA DE VIRIDIAN!",
  ["g3:081c149d"] = "Oi! Eu gosto de shorts!\\nSão confortáveis e fáceis de usar!\\pVocê também devia estar usando\\nshorts!",
  ["g3:081c14f3"] = "Com licença!\\nVocê continua olhando pra mim, né?",
  ["g3:081c1521"] = "Você é TREINADOR, não é?\\nEntão vamos nessa agora mesmo!",
  ["g3:081c155d"] = "O jeito que você me olhou...\\nMe deixa tão intrigada!",
  ["g3:081c1588"] = "Ei! Qual é o seu problema?\\nVocê ainda não tá usando shorts!",
  ["g3:081c15c5"] = "Vou batalhar usando os POKéMON \\nque comecei a criar.",
  ["g3:081c15f9"] = "Ai!\\nFoi você que me empurrou?",
  ["g3:081c160f"] = "Sempre capturo POKéMON cogumelo\\nno MONTE LUA.",
  ["g3:081c163c"] = "Ah! Então é você, jovem xereta que\\nestava escutando a nossa conversa!",
  ["g3:081c166d"] = "Com licença! Eu não disse que\\nisso é uma conversa particular?\\pVocê não devia estar escutando,\\nô sem educação!",
  ["g3:081c16e2"] = "Tô tentando encontrar algo bom que\\nnão seja um POKéMON INSETO, mas...",
  ["g3:081c1723"] = "Hã?\\nVocê quer batalhar comigo de novo?",
  ["g3:081c1746"] = "Eu?\\nTá bom. Vou batalhar só dessa vez.",
  ["g3:081c176b"] = "Ei, quanto tempo!\\nVocê ficou mais forte?",
  ["g3:081c1793"] = "Você é hábil em POKéMON, mas e a\\nsua nota em química, como vai?",
  ["g3:081c17cd"] = "Tudo bem!\\nVamos jogar outra partida!",
  ["g3:081c17f1"] = "Você precisa de estratégia para\\nvencer batalhas.\\pTá seguindo o meu conselho?",
  ["g3:081c1834"] = "Eu colecionei vários NIDORAN.\\nNão quero que eles evoluam, mas...",
  ["g3:081c1873"] = "A escola é divertida, mas eu ainda\\nacho que POKéMON também são.",
  ["g3:081c18aa"] = "MEOWTH e PERSIAN são tão fofinhos,\\nmiau, miau, miau!",
  ["g3:081c18dc"] = "A gente pode até parecer bobo\\nparado aqui assim, mas eu ainda\\pposso batalhar.",
  ["g3:081c191f"] = "Sou um cara que vive falando e\\njogando! Tô numa maré de vitórias!",
  ["g3:081c1955"] = "Qual é o POKéMON fofo, redondo\\ne macio?\\pVocê já sabe, não sabe?",
  ["g3:081c199c"] = "Minha moto ainda tá com problema,\\ncara.",
  ["g3:081c19bc"] = "Tá bom, jovem!\\nNão espere misericórdia desta vez!",
  ["g3:081c19e5"] = "ELI: Nosso poder de gêmeas ficou\\nainda melhor!",
  ["g3:081c1a0d"] = "ANNE: Nosso poder de gêmeas\\naumentou ainda mais!",
  ["g3:081c1a2e"] = "Vamos batalhar de novo?\\nDesta vez, eu te pego!",
  ["g3:081c1a5d"] = "Não esqueci que você estava com\\naqueles POKéMON bonitoes.",
  ["g3:081c1a9b"] = "Vou passar pelo TÚNEL DE ROCHA\\npara chegar a LAVENDER...\\pMas todo mundo fica me parando\\npelo caminho...",
  ["g3:081c1afb"] = "Nem pensa em me subestimar hoje!\\nAgora é pra valer!",
  ["g3:081c1b37"] = "Bwahaha!\\nÓtimo! Eu tava entediado de novo!",
  ["g3:081c1b5e"] = "Hahaha!\\nForte como sempre!",
  ["g3:081c1b83"] = "Eu acordava cedo todo dia pra\\ntreinar meus POKéMON desde os\\pcasulos!",
  ["g3:081c1bbe"] = "Hahahaha!\\nDesta vez eu vou vencer!",
  ["g3:081c1bdc"] = "Vão lá e vençam, meus super\\nPOKéMON INSETO!",
  ["g3:081c1bfa"] = "Uau, você veio aqui de novo? Será\\nque você também é POKéMANÍACO?\\pQuer ver minha coleção?",
  ["g3:081c1c4f"] = "Ha-hahaha-ha-ha!\\nNão consigo parar de espirrar!",
  ["g3:081c1c76"] = "Oi, criança!\\nEu te mostrei meus POKéMON?",
  ["g3:081c1c9a"] = "Eu fui a um GINÁSIO POKéMON de\\nnovo.\\p... Mas perdi, como sempre.",
  ["g3:081c1cd3"] = "Ah!\\nO ar desta montanha é delicioso!\\pÉ tão bom que não consigo ir embora!",
  ["g3:081c1d14"] = "Minha cabeça tá começando a girar.\\nTô caminhando há tempo demais...",
  ["g3:081c1d50"] = "Vencendo, perdendo ou empatando!\\nAgora vamos para a revanche!",
  ["g3:081c1d79"] = "Competir é a emoção suprema.\\nEu ainda não me canso disso!",
  ["g3:081c1db5"] = "Você sabe, né?\\nVamos lá, mas nada de trapacear!",
  ["g3:081c1de1"] = "Oi!\\pMas cuidado!\\nAinda estou passando alguns cabos!",
  ["g3:081c1e1f"] = "Me tornei TREINADOR há algum tempo.\\nMas acho que consigo vencer.",
  ["g3:081c1e57"] = "Fwahaha!\\nEu nunca perdi!\\p... E se perdi, já até esqueci!",
  ["g3:081c1e9f"] = "Eu nunca venci antes...\\pTalvez eu esteja destinado a\\ncontinuar assim...",
  ["g3:081c1ee2"] = "Sou o melhor da minha turma!\\nTreino toda manhã e toda noite!",
  ["g3:081c1f1d"] = "Fica de olho nos fios energizados!",
  ["g3:081c1f40"] = "Criei meus POKéMON com cuidado.\\nEles devem estar prontos agora!\\pDesta vez, eles vão vencer.",
  ["g3:081c1f9d"] = "É isso aí!\\nFisguei alguma coisa aqui!\\pE-essa pode ser uma grande captura!",
  ["g3:081c1fd8"] = "Você finalmente chegou.\\nPescar é um jogo de paciência.",
  ["g3:081c2008"] = "Ainda não consegui encontrar uma\\nPEDRA DA LUA...\\pVocê encontrou alguma?",
  ["g3:081c203b"] = "Eletricidade sempre foi minha\\nespecialidade.\\pMas eu não entendo nada de\\nPOKéMON do mar.",
  ["g3:081c209c"] = "O MANÍACO POR PESCA contra \\nTREINADOR POKéMON!\\pMais uma rodada, lutem!",
  ["g3:081c20d4"] = "Eu amo pescar, não me entenda mal.\\nMas eu queria ter mais trabalho...\\p... É difícil largar a pesca!",
  ["g3:081c2134"] = "Qual é a boa?\\pVocê nunca vai descobrir a menos\\nque me vença!",
  ["g3:081c216b"] = "JES: Hoje vou vencer e pedir minha\\nGIA em casamento.",
  ["g3:081c219b"] = "GIA: Ei, JES...\\nJá tô esperando há muito tempo.\\pSe a gente vencer hoje, eu me caso\\ncom você!",
  ["g3:081c21ee"] = "Meus POKéMON pássaro se lembram\\nde você!",
  ["g3:081c220c"] = "Quero ser a melhor TREINADORA\\nenquanto ainda sou criança!",
  ["g3:081c223c"] = "Uau!\\pVocê conseguiu mais INSÍGNIAS\\nlegais!",
  ["g3:081c225b"] = "Meus POKéMON fofos e crescidos\\nquerem reencontrar você.",
  ["g3:081c2299"] = "Gastei todas as minhas economias\\ne comprei mais CARBOIDRATOS.",
  ["g3:081c22ca"] = "Desta vez eu não vou perder.\\nO vento está soprando a meu favor!",
  ["g3:081c2306"] = "Ah, você voltou?\\pClaro, eu brinco de novo com você,\\namorzinho.",
  ["g3:081c2340"] = "Não dá pra você esquecer que\\njá batalhou comigo?",
  ["g3:081c236b"] = "Tá olhando o quê?",
  ["g3:081c2383"] = "Sempre uso os POKéMON pássaro.\\nMe dediquei totalmente a eles.",
  ["g3:081c23c1"] = "Usei MTs para ensinar movimentos\\nbons aos meus POKéMON.",
  ["g3:081c23ef"] = "Meus POKéMON pássaro devem estar\\nprontos para a batalha desta vez.",
  ["g3:081c2425"] = "Você está usando MTs nos seus\\nPOKéMON?\\pSó ficar guardando elas não adianta\\nnada.",
  ["g3:081c2461"] = "Você ensinou seus POKéMON pássaro\\na VOAR?\\pCom isso, você vai poder voar alto\\npelo céu! Experimente.",
  ["g3:081c24cb"] = "A lenda das miragens aladas...\\nVocê já ouviu falar, né?",
  ["g3:081c2505"] = "Não curto muito isso, mas tudo bem.\\nVamos lá!",
  ["g3:081c2531"] = "Ei!\\nEu me lembro de você!\\pBora, bora!\\nVamos, vamos, vamos!",
  ["g3:081c2572"] = "Você tá aqui de novo, hein?\\nCala a boca e vamos batalhar.",
  ["g3:081c259e"] = "A gente tá andando de moto por aqui\\npor causa dos espaços abertos.",
  ["g3:081c25d6"] = "Batalha de POKéMON, né?\\nLegal! Vamos batalhar!",
  ["g3:081c25fb"] = "KIRI: JAN, tomara que a gente\\nvença hoje.",
  ["g3:081c261b"] = "JAN: KIRI, lá vamos nós!\\nDesta vez, vamos vencer com certeza!",
  ["g3:081c2650"] = "Vou continuar batalhando com os\\nPOKéMON que consegui em trocas.",
  ["g3:081c268d"] = "Você parece ser gentil, então acho\\nque posso te vencer.\\pVou tentar mais uma vez!",
  ["g3:081c26d3"] = "Quando eu assobio, os POKéMON\\npássaro se juntam ao meu redor.\\pEles são incrivelmente fofos!",
  ["g3:081c2717"] = "Hmm? Meus pássaros estão tremendo!\\pEspera... não é você que me enfrentou naquela vez?",
  ["g3:081c2753"] = "Ah, que gracinha!\\nParece até um POKéMON fofinho!\\pAgora eu lembrei de você!",
  ["g3:081c279d"] = "Crio POKéMON para me proteger,\\nporque moro sozinha.\\pIsso não mudou.",
  ["g3:081c27e7"] = "Ei, jovem! Vamos nessa!\\nConsegui estes POKéMON de um\\pperdedor qualquer!",
  ["g3:081c2814"] = "Passa todo o seu dinheiro quando\\nvocê perder pra mim, jovem!",
  ["g3:081c2846"] = "O que é legal e está na moda?\\nTrocar POKéMON, é claro!",
  ["g3:081c287d"] = "Quer brincar com meus POKéMON\\nde novo?",
  ["g3:081c28a1"] = "MYA: Oi, a gente vive se\\nencontrando, não é?\\pAjuda a treinar meu irmãozinho\\nde novo?",
  ["g3:081c28ec"] = "RON: Minha irmã ficou mais forte...",
  ["g3:081c2913"] = "O que você quer?",
  ["g3:081c2925"] = "Bela BIKE!\\nEntrega ela logo!",
  ["g3:081c2944"] = "Apareça e venha brincar, cara de rato.\\nVou cuidar bem de você!",
  ["g3:081c297b"] = "Ei, espera um segundo!\\nNão me chame e depois saia correndo!",
  ["g3:081c29b0"] = "Tô com fome e de mau humor!\\nPreciso de um saco de pancadas!",
  ["g3:081c29eb"] = "Ei, você aí!\\nVamos nos divertir muito!",
  ["g3:081c2a19"] = "JED: Veio ver o nosso amor,\\nque não conhece limites?",
  ["g3:081c2a53"] = "LEA: Às vezes, a intensidade do\\nnosso amor me assusta.",
  ["g3:081c2a88"] = "Eu te disse, não dá pra enriquecer\\nrápido batalhando com crianças.",
  ["g3:081c2ac4"] = "Tenho muito orgulho do meu corpo,\\njovem. Vamos nessa!",
  ["g3:081c2af0"] = "Tá passeando?",
  ["g3:081c2b06"] = "Nós somos MOTOQUEIROS!\\nA gente manda nas estradas, cara!",
  ["g3:081c2b2c"] = "VOLTORB vai eletrizar você pra\\nvaler hoje!",
  ["g3:081c2b5e"] = "Subi o nível do meu POKéMON, mas\\nele não evolui de jeito nenhum.\\pPor quê?",
  ["g3:081c2b9c"] = "Gaaah! Preciso mesmo me exercitar\\ne perder essa gordura!",
  ["g3:081c2bda"] = "Seja rebelde!",
  ["g3:081c2be6"] = "É verdade, que BICICLETA legal!\\nComo ela corre?",
  ["g3:081c2c10"] = "Cai fora, jovem!\\nTô exausto!",
  ["g3:081c2c2b"] = "Tenho olhado em cada área de grama\\nà procura de novos POKéMON.\\pMas nem sempre é fácil...",
  ["g3:081c2c7b"] = "Cucurucucuu!\\nMeu canto de pássaro tá melhorando?",
  ["g3:081c2ca8"] = "Eu te avisei antes, este é o\\nmeu território!\\pNão quero você por aqui.",
  ["g3:081c2cee"] = "Tô quase aquecido pra dar um\\nmergulho.",
  ["g3:081c2d19"] = "Espera! Vai devagar! E se você\\ntiver um ataque do coração?",
  ["g3:081c2d4b"] = "Adoro nadar!\\nAcho que você é do tipo que surfa.",
  ["g3:081c2d7d"] = "O que há além do horizonte?\\nVocê já viu?",
  ["g3:081c2da7"] = "Tentei mergulhar à procura de\\nPOKéMON de novo, mas não deu\\pem nada como antes.",
  ["g3:081c2de9"] = "Olho pro mar pra esquecer todas\\nas coisas ruins que aconteceram.\\p... Tipo perder pra você da última\\nvez!",
  ["g3:081c2e4a"] = "Você sempre pode montar no seu\\nPOKéMON...\\pParece tão relaxante.\\nPosso ficar com ele se eu vencer?",
  ["g3:081c2e9d"] = "Nadar é ótimo!\\nQueimaduras de sol não!",
  ["g3:081c2ec0"] = "Estas águas são traiçoeiras!\\nVocê não deveria voltar aqui!",
  ["g3:081c2efc"] = "Nadei até aqui com meus amigos...\\nTô cansada...\\pA gente tem mesmo que batalhar\\nde novo?",
  ["g3:081c2f41"] = "LIA: Você sabe que meu irmão acabou\\nde se tornar um TREINADOR, né?\\pQuero que ele melhore, então preciso\\nda sua ajuda de novo.",
  ["g3:081c2fae"] = "LUC: Minha irmã me ensinou tudo\\nsobre POKéMON.\\pSerá que estou melhor?",
  ["g3:081c2ff3"] = "A água é rasa por aqui.\\nTem muita gente nadando.",
  ["g3:081c302e"] = "Você tá com inveja de eu estar\\nde férias nas ILHAS ESPUMA?",
  ["g3:081c305f"] = "Adoro flutuar com os peixes aqui\\nentre as ondas.",
  ["g3:081c3095"] = "Você também estava de férias?",
  ["g3:081c30b0"] = "Dá uma olhada no meu físico!\\pTô mais sarado do que nunca!",
  ["g3:081c30ed"] = "Por que você se montou em um\\nPOKéMON?\\pAinda não aprendeu a nadar?",
  ["g3:081c312c"] = "Vim montado no meu POKéMON pássaro\\naté aqui.",
  ["g3:081c3149"] = "Meu namorado me deu pérolas grandes.\\nE elas cresceram ainda mais!",
  ["g3:081c3185"] = "Nadei da ILHA DE CINNABAR até aqui.\\nNão foi nada fácil, como eu disse.",
  ["g3:081c31c4"] = "CINNABAR, no oeste, tem um\\nLABORATÓRIO para POKéMON.\\pMeu papai trabalha lá.",
  ["g3:081c3208"] = "Você quer saber se os peixes estão\\nmordendo?",
  ["g3:081c3231"] = "Fiz uma grande pescaria de novo!\\nQuer mais uma rodada?",
  ["g3:081c3264"] = "O mar limpa meu corpo e minha alma!",
  ["g3:081c3298"] = "Peguei meus POKéMON no mar.\\nE é nele que eu treino eles.",
  ["g3:081c32d3"] = "Neste momento, estou em outra\\ncompetição de triatlo!",
  ["g3:081c32fd"] = "Ahh!\\nSinta o sol e o vento!",
  ["g3:081c331d"] = "Ei, para com isso já!\\nVocê sempre espanta os peixes!",
  ["g3:081c3356"] = "Fica comigo até eu fisgar algo.",
  ["g3:081c3378"] = "LIL: Hein? Outra batalha?\\nIAN, não consegue sozinho?",
  ["g3:081c33ae"] = "IAN: Minha irmã é muito mole.\\nMe ajuda a dar um jeito nela!",
  ["g3:081c33e7"] = "Não vou perder enquanto eu\\nestiver aqui!",
  ["g3:081c3404"] = "Meu pai me levou a uma festa\\nótima no SANTA ANA na CIDADE\\pDE VERMILION.",
  ["g3:081c3445"] = "Sou um cara descolado.\\nTenho uma namorada!\\pDesta vez, vou mostrar pra ela\\ncomo eu sou legal com certeza!",
  ["g3:081c349c"] = "Oi!\\nMeu namorado é o máximo!\\pTô em ótima forma hoje!",
  ["g3:081c34d4"] = "Eu tive esse pressentimento...\\pSabia que batalharia com você de\\nnovo!",
  ["g3:081c350a"] = "Minha amiga tem muitos POKéMON\\nfofos. Tô morrendo de inveja!",
  ["g3:081c353b"] = "Acabei de treinar no MONTE LUA,\\nmas ainda tenho energia de sobra!",
  ["g3:081c357e"] = "Um POKéMANÍACO vive no cabo.\\nJá viu a coleção dele?",
  ["g3:081c35bc"] = "Você vai ver o BILL de novo?\\nPrimeiro, vamos batalhar!",
  ["g3:081c35ee"] = "Vi o seu feito aqui do meio da\\ngrama!",
  ["g3:081c360e"] = "Tudo bem!\\nVou te esmagar!",
  ["g3:081c3624"] = "Você sempre parece estar nos corres...\\nNão tá se cansando?",
  ["g3:081c3657"] = "Você deve amar mesmo vir até a\\nPONTE DA PEPITA.",
  ["g3:081c3685"] = "Aquela vez que batalhamos...\\pMesmo eu sendo o segunda da\\nfila, eu era a melhor, não era?",
  ["g3:081c36da"] = "O pessoal chama este lugar de\\nPONTE DA PEPITA!\\pVocê já nos venceu, então não pode\\naceitar o desafio...\\p... Mas, sinta-se à vontade pra\\nbatalhar com a gente de novo.",
  ["g3:081c3773"] = "Deitado, balançando nas ondas...\\nNem noto o tempo passar...",
  ["g3:081c37b5"] = "O tempo está maravilhoso!\\nVou tentar não estragá-lo.",
  ["g3:081c37e7"] = "Minha queimadura de sol tá\\ncomeçando a doer...",
  ["g3:081c3807"] = "A montanha do pássaro de fogo\\nprojeta uma sombra enorme...",
  ["g3:081c3835"] = "Tenho esse forte pressentimento\\nde que posso vencer desta vez!",
  ["g3:081c386a"] = "Espera! Espera um pouco! Tenho\\ncerteza que fisguei um dos grandes!",
  ["g3:081c389f"] = "Você vai me ajudar com o meu\\ntreinamento de novo?",
  ["g3:081c38ca"] = "Não perdemos um único dia de\\ntreinamento ainda!",
  ["g3:081c38fa"] = "Todo dia de manhã, antes do café,\\neu nado em volta desta ilha...\\pTrês vezes!",
  ["g3:081c3943"] = "Vista-se adequadamente para a\\nbatalha!\\pTire essa roupa fútil, eu já disse!",
  ["g3:081c3987"] = "Sabe, tudo fica com um gosto ótimo\\nquando você tá no meio na natureza.",
  ["g3:081c39c6"] = "Comi demais de novo, então quer\\nbatalhar comigo para exercitar?",
  ["g3:081c3a05"] = "KIA: Meu irmão e eu somos uma\\ncombinaçao incrível!\\pNão vamos perder desta vez!",
  ["g3:081c3a55"] = "MIK: Junto com a KIA, a gente\\nnão teme nada!\\pVamos provar pra você desta vez!",
  ["g3:081c3aa7"] = "Vamos batalhar de novo?",
  ["g3:081c3abf"] = "De onde você veio e para onde\\nestá indo?",
  ["g3:081c3af2"] = "Quero nadar sem minha boia\\nlogo logo.",
  ["g3:081c3b1d"] = "Eba, eba!\\nPOKéMON!",
  ["g3:081c3b30"] = "Ah, não, eu já não te disse?\\nPor favor, fica longe de mim!",
  ["g3:081c3b6e"] = "JOY: Ficamos mais fortes!\\nMuito, muito mesmo!",
  ["g3:081c3b99"] = "MEG: Você não pode vencer a\\ngente hoje!",
  ["g3:081c3bb7"] = "Olá, olá!\\pVocê está criando seus POKéMON\\nem um bom ambiente?",
  ["g3:081c3bf6"] = "Com estas mãos, conquistarei\\nminha vitória hoje.",
  ["g3:081c3c28"] = "Vou ter que repetir?\\nTô tentando pintar.\\pPor favor, saia da minha frente!",
  ["g3:081c3c70"] = "Não fiz progresso algum...\\nAinda não consigo o ângulo certo...",
  ["g3:081c3cb0"] = "Oh, você me dará outra oportunidade\\nde medir forças com você?",
  ["g3:081c3cf1"] = "Estao quase terminando de fazer a\\npiscina para meus POKéMON.\\pVocê precisa passar para uma visita.",
  ["g3:081c3d47"] = "Sou um bom corredor.\\nFiquei ainda mais rápido!",
  ["g3:081c3d73"] = "Diga lá, camarada!\\nVamos aproveitar nosso tempo juntos!",
  ["g3:081c3da2"] = "Sou o mais velho dos IRMÃOS\\nPÁSSARO. Lembra de mim?\\pIsso mesmo, sou quem ama os\\npássaros por seus bicos!",
  ["g3:081c3e0f"] = "Sou o filho do meio dos IRMÃOS\\nPÁSSARO.\\pSou aquele que ama as asas.\\nVamos batalhar de novo!",
  ["g3:081c3e6a"] = "Sou o mais novo dos IRMÃOS\\nPÁSSARO.\\pAmo os pássaros por sua penugem.\\nNão achei que te veria de novo!",
  ["g3:081c3ed0"] = "Ainda não tive sorte nenhuma.\\nUma batalha seria uma boa\\pmudança de ritmo!",
  ["g3:081c3f11"] = "Oof... Oof...\\pNadei do porto da SEIS ILHAS\\naté aqui direto, de novo.",
  ["g3:081c3f51"] = "Você sempre aparece enquanto\\nestou nadando.",
  ["g3:081c3f7b"] = "AVA: Vamos ter outra batalha\\nmarinha de dois contra dois hoje!",
  ["g3:081c3fb3"] = "GEB: Minha irmã e eu estamos muito\\nmais fortes do que antes!",
  ["g3:081c3fe9"] = "... Ha?\\pEu penso na minha casa, mas\\nsempre me TELEPORTO pra cá!",
  ["g3:081c4028"] = "Oh, olá.\\nUma brisa agradável sopra novamente.",
  ["g3:081c4057"] = "Hehehe, estou praticando em\\nsegredo novamente.",
  ["g3:081c407f"] = "Como é? Cansou de ver NADADORES\\ncomo eu?\\pAh, não seja ranzinza!\\nBatalhe comigo de novo.",
  ["g3:081c40d9"] = "Aff...\\nMeu namorado tá ocupado de novo...",
  ["g3:081c40fa"] = "Diga logo, onde ficam as montanhas\\npor estas bandas?",
  ["g3:081c4138"] = "MIU: Olá, POKéMON!\\nÉ hora de brincar de novo!",
  ["g3:081c4166"] = "MIA: Olá, POKéMON!\\nÉ hora de batalhar de novo!",
  ["g3:081c4196"] = "Parece que ainda existem muitos\\nsegredos não resolvidos neste mundo.",
  ["g3:081c41d4"] = "Oi, a gente já não se conheceu?\\nO que te obrigou a voltar?",
  ["g3:081c4210"] = "Dizem que existem pedras\\nmisteriosas nesta ilha.\\pDescobriu algo desde a última\\nvez que a gente se viu?",
  ["g3:081c4280"] = "Uma revanche com você,\\naqui tão no alto!",
  ["g3:081c42a0"] = "Conheço bem esta região.",
  ["g3:081c42d6"] = "Senti sua aproximação.",
  ["g3:081c42ee"] = "Em algum lugar desta ilha, POKéMON\\npeculiares estão dormindo.",
  ["g3:081c4327"] = "Kyahaha!\\pVoltar não vai mudar nada.\\nVou te derrotar num piscar de olhos!",
  ["g3:081c4374"] = "Olá! Você é membro do meu\\nfã-clube, não é mesmo?",
  ["g3:081c43ad"] = "Esta ilha é grande demais...\\nPatrulhar este lugar é um saco...",
  ["g3:081c43ec"] = "Eu não perdoo quem maltrata\\nPOKéMON!",
  ["g3:081c4416"] = "EVE: Vou fazer dupla com o JON\\ne batalhar juntos de novo.",
  ["g3:081c444c"] = "JON: Quando estou com a EVE,\\nsinto que nunca perderemos,\\pnunca mesmo.",
  ["g3:081c4491"] = "Vamos batalhar de novo.\\nEstou em plena forma!",
  ["g3:081c44cb"] = "Não importa se você por acaso\\ntem os POKéMON mais fortes...\\pNão significa nada se você não\\nsouber usá-los direito!",
  ["g3:081c454e"] = "Eu trabalho para proteger o meio\\nambiente.\\pEm troca, a natureza me protege!",
  ["g3:081c458e"] = "Toda vez que a gente se vê, você\\nestá com esses calçados estilosos.",
  ["g3:081c45c2"] = "Você deve ter ficado mais forte.\\pDeixa eu batalhar com você,\\npor favor!",
  ["g3:081c45fb"] = "Recebi a melhor educação possível\\npara me tornar assim tão forte.\\pNão vou perder desta vez.\\nCom certeza não!",
  ["g3:081c4662"] = "LEX: Minha querida NYA, juntos\\nvenceremos com certeza!",
  ["g3:081c4699"] = "NYA: Não vou decepcionar meu\\nmentor LEX! Nós vamos vencer!",
  ["g3:081c46d3"] = "Você descobriu alguma coisa sobre\\nesta câmara de pedra?",
  ["g3:081c470a"] = "Dizem que um POKéMON místico\\ndorme aqui dentro.",
  ["g3:081c4739"] = "Meu professor está me ensinando a\\npintar um pouco mais.",
  ["g3:081c476a"] = "Hoje, além da nossa aula, viemos\\nver a câmara novamente.",

